INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 614, 'ruRU', 'О, ты $Gнашёл:нашла; его! О, радость, о счастье! Спасибо, $N. Ко мне вернулся мой сундук, и в душе разгорается прежний огонь.$B$BНо месть моя еще не свершилась...' FROM `quest_offer_reward` WHERE `ID`=614 AND MD5(`RewardText`)='98ad3e645a229540e56906306778229f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=614 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 1191, 'ruRU', 'Поехали!' FROM `quest_offer_reward` WHERE `ID`=1191 AND MD5(`RewardText`)='634efc0701950e9b2b97384327c8d5d2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=1191 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 1682, 'ruRU', 'Вот тебе оружие, только что с наковальни. На него пошла добытая тобой мрачная руда!$b$bЧто же, $N, выбирай!' FROM `quest_offer_reward` WHERE `ID`=1682 AND MD5(`RewardText`)='a87529a61b1cda145a59ab4672be2f00' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=1682 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 2399, 'ruRU', 'Папоротник, который Деналан посадил у себя в саду, проклюнулся и вырос. Ростки так и просят, чтобы их скорее собрали...' FROM `quest_offer_reward` WHERE `ID`=2399 AND MD5(`RewardText`)='495902679538850b2bd2ed936e2adda5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=2399 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 2985, 'ruRU', 'Ветер следует за тобой, по земле ты шагаешь твердо, а дух уже согрет огнем – я бы сказала, что пришло время познать чистоту воды.\n\nПуть твой был долог, и сила духа позволит тебе пройти еще дальше. Но первый шаг делать тебе.' FROM `quest_offer_reward` WHERE `ID`=2985 AND MD5(`RewardText`)='ec0a1b5812f9e8462c688e2a780eb239' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=2985 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 3083, 'ruRU', 'Ну а до тех пор будешь у меня в обучении. Я тебе расскажу, что к чему. Когда решишь, что $gготов:готова;, приходи ко мне, и я тобой займусь. А пока упражняйся в том, что уже умеешь. Все твои навыки должны быть отточены, как бритва! Никогда не знаешь, в какой момент пригодится какое-нибудь пустяковое умение.' FROM `quest_offer_reward` WHERE `ID`=3083 AND MD5(`RewardText`)='a23b42701673c809b03baa185fd87c2a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=3083 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 4967, 'ruRU', 'А, ты ищешь чего-то более... вещественного. Я помогу тебе, если хочешь.\n\nПриятно видеть, что не все наши сородичи стремятся к одним лишь знаниям.\n\nИтак, думаешь, ты готов, $N?' FROM `quest_offer_reward` WHERE `ID`=4967 AND MD5(`RewardText`)='1efd276a5d163c62f5404d6269d3512f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=4967 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 5058, 'ruRU', 'В дневнике с пожелтевшими от времени страницами открыта последняя запись:$B$B"Гарольд превратился в нежить, и я не знаю, что теперь будет. Я из последних сил утащила его в единственное место, которое можно надежно запереть. Я держу ключ при себе, будем надеяться, что моя уловка сработает...$B$BНадеюсь, я смогу выбраться отсюда, но для этого нужны деньги. Все наши вещи в шкафу... и, кажется, Гарольд держал ключ от него при себе.$B$BПора мне отдохнуть, я смертельно устала."' FROM `quest_offer_reward` WHERE `ID`=5058 AND MD5(`RewardText`)='041d6e04d597a89c9263dfdecc68f955' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=5058 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 5305, 'ruRU', 'Вот чертежи молота, $N. Надеюсь, с его помощью ты многим даруешь безмятежность!' FROM `quest_offer_reward` WHERE `ID`=5305 AND MD5(`RewardText`)='9a13556b5e84ea1d575e107b0e96cace' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=5305 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 5307, 'ruRU', 'Меч – самый лучший выбор, это же очевидно!' FROM `quest_offer_reward` WHERE `ID`=5307 AND MD5(`RewardText`)='94d59aec39f78d9673d8175402b091c4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=5307 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 5401, 'ruRU', 'Все, кто борется со злом от имени Серебряного Рассвета, должны носить жетон. Ношение таких жетонов позволит тебе достичь права получать награды у наших интендантов, которые они могут предложить.$B$BТак же вы можете получать за убитую нежить камень Плети. Эти камни ты можешь приносить мне и обменивать их на знак доблести Серебряного Рассвета.$B$BОбеспечь свою судьбу, $C – присоединяйся к борьбе уже сегодня!' FROM `quest_offer_reward` WHERE `ID`=5401 AND MD5(`RewardText`)='d3cee4cd616a09589487cc5b5570d31a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=5401 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 5503, 'ruRU', 'Все, кто борется со злом от имени Серебряного Рассвета, должны носить жетон. Ношение таких жетонов позволит тебе достичь права получать награды у наших интендантов, которые они могут предложить.$B$BТак же вы можете получать за убитую нежить камень Плети. Эти камни ты можешь приносить мне и обменивать их на знак доблести Серебряного Рассвета.$B$BОбеспечь свою судьбу, $C – присоединяйся к борьбе уже сегодня!' FROM `quest_offer_reward` WHERE `ID`=5503 AND MD5(`RewardText`)='44d860b7d20315bca124c81ec9990671' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=5503 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 5891, 'ruRU', 'Вот тебе кенарийский бальзам, и за него я прошу только одну порцию простой субстанции Пустоты, $N. Субстанция эта – вещество самое мощное из тех, что я применяю при перековке мечей на орала. Если тебе понадобится еще бальзам, ищи меня тут!' FROM `quest_offer_reward` WHERE `ID`=5891 AND MD5(`RewardText`)='9a43c7747c8a716ab4fdd44fcccb1dbb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=5891 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 7490, 'ruRU', 'Это великая победа для Орды, $N Тебе уже не раз случалось постоять за честь своего вождя. Пришла пора и вождю оказать тебе честь!' FROM `quest_offer_reward` WHERE `ID`=7490 AND MD5(`RewardText`)='2a22bf4cdeb0de72769ad568303b6981' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=7490 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 7658, 'ruRU', 'С тобой приятно иметь дело.$B$BИ, пожалуйста, $N, сотри это выражение недовольства со своего лица.' FROM `quest_offer_reward` WHERE `ID`=7658 AND MD5(`RewardText`)='2b77ba927ba1f103946dd6616986a852' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=7658 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8171, 'ruRU', 'Разведчик Осквернителей пришел ко мне с рапортом о вашем успехе, $N. Неплохо сработано.\n\nКак вы вскоре поймете, чтобы выиграть битву в Низине Арати, мы должны быть постоянно начеку и пресекать любые попытки экспансии Альянса. Поступайте так – и тем вы обеспечите нам победу.' FROM `quest_offer_reward` WHERE `ID`=8171 AND MD5(`RewardText`)='80f63dff98889197f790195cbaa8eeac' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8171 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8326, 'ruRU', 'Башня и прилегающие районы теперь должны быть относительно безопасными, но только на время. Ты хорошо поработал, предоставив нам буфер безопасности, но нам нужно будет восстановить контроль над всем островом, если мы хотим выжить здесь в долгосрочной перспективе. Это будет включать в себя борьбу с гораздо большими угрозами, чем с ошибочными мана-змеями и рысями. $B$BВозьми, $n - это несомненно пригодится тебе для выполнения будущих задач.' FROM `quest_offer_reward` WHERE `ID`=8326 AND MD5(`RewardText`)='3169f997f495767b8ba28cb678ef2257' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8326 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8328, 'ruRU', 'А, $N, видимо, ты из новых магов нашего острова, да? Что же, ты не ошибся, заглянув ко мне. Если ты хочешь овладеть искусством магии, то я согласна делиться с тобой своими знаниями – покуда твоих денег и способностей будет хватать для продвижения в науке.\n\nНачнем же!' FROM `quest_offer_reward` WHERE `ID`=8328 AND MD5(`RewardText`)='d2620e754d75034e89bd88ee4ff73be0' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8328 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8330, 'ruRU', 'Отлично! Я знал, что ты идеально подходишь для этой задачи. Как только мы сможем использовать наши другие структуры по всему острову, эти вещи очень пригодятся мне.$B$BКстати, вот, как и обещал, не стесняйся забрать сумку. Также тебе может пригодиться этот доспех. Считай это хорошей наградой за простое, но добросовестно выполненное поручение!' FROM `quest_offer_reward` WHERE `ID`=8330 AND MD5(`RewardText`)='6e05908a7510319308b297b74d1e777e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8330 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8336, 'ruRU', 'Великолепно - отличные осколки. Я много думал о недомогании, которым страдает Остров Солнечного Скитальца. Один из возможных вариантов действий, который я обдумывал, заключался в том, чтобы собрать эти магические осколки у существ на острове. Также можно поэксперементировать на этих созданиях, но это накладывает определенную вину.$B$BВ любом случае, я склоняюсь продолжить исследования. Позволь мне применить к тебе это заклинание. Я уверен, что оно поможет тебе в твоих странствиях!' FROM `quest_offer_reward` WHERE `ID`=8336 AND MD5(`RewardText`)='afa4a44b55905dfcf0773655e7e64717' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8336 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8414, 'ruRU', 'Исцелять камень Плети от зла рискованно, ведь может явиться нежить со всех сторон света. Но ты предан делу Света, и я не боюсь за тебя, $N…' FROM `quest_offer_reward` WHERE `ID`=8414 AND MD5(`RewardText`)='4d5801c88ea88eedc45a41094cb4397c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8414 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8416, 'ruRU', 'Ты выполнил мой приказ без лишних слов, $N.$B$BПохоже, тебе можно верить. Пожалуй, я поделюсь с тобой своим планом.' FROM `quest_offer_reward` WHERE `ID`=8416 AND MD5(`RewardText`)='17a6a9b64cdebb53b9108421236490c0' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8416 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8463, 'ruRU', 'Прекрасно, $n.' FROM `quest_offer_reward` WHERE `ID`=8463 AND MD5(`RewardText`)='5da6a0f543e3688656bc9e597c76ea07' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8463 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8468, 'ruRU', 'Наконец-то этот негодяй, Таэлис, получил по заслугам! Молодец, $n. Теперь-то Презренные присмиреют хотя бы на время!' FROM `quest_offer_reward` WHERE `ID`=8468 AND MD5(`RewardText`)='a3d2188d905e291ce295c1290f59bcc2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8468 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8472, 'ruRU', 'Молодец, $n! Теперь, когда наши волшебные святилища не работают в полную силу, эти энергетические сердечники очень сильно поспособствуют решению наших проблем.' FROM `quest_offer_reward` WHERE `ID`=8472 AND MD5(`RewardText`)='e110cc66bf17b444d9b300bca4464aa9' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8472 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8473, 'ruRU', 'Значит, дело сделано... Будь прокляты эти времена, вынудившие нас пойти на крайние меры... и будь проклята Плеть!\n\nЗапомни, $N: мы должны защищать свои земли во что бы то ни стало! И мы победим!' FROM `quest_offer_reward` WHERE `ID`=8473 AND MD5(`RewardText`)='bd7d1931b6f476559481528b06987745' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8473 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8474, 'ruRU', 'О-о... эта подвеска... Я подарила ее Старому Белостволу, после того как его народ помог нам отстроить нашу деревню.\n\nБоюсь, это означает, что он…\n\nЭльфийка откашливается и берет себя в руки.\n\nСпасибо, что принесла мне эту вещь, $N. Я хотела бы попросить тебя об одной услуге...' FROM `quest_offer_reward` WHERE `ID`=8474 AND MD5(`RewardText`)='aefaf8e2a806c74957c9f627465a7102' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8474 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8479, 'ruRU', 'О да! Наконец-то Зул\'Марош получил по заслугам! Он сжег деревню Вень\'яши. Я убил много Амани, прежде чем меня затолкали в эту клетку! Я спрятал кое-что в песке – это будет мой дар тебе.\n\nОх... яд расходится по жилам... Пора мне помирать...' FROM `quest_offer_reward` WHERE `ID`=8479 AND MD5(`RewardText`)='0a3564c104de241214934d74be04915e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8479 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8490, 'ruRU', 'Отлично! Значит, наша оборона от Плети продержится еще немного. Спасибо тебе за помощь, $N!' FROM `quest_offer_reward` WHERE `ID`=8490 AND MD5(`RewardText`)='cd5db04f11a60c3cabd04abfc42df8f5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8490 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8563, 'ruRU', '$N... говорят, ты ищешь наставника в чернокнижии? Ты кажешься мне довольно способным, но первое впечатление часто бывает обманчивым. Я жду от тебя готовности ступить в поисках силы туда, куда другие страшатся даже заглянуть. Ты будешь учиться, но неудачи я не прощу.\n\nТвое обучение будет стоить определенной платы, но лучше подумай о том, какую цену придется заплатить твоему разуму за тайное знание. Если у тебя не осталось сомнений в твоем предназначении – мы начнем.' FROM `quest_offer_reward` WHERE `ID`=8563 AND MD5(`RewardText`)='63efb7d9dab069e0b9439ada89b0417f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8563 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8635, 'ruRU', 'Легенды растут из семени давних битв. Ты живешь в эпоху героев, $gюноша:девушка;. Да укоренится твоя легенда и да принесет она обильный плод.$B$BВсего тебе наилучшего, $N. Прими от меня этот знак...' FROM `quest_offer_reward` WHERE `ID`=8635 AND MD5(`RewardText`)='ee092932475c1ac3c64928fe9791328a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8635 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8644, 'ruRU', 'Приятно знать, что народ этих земель все еще отдает дань уважения древним расам. Всего хорошего, $N. Прими этот знак...' FROM `quest_offer_reward` WHERE `ID`=8644 AND MD5(`RewardText`)='273cbc6804cc1c9d921cbe392e268f9e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8644 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8645, 'ruRU', 'Приятно знать, что народ этих земель все еще отдает дань уважения древним расам. Всего хорошего, $N. Прими этот знак...' FROM `quest_offer_reward` WHERE `ID`=8645 AND MD5(`RewardText`)='0f6ce527cc9d8ad5e7d20a0d5c593d96' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8645 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8646, 'ruRU', 'Приятно знать, что народ этих земель все еще отдает дань уважения древним расам. Всего хорошего, $N. Прими этот знак...' FROM `quest_offer_reward` WHERE `ID`=8646 AND MD5(`RewardText`)='0f6ce527cc9d8ad5e7d20a0d5c593d96' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8646 AND x.`locale`='ruRU');
