INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8685, 'ruRU', 'Жизнь так и кипит в тебе, $gюный:юная; |3-6($c). Я принимаю твою дань уважения. Возьми взамен этот знак...' FROM `quest_offer_reward` WHERE `ID`=8685 AND MD5(`RewardText`)='59dca4c17bd2d1169fe2d539a13985c7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8685 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8686, 'ruRU', 'Жизнь так и кипит в тебе, $gюный:юная; |3-6($c). Я принимаю твою дань уважения. Возьми взамен этот знак...' FROM `quest_offer_reward` WHERE `ID`=8686 AND MD5(`RewardText`)='59dca4c17bd2d1169fe2d539a13985c7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8686 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8885, 'ruRU', 'Наконец-то! Правда, мурлоки так и не ушли, но все же приятно было видеть, как они забегали в панике, когда ты сразила их так называемого "вождя". Я благодарю тебя, а вместе со мной – и все син\'дорай Луносвета!\n\nПожалуйста, выбери одну из этих вещей в награду за оказанную тобой услугу!' FROM `quest_offer_reward` WHERE `ID`=8885 AND MD5(`RewardText`)='e6dc20dfddf0acdc69d39960c8b14c67' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8885 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8888, 'ruRU', 'Ах, магистр обо мне тревожится? Как это мило. Лучше бы он обо мне побеспокоился раньше, когда мы были еще в замке!\n\nНу, неважно. Пожалуйста, |3-6($C), выслушай меня внимательно. Мне придется попросить тебя об услуге.' FROM `quest_offer_reward` WHERE `ID`=8888 AND MD5(`RewardText`)='1df7e037236b7c4932dca1bde691506c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8888 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8889, 'ruRU', 'Я так благодарна тебе за помощь! Однако печально слышать, что некоторые из моих сотоварищей поддались искушению…\n\nТеперь, когда источники энергии отключены, я, пожалуй, побуду здесь и подожду, пока все успокоится, а потом проберусь внутрь и заберу их останки...' FROM `quest_offer_reward` WHERE `ID`=8889 AND MD5(`RewardText`)='f7d8613b66a2664658c598f1dddec43c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8889 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8890, 'ruRU', 'О нет! Значит, я опоздал... Это все моя вина.\n\nМои исследования альтернативных источников магии зашли слишком далеко, прежде чем я догадался положить этому конец. Если бы только я отправился туда сам... или если бы они вняли моим предупреждениям!\n\nИх судьба на моей совести, |3-6($C). Но все равно, я благодарю тебя за то, что ты помогла истерзанным душам моих бывших учеников обрести покой. Меня отчасти утешает то, что они недолго пребывали в этом состоянии, которое для эльфа хуже смерти.' FROM `quest_offer_reward` WHERE `ID`=8890 AND MD5(`RewardText`)='a491d830091161db4b978050fdfc48e2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8890 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8891, 'ruRU', 'Да, $N, вот оно, доказательство моего преступления! В этом журнале – описание всех моих неосторожных опытов.\n\nМеня предупреждали, но я не обращал внимания, я продолжал свои исследования, пока не стало поздно! Тогда я осознал свою ошибку и попытался ее исправить. Однако некоторые из моих учеников успели зайти слишком далеко. Я эвакуировал замок, чтобы изолировать их от порчи, но в спешке забыл отключить источники энергии...\n\nЯ сожгу этот журнал, чтобы никто более не пал жертвой подобного искушения! Я ведь всего лишь хотел помочь син\'дорай...' FROM `quest_offer_reward` WHERE `ID`=8891 AND MD5(`RewardText`)='dfce588862fe054e7ecb53bf0b1e2e07' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8891 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8894, 'ruRU', 'Ну, думаю, этого должно быть достаточно, не правда ли? Спасибо за помощь, |3-6($C). Могу только надеяться, что этот беспорядок окончательно ликвидируют к тому времени, как в Замок Блеклых Сумерек вернется магистр.\n\nНа вот, возьми эту мелочь. Это немного, но больше у меня при себе сейчас нет. Можешь перед уходом ликвидировать еще нескольких тварей, если тебя не затруднит.' FROM `quest_offer_reward` WHERE `ID`=8894 AND MD5(`RewardText`)='b62b59dd69579fc2b8e4dc65abe82fc8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8894 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 8895, 'ruRU', 'Спасибо, $n. Я ждал этого письма.' FROM `quest_offer_reward` WHERE `ID`=8895 AND MD5(`RewardText`)='3f3d06349aaef9cf60c625375ed1ef2f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=8895 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9124, 'ruRU', 'Отлично, $N. Имей в виду, я всегда готов купить еще.' FROM `quest_offer_reward` WHERE `ID`=9124 AND MD5(`RewardText`)='1f6cfdd48cd1477e3070865ab67ac9c1' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9124 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9128, 'ruRU', 'Отличная работа, $N! Как и было обещано, значок твой.' FROM `quest_offer_reward` WHERE `ID`=9128 AND MD5(`RewardText`)='2e26d4ec778d3649a43268ff6fbccd80' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9128 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9136, 'ruRU', 'Благодарю тебя, $N.$B$B<Райн кланяется>$B$BПомни, что ростки всегда нужны мне.' FROM `quest_offer_reward` WHERE `ID`=9136 AND MD5(`RewardText`)='a1539954b685cc3fc86f9a456eebfbb8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9136 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9138, 'ruRU', 'Невероятно! Но сколько же еще нужно сделать до того, как Плеть окончательно и бесповоротно будет изгнана из могучего Кель\'Таласа!\n\nВот, прими эту плату. Тут немного, но ты заслужил.' FROM `quest_offer_reward` WHERE `ID`=9138 AND MD5(`RewardText`)='0c9ec28dfaf2cf99e7cb8e4e54498d8d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9138 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9139, 'ruRU', 'Твой успех в Деревне Золотистой Дымки еще на шаг приблизил нас к отвоеванию наших земель. Но не обольщайся, |3-6($C) – битва далеко не закончена.\n\nВот, бери, это более чем заслуженная награда. Эта вещь может тебе пригодиться, когда ты пойдешь наводить порядок в деревне Ветрокрылых.' FROM `quest_offer_reward` WHERE `ID`=9139 AND MD5(`RewardText`)='5535054e6aacc75d1ce60ef751a2c42b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9139 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9140, 'ruRU', 'Дело сделано, $N. Ты вырвала из когтей Плети целых три поселения! Теперь мы сможем собрать больше сил для противостояния тварям Плети на Тропе Мертвых и к югу от Смертхольма.\n\nВот – выбирай что хочешь. Надеюсь, ты никуда не уезжаешь? Ты нам тут еще очень пригодишься!' FROM `quest_offer_reward` WHERE `ID`=9140 AND MD5(`RewardText`)='57fcd46c573594c22f0fc0fd00ed5750' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9140 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9143, 'ruRU', 'Спасибо тебе за труды, |3-6($C)! Спасибо. Теперь хоть можно сказать, что наш поход и наши потери не были напрасны.' FROM `quest_offer_reward` WHERE `ID`=9143 AND MD5(`RewardText`)='a6eb0e4a3710fb4bca7d183657314a66' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9143 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9146, 'ruRU', 'Воистину злые вести – я переоценил командирские способности Томатрена. Я тотчас отправлю отряд, чтобы они доставили его и Валанну сюда в целости и сохранности.\n\nУвы, мы так ничего и не знаем о следопыте Салиссе, так что я опасаюсь худшего.\n\nТы сегодня оказала огромную услугу Странникам, |3-6($C). Прошу – прими этот маленький дар в знак нашей благодарности.' FROM `quest_offer_reward` WHERE `ID`=9146 AND MD5(`RewardText`)='adff5b157661b1f9f5711af290a8da4b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9146 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9147, 'ruRU', 'Вовремя, $N! Я уж собралась было копать могилку нашему приятелю.\n\nПохоже, мое зелье действует – мальчик-то приходит в себя.\n\nЭй, похоже, он хочет что-то тебе сказать! Почему бы тебе не поговорить с ним?' FROM `quest_offer_reward` WHERE `ID`=9147 AND MD5(`RewardText`)='d35460290058528151ec62c39013ad0a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9147 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9148, 'ruRU', 'Наконец-то! Мы ждали ответа от лорда-регента несколько недель! Посмотрим, что он пишет...\n\nВандрил начинает читать письмо.\n\nЧто такое? Тьма? Он ощущает присутствие тьмы в Призрачных землях?! Будто я сам не вижу!\n\nИ этого ответа мы так долго дожидались?' FROM `quest_offer_reward` WHERE `ID`=9148 AND MD5(`RewardText`)='4be88ae2d7ecdce6f9a7d7760492b693' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9148 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9149, 'ruRU', 'Блестяще! Эти хребты как нельзя лучше годятся для моих исследований! Когда я найду лекарство от чумы и слух обо мне пойдет по городам и весям, тогда уж я не позабуду упомянуть о тебе!\n\nА пока вот тебе награда. Они могут тебе понадобиться, если решишь вернуться на побережье.' FROM `quest_offer_reward` WHERE `ID`=9149 AND MD5(`RewardText`)='f86fa2e9ec6a4e11484029dd34dac58c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9149 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9151, 'ruRU', 'Так ты от Дарэниса? Очень хорошо, думаю, твоя помощь в сражении с силами Дар\'Кхана нам пригодится.' FROM `quest_offer_reward` WHERE `ID`=9151 AND MD5(`RewardText`)='42a2fd312726525d6a92d3c10f4b106a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9151 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9152, 'ruRU', 'Теперь, когда мои припасы при мне, я могу открыть свою лавочку. Уверен, что верховный палач будет весьма рад узнать, что можно начинать войну против Дар\'Кхана и Плети.\n\nКонечно же, мы не забыли о вознаграждении. Вот, |3-6($C), деньги, о которых я говорил. Заходи, если понадобится купить что-нибудь.' FROM `quest_offer_reward` WHERE `ID`=9152 AND MD5(`RewardText`)='27e3a0a2f3c4071ec4a56ddba396dba7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9152 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9155, 'ruRU', 'Неплохо, $N. Вот, держи. Было бы славно, если бы таких как ты, было побольше в этих краях.' FROM `quest_offer_reward` WHERE `ID`=9155 AND MD5(`RewardText`)='30e79361bfd5f149d4ffa54df342d11a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9155 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9156, 'ruRU', 'Ага... Лузран и Гнилоступ! Ну, что невеселый нынче у вас видок, а? Хотя краше вы, как вижу, не стали.\n\nВозьми себе награду из этих вещей на выбор, $N. Ты ее заслужила.' FROM `quest_offer_reward` WHERE `ID`=9156 AND MD5(`RewardText`)='2537e277b7d5d2ed67e3d9123d99cdbf' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9156 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9157, 'ruRU', 'Теперь, когда у нас снова есть эти медальоны, мы призовем Аквантиона. Этот мятежный элементаль заплатит за нашу смерть. Мы будем отомщены!' FROM `quest_offer_reward` WHERE `ID`=9157 AND MD5(`RewardText`)='74e934509737b16c018cd756d2eeec30' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9157 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9158, 'ruRU', 'Ты хорошо потрудилась, $N. Очень важно, чтобы зараза не перекинулась на здоровых животных Вечной Песни. Если ты ищешь, что бы еще сделать, то у меня всегда найдется для тебя работа.' FROM `quest_offer_reward` WHERE `ID`=9158 AND MD5(`RewardText`)='4afee224086e56105493ff11d5f6c0ec' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9158 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9159, 'ruRU', 'Ты серьезно подошла к решению задачи, и потому я хотела бы достойно наградить тебя. Побольше бы нам таких отважных и решительных союзников, $N.' FROM `quest_offer_reward` WHERE `ID`=9159 AND MD5(`RewardText`)='9a7079ed66cc327974c63cbee70349e2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9159 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9160, 'ruRU', 'Как жаль, что операция в Ан\'дароте не пролила свет на планы ночных эльфов! Однако меня заинтересовали эти предметы, похожие на магически выращенные деревья с наполненными силой шарами наверху! Возможно, нам следует более целенаправленно собирать информацию.\n\nВозьми эти деньги и эликсиры. Уверена, они тебе понадобятся очень скоро, особенно в наших делах с ночными эльфами.' FROM `quest_offer_reward` WHERE `ID`=9160 AND MD5(`RewardText`)='6d2ef0f7fc28d3ca7edc15f9ef3fdb94' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9160 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9161, 'ruRU', 'Перевернув несколько страниц этой древней книжицы, вы приходите к выводу, что некогда она принадлежала эльфу по имени Дар\'Кхан Дратир.' FROM `quest_offer_reward` WHERE `ID`=9161 AND MD5(`RewardText`)='68a3bc016fa408696a9f65456106341f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9161 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9162, 'ruRU', 'Это бесценная информация, $N. О том, что Дар\'Кхан намерен похитить силу Солнечного колодца ради блага Плети, мы знаем, но большинство найденной здесь информации – новость для нас. Магистр Каендрис из святилища Солнца захочет ознакомиться с этим дневником.' FROM `quest_offer_reward` WHERE `ID`=9162 AND MD5(`RewardText`)='41e60b9284439f20d777dc9d3e9a7401' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9162 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9163, 'ruRU', 'Очень тревожно! Из этих планов видно, что силы ночных эльфов сосредоточены не только в Ан\'дароте – это нам известно, – но и в Ан\'овине, более удаленном узле линии силы к юго-востоку отсюда.\n\nНа востоке есть еще третий узел, о котором здесь не упоминается, – Ан\'телас. У меня очень нехорошие предположения насчет всего этого, |3-6($C).' FROM `quest_offer_reward` WHERE `ID`=9163 AND MD5(`RewardText`)='88b24c7f58dc2c515ffe00927d404bea' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9163 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9164, 'ruRU', 'Замечательная работа, $N. Без твоей помощи эти несчастные утратили бы разум, и их душами завладела бы Плеть.' FROM `quest_offer_reward` WHERE `ID`=9164 AND MD5(`RewardText`)='c89b8c3190738ffac6350016d6ac9ccb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9164 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9165, 'ruRU', '<Командир Метц берёт приказ и подписывает его.>$B$BОтличная работа, $N. Прими это в знак нашей благодарности.' FROM `quest_offer_reward` WHERE `ID`=9165 AND MD5(`RewardText`)='80bc67f662df5ebc080b9ea3dea1faf3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9165 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9166, 'ruRU', 'Это ужасно! Ночные эльфы! Они создали здесь свой лунный кристалл с какой-то нечестивой целью, но я ускользнул от них и собрал отряд разведчиков и заклинателей из соседнего святилища Солнца. Мы перебили большинство их, и сейчас отряд выслеживает и истребляет оставшихся!\n\nЯ рад, что ты сейчас здесь, у меня для защиты осталась только пара разведчиков! Тут небезопасно!\n\nПодожди минуточку, я просмотрю эти планы и пойму, что затевают ночные эльфы.' FROM `quest_offer_reward` WHERE `ID`=9166 AND MD5(`RewardText`)='abadb0fc2263b69322324bee34b12e0f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9166 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9167, 'ruRU', 'Сегодня ты нанесла сокрушительный удар по господству Плети в этих краях.\n\nТеперь, когда гнусный предатель мертв, мы вернем себе наши земли, и величие наше будет восстановлено!' FROM `quest_offer_reward` WHERE `ID`=9167 AND MD5(`RewardText`)='b15c6bffb7e319b47fc90bd5fc6d895f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9167 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9169, 'ruRU', 'Какое облегчение, |3-6($C)! Знай, что если бы ты не отключила эти следящие шары, мы оказались бы в еще более тяжелом положении, чем сейчас! Подумай только – кругом враги, и один из них способен следить за каждым нашим шагом!\n\nНо теперь нам не надо об этом беспокоиться – и все благодаря тебе! Вот, возьми, я хочу вознаградить тебя за труды, а у меня тут как раз образовалось несколько вещиц, которые мне уже больше не понадобятся.\n\nЕще раз спасибо тебе, $N!' FROM `quest_offer_reward` WHERE `ID`=9169 AND MD5(`RewardText`)='a45cd92af68aa79f84511d5ef9d5a237' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9169 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9170, 'ruRU', 'Армии Дар\'Кхана скоро будут разгромлены. Плеть не выстоит против объединенной мощи син\'дорай и Отрекшихся.' FROM `quest_offer_reward` WHERE `ID`=9170 AND MD5(`RewardText`)='80b6a75469dcc6867bc2a6c8569e10e6' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9170 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9171, 'ruRU', 'Отлично, то что надо! Нет, не рассказывай мне про этих ползучих тварей, слушать не желаю! Я обращу свою магию на эти ножки, и они станут замечательно вкусными. Немножко специй, немножко травок-приправок и, конечно, щепоточку чар, и вот вам блюдо, достойное королевы! Или, в нашем случае, благородной дамы.\n\nТы сослужила мне хорошую службу, |3-6($C). Вот тебе в награду рецепт и кусочек на пробу.' FROM `quest_offer_reward` WHERE `ID`=9171 AND MD5(`RewardText`)='a86f3393ab57dc2136806e0a9895b109' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9171 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9172, 'ruRU', 'Эта книжица... быть того не может! Это почерк самого Дар\'Кхана. В ней должна быть информация, которая раскроет нам слабости нашего противника.\n\nХорошо, что ты пришла с ней к нам, $N. Странники проявили великую мудрость, передав эти записи нам. А вот этот доспех в грядущем пригодится тебе на службе нашему общему делу.' FROM `quest_offer_reward` WHERE `ID`=9172 AND MD5(`RewardText`)='bf75eb184b9357a44701bec2229fd9d0' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9172 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9173, 'ruRU', 'Уверен, что леди Сильвана будет довольна, узнав о наших успехах здесь.\n\nВозьми эту монету за труды.' FROM `quest_offer_reward` WHERE `ID`=9173 AND MD5(`RewardText`)='1f79f6d20a6d0f0c8450cdefcd305441' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9173 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9174, 'ruRU', 'Ты отомстила за нашу гибель и освободила наши души от власти Аквантиона. Наконец-то мы обретем покой.' FROM `quest_offer_reward` WHERE `ID`=9174 AND MD5(`RewardText`)='c6f17c21b1629b6e98504738acea2129' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9174 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9176, 'ruRU', 'Слухи были верны! Камень Света и камень Пламени и правда существуют! Мы сделаем из них оружие, которое обратим против Дар\'Кхана.\n\nВоспользуйся им, когда наступит срок, и сила Солнечного Колодца, заключенная в них, поразит предателя той самой силой, которую он хотел похитить у нас!' FROM `quest_offer_reward` WHERE `ID`=9176 AND MD5(`RewardText`)='90761fae12e5ca75817fd9f3368615d0' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9176 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9178, 'ruRU', 'Ага, они пригодятся для оружия.' FROM `quest_offer_reward` WHERE `ID`=9178 AND MD5(`RewardText`)='6408d4655f963e8d8a2a45b27600aad4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9178 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9179, 'ruRU', 'Больше брони для войска! Превосходно, $N!' FROM `quest_offer_reward` WHERE `ID`=9179 AND MD5(`RewardText`)='8e897d7549f5546f28b3cf9ed107b9c9' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9179 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9180, 'ruRU', 'Сильвана выхватывает у вас ожерелье.\n\nБыть того не может! Столько лет прошло... я думала, оно навсегда пропало...\n\nПосле долгого задумчивого молчания леди приходит в себя и берет себя в руки.\n\nТы думала, это меня обрадует? Думаешь, я вспоминаю те времена, когда не была владычицей Отрекшихся? Оно ничего для меня не значит, как, впрочем, и для тебя. И Аллерия Ветрокрылая давно мертва и позабыта!\n\nОна роняет амулет на землю.\n\nТеперь можешь удалиться, |3-6($C).' FROM `quest_offer_reward` WHERE `ID`=9180 AND MD5(`RewardText`)='5132f84fd6ac08c6625b9fd84ed8fa41' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9180 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9181, 'ruRU', 'Они должны прекрасно сочетаться с массивным грузилом.' FROM `quest_offer_reward` WHERE `ID`=9181 AND MD5(`RewardText`)='7b7b0d63b56c90464fe9f6a2cea842cc' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9181 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9182, 'ruRU', 'А они не столь велики, как я ожидал. Но, сделка есть сделка.' FROM `quest_offer_reward` WHERE `ID`=9182 AND MD5(`RewardText`)='972ebccc0463086c5109a54e79e10238' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9182 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9183, 'ruRU', 'Отлично. Они прекрасно подойдут для укрепления наших войск, против мерзкой Плети.' FROM `quest_offer_reward` WHERE `ID`=9183 AND MD5(`RewardText`)='691f5d2f96d78470627529c908a14e39' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9183 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9184, 'ruRU', 'То, что нужно.' FROM `quest_offer_reward` WHERE `ID`=9184 AND MD5(`RewardText`)='ebdd68e74910eaee7b903c4700a9f5bb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9184 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9186, 'ruRU', 'Хм, это действительно прекрасные ремни.' FROM `quest_offer_reward` WHERE `ID`=9186 AND MD5(`RewardText`)='232998b9dcaf35c698bb86a088962639' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9186 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9187, 'ruRU', 'Друиды по достоинству оценят эти штаны. Большое спасибо, $C.' FROM `quest_offer_reward` WHERE `ID`=9187 AND MD5(`RewardText`)='4e267f09e7b83c9007907afdf12c4da3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9187 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9189, 'ruRU', 'Посол Печаль Солнца явно рассчитывает, что твое возвышение пойдет на пользу син\'дорай. Впрочем, неудачно получилось с леди Сильваной. Не обращай внимания, $N, ты не напрасно вернула ей ожерелье. Ей бы спасибо тебе сказать, но таковы уж все правители.\n\nЕсли ты возьмешься помогать Отрекшимся в Гробнице – смотри, не распускайся. Ты ведь не хочешь испортить наши отношения с Ордой?' FROM `quest_offer_reward` WHERE `ID`=9189 AND MD5(`RewardText`)='25f2c38f3e2fddf907ebdc5403c19d16' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9189 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9190, 'ruRU', 'Клянусь бородой Бронзоборода! Ты и в самом деле $Gпринёс:принесла; рунические сапоги... Я думал, что никогда не увижу их.' FROM `quest_offer_reward` WHERE `ID`=9190 AND MD5(`RewardText`)='d6310cf6578c32d26db8af82ebdac68c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9190 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9192, 'ruRU', 'Славную кровавую баню ты учинила там, |3-6($C)! Теперь горняки вернутся к работе. Уверен, они будут разочарованы, что перекур кончился, но надо ковать оружие и доспехи, стало быть, добывать руду.\n\nВот, прими в награду за выполнение долга. Чини оружие и доспехи – и выпей за мое здоровье!' FROM `quest_offer_reward` WHERE `ID`=9192 AND MD5(`RewardText`)='f4fb8231c4879519b4c7a32a27acc882' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9192 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9195, 'ruRU', 'Отлично, $C. Это будет большой бум!' FROM `quest_offer_reward` WHERE `ID`=9195 AND MD5(`RewardText`)='50f8843ac7ff7b1b85ba7caf696f58c4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9195 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9197, 'ruRU', 'Почему ты улыбаешься? Что здесь смешного? Боевой цыпленок гномов очень важная единица! Мы посылаем их в зараженные районы, и они очищают их от разных чумных насекомых.' FROM `quest_offer_reward` WHERE `ID`=9197 AND MD5(`RewardText`)='74490449893f1d41977ee1df4a310ea8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9197 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9199, 'ruRU', 'Значит, мумий поднимают тролльские жрецы... умно! Видать, тролли Призрачной Сосны пытаются пополнить свои ряды при помощи некромантии. Готов поспорить, что эти оракулы использовали джуджу во время обряда воскрешения.\n\nТы еще раз подтвердила свою верность долгу, а чего еще ждать от |3-1($C) с такой репутацией? Прими это вместе с моей благодарностью!' FROM `quest_offer_reward` WHERE `ID`=9199 AND MD5(`RewardText`)='a4fafc5cf42d9c0f600c8e190273d2d0' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9199 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9203, 'ruRU', 'Без комментариев.$B$BЯ сказал без комментариев! А теперь, убирайся с глаз моих!' FROM `quest_offer_reward` WHERE `ID`=9203 AND MD5(`RewardText`)='8af11e1e80f102f6a08064dcb56ffe63' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9203 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9212, 'ruRU', 'Ты настоящая героиня, |3-6($C), раз сумела привести ее сюда в целости и сохранности! Полагаю, придется устроить рейд и зачистить еще и эти катакомбы. Можно подумать, нам не хватает проблем с живыми троллями!\n\nСегодня ты совершила великий подвиг, и я должен наградить тебя. Выбирай любой из этих предметов.' FROM `quest_offer_reward` WHERE `ID`=9212 AND MD5(`RewardText`)='fe015a392f9e9be31604cbc95d351445' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9212 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9214, 'ruRU', 'Тотчас же отправлю несколько следопытов оценить урон, нанесенный тобою троллям Призрачной Сосны. Если это оружие – действительно свидетельство твоего успеха, то не сомневаюсь, что после твоего подвига мы сотрем их с лица земли и вплотную займемся Плетью.\n\nВот, прими эти монеты за труды. У меня все равно карман дырявый.' FROM `quest_offer_reward` WHERE `ID`=9214 AND MD5(`RewardText`)='25ddda2573c9a7d8f6a4b4033189e71b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9214 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9216, 'ruRU', 'Возьми этот напиток, $N. Как только ты его выпьешь, твоя физическая сила в бою с Плетью усилится многократно. Если тебе понадобится еще порция напитка, принеси мне еще сердец.' FROM `quest_offer_reward` WHERE `ID`=9216 AND MD5(`RewardText`)='ab72ff52edf8eaf2de3e14f018e75a6c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9216 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9218, 'ruRU', 'Вот, возьми, $N. Разницу ты почувствуешь тотчас же!\n\nМожешь приносить еще – все пойдет в дело. Побочные эффекты? Ну, может, суставы немного поноют. Но ничего хронического, уверяю тебя!' FROM `quest_offer_reward` WHERE `ID`=9218 AND MD5(`RewardText`)='07f559f9bfb3b5b621032f08b973b363' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9218 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9220, 'ruRU', 'Плеть познала силу нашего гнева, $N! Скоро их проклятая цитадель превратится в руины!\n\nТеперь, когда их силы ослабли, пора ударить и по другим стратегическим точкам.' FROM `quest_offer_reward` WHERE `ID`=9220 AND MD5(`RewardText`)='1bfa48455ae706c632adfbb599316247' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9220 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9274, 'ruRU', 'Благодарю за помощь, $N.Мое сердце разрывалось на части от осознания того, что души моих предков не могут найти пристанище. Да обретут они, наконец, заслуженный покой.' FROM `quest_offer_reward` WHERE `ID`=9274 AND MD5(`RewardText`)='e143d702bf8415cfcbd5e137d1aac21e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9274 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9275, 'ruRU', 'О, блестяще! Я знал, что $R-курьер – самый эффективный способ доставки яда! Если нам повезет, то тролли Призрачной Сосны вскорости обожрутся и отдадут концы. И не будут больше сидеть бельмом на глазу у Странников, а я вернусь в Транквиллион.\n\nПриятно было работать с тобой, |3-6($C)!' FROM `quest_offer_reward` WHERE `ID`=9275 AND MD5(`RewardText`)='7c8d6030b42484b5d8db9042028f715c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9275 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9276, 'ruRU', 'Славно, славно! Ты прекрасно справилась с этим делом! Поищем теперь для тебя задачку потруднее.' FROM `quest_offer_reward` WHERE `ID`=9276 AND MD5(`RewardText`)='9350b8a3a377eeb9c1d756226e771e74' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9276 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9277, 'ruRU', 'Невероятно! Нет, тебе надо поговорить с нашим капитаном насчет вступления в ряды Странников.\n\nЛадно, $N, ты дала нам передышку, достаточную для того, чтобы собраться с силами в здешних краях. Благодаря тебе троллей тут почти не осталось! Может, теперь мы сможем объединиться с Транквиллионом и напасть на Смертхольм?\n\nДумаю, ты заслужила небольшую награду. Выбирай.' FROM `quest_offer_reward` WHERE `ID`=9277 AND MD5(`RewardText`)='1fe0015e145966de70a016cce4e7a045' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9277 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9279, 'ruRU', 'Клянусь бессмертной душой, я рад видеть тебя, $N! Не знаю, что стряслось с Экзодаром. Кажется, в живых остались лишь те, кто был в этой части корабля.$b$bЕсли мы хотим спасти других выживших, время у нас на исходе!' FROM `quest_offer_reward` WHERE `ID`=9279 AND MD5(`RewardText`)='dc29d43dff98f4454548ecb841b9f994' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9279 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9280, 'ruRU', 'Жаль, что приходится обменивать жизни этих существ на наши – подобная жестокость противна духу дренеев. Зато собранная кровь напитает исцеляющие кристаллы, так что совки погибли не зря.' FROM `quest_offer_reward` WHERE `ID`=9280 AND MD5(`RewardText`)='01bf0d2f9f90c52019dc49c94b6d92b1' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9280 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9281, 'ruRU', 'Спасибо за помощь, $N. Мне даже думать страшно было о том, чтобы отправиться в леса так близко от Смертхольма.' FROM `quest_offer_reward` WHERE `ID`=9281 AND MD5(`RewardText`)='9c09e5d3234a4d151f290d9d2b291831' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9281 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9293, 'ruRU', 'О, спасибо тебе, |3-6($c)!$b$bПока ты $gходил:ходила; за образцами, я ухитрилась собрать кое-какое оборудования для анализов. Подожди немного...' FROM `quest_offer_reward` WHERE `ID`=9293 AND MD5(`RewardText`)='438f2863c9548ee4047242a8def274f3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9293 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9303, 'ruRU', 'Большая часть совунов привита, и мы сможем сосредоточить усилия на том, чтобы выбраться отсюда, не беспокоясь об уничтожении совунов.$b$bВыбери, что тебе больше подходит. Хорошая работа заслуживает награды!' FROM `quest_offer_reward` WHERE `ID`=9303 AND MD5(`RewardText`)='d320d64485d4709ba004e2a78d195e8c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9303 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9305, 'ruRU', 'Дай-ка поглядеть.$b$bДа, эти части подойдут. Спасибо, $N. Передатчик – сложное устройство, так сходу его не починишь. Я сообщу тебе, когда закончу работу.$b$bПока что ты можешь заглянуть к воздаятелю Алдару, может, ему нужна твоя помощь.' FROM `quest_offer_reward` WHERE `ID`=9305 AND MD5(`RewardText`)='1b593be7a8a271407dbddeb325dd827c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9305 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9309, 'ruRU', 'Помоги... Эльфы крови! Я... попал в засаду. Мне... недолго осталось.' FROM `quest_offer_reward` WHERE `ID`=9309 AND MD5(`RewardText`)='f96e46c1222d94a39e117d5f2d5c867f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9309 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9313, 'ruRU', 'О, рад тебя видеть! Хорошо, что удалось починить оба излучателя, иначе бы нам не отыскать друг друга. Не беспокойся, мы позаботимся о том, чтобы в долину Аммен отправили побольше припасов и войск.$b$bКстати говоря, раз уж ты здесь, пойди, познакомься с другими обитателями форпоста. Дел здесь полно.' FROM `quest_offer_reward` WHERE `ID`=9313 AND MD5(`RewardText`)='2f1f9aba0a2481568068c8c1c1185686' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9313 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9314, 'ruRU', 'О, должно быть, ты $gодин:одна; из выживших, о которых в последнее время столько говорят!$b$bХорошо, что ты $gпришел:пришла;. Не беспокойся, мы отправим кого-нибудь на помощь Аэуну.$b$bЯ с радостью послушаю, как умудрились выжить дренеи в соседней долине! Ты $gхрабрец:смелая женщина;, раз $gрешился:решилась; пойти сюда.' FROM `quest_offer_reward` WHERE `ID`=9314 AND MD5(`RewardText`)='fc1b3ecce9a554cd37981fa08ef79ef1' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9314 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9315, 'ruRU', 'Прости за неточные разведданные, |3-6($C). Знай я раньше об этой Анок\'сутен, то непременно тебе сказал бы.\n\nНас тут слишком мало, и многое просто проскальзывает меж пальцев!' FROM `quest_offer_reward` WHERE `ID`=9315 AND MD5(`RewardText`)='21f02c99d13a6aedb6986e7a15ed74fc' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9315 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9327, 'ruRU', 'Я знаю, что для тебя выглядим чудовищами, но уверяю, мы не хотим зла вашему народу. У нас общий враг – предатель Дар\'Кхан! Он вернулся и ныне командует Плетью, чьи полчища вторглись в эти края из его логова, Смертхольма, что на юге.\n\nНаша предводительница, Леди Сильвана Ветрокрылая, родом из этих мест, а при жизни она была эльфом! У Дар\'Кхана перед ней должок, и она жаждет его смерти не меньше, чем вы.\n\nВместе мы разобьем его, |3-6($C)!' FROM `quest_offer_reward` WHERE `ID`=9327 AND MD5(`RewardText`)='2a2e0625268af07aeaff10147ab8e054' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9327 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9328, 'ruRU', 'М-да... Не ожидал увидеть это лицо так скоро.\n\nЧто ж, ты принесла мне весьма радостную весть, $N.' FROM `quest_offer_reward` WHERE `ID`=9328 AND MD5(`RewardText`)='5f2321809495de1ff1c5ef6c0e0e5224' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9328 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9329, 'ruRU', 'Мы, Отрекшиеся, потому здесь, что у нас с вами общий враг – Дар\'Кхан! Он вернулся и ныне командует Плетью, чьи полчища вторглись в эти края из его логова, Смертхольма, что на юге.\n\nНаша предводительница, Сильвана Ветрокрылая, родом из этих мест, при жизни она была эльфом! У Дар\'Кхана перед ней должок, и она жаждет его смерти не меньше, чем вы.\n\nВместе мы разобьем его, $C!' FROM `quest_offer_reward` WHERE `ID`=9329 AND MD5(`RewardText`)='87898f3eb09d812c1bffc1ba1711b286' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9329 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9340, 'ruRU', 'Неплохо, $N. Это научит камнедеров держаться от нас подальше.' FROM `quest_offer_reward` WHERE `ID`=9340 AND MD5(`RewardText`)='f26294e4eb519813999b3aa597eefbd5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9340 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9345, 'ruRU', 'Это должно помочь. Сейчас я приготовлю мазь, а затем наложу шину. В таком виде кое-как до Траллмара доковыляю. Могу представить, что скажет провозвестница Регулкут, когда меня увидит.\n\nГрелаг тяжело вздыхает.\n\nСпасибо тебе за помощь, $N У меня осталось несколько листьев гребнелиста, возьми с собой, если хочешь. Как знать, может, и пригодятся.' FROM `quest_offer_reward` WHERE `ID`=9345 AND MD5(`RewardText`)='7ab88106db62da0baf0b2ea85bd5ab87' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9345 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9349, 'ruRU', 'Чтобы блюдо было отменным, его надо готовить из отменных продуктов! Эти яйца прекрасны.$B$BСейчас я дочищу свою сковородку, и можешь присоединяться к трапезе!' FROM `quest_offer_reward` WHERE `ID`=9349 AND MD5(`RewardText`)='c0bb7ccc7a0b96806d2fcebec9fabdc4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9349 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9351, 'ruRU', 'Отлично! Вот это мощь! Мне придется усовершенствовать двигатель, чтобы воспользоваться всеми преимуществами этой штуки. Если... в смысле, когда мы отсюда выберемся, в Зоне 52 ахнут, увидев, что я придумал!' FROM `quest_offer_reward` WHERE `ID`=9351 AND MD5(`RewardText`)='670e0dcf219be70ac7927ee4e258dfb6' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9351 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9356, 'ruRU', 'Яйца опустошителей. Раз!$B$BБекон зловепря. Два!$B$BКрылья канюка. Три!$B$BОтличное меню. Ты обязательно $gдолжен:должна; это попробовать.' FROM `quest_offer_reward` WHERE `ID`=9356 AND MD5(`RewardText`)='78a2372bef44c9802a99d25b73ba70e7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9356 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9361, 'ruRU', 'Хм...$B$BВыглядит съедобным, если проперчить хорошенько. Лучше не будем говорить Скриду, откуда взялся его завтрак, ладно?' FROM `quest_offer_reward` WHERE `ID`=9361 AND MD5(`RewardText`)='6dc9de19a3686bb9aa5044c73da95074' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9361 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9363, 'ruRU', 'Ты принесла очень важные сведения, $N. Теперь, когда мы знаем о планах троллей, мы будем готовы к нападению.\n\nНас не застанут врасплох!' FROM `quest_offer_reward` WHERE `ID`=9363 AND MD5(`RewardText`)='de3c5e68776a6f6671e816037db14245' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9363 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9366, 'ruRU', 'В этих образцах содержится неимоверная энергия, $N. Нам необходимо наладить постоянную и беспрепятственную доставку оскверненной крови.' FROM `quest_offer_reward` WHERE `ID`=9366 AND MD5(`RewardText`)='037fddbfb6a2bd2d2350c256dc5ba8d2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9366 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9370, 'ruRU', 'Пусть эти святые фанатики не лезут не в свое дело.' FROM `quest_offer_reward` WHERE `ID`=9370 AND MD5(`RewardText`)='6e3590f644e6840110038464529e37fd' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9370 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9371, 'ruRU', 'О, слава Небу, что ты здесь. У нас очень много работы.' FROM `quest_offer_reward` WHERE `ID`=9371 AND MD5(`RewardText`)='fed3d3fd549a190831514e14e90d54ac' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9371 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9373, 'ruRU', 'Спасибо, что принес мне эту вещь, $C. Я-то думала, почему так долго нет вестей от Экспедиции. Хотела бы я знать, как давно было отправлено это послание и что случилось с его курьером.$B$BВозьми за труды немного денег.' FROM `quest_offer_reward` WHERE `ID`=9373 AND MD5(`RewardText`)='f688b2c20edbde189371a563d4640585' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9373 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9374, 'ruRU', 'Журнал моего мужа... Да там нет ни слова о научных изысканиях!\n\nКак я могла быть такой идиоткой?"Магические свойства оскверненного ила..."Да он просто пудрил мне мозги!' FROM `quest_offer_reward` WHERE `ID`=9374 AND MD5(`RewardText`)='5c1abac5c3dcec74d6a5823ae700cabf' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9374 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9375, 'ruRU', 'Талерис рявкает, обращаясь к эльфам крови на заставе \n\nЗанесите ее внутрь и перевяжите!\n\n Затем снова обращается к вам \n\nЕй повезло, что ты нашла ее, $C. Я думаю, она недолго бы протянула. \n\nТы поняла, о чем она говорила?' FROM `quest_offer_reward` WHERE `ID`=9375 AND MD5(`RewardText`)='ccf0a14d481345e5038279eff060b3eb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9375 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9376, 'ruRU', 'Спасибо, что вернула сумки, $N. Не знаю, что там такого важного, но она не подпускала к себе никого, пока не получила свои вещи обратно.' FROM `quest_offer_reward` WHERE `ID`=9376 AND MD5(`RewardText`)='e971c37b9ed49fd8c35e8c961c6a0f21' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9376 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9381, 'ruRU', 'Да, это подойдет. Нашем следопытам давно не хватает стрел, так что одной головной болью стало меньше. Спасибо за помощь, $C.' FROM `quest_offer_reward` WHERE `ID`=9381 AND MD5(`RewardText`)='5200812ac211cb8e556c1ed352e8e450' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9381 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9387, 'ruRU', 'Ты оказала мне большую услугу, $N. А теперь посмотрим, что скажет наш синий друг.' FROM `quest_offer_reward` WHERE `ID`=9387 AND MD5(`RewardText`)='9a9d98612d99f54d45a97e5262b073ae' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9387 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9390, 'ruRU', 'Вы находите тело юного дренейского паладина. Он убит стрелой в спину.' FROM `quest_offer_reward` WHERE `ID`=9390 AND MD5(`RewardText`)='e62e4dce4b841e8d4278effafa656d63' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9390 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9391, 'ruRU', 'Глубокий Разлом все еще опасен, но, по крайней мере, там можно пройти.\n\nЕсли бы Альянс не караулил все известные нам дороги, вряд ли бы мы решили на такое дело.' FROM `quest_offer_reward` WHERE `ID`=9391 AND MD5(`RewardText`)='7ec2b86b202eaafbc2ec607678946c8a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9391 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9392, 'ruRU', 'Твое имя прошептали мне тени, $N. Говорят, ты ищешь опытного наставника, который покажет тебе что к чему, – то есть кого-то вроде меня. Что же, я могу тебе помочь, но это будет тебе стоить небольшого процента со всей добычи каждый раз, как я буду чему-нибудь тебя учить. Да, я расскажу тебе, что значит быть разбойником.\n\nНо запомни: если тебя уличат в воровстве, ты меня не знаешь. А теперь иди сюда и покажи, из какого теста ты сделана!' FROM `quest_offer_reward` WHERE `ID`=9392 AND MD5(`RewardText`)='e994e0e5deb17fc0a751af43fae1209c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9392 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9394, 'ruRU', 'Кто ты? Ты не из учеников магистра, это точно!\n\nТебя прислали помочь мне ликвидировать все это безобразие?' FROM `quest_offer_reward` WHERE `ID`=9394 AND MD5(`RewardText`)='5051ae7bd196caa9f8d170f1020d338e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9394 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9396, 'ruRU', 'Неплохо сработано, $N. Запределью не удасться утаить от нас свои секреты.\n\nНаше призвание – стать хозяевами этого мира!' FROM `quest_offer_reward` WHERE `ID`=9396 AND MD5(`RewardText`)='236c78ad8e744c58e176bd7af820f109' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9396 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9397, 'ruRU', 'Вот она! Настоящая юная самка калири!\n\nКакая она хорошенькая! Спасибо тебе, $N.' FROM `quest_offer_reward` WHERE `ID`=9397 AND MD5(`RewardText`)='e724ffca118cb345f824af178d7687ab' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9397 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9407, 'ruRU', 'Наша экспедиция благополучно прошла через портал и основала новую базу, именуемую Траллмар. Но, как ты видишь, Пылающий Легион своим вторжением отрезал нас от наших собратьев. Любому понятно, что демоны надеются отбить Темный портал и не позволить нам получить подкрепление с Азерота.' FROM `quest_offer_reward` WHERE `ID`=9407 AND MD5(`RewardText`)='b3dc5bc590c50fc697c808edaa3ff943' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9407 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9409, 'ruRU', 'Отличная работа! Эта кровь прекрасно подойдет для наших исцеляющих кристаллов.$b$bРаз уж ты здесь, у меня найдется для тебя поручение. Ты не против?' FROM `quest_offer_reward` WHERE `ID`=9409 AND MD5(`RewardText`)='21e5e35b061d1a8e8a7c1576f1a9e11b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9409 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9418, 'ruRU', 'Эта сфера вернула мне свободу. Вот твоя награда, $gсмертный:смертная;. Я всегда расплачиваюсь с долгами.' FROM `quest_offer_reward` WHERE `ID`=9418 AND MD5(`RewardText`)='f362ba927ac7707887d26a2a8e26eab2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9418 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9420, 'ruRU', 'Ты $gвыполнил:выполнила; свою часть сделки. Дело есть дело!$B$BВозьми, $gдружище:подруга;. Заботься о ней как следует.' FROM `quest_offer_reward` WHERE `ID`=9420 AND MD5(`RewardText`)='e4e5f5d8f853894d209acb15e92373d6' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9420 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9424, 'ruRU', 'Да... Месть! Ты $gпоступил:поступила; как должно.$B$BВозьми это. Теперь оно приносит Макуру только горе...' FROM `quest_offer_reward` WHERE `ID`=9424 AND MD5(`RewardText`)='556864c49475fac6b1ce08779837c61a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9424 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9429, 'ruRU', 'Приветствую вас, $C. Хотелось бы верить, что путешествие ваше обошлось без неожиданностей?$B$BЭти несчастные со всех сторон окружены исчадиями ночи. Мы хотим, чтобы вы оказали им посильную помощь и разогнали тьму.$B$BПобродите по городу, познакомьтесь с его жителями. Пожалуйста, $N, помогите им, чем сможете.' FROM `quest_offer_reward` WHERE `ID`=9429 AND MD5(`RewardText`)='0d7926ddc27be47e8185bba0e9269068' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9429 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9430, 'ruRU', 'Тебе сопутствовала удача. Как я и надеялся, мы нашли то, что искали.' FROM `quest_offer_reward` WHERE `ID`=9430 AND MD5(`RewardText`)='881b06d4fc8989c79b89e9933f54760e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9430 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9431, 'ruRU', 'Что? Она не сказала про лунный колодец? Так ведь у нее именно это и было на уме. Признаться, все это выглядит немного странно, но не буду же я в здравом уме лишаться клиента! Тем более – единственного.\n\nКонечно, я бы не сказал, что это очень благоразумно – лезть в поселок ночных эльфов и воровать воду из их колодца, но раз она за это платит, то стоит попробовать.' FROM `quest_offer_reward` WHERE `ID`=9431 AND MD5(`RewardText`)='8387fa0794ab640d9801a5c0917ab9e3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9431 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9432, 'ruRU', 'Всегда приятно увидеть почти знакомое лицо. Наверное, ты $N. Эмиссар Валастраа сообщила мне, что ты скоро будешь.$B$BНароду Ясеневого леса нужна наша поддержка, $C. Поговори с жителями Астранаара и узнай, какая помощь им нужна.' FROM `quest_offer_reward` WHERE `ID`=9432 AND MD5(`RewardText`)='8162cafe760daaa9363e6fc6f4beecdf' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9432 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9433, 'ruRU', 'Все вышло даже лучше, чем я хотел! Запиши за гоблинами еще одно гениальное изобретение!\n\nЕдинственная проблема в том, что оно безнадежно покрыто пылью. У меня вся жизнь уйдет на то, чтобы его отчистить и вернуть на место.\n\nХотя чего-чего, а времени у меня хватает.' FROM `quest_offer_reward` WHERE `ID`=9433 AND MD5(`RewardText`)='afb6cbf9690fc84485fbfa0cdaf25470' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9433 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9434, 'ruRU', 'Замечательно, все на месте. Осталось только перемешать и посмотреть, что выйдет. Если этот тоник сработает так, как я предполагаю, то, возможно, я смогу ослабить зависимость от магии у моего народа.\n\nСмотри, $N, на твоих глазах вершится история! Подумать только – без твоей помощи у меня ничего бы не вышло!' FROM `quest_offer_reward` WHERE `ID`=9434 AND MD5(`RewardText`)='e99d55610577150c81f93a302389173b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9434 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9438, 'ruRU', 'Вы видите, что напряжение уходит с лица Тралла по мере того, как он читает донесение Назгрела  \n\nМой народ... Мы должны отправиться к ним. Мы должны отпавиться в Награнд как можно скорее!' FROM `quest_offer_reward` WHERE `ID`=9438 AND MD5(`RewardText`)='c45b4e65eac882e8f8d668d6fae4429f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9438 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9440, 'ruRU', 'Прекрасно! Жду не дождусь, когда смогу оценить эффект от последней партии!\n\nТы все сделал замечательно, прелесть моя. Я бы дала тебе и больше за то развлечение, которое ты мне устроил, но ты же знаешь, здесь на болотах денег днем с огнем не найти.\n\nНо я уверена, что забава того стоит!' FROM `quest_offer_reward` WHERE `ID`=9440 AND MD5(`RewardText`)='03462af899555b8a0cd3a40482bf06b6' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9440 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9453, 'ruRU', 'Бедная Диктинна... Мурлок ее сильно напугал.$B$B Актеон вздыхает. $B$BНадеюсь, она скоро оправится от ран...$B$BПолагаю, ты ищешь работу. Чего-чего, а этого на Лазурной заставе хватает!' FROM `quest_offer_reward` WHERE `ID`=9453 AND MD5(`RewardText`)='211f322f3b25b064ed8aee78bd4e1dc0' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9453 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9454, 'ruRU', 'Молодец, $n, молодец!$B$BПока ты $Gохотился:охотилась;, я приготовил тебе немного вырезки. Может, ты и от рецепта не откажешься?' FROM `quest_offer_reward` WHERE `ID`=9454 AND MD5(`RewardText`)='9de5a9e3699b4bacc3b9d23e9a7fd230' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9454 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9455, 'ruRU', 'Как такая вещь могла оказаться в желудке ночного ловца? Не заражены ли и другие звери осколками от разбившегося корабля?' FROM `quest_offer_reward` WHERE `ID`=9455 AND MD5(`RewardText`)='2ef49a18a3b083f598401b5badd4c4da' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9455 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9456, 'ruRU', 'Надеюсь, еще не поздно...' FROM `quest_offer_reward` WHERE `ID`=9456 AND MD5(`RewardText`)='7d6582810c4e09689ca54f8c32325846' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9456 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9463, 'ruRU', 'Будем надеяться, что мазь укрепит ее дух и поможет больной встать на ноги!' FROM `quest_offer_reward` WHERE `ID`=9463 AND MD5(`RewardText`)='d9765b3bb9a47753e381d208a113ca69' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9463 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9466, 'ruRU', 'Ты достойный, $C, $N. Эта тварь унесла жизни многих охотников.\n\nВозьми награду, ты ее заслужил.' FROM `quest_offer_reward` WHERE `ID`=9466 AND MD5(`RewardText`)='2f5b34e5972360913c38f4ff76b5a144' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9466 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9469, 'ruRU', 'В дневнике Пероборода очень много записей. Вы пролистываете его до конца и ищете в тексте информацию о том, где может быть хозяин.' FROM `quest_offer_reward` WHERE `ID`=9469 AND MD5(`RewardText`)='783f96b0423c1e2130569f47de557360' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9469 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9470, 'ruRU', 'Большое спасибо, $N. Дворфы Громового Молота будут рады узнать, что противостоят троллям племени Сухокожих не в одиночку. Пусть тролли знают, что на нашей стороне грифоны – глядишь, наглость свою и поумерят.' FROM `quest_offer_reward` WHERE `ID`=9470 AND MD5(`RewardText`)='b52d2764919e7ff24cdc2b7c22600f6b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9470 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9471, 'ruRU', 'Посол Руалет кивает и берет у вас отчет $B$BВы отлично справились. Клан Громового Молота обязательно узнает о том, что поголовье среброгривов уменьшилось. Когда я встречусь с их предводителями, я непременно прослежу за тем, чтобы ваши старания не прошли незамеченными перед Альянсом. Пожалуйста, примите это в знак моей благодарности, $N.' FROM `quest_offer_reward` WHERE `ID`=9471 AND MD5(`RewardText`)='d10cb49b1170f072ca3314941fd5e2d1' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9471 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9472, 'ruRU', 'Отлично! Теперь эта предательница больше никогда не соблазнит ничьего мужа.\n\nВот, возьми за труды. Надеюсь, все останется между нами, $N.' FROM `quest_offer_reward` WHERE `ID`=9472 AND MD5(`RewardText`)='c1d366000499a96a74d5203bcdc5739f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9472 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9473, 'ruRU', 'Смотри, как растение исцеляет больную.' FROM `quest_offer_reward` WHERE `ID`=9473 AND MD5(`RewardText`)='f693535692063560f73387a6ae48ef80' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9473 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9474, 'ruRU', 'Спасибо, |3-6($C)! Возвращение реликвии – большая радость для всех, кто чтит память Утера Светоносного.' FROM `quest_offer_reward` WHERE `ID`=9474 AND MD5(`RewardText`)='a22cb64eccc54bbfb9712091a027660d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9474 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9475, 'ruRU', 'Вы отдаете послу яйца и рассказываете о том, что обнаружили в лачуге Пероборода и в Шадра\'Алор $B$BТролли Сухокожих убили Пероборода?$B$B Риалет приходит в ужас, услышав об ужасной смерти дворфа и о ее последствиях $B$BЯ понимаю, почему он пошел искать яйца сам, но лучше бы он привел с собой подмогу. Вне всяких сомнений, его смерть приведет Фалстада Громового Молота в ярость, и моя аудиенция будет вновь отложена на неопределенный срок.' FROM `quest_offer_reward` WHERE `ID`=9475 AND MD5(`RewardText`)='618b4b75c6061118b24a4c6cd29ca64a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9475 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9476, 'ruRU', 'На алтаре лежит куча костей, с виду принадлежавших дворфу. Никаких особых примет не видно, но вы решаете осмотреть тело и убедиться в том, что это и впрямь останки Пероборода.' FROM `quest_offer_reward` WHERE `ID`=9476 AND MD5(`RewardText`)='fc5db717c2b8c3f8526983752b46608d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9476 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9505, 'ruRU', 'Ты говоришь, что найдена одна из наших? И что она ранена? Я немедленно пошлю в вашу деревню одного из своих воинов.' FROM `quest_offer_reward` WHERE `ID`=9505 AND MD5(`RewardText`)='3d67f62de51d664b2459c8a89b0eebd7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9505 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9506, 'ruRU', 'С такими способностями ты далеко пойдешь! При помощи навигационных приборов мы сможем определить, далеко ли отклонились от курса.$B$BВпрочем, стой, что это? В карту что-то завернуто. Посмотрим…$B$BЭто приказы Могула Раздунка из Торговой компании. Согласно этим планам они должны собрать на острове все кристаллы и похитить наши корабли.$B$BКлянусь кустистыми бровями Бронзоборода! Вот зачем нас заставили причалить! Но как они узнали о наших планах?!$B$BЭто предательство...' FROM `quest_offer_reward` WHERE `ID`=9506 AND MD5(`RewardText`)='3d417ce8c795e0cab72e54e83522f282' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9506 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9513, 'ruRU', 'Хвала Элуне! Неприкаянные души теперь могут обрести покой.' FROM `quest_offer_reward` WHERE `ID`=9513 AND MD5(`RewardText`)='248876c6de086bcfb20f7e6f6615e468' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9513 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9514, 'ruRU', 'Нет, я не могу прочесть эти руны, но я знаю, кто может...' FROM `quest_offer_reward` WHERE `ID`=9514 AND MD5(`RewardText`)='de38b64c349ce072ba3e9ed9d1adcf96' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9514 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9516, 'ruRU', 'Примите мое почтение и благодарность, $C. Может быть, нам все же удастся построить здесь новый дом, не страшась больше Пылающего Легиона.' FROM `quest_offer_reward` WHERE `ID`=9516 AND MD5(`RewardText`)='025c0cb1ed5aa4855b25457365741516' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9516 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9517, 'ruRU', 'Дерево, поваленное орочьими грубыми клинками, изуродовано так, словно его ураганом повалило. Из него ничего путного не построишь, но я очищу его от порчи и верну архитектору Немосу и его работникам. Хоть какое-то добро выйдет из этого лиха, в конце концов.' FROM `quest_offer_reward` WHERE `ID`=9517 AND MD5(`RewardText`)='daba08fc9095c91431e44b9b7e7c3a95' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9517 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9518, 'ruRU', 'Наконец-то мы преподали оркам урок, который они не осмелятся проигнорировать. Любой мастер или старшина, который сунется на лесозаготовки и заменит Гортака, на собственной шкуре испытает мой гнев!$B$BМы должны развить успех, $N, и не останавливаться, пока от лесозаготовок Песни Войны не останутся лишь смутные воспоминания, а на их месте не поднимется роща.' FROM `quest_offer_reward` WHERE `ID`=9518 AND MD5(`RewardText`)='3b7fba417c1ae44dca5b1bd90af34bab' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9518 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9519, 'ruRU', 'Прекрасная работа, $N. В этой чаше определенно есть скрытая сила, которую не смогла уничтожить даже скверна сатиров! Видишь, как ярко она сияет, хотя столько лет прошло?' FROM `quest_offer_reward` WHERE `ID`=9519 AND MD5(`RewardText`)='f7664eefd94f68b2ae5b765ce850d8bc' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9519 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9520, 'ruRU', 'Клянусь Семью Кристаллами Ата\'мала, этого не может быть! Они хотят напасть на нас здесь, в Лесной Песне?!$B$BНе будет этого, доколе я жив!$B$B<Воздаятель Ведаар сминает в кулаке пергамент с демоническими планами.>$B$BНет. Мы этого не допустим!' FROM `quest_offer_reward` WHERE `ID`=9520 AND MD5(`RewardText`)='9a1849597426d2988eacfc07ea8b912c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9520 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9521, 'ruRU', 'Благодарю за доставку этого донесения, $C. Из того, что пишет часовой Люсьель, видно, что оправдываются наши худшие опасения. С каждым нашим очередным успехом Орда все решительнее пытается нанести нам как можно больше урона.$B$BМы не можем позволить себе отступить. Судьба земель наших предков стоит на кону. Но если на границе будет больше таких, как ты, мы точно победим. Будешь ли ты биться вместе с нами?' FROM `quest_offer_reward` WHERE `ID`=9521 AND MD5(`RewardText`)='c6d28c691711f24b0ec90799b4db7d02' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9521 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9522, 'ruRU', 'Никогда более Пылающий Легион не потревожит нас в этих местах! Вы избавили нас от битвы, которую мы наверняка проиграли бы, $C.$B$BЯ приношу вам благодарность и глубочайшее уважение от лица Длани Аргуса. Для меня большая честь, что вы сражаетесь на нашей стороне.' FROM `quest_offer_reward` WHERE `ID`=9522 AND MD5(`RewardText`)='5bf741eba75ec7d6b6c77a3dd385f0bb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9522 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9526, 'ruRU', 'Добро. Хотя много твоих годов утечет прежде, чем эти саженцы превратятся в Древних, но со временем они помогут нам в борьбе против демонов на Холме Демонического Огня.$B$BСтупай же с миром, младший брат.' FROM `quest_offer_reward` WHERE `ID`=9526 AND MD5(`RewardText`)='9ce846a02f874306bc3734cbb5c117e6' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9526 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9533, 'ruRU', 'Радостно видеть нового гостя в Лесной Песни.$B$BПоборница Паланаар присылает на помощь столько народу, сколько может, и мы рады каждой паре рук.$B$BПосмотрите вокруг, $C. Может, сейчас вид не слишком впечатляет, но пройдет время, и при помощи наших союзников ночных эльфов мы построим здесь поселение, которое будет достойно называться домом. Сделать предстоит очень много, и любую помощь мы примем с радостью.' FROM `quest_offer_reward` WHERE `ID`=9533 AND MD5(`RewardText`)='b12729f196ba5db61913914390962f5f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9533 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9534, 'ruRU', 'Это куда лучше! Нет ничего достойнее, чем очищать наш мир от демонов. Да и противники они стоящие, не то что эти дохляки из Альянса.' FROM `quest_offer_reward` WHERE `ID`=9534 AND MD5(`RewardText`)='8a0b7876445fea06de6f5adc02e7dcb8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9534 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9535, 'ruRU', 'Повелители Ужаса! Они хотят напасть на нашу заставу Расщепленного Дерева?!\n\nПока жива – не допущу!\n\n<Валуша сминает в кулаке пергамент с планами демонов.>\n\nНет. Они не пройдут! Они – погибель для нашего мира!' FROM `quest_offer_reward` WHERE `ID`=9535 AND MD5(`RewardText`)='6f7faecda77e2f1385b4c29e243accd8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9535 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9536, 'ruRU', 'Никогда больше Пылающему Легиону не поработить ни орков, ни какую другую расу Орды!\n\nТы отважный боец, |3-6($C)! В груди твоей бьется сердце истинного сына Орды! Мы гордимся тобой!' FROM `quest_offer_reward` WHERE `ID`=9536 AND MD5(`RewardText`)='83ef33042d11e31cc412c9e8d2b92b56' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9536 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9537, 'ruRU', 'Немыслимо! Мы имеем дело с колоссальным заговором!$B$BОб этом должен узнать король и ваши вожди. Последствия могут быть ужасны.' FROM `quest_offer_reward` WHERE `ID`=9537 AND MD5(`RewardText`)='c3cd1fe41aa7d8549cfefc093eb7610b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9537 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9538, 'ruRU', 'На тотеме вырезано множество примитивных рисунков: совы, медведи, волки и олени.$B$BВам бросается в глаза странный набор символов, и губы сами собой произносят: "А-К-И-Д-А".' FROM `quest_offer_reward` WHERE `ID`=9538 AND MD5(`RewardText`)='969ed5cf8368ff031401059c615b9fc3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9538 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9539, 'ruRU', 'На тотеме вырезано множество примитивных рисунков: совы, медведи, волки и олени.$B$BВам бросается в глаза странный набор символов, и губы сами собой произносят: "КУ".' FROM `quest_offer_reward` WHERE `ID`=9539 AND MD5(`RewardText`)='dcbae92f449ff0de602a9cf47e60f0ce' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9539 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9540, 'ruRU', 'На тотеме вырезано множество примитивных рисунков: совы, медведи, волки и олени.$B$BВам бросается в глаза странный набор символов, и губы сами собой произносят: "Т-И-К-Т-И".' FROM `quest_offer_reward` WHERE `ID`=9540 AND MD5(`RewardText`)='62ab4247c7be7d8bceaac21b15d72eeb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9540 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9541, 'ruRU', 'На тотеме вырезано множество примитивных рисунков: совы, медведи, волки и олени.$B$BВам бросается в глаза странный набор символов, и губы сами собой произносят: "Й-О-Р".' FROM `quest_offer_reward` WHERE `ID`=9541 AND MD5(`RewardText`)='ee357bfde0dcc65b4cbe602e81ce37f9' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9541 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9542, 'ruRU', 'Вы читаете надпись на тотеме, и губы сами собой произносят: "В-А-Р-К".' FROM `quest_offer_reward` WHERE `ID`=9542 AND MD5(`RewardText`)='647a4792b2f2a186942fca11d8ea53bd' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9542 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9544, 'ruRU', 'Говорит по-фурболгски  Пророчество гласило, что явится Избранный, который избавит нас от смертельной хватки Косолапов, и сами духи возвестят прибытие этого героя.$B$BИ вот ты здесь.$B$BПреклоняюсь пред тобой, о $gВеликий:Великая;.' FROM `quest_offer_reward` WHERE `ID`=9544 AND MD5(`RewardText`)='66066965846293744776a2969a6381a9' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9544 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9545, 'ruRU', 'Надеюсь, что видение, представшее твоим глазам, помогло понять, что случилось в результате смерти Седаи. Реликвия показала тебе ряд событий, которые могли бы привести к тому, что сейчас происходит. Правда может быть разной, и ее никогда нельзя знать точно.$B$BИзменился ли твой образ мысли теперь, когда ты обладешь этим знанием?$B$BКто может сказать, продолжатся ли наши распри с орками? Важно оставаться открытым для всех возможностей.' FROM `quest_offer_reward` WHERE `ID`=9545 AND MD5(`RewardText`)='845baa73e3075bdc3cb6dec7891718c3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9545 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9550, 'ruRU', 'При внимательном рассмотрении выясняется, что найденная книга представляет собой дневник. Записи в нем сделаны изящным почерком, сильно отличающимся от почерка картографа. Впрочем, картограф отметился и здесь: на многих страницах нельзя разобрать первоначальный текст – поверх него сделаны какие-то наброски и записи.$B$BВозможно, изначально рукопись действительно содержала ценные сведения, но сейчас прочесть удается только рассказ картографа о каком-то пьяном загуле в порту.' FROM `quest_offer_reward` WHERE `ID`=9550 AND MD5(`RewardText`)='3150dd940252d4452084f4939cbf6cfd' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9550 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9557, 'ruRU', 'Хмм... Непростая задача. Да, вероятно, я сумею выяснить, что же написал на этих страницах первый автор.$B$BСначала мне нужно взять все необходимое для расшифровки. Это не займет много времени...' FROM `quest_offer_reward` WHERE `ID`=9557 AND MD5(`RewardText`)='64eb49832c1b26106b36017dc177105b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9557 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9558, 'ruRU', 'Как ты нас $gнашел:нашла;, |3-6($c)? Впрочем, не важно, наверное, тебя прислали нам на помощь. Ну тогда давай за работу!' FROM `quest_offer_reward` WHERE `ID`=9558 AND MD5(`RewardText`)='8caebf83465ea8b73fb70fdc9e659470' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9558 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9559, 'ruRU', 'Много сотен лет мы жили в относительном мире с прочими обитателями этих земель. Несколько месяцев назад Курц увидел грозные предзнаменования. Долгий мир подошел к концу. Но мы и не представляли, насколько серьезны будут последствия катастрофы!$B$BКажется, будто сами боги принесли раздор в наши края: против нас выступили и враги, и друзья. Но пророчество говорит и о другом... Среди всеобщего хаоса нам явится герой – герой не нашей крови. Избранный спасет нас от гибели.$B$BЭтот герой – ты.' FROM `quest_offer_reward` WHERE `ID`=9559 AND MD5(`RewardText`)='0394df75161c779cd77285c8da623f0e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9559 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9560, 'ruRU', 'Пророчество воистину сбылось, а доспехи получились великолепные! В самый раз для защитника! Я продам их тебе со скидкой, о $gБезволосый:Безволосая;.$B$BШутка... Первый доспех – в подарок.' FROM `quest_offer_reward` WHERE `ID`=9560 AND MD5(`RewardText`)='5afdf12a2e9e23aca6029e3ee2868853' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9560 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9561, 'ruRU', 'Земляной холмик, явно искусственного происхождения, зарос травами и кустарником.$B$BЧерез несколько минут из-под слоя земли появляется старый ящик. Вероятно, это именно то, о чем говорилось в записях Нолкаи.' FROM `quest_offer_reward` WHERE `ID`=9561 AND MD5(`RewardText`)='b2051406ddd02904d9ecd44012977156' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9561 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9562, 'ruRU', 'М... Вкусное зерно... Паркат будет в восторге!' FROM `quest_offer_reward` WHERE `ID`=9562 AND MD5(`RewardText`)='026eac7e47bc18c574fb8f92f7e699f7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9562 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9563, 'ruRU', 'О, да! Похоже, с тобой все в порядке, |3-6($r). Думаю, что могу тебе доверять.' FROM `quest_offer_reward` WHERE `ID`=9563 AND MD5(`RewardText`)='3a885f0b90cec2b7555bc540f47e891b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9563 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9564, 'ruRU', 'Гурф плюет на клок шерсти и пытается приспособить его к плеши на заду. $B$BПока и так сойдет! Надеюсь, кто-нибудь из наших шаманов мне поможет.' FROM `quest_offer_reward` WHERE `ID`=9564 AND MD5(`RewardText`)='6acf895eace0c2e9486ddf359aa71882' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9564 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9565, 'ruRU', 'Кровавый кристалл окружает неприятная аура, расползающаяся по пещере.' FROM `quest_offer_reward` WHERE `ID`=9565 AND MD5(`RewardText`)='72f65250de87c6f0adc57884260dd364' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9565 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9566, 'ruRU', 'Мои разведчики видели много таких же кристаллов на севере.$B$BБлагодарю за помощь, но теперь мне нужно посоветоваться со старейшинами. По окончании совещания я пошлю за тобой.' FROM `quest_offer_reward` WHERE `ID`=9566 AND MD5(`RewardText`)='d7601f48c7ed713b97ce8f038f14fe7f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9566 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9569, 'ruRU', 'Лишившись своего предводителя, а заодно и уже собранных оскверненных кристаллов, сатиры стали значительно менее опасными для нас. Но лишь Предвечному Свету ведомо, сколько здесь еще этих злосчастных тварей...$B$BМы – я и вестник Миколаас – благодарны тебе за помощь: если бы не это, сатиры стали бы для нас слишком серьезной угрозой. Решимость и отвага – вот ключ к победе над Легионом и его приспешниками!' FROM `quest_offer_reward` WHERE `ID`=9569 AND MD5(`RewardText`)='36f0064ba450dfba6612501db378a661' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9569 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9570, 'ruRU', '$GИзбранный вернулся:Избранная вернулась; с победой!$B$BПророчество почти исполнилось. Что же до шкуры...' FROM `quest_offer_reward` WHERE `ID`=9570 AND MD5(`RewardText`)='680165837dd2031991db2161da1498fc' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9570 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9575, 'ruRU', 'Знаешь, что я ненавижу больше, чем ошибаться? Проигрывать деньги. Я поспорил, что ты не справишься с заданием, дорогуша.$b$bНеплохое начало. Смерть командиров внесет панику в их ряды. Обезвредив их артиллерию, мы получим достаточно времени, чтобы подобраться к самой цитадели.$B$BНо орков по-прежнему больше, чем может охватить глаз, так что жди нового задания.$B$BНо пока я тобой доволен. Можешь выбрать в оружейной, что захочешь.' FROM `quest_offer_reward` WHERE `ID`=9575 AND MD5(`RewardText`)='ad5af4bddfdd056cb02dc05ff00d7b8c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9575 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9578, 'ruRU', 'На трупе одежда экзодарских техников, но подвески, о которой говорила Морэ, нет.' FROM `quest_offer_reward` WHERE `ID`=9578 AND MD5(`RewardText`)='a80c8577a77817a4e704a8cffecf0977' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9578 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9579, 'ruRU', 'Морэ выслушивает рассказ о том, что удалось обнаружить среди обломков криоядра. $B$BЗначит, он...$B$BДумаю, я все время знала это, просто не позволяла себе поверить. Конечно, я надеялась услышать совсем другие новости... Но все же прими мою глубочайшую благодарность за то, что $Gотыскал:отыскала; моего Галена.' FROM `quest_offer_reward` WHERE `ID`=9579 AND MD5(`RewardText`)='334ad6dfb396c0fb2d8d67a9cef4376e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9579 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9580, 'ruRU', 'На некоторое время нам этих припасов хватит. Да и мне найдется чем заняться: буду готовить еду... Благодарю тебя, $N.' FROM `quest_offer_reward` WHERE `ID`=9580 AND MD5(`RewardText`)='92e18037bb356dbc82a1997818009306' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9580 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9581, 'ruRU', 'Этот осколок кристалла даст нашим исследователям базу для сравнения – он принесен из той части острова, которую не так сильно затронула скверна.$B$BОднако же пока не имеет смысла посылать образец в Экзодар – сначала нам нужно собрать полный набор кристаллов. Начало, безусловно, положено. Поверь, если ты поможешь мне и в остальном, я сам прослежу за тем, чтобы твои усилия были вознаграждены.' FROM `quest_offer_reward` WHERE `ID`=9581 AND MD5(`RewardText`)='0e1bba7f387b8b87d1e13113191dd8b6' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9581 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9587, 'ruRU', 'Говоришь, на нем стоит подпись Иллидана? Дай-ка взглянуть.$B$B*Командир читает письмо, задумывается на минуту, затем снова его перечитывает."$B$BЭто действительно зловещие новости. Мы должны как можно быстрее воплотить в жизнь наш план атаки на Цитадель Адского Пламени и Кузню Крови. Ты $gдоказал:доказала;, что отлично справляешься с работой, так что именно ты этим и займешься.$B$BГанни даст тебе новое задание, думаю, оно будет куда более смертоносным, чем предыдущее.$B$BДа хранит тебя Свет, $N!' FROM `quest_offer_reward` WHERE `ID`=9587 AND MD5(`RewardText`)='1b3b2f855b50c8a3734c8402e662c51a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9587 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9598, 'ruRU', 'Надеюсь, ты все это время $Gизучал:изучала; фолиант?$B$BВ таком случае ты $Gдолжен:должна; быть $Gготов:готова; к испытанию. После крушения "Экзодара" в этих новых землях много дел для таких, как мы: всегда есть те, кто нуждается в помощи, сострадании и понимании; всегда есть враждебные твари, которых необходимо уничтожать...$B$BДоказав, что ты обладаешь достаточным терпением, чтобы помогать ближним, ты тем самым покажешь, что твои помыслы чисты и что ты воистину служишь Свету.' FROM `quest_offer_reward` WHERE `ID`=9598 AND MD5(`RewardText`)='375918a3b956f37b5dd40e0c1dda505e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9598 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9600, 'ruRU', 'Не стоит смущать души тех, кому тебе довелось помочь. Видишь ли, те, кто волею судьбы был возвращен в мир живущих, некоторое время обычно пребывают в растерянности. Думаю, потрясение от встречи с чужаком, да еще и непривычного вида, может оказаться слишком большим испытанием...$B$BБлагодаря тебе юный шаман сумел пережить это жестокое испытание; полагаю, ты вполне $Gдостоин:достойна; того, чтобы использовать силу священного Символа.' FROM `quest_offer_reward` WHERE `ID`=9600 AND MD5(`RewardText`)='07fd4b27db519a61fed831f01e347122' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9600 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9607, 'ruRU', 'У НИХ ЕСТЬ ВЛАСТИТЕЛЬ ПРЕИСПОДНЕЙ?!$B$BБоевой командир оглядывается на остальных и понижает голос.*$B$BЭто все объясняет. Должно быть, они использовали кровь этого властителя преисподней, чтобы создать орков Скверны. Значит, они тоже связаны с Пылающим Легионом. Если они смогли это сделать с коричневыми орками, значит, рано или поздно доберутся и до зеленых. Если из Темного портала выйдут орки новой Орды, нам придется несладко.$B$BМы должны нанести превентивный удар, и как можно скорее!' FROM `quest_offer_reward` WHERE `ID`=9607 AND MD5(`RewardText`)='5eb5d0af215c52e112f646051e420fad' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9607 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9616, 'ruRU', 'Клянусь безбородой кубической головой О\'роса! Хорошо, что ты принес это мне, $n. Эльфы крови жаждут нашей... хм, крови. Необходимо уведомить Велена! Прими это в награду.' FROM `quest_offer_reward` WHERE `ID`=9616 AND MD5(`RewardText`)='b0d478519c3a526baaaa3ef2569f79eb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9616 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9621, 'ruRU', 'Итак, свершилось. Подлый предатель получил по заслугам.\n\nТак этот подвиг совершила ты? Подобные свершения доказывают, что ваша раса не ослабела, $N.\n\nЯ вижу, что вести Лортемара значительно улучшат его отношения с Траллом.' FROM `quest_offer_reward` WHERE `ID`=9621 AND MD5(`RewardText`)='d83e42edfdf11a2e5dc509abb26bb75e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9621 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9622, 'ruRU', 'Видения, говоришь? Интересно... Так пророчество сбылось?$B$BЗначит, они видели энергетическое ядро Экзодара? И О\'рос тоже являлся им в видении? Что бы это значило?' FROM `quest_offer_reward` WHERE `ID`=9622 AND MD5(`RewardText`)='bfb921059188dcf8c9802b3b629bff09' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9622 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9623, 'ruRU', 'Тораллиус вздыхает. $B$BЛадно, давай распоряжения – почитаем.' FROM `quest_offer_reward` WHERE `ID`=9623 AND MD5(`RewardText`)='c8719c24684ce70b0659cfd1302c4310' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9623 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9626, 'ruRU', 'Тралл открывает письмо и начинает читать.\n\nЭтой леди Сильване упорства не занимать. Значит, теперь она прислала одного из героев Луносвета... Но что это меняет?' FROM `quest_offer_reward` WHERE `ID`=9626 AND MD5(`RewardText`)='caaae481c9e698b3db011b02501dd6a2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9626 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9627, 'ruRU', 'Ты оказала нам неоценимую услугу. Теперь Тралл считает нашу расу сильной и могущественной и верит, что сможет с нашей помощью воззвать к своим сородичам в Запределье.\n\nЧто ж, он почти прав. Почти.\n\nНастала эпоха великих перемен, $N. Теперь мы стали частью Орды.' FROM `quest_offer_reward` WHERE `ID`=9627 AND MD5(`RewardText`)='7b821f4dab54501bde2fc3a6d50ac778' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9627 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9641, 'ruRU', 'Неплохо. Теперь у меня есть исходные материалы для воссоздания кристаллов.$B$BТы можешь выбрать один из трех видов кристаллов, которые я могу создать. Каждый вид хорош для охоты на определенную добычу...' FROM `quest_offer_reward` WHERE `ID`=9641 AND MD5(`RewardText`)='30f54babeae09bfcebfbe1db33c8edb4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9641 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9648, 'ruRU', 'Ну, я же тебя предупреждал, верно? Впрочем, надеюсь, оплата послужит достаточной компенсацией за те небольшие удобства, которые тебе довелось испытать. Когда восстановишь силы, возвращайся: возможно, я найду для тебя новое задание... Грибы – такая вещь, которой не бывает много!' FROM `quest_offer_reward` WHERE `ID`=9648 AND MD5(`RewardText`)='7e2443f09bd61afeee6ee29b6ceaae94' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9648 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9672, 'ruRU', 'Скажи, ты, $Gсухопутный червяк:сухопутная мартышка;, тебе приходилось слышать о проклятии? Ну да, конечно, разумеется, ничего! А между тем именно проклятье и потопило все эти корабли; вернее сказать, это сделал Проклятый Риф – мерзейшее место в мире. Я и сам здесь торчу уже двадцать лет, если ты этого не знаешь.$B$BЯкорь мне в глотку!.. Вот тут-то я и помер, стал падалью, которой даже драконы брезгуют... Впрочем, это совсем другая история. Я сейчас не о том. Мы должны помочь тем злосчастным душам, которые попали в ловушку на этом рифе.' FROM `quest_offer_reward` WHERE `ID`=9672 AND MD5(`RewardText`)='4029ded0533f1a23a0c989fe75b26e6b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9672 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9674, 'ruRU', 'Отличное начало – но только начало...' FROM `quest_offer_reward` WHERE `ID`=9674 AND MD5(`RewardText`)='c71f12dece813864f83080b7e5bcd43c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9674 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9683, 'ruRU', 'Подумать только! Тебе это удалось!.. Благодарение сотен и сотен душ пребудет с тобой.$B$BПозволь кое-что предложить тебе...' FROM `quest_offer_reward` WHERE `ID`=9683 AND MD5(`RewardText`)='bf74457bfee557b2cd284d823b053d05' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9683 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9687, 'ruRU', 'Ритуал?.. Совуны тысячи лет жили в гармонии с природой и этой землей. Это безумие какое-то!..$B$BКак жаль...' FROM `quest_offer_reward` WHERE `ID`=9687 AND MD5(`RewardText`)='6c87e6414ca60f1af737aaf1d161c78a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9687 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9688, 'ruRU', 'Каким бы отвратительным ни было это деяние, его нужно было совершить. И теперь тебе предстоит взглянуть в лицо истинному злу.' FROM `quest_offer_reward` WHERE `ID`=9688 AND MD5(`RewardText`)='605796dc44b5e0cb038974d032d486bd' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9688 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9697, 'ruRU', 'О, замечательно! Наконец-то хоть какая-то помощь! У меня так много дел, а я вынуждена сидеть здесь, чтобы организовывать работу.$b$bНадеюсь, ты не боишься грязной работы?' FROM `quest_offer_reward` WHERE `ID`=9697 AND MD5(`RewardText`)='54ccb1d137141f8adf52850aafd19a50' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9697 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9701, 'ruRU', 'Что?! Болотники с гряды Квагг пожирают отпрысков спорлингов?! Это ужасно!' FROM `quest_offer_reward` WHERE `ID`=9701 AND MD5(`RewardText`)='6b343ea29fd075a1abd36cf215a56916' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9701 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9702, 'ruRU', 'Вот это и есть твои находки? Странно. Эти объедки грибов выглядят необычно, и в то же время как-то знакомо…$b$bПодожди минутку, мне необходимо подумать. Смотри, никуда не уходи!' FROM `quest_offer_reward` WHERE `ID`=9702 AND MD5(`RewardText`)='a202eff0d8a26326d6dd134d2d12eed7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9702 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9705, 'ruRU', 'Во имя Солнечного Колодца! Это третий курьер, которого мы потеряли за последний месяц!$B$BЯ ценю твою отвагу – не каждый осмелится сунуться на Рассветную улицу. Стражам нужно лучше следить за этими злосчастными Презренными.' FROM `quest_offer_reward` WHERE `ID`=9705 AND MD5(`RewardText`)='7463ce741a2f4ae214d5fe9b265daf8d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9705 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9706, 'ruRU', 'Читая дневник, Курос бледнеет; по его лицу катятся слезы. $B$BСаруан был моим господином... моим учителем... наставником... Я лишь недавно занял его место в Триумвирате – и только после того, как мы уверились, что самого Саруана не отыщем.$B$B Лицо Куроса искажается от гнева. $B$BАх, вот как?.. Матис!' FROM `quest_offer_reward` WHERE `ID`=9706 AND MD5(`RewardText`)='c0ee9a2f62510d0fc582edc01a33c719' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9706 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9708, 'ruRU', 'Да, все сходится... Присутствие огров и то, чем они занимаются, объясняет все. Да уж, теперь понятно, отчего та местность называются Болотными вырубками!$b$bНужно как-то исправить положение, но как? Не можем же мы просто истребить этих огров! В конце концов, они точно так же имеют право на жизнь, как и любые другие жители болот!' FROM `quest_offer_reward` WHERE `ID`=9708 AND MD5(`RewardText`)='6d696c765f9448ead3e6a3db86e1696a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9708 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9715, 'ruRU', 'Отличный гибискус! Но лишний гибискус нам никогда не помешает. Будешь в Нижетопи, имей это в виду!' FROM `quest_offer_reward` WHERE `ID`=9715 AND MD5(`RewardText`)='8ba9b372ebc22ba89289886f1b57ab24' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9715 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9716, 'ruRU', 'За этим стоят наги! Но зачем им это? Судя по тому, что ты описываешь, этот паровой насос может быть причиной того, почему уровень воды в болоте падает!$b$bЭто объясняет то, отчего они относятся к нам столь враждебно... Что ж, не будем тратить времени. Я попрошу тебя выполнить для нас еще одно задание.' FROM `quest_offer_reward` WHERE `ID`=9716 AND MD5(`RewardText`)='b19d64c09554fc0d736acfa9f50ab9eb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9716 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9717, 'ruRU', '<Спорлинг издает звук, отдаленно напоминающий хмыканье.>$B$BВеликолепно! Несомненно, боевой дух споровых великанов упадет ниже дна болота, как только они поймут, что тебе удалось совершить.$B$BПравда, возможно, они так разгневаются, что нападут на нас снова...$B$B<Тшу делает такое движение, как будто пожимает плечами.>' FROM `quest_offer_reward` WHERE `ID`=9717 AND MD5(`RewardText`)='4da9cb5b40f4a80432ffad6e34f1b5d3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9717 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9718, 'ruRU', 'Все как я подозревала! Наги установили насосы на всех крупных озерах Зангартопи!$b$bИх необходимо остановить, если мы хотим спасти болота...' FROM `quest_offer_reward` WHERE `ID`=9718 AND MD5(`RewardText`)='e15fcc75c8310ce474a9cd2ca1b5e176' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9718 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9719, 'ruRU', 'Черная Охотница мертва! Нехорошо радоваться убийству, но эта великая мать и все ее племя на протяжении веков причиняли моему народу неисчислимые страдания.\n\nУвы, теперь одна из ее потомков преобразуется и займет ее место, однако это все же займет какое-то время, и мы сможет перевести дух. В течение некоторого времени болотоходы перестанут нас тревожить...' FROM `quest_offer_reward` WHERE `ID`=9719 AND MD5(`RewardText`)='22cc7bfc7bf6cbbc918479e99ecd7446' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9719 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9720, 'ruRU', 'Итак, дело сделано. Болота пока что в безопасности.$b$bНо не надейся, что мы больше не услышим о нагах! Нам придется постоянно быть начеку.' FROM `quest_offer_reward` WHERE `ID`=9720 AND MD5(`RewardText`)='26dae59900aff2a7ac97f943314e3378' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9720 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9724, 'ruRU', 'Принесенные тобой новости о деятельности наг в Зангартопи воистину ужасны! Исиэль поступила разумно, что сообщила об этом нам. Она не забывает, что экспедиции не выжить без поддержки Круга...' FROM `quest_offer_reward` WHERE `ID`=9724 AND MD5(`RewardText`)='67fda9837df2675b1d9ef59de0a086a2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9724 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9738, 'ruRU', 'Я рада, что хоть кто-то из моих друзей уцелел, и все же судьба остальных разбила мне сердце... $B$BПо крайней мере они погибли, занимаясь любимыми делом. Моя благодарность тебе безгранична, $N. $B$BПрошу тебя, прими это в знак моей признательности.' FROM `quest_offer_reward` WHERE `ID`=9738 AND MD5(`RewardText`)='75fe663f25f4c90ec1026821dcd514d4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9738 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9739, 'ruRU', 'Тебе это удалось! Мой народ несказанно благодарен тебе.$b$bНадеюсь, ты нас поймешь... ведь из этих мешочков появляются на свет наши малыши! Мы не можем допустить, чтобы эти чудовища пожирали мешочки!' FROM `quest_offer_reward` WHERE `ID`=9739 AND MD5(`RewardText`)='b61aaba771ed887014cdbf855bb3ee8c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9739 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9740, 'ruRU', 'Роскошно! Теперь врагам не получить подкреплений! Осталось только прикончить их...' FROM `quest_offer_reward` WHERE `ID`=9740 AND MD5(`RewardText`)='131df4902529612bc6016eea4e897a94' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9740 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9742, 'ruRU', 'Да! Благодаря тебе спасено ещё несколько мешочков со спорами!$B$BТы не $Gтакой:такая;, как другие пришельцы. Я поведаю моему народу о твоих деяниях!$B$B<Это задание можно выполнять повторно до тех пор, пока не добьёшься дружелюбного отношения.>' FROM `quest_offer_reward` WHERE `ID`=9742 AND MD5(`RewardText`)='ed150ea489da15f2e4d218c106170cff' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9742 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9744, 'ruRU', 'Невероятно! Нужны сотни спорлингов, чтобы перебить столько же великанов, сколько ты! Я позабочусь о том, чтобы о твоих деяниях стало известно всем.$B$B<Это задание можно выполнять повторно до тех пор, пока не добьёшься дружелюбного отношения.>' FROM `quest_offer_reward` WHERE `ID`=9744 AND MD5(`RewardText`)='c96cd58ff044131bfc58bfaef693bffd' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9744 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9746, 'ruRU', 'Это, несомненно, ослабит их оборону. Теперь эльфы Крови не раз подумают, прежде чем попытаться напасть на нас!' FROM `quest_offer_reward` WHERE `ID`=9746 AND MD5(`RewardText`)='db360322776b642294763e2b9efa3479' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9746 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9758, 'ruRU', 'А, ты здесь, как хорошо! И как раз вовремя! Здесь много что предстоит сделать!' FROM `quest_offer_reward` WHERE `ID`=9758 AND MD5(`RewardText`)='b1f6de5c6f0ebf1953b2120acf0923dc' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9758 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9760, 'ruRU', 'Возможно, именно ты укажешь нашему народу путь к миру и процветанию...' FROM `quest_offer_reward` WHERE `ID`=9760 AND MD5(`RewardText`)='ff72a78ebd62da44d542f9441789846e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9760 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9761, 'ruRU', 'Надеюсь, герой объявится раньше, чем Ястребы вызовут подкрепления, – а иначе и путь ему расчищать не имело смысла...' FROM `quest_offer_reward` WHERE `ID`=9761 AND MD5(`RewardText`)='7f55920695b963c8b257a048fc4de3e8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9761 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9776, 'ruRU', 'Если анахорет Ахуурн считает тебя другом, возможно, ты и впрямь $gдостоин:достойна; доверия. Пожалуйста, |3-6($r), прости мне мою недоверчивость: зачастую она бывает единственным, что спасает меня и моих товарищей от гибели. Ты можешь найти приют среди нас, и, быть может, наше взаимное доверие со временем укрепится.' FROM `quest_offer_reward` WHERE `ID`=9776 AND MD5(`RewardText`)='1d45d49ab05324cf550222845e89699a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9776 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9778, 'ruRU', 'Ты от Исиэли? Ну да, разумеется, $Gтакой:такая;, как ты, мне всегда пригодится! Опытные, стойкие бойцы нам никогда не помешают.' FROM `quest_offer_reward` WHERE `ID`=9778 AND MD5(`RewardText`)='7bd97ece7a9d260f99384257f1cf66ae' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9778 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9779, 'ruRU', 'Воздаятель Борос разглядывает документ. $B$BНаписано на талассийском... По счастью, я знаю, кто это сможет перевести...' FROM `quest_offer_reward` WHERE `ID`=9779 AND MD5(`RewardText`)='41a4746fa8c854c09c19807650c6778a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9779 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9781, 'ruRU', 'Молодец! На ближайшее будущее этого должно быть достаточно, чтобы уменьшить конкуренцию. Но, конечно, со временем придется искать новые источники пищи. На одной рыбе и грибах прожить можно, но разнообразие не помешает...' FROM `quest_offer_reward` WHERE `ID`=9781 AND MD5(`RewardText`)='4937ccf8b663b06afbb6bebf5e73ee13' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9781 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9782, 'ruRU', 'Почва, похоже, истощена. Но это еще ничего не объясняет. В чем же дело? Отчего же все внезапно принялось вымирать?' FROM `quest_offer_reward` WHERE `ID`=9782 AND MD5(`RewardText`)='348d084ac1dc0ad6a02c0eacc511f7e8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9782 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9784, 'ruRU', 'Отлично. Если найдёшь другие части растений, приноси их мне.$B$B<Это задание можно повторять, пока не будет достигнуто уважительное отношение.>' FROM `quest_offer_reward` WHERE `ID`=9784 AND MD5(`RewardText`)='fd6be5c31d4ae820c702fe64bb716734' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9784 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9785, 'ruRU', 'Ты $gвернулся:вернулась;! Удалось ли тебе получить благословение Древ?' FROM `quest_offer_reward` WHERE `ID`=9785 AND MD5(`RewardText`)='616e2f62602fe651a02fc1fd084c698e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9785 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9793, 'ruRU', 'Хм... Да, я помню, как наши разведчики упоминали о руинах дренейского поселения в северной части леса. Самому мне об этих развалинах мало что известно, но ты, если хочешь, можешь поговорить с разведчиками.' FROM `quest_offer_reward` WHERE `ID`=9793 AND MD5(`RewardText`)='463e7c899e9bb0f9674adf408aa4d263' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9793 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9795, 'ruRU', 'Дэнжай просит о помощи? Нет, я, конечно, пошлю ему подкрепление, но у нас и тут бойцов негусто... И нас тоже донимают огры.\n\nЯ при первой же возможности сообщу ему все, что нам известно о местных племенах огров и об их тактике. Быть может, если Дэнжай продержится достаточно долго, мы сумеем ударить на этих гнусных тварей с двух сторон одновременно...' FROM `quest_offer_reward` WHERE `ID`=9795 AND MD5(`RewardText`)='a36af789a56669b6c81fe16df93bd03d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9795 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9799, 'ruRU', 'Неплохие образцы. Спасибо за помощь. Как только я найду время и проведу анализ этих растений, можно будет примерно понять, сколько усилий потребуется для восстановления полей.' FROM `quest_offer_reward` WHERE `ID`=9799 AND MD5(`RewardText`)='ea54ad71c564497b0f9561e83ef004fd' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9799 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9801, 'ruRU', 'Да, это отлично подойдет! Минутку, я сейчас приготовлю зелье...' FROM `quest_offer_reward` WHERE `ID`=9801 AND MD5(`RewardText`)='d0d60626571da15bf0862ce8d7e16f43' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9801 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9803, 'ruRU', 'Они отказались? Разумеется, они вправе сами выбирать свой путь, и все же их выбор меня изумляет. Мне казалось, что все дренеи, будь то Сломленные или Заблудшие, должны в глубине души помнить, что все мы когда-то были единым народом…$b$bПолагаю, он прав, и глупо было пытаться их обмануть, но неужели он не понимает, что мы сделали это с наилучшими намерениями?' FROM `quest_offer_reward` WHERE `ID`=9803 AND MD5(`RewardText`)='0fcdd6d66f8a6d0fad237a463f5c2e19' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9803 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9807, 'ruRU', 'Мы ценим твою помощь, $N. Ждём новых спор!' FROM `quest_offer_reward` WHERE `ID`=9807 AND MD5(`RewardText`)='6e90d628c829be04b1d3d61ca9814ad4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9807 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9808, 'ruRU', 'Это поможет нам приобретать еду и припасы у других спорлингов! Спореггар благодарит тебя, $n!' FROM `quest_offer_reward` WHERE `ID`=9808 AND MD5(`RewardText`)='4bb25556e23f2e0cb25257fd5436d55b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9808 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9809, 'ruRU', 'Спасибо тебе, $N! Я, как старейшина Спореггара, должен заботиться о том, чтобы у моего народа всего было в достатке. И ты сильно облегчаешь мою задачу!' FROM `quest_offer_reward` WHERE `ID`=9809 AND MD5(`RewardText`)='d3f8ae60a25ad0c323adfb7280224850' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9809 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9827, 'ruRU', 'Это выглядит как базидия болотохода, но мне еще никогда не встречались базидии в таком состоянии...Я слышал, что великаны Мертвой трясины начинают вянуть, но тут дело зашло куда дальше, чем я предполагал…$b$bМертвая трясина когда-то была таким же озером, как и остальные озера на болотах, и великаны как раз там и плодились. Теперь же, когда вода отступила, им, похоже, просто негде рассеивать споры. Если так пойдет и дальше, великаны могут полностью исчезнуть...' FROM `quest_offer_reward` WHERE `ID`=9827 AND MD5(`RewardText`)='cb729cd9fdb34f79972b49a85d3507ea' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9827 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9833, 'ruRU', 'Отличные новости! Конечно, до полной безопасности здешним дорогам пока далеко, однако же наши посланцы умны и находчивы...' FROM `quest_offer_reward` WHERE `ID`=9833 AND MD5(`RewardText`)='d42cb4890af05c91397d552c6798e9ab' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9833 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9834, 'ruRU', 'Макту думает, это хорошие шкуры. Из них получатся отличные доспехи.$b$bКто знает? Возможно, тут хватит и на несколько доспехов для дренеев.' FROM `quest_offer_reward` WHERE `ID`=9834 AND MD5(`RewardText`)='6546e8d008da0eb8e67fbe567dab8cb2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9834 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9835, 'ruRU', 'Теперь огры на время притихнут, но я уверен: так быстро они не сдадутся! С тех пор, как я перестал быть дренеем, я многое забыл, но как упорны огры – это не забывается!' FROM `quest_offer_reward` WHERE `ID`=9835 AND MD5(`RewardText`)='0998b3b3e97e3dac5be1e8fcc96d04a9' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9835 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9839, 'ruRU', 'Наконец-то! Мы благодарим тебя за помощь – благодаря тебе наше положение упрочилось. Я пошлю весть о твоих деяниях в куренайский город Телаар в Награнде. У наших народов еще не раз будет случай сражаться плечом к плечу!' FROM `quest_offer_reward` WHERE `ID`=9839 AND MD5(`RewardText`)='4e14ae2ff4e154e28191305499c6c6c7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9839 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9848, 'ruRU', '*Тимоти бросается листать справочник."$b$bОни используют в качестве основного компонента кисейницу? Ерунда какая-то. Кисейница же совершенно не ядовита!$b$bВводить в состав яда кисейницу – это все равно, что разбойнику сражаться двумя палицами. Можно, конечно, но какой смысл?! Решительно не понимаю...$b$b*Тимоти прочищает горло.*$b$bВ общем, спасибо большое. Попробую приготовить этот яд, как только будет время...' FROM `quest_offer_reward` WHERE `ID`=9848 AND MD5(`RewardText`)='9c58f74f7107f353ffc97ad7c3977a82' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9848 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9861, 'ruRU', 'Это крик боли и призыв о помощи, |3-6($r). Некая внешняя сила пытается разрушить стихии.' FROM `quest_offer_reward` WHERE `ID`=9861 AND MD5(`RewardText`)='10ed174ebfd0bf14217d8ff12c701a66' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9861 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9872, 'ruRU', 'Гаррош мнет карту и бросает ее в огонь.\n\nКакая разница? Это уже далеко не новость. Они давно нас атакуют. Мы пока держимся, но...\n\nНеужели ты не понимаешь? Все кончено... Великая Матерь Гейя умирает.' FROM `quest_offer_reward` WHERE `ID`=9872 AND MD5(`RewardText`)='7ef69155b4d9840634b761f5868133a4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9872 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9876, 'ruRU', 'Слава Кенарию, что ты здесь! Я не могла выбраться наружу из-за ран...' FROM `quest_offer_reward` WHERE `ID`=9876 AND MD5(`RewardText`)='655e5297ce0ad736ebdf2df279a88341' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9876 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9877, 'ruRU', 'Так, значит, Джанеда посылает тебя вызволить пленников Смертхольма? Стало быть, она высоко ставит тебя, $N.' FROM `quest_offer_reward` WHERE `ID`=9877 AND MD5(`RewardText`)='b8e48c26daf35aa7a6ed616e53322404' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9877 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9888, 'ruRU', 'Килрат говорит, понизив голос.\n\nЭти огры какие-то странные... И на редкость тупые. Смотри, как тот толстый заставляет плясать тех, которые... э... менее толстые. Завораживающее зрелище.' FROM `quest_offer_reward` WHERE `ID`=9888 AND MD5(`RewardText`)='7ac724ba15f9890e85ea2fc3b15e15a2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9888 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9889, 'ruRU', 'Не убивай меня, я все расскажу!' FROM `quest_offer_reward` WHERE `ID`=9889 AND MD5(`RewardText`)='107fdf408d224d7205bb0a521bc7ba0f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9889 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9890, 'ruRU', 'Эй, притормози, $N... Я всего лишь скромный разбойник. Что мне делать с такими сведениями?' FROM `quest_offer_reward` WHERE `ID`=9890 AND MD5(`RewardText`)='6d157d8462d036ac0d76180d3bca4858' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9890 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9891, 'ruRU', 'Они что, считают, у них есть право убивать орков и изгонять их с исконных земель? Надо думать, это никоим образом не связано с тем обстоятельством, что наш предводитель – сопливый щенок... Если бы в нем была хоть десятая доля той ярости, что полыхала в душе в его отца...' FROM `quest_offer_reward` WHERE `ID`=9891 AND MD5(`RewardText`)='fe4cb5ab573c5e606878c371d181bd7b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9891 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9895, 'ruRU', 'Теперь, когда тебе довелось своими глазами повидать последствия нарушения природного равновесия, не забывай о них в своих скитаниях!' FROM `quest_offer_reward` WHERE `ID`=9895 AND MD5(`RewardText`)='495a69a0ac7a602c64447a05d4442ea3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9895 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9896, 'ruRU', 'У меня просто слов нет, чтобы выразить, как я тебе благодарен! Ох, и потеха будет...' FROM `quest_offer_reward` WHERE `ID`=9896 AND MD5(`RewardText`)='6282115c64729346257dbb236ce33120' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9896 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9905, 'ruRU', '*Макту одобрительно кивает.*$b$bМакту благодарит тебя за помощь. Его гордость успокоена. Больше его не застанут врасплох!' FROM `quest_offer_reward` WHERE `ID`=9905 AND MD5(`RewardText`)='bba19db0be241b055d9ac33d7be0824c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9905 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9906, 'ruRU', 'Это только начало. Есть и другие, кому мы должны преподать урок!' FROM `quest_offer_reward` WHERE `ID`=9906 AND MD5(`RewardText`)='301ded20e1fecdb829cb571210cc71a8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9906 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9907, 'ruRU', 'Уж если и это их не напугает – тогда нам не на что рассчитывать. Ты сослужил маг\'харам достойную службу, $N. И получишь достойную награду.' FROM `quest_offer_reward` WHERE `ID`=9907 AND MD5(`RewardText`)='c8a958a689075adb926ef91917b31237' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9907 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9910, 'ruRU', 'Может, возьмешься еще за одну работенку? На этот раз, скажем так, более деликатного свойства?' FROM `quest_offer_reward` WHERE `ID`=9910 AND MD5(`RewardText`)='abde6c04aa4768dd9c95eeaefc752522' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9910 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9912, 'ruRU', 'Добро пожаловать в Кенарийский оплот, $n! Надеюсь, ты здесь затем, чтобы помогать нам в работе? У нас тут дел по горло!' FROM `quest_offer_reward` WHERE `ID`=9912 AND MD5(`RewardText`)='b9ece27c62b73510b01b46b0dd9c080e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9912 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9916, 'ruRU', 'Почти все наши пожитки либо погибли, либо были украдены при нападениях. Я мало что могу тебе предложить, но кое-что интересное у меня есть... Оно тебе наверняка пригодится...' FROM `quest_offer_reward` WHERE `ID`=9916 AND MD5(`RewardText`)='235dcd02fef8b89c3888460ffb0780b7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9916 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9919, 'ruRU', '$R, ты $gпомог:помогла; защитить новое поколение спорлингов! Мы можем тебе отплатить только одним: пригласив в свои дома. Поживи у нас, познакомься с другими спорлингами. Они захотят тебя о многом расспросить – но ты, надеюсь, не будешь против?' FROM `quest_offer_reward` WHERE `ID`=9919 AND MD5(`RewardText`)='e0e81cd58a0718a94ecd7213b1068f01' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9919 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9957, 'ruRU', 'Хорошо, что к нам хоть кого-то прислали. Всех местных друидов убили! Выжить удалось только мне и еще одному, да и тот сошел с ума.\n\nНе знаю, что тут стряслось, но обязательно докопаюсь до правды. Что бы это ни было, все случилось очень быстро и оставило ощущение какой-то неестественности.\n\nВы мне поможете?' FROM `quest_offer_reward` WHERE `ID`=9957 AND MD5(`RewardText`)='35979b3fa083c235d295b8b8e3f25399' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9957 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9962, 'ruRU', 'Гм... неплохо, неплохо... У тебя очень хорошие данные, малыш. Вот тебе немного золота – пусть звенит в карманах.' FROM `quest_offer_reward` WHERE `ID`=9962 AND MD5(`RewardText`)='0372ac14460106ff5718af0e89033f23' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9962 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9970, 'ruRU', 'Ты хорошо погонял этих огров, малыш! Заставил их попотеть! Вот тебе кое-что сверху оговоренного – смотри, не трать все сразу!\n\nТы готов к следующей схватке? Гаргток ставит на тебя! Смотри не подведи!' FROM `quest_offer_reward` WHERE `ID`=9970 AND MD5(`RewardText`)='ba10a0467eda446b0727fdf891a28269' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9970 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9972, 'ruRU', 'МАЛЫШ! СВЕРШИЛОСЬ! Следующий бой будет воистину грандиозным! Бой за звание чемпиона!\n\nБрось, не стоит паниковать. Спокойствие, только спокойствие! Мы же не хотим, чтобы эти огры узнали, что у нас тут затевается кое-что интересное. В конце концов, у меня есть и свой интерес. И своя доля во всем этом деле.' FROM `quest_offer_reward` WHERE `ID`=9972 AND MD5(`RewardText`)='b5dcc9057805908bd750fd05eae0e00a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9972 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9973, 'ruRU', 'О, боги. Герой Боевого Молота Могор желает воспользоваться своим правом выйти на бой. Тебе придется сразиться с ним!\n\nИ знаешь, молотобойцы ведь не зря так зовутся.' FROM `quest_offer_reward` WHERE `ID`=9973 AND MD5(`RewardText`)='a2d9645f30100fb315e82665103d071f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9973 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9977, 'ruRU', 'Гаргток обещал, что ты получишь достойную награду. И он свое слово сдержит!' FROM `quest_offer_reward` WHERE `ID`=9977 AND MD5(`RewardText`)='f67a663df2075ab2933230371390df39' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9977 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9987, 'ruRU', 'Замечательно, $N. Теперь можно не беспокоиться хотя бы о том, что араккоа нападут на наших торговцев и курьеров – и без этого забот полно.' FROM `quest_offer_reward` WHERE `ID`=9987 AND MD5(`RewardText`)='d8616cb722f58b3d485ae647a3752b69' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9987 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9992, 'ruRU', 'Спасибо за семена! У меня набралось почти достаточно для отправки первой партии!' FROM `quest_offer_reward` WHERE `ID`=9992 AND MD5(`RewardText`)='6b9ecf57c58ce6fbd61ac3cf8ead4cb2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9992 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9998, 'ruRU', '<Высшая эльфийка кивает>$B$BНеплохо для начала, но Бертельм правильно сделал, что прислал тебя ко мне. Я обнаружила кое-что, что может объяснить присутствие здесь этих орков Скверны.' FROM `quest_offer_reward` WHERE `ID`=9998 AND MD5(`RewardText`)='78cabf13c3f95e62ab30a5767cf5b5b7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9998 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 9999, 'ruRU', 'Этого я и боялся. Железо Скверны так просто не уничтожить. Но отчаиваться рано…' FROM `quest_offer_reward` WHERE `ID`=9999 AND MD5(`RewardText`)='c30ca21e169dc2e862efd7746f3a9a94' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=9999 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10001, 'ruRU', 'Надеюсь, мой знакомый найдет способ стереть эти лагеря с лица земли. В конце концов, он когда-то был инженером в Легионе…' FROM `quest_offer_reward` WHERE `ID`=10001 AND MD5(`RewardText`)='94ebf5c91f146122a032d4a4afabba8c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10001 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10002, 'ruRU', '<Телория кивает>$B$BПрекрасно, мы выиграли немного времени. Эльфы крови непременно захотят узнать, что произошло с их подругой, но к тому времени, надеюсь, мы сумеем разобраться в их намерениях.' FROM `quest_offer_reward` WHERE `ID`=10002 AND MD5(`RewardText`)='cde3e64b323aa0750a0a2265c28839d8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10002 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10003, 'ruRU', '<Кайд кивает>$B$BПрекрасно, мы выиграли немного времени. Эльфы крови непременно захотят узнать, что произошло с их подругой, но к тому времени, надеюсь, мы сумеем разобраться в их намерениях.' FROM `quest_offer_reward` WHERE `ID`=10003 AND MD5(`RewardText`)='1a2befcf96227d4b5aaee124b2f1a303' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10003 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10006, 'ruRU', 'Бомба на чистейшей мане, способная стирать с лица земли целые города! Но зачем? Зачем эльфам крови создавать нечто подобное и сбрасывать на нас? Перелесок Кенария всегда был мирным и спокойным местом.\n\nКаковы бы ни были причины, их наверняка придумал хранитель Древлос, и я не имею ни малейшего понятия о том, как вылечить его. Быть может, его разум со временем излечится сам?\n\nЯ могу лишь надеяться на то, что такое несчастье больше никогда не постигнет нас!' FROM `quest_offer_reward` WHERE `ID`=10006 AND MD5(`RewardText`)='bbb6b55f5bd432c24c0908f87800757b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10006 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10007, 'ruRU', 'Дело начинает проясняться. Думаю, что если мы сумеем не дать оркам закрепиться здесь, мы удержим позиции за собой.' FROM `quest_offer_reward` WHERE `ID`=10007 AND MD5(`RewardText`)='72672696f30b8311c5da944d9d3ccc5d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10007 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10009, 'ruRU', 'Сальсалабим держать свой договор, только ты не будь злой потом, да?' FROM `quest_offer_reward` WHERE `ID`=10009 AND MD5(`RewardText`)='03540b42eddc949d3e2cf8ee5d1f8f5c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10009 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10011, 'ruRU', 'Мы побеждаем! Нам удалось сдержать натиск Легиона!\n\nТы совершил героический подвиг и теперь можешь выбрать награду.' FROM `quest_offer_reward` WHERE `ID`=10011 AND MD5(`RewardText`)='7d19734b6643ca6ca08f9bf3c5931c79' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10011 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10012, 'ruRU', '<Бертельм берет у вас планы и изучает их>$B$BЕсли бы вы не принесли мне эту карту, я бы подумал, что вы выжили из ума, однако вот она, тут! Орки Скверны не только служат эльфам крови, но им еще и приказано отвлекать нас.$B$BЭта карта дает вопросов больше, чем ответов, но, по крайней мере, мы теперь знаем, с чем имеем дело.' FROM `quest_offer_reward` WHERE `ID`=10012 AND MD5(`RewardText`)='6be05ff226caa3f5cabe19bddb58187e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10012 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10013, 'ruRU', 'Рокаг берет у вас планы и изучает их\n\nКайд все же был прав! Эти гнусные орки Скверны и впрямь что-то затевали, хотя я бы в жизни не подумал, что они скооперируются с эльфами крови.\n\nСудя по карте, орки должны отвлекать нас... но от чего? Это очень нехорошие новости, $N. вы правильно сделали, что сразу вернулись ко мне.' FROM `quest_offer_reward` WHERE `ID`=10013 AND MD5(`RewardText`)='0d1b42cdf6763111ebb8ea2794cef774' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10013 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10016, 'ruRU', 'О, большое спасибо, $Gдруг:подруга; $Gмой:моя;. Эти хвостики даже еще лучше, чем я думал, из них выйдет прекрасный плащ.$B$B<Бертельм бросает быстрый взгляд на таверну>$B$BО да, плащ выйдет отличный.' FROM `quest_offer_reward` WHERE `ID`=10016 AND MD5(`RewardText`)='b9329678d0b9df8de12e763df89566eb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10016 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10020, 'ruRU', 'Спасибо, $N. Заботиться о больных нелегко, но со временем я поняла, что это само по себе является отличной наградой.' FROM `quest_offer_reward` WHERE `ID`=10020 AND MD5(`RewardText`)='07884b0a4a88927cb1082d84e9e2fc20' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10020 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10021, 'ruRU', 'Благодарю вас, $N. Мы – хранители света, и даже в самые трудные времена не можем пренебрегать своим долгом.' FROM `quest_offer_reward` WHERE `ID`=10021 AND MD5(`RewardText`)='dfbec34ecb6ed20dbf8fcc287c5597e1' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10021 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10024, 'ruRU', 'Они в отличном состоянии, $N! Не останавливайтесь на достигнутом, и скоро Провидцы станут воспринимать вас как друга.' FROM `quest_offer_reward` WHERE `ID`=10024 AND MD5(`RewardText`)='8b711bcb6f7c6fc3a660d1153fd28490' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10024 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10026, 'ruRU', '<Андарл вытирает лоб рукавом мантии>$B$BУфф... Большое спасибо! Если бы эти твари остались в живых, они бы причиняли нам массу неудобств.' FROM `quest_offer_reward` WHERE `ID`=10026 AND MD5(`RewardText`)='0cf86d4ca6dfbebc9dccd81ec6831408' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10026 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10028, 'ruRU', 'Надеюсь, это не все сосуды, что были в том городе. На первое время этого хватит, но потом нам потребуется намного больше.' FROM `quest_offer_reward` WHERE `ID`=10028 AND MD5(`RewardText`)='03725a08e5382c0a3686b32cd41edeaf' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10028 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10030, 'ruRU', 'Отлично, именно этого мне и не хватало... еще костей.\n\nРамдор вздыхает\n\nДа, да, я прослежу за тем, чтобы эти останки наших высокочтимых предков были надлежащим образом захоронены, так что не беспокойтесь.\n\nА раз уж вы так заинтересованы в том, чтобы помочь мертвым, то я могу дать вам еще одно дело.' FROM `quest_offer_reward` WHERE `ID`=10030 AND MD5(`RewardText`)='2df54f2224e937e2c746c118e52c7967' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10030 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10037, 'ruRU', 'Спасибо! Я уж и забыл, когда в последний раз ел угря!\n\nИ как же мне их приготовить?' FROM `quest_offer_reward` WHERE `ID`=10037 AND MD5(`RewardText`)='d82d23b5a176c7212f8394c18e2f9c5f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10037 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10050, 'ruRU', 'О том, что происходит в Оружейной, многие предпочитают умалчивать, но Сыны благодарны тебе за помощь.' FROM `quest_offer_reward` WHERE `ID`=10050 AND MD5(`RewardText`)='e900d161e70bbd7a63103b9ecf63066c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10050 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10055, 'ruRU', 'Выглядит лучше, чем я думал. Уйдет немало времени, чтобы счистить всю эту пыль и ржвачину, но выбора у меня все равно нет.' FROM `quest_offer_reward` WHERE `ID`=10055 AND MD5(`RewardText`)='12b1f85207bca6553549d8623fbe33b6' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10055 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10058, 'ruRU', 'Это правда она? Невероятно, как эта книга сумела уцелеть во время битвы. Время, проведенное среди руин, не пошло ей на пользу, но я рад, что она снова ко мне вернулась.$B$BЭто моя единственная память о Туралионе.$B$B*Отец Дивидикус пытается сдержать слезы.*$B$BЕсли ты долго сражаешься с кем-то плечом к плечу, то он становится тебе дороже, чем брат.' FROM `quest_offer_reward` WHERE `ID`=10058 AND MD5(`RewardText`)='d622634ed5e91b9c533e9282b5c42aa8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10058 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10063, 'ruRU', 'Так я и думал! Между прочим, этот старый ворчливый тип должен был мне помочь с оборудованием и сбором информации. Как же! Двадцать раз! Конечно, ему гораздо больше нравится торчать в этом дренейском городе и надираться в стельку!' FROM `quest_offer_reward` WHERE `ID`=10063 AND MD5(`RewardText`)='11f989d06074c3f8cac18eb9d6bcfd4b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10063 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10064, 'ruRU', 'Я надеялась, что как только на Кровавой заставе поймут, что нам противостоит, к нам пришлют подкрепления.' FROM `quest_offer_reward` WHERE `ID`=10064 AND MD5(`RewardText`)='e8add1e2a8e0a4e06346cc387f9a3319' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10064 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10065, 'ruRU', 'Похоже, вокруг стало поспокойнее... А все-таки, может, лучше остаться здесь и дождаться лекаря?' FROM `quest_offer_reward` WHERE `ID`=10065 AND MD5(`RewardText`)='7f3cdf3cbbf34adff4dae4b40472fe50' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10065 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10068, 'ruRU', 'Я ждал тебя, $c.У меня есть несколько поручений, для выполнения которых ты подходишь как нельзя лучше.' FROM `quest_offer_reward` WHERE `ID`=10068 AND MD5(`RewardText`)='a737a57c382eab4a584f3881fa038048' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10068 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10070, 'ruRU', 'Я ждал тебя, $c.У меня есть несколько поручений, для выполнения которых ты подходишь как нельзя лучше.' FROM `quest_offer_reward` WHERE `ID`=10070 AND MD5(`RewardText`)='39748bbc84e08c1bf3f2954af84aa8d2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10070 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10071, 'ruRU', 'Я ждал тебя, $c.У меня есть несколько поручений, для выполнения которых ты подходишь как нельзя лучше.' FROM `quest_offer_reward` WHERE `ID`=10071 AND MD5(`RewardText`)='39748bbc84e08c1bf3f2954af84aa8d2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10071 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10074, 'ruRU', 'Замечательно, $N. Это очень поможет нам в битве с мерзавцами из Альянса, которые недавно появились в Запределье.' FROM `quest_offer_reward` WHERE `ID`=10074 AND MD5(`RewardText`)='24539e09763ea7e7b5e023bb1c46f3bb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10074 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10078, 'ruRU', 'Вот это сила духа!$B$BЯ рад, что мы наконец получили подкрепление, но я не уверен в их отношении к Орде. На моей родине считают врагом любого, кто поднял на тебя руку, а с врагом у нас разговор короткий!' FROM `quest_offer_reward` WHERE `ID`=10078 AND MD5(`RewardText`)='af5d52265e9b73810842477ecc107917' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10078 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10086, 'ruRU', 'Отличный материал! Здесь немного покореженный, здесь малость обгорелый, но даже из этого старья я сооружу отличную взрывчатку.\n\nСпасибочки, $N. Сразу видно, что ты знаешь толк в мусоре!' FROM `quest_offer_reward` WHERE `ID`=10086 AND MD5(`RewardText`)='e0f53c030ca2a3fb001e208060447e0a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10086 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10087, 'ruRU', 'Так я и думал! Отсюда, конечно, было ничего не разглядеть, но могу представить, как оно взрывалось. Прелестно, просто прелестно!\n\nНеплохая работенка, $N В Траллмаре будут рады слышать о твоих подвигах.' FROM `quest_offer_reward` WHERE `ID`=10087 AND MD5(`RewardText`)='ad6f2773b61baa96bcad2aa9c9d5db01' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10087 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10093, 'ruRU', 'А, ты знаешь провидца Крива. Он мудр и обладает многими добродетелями. Любой |3-6($r), который зовет его другом, станет другом и мне.$B$BРасполагайся здесь. Можешь познакомиться с остальными обитателями храма.' FROM `quest_offer_reward` WHERE `ID`=10093 AND MD5(`RewardText`)='f01915042a7d746b0a8fc83d640fb9ed' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10093 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10096, 'ruRU', 'Отлично! Эти болотные твари не имеют никакого права захватывать дом спорлоков!$b$bКонечно, было бы лучше, если бы эти существа научились мирному сосуществованию, но, раз уж это невозможно, нам следует взять дело в свои руки!$b$bВот, пожалуйста, возьмите это в благодарность за труды.' FROM `quest_offer_reward` WHERE `ID`=10096 AND MD5(`RewardText`)='33cf91b31cd1a208cc62b5a6bfcf76a8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10096 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10099, 'ruRU', 'Я так рад, что ты $gсмог:смогла; позаботиться о...о... Как, ты говоришь, оно себя называло? З\'Крел?$B$BПо твоему описанию я не смог понять, какого оно пола. Но это совершенно не важно, раз оно уже дохлое.' FROM `quest_offer_reward` WHERE `ID`=10099 AND MD5(`RewardText`)='394ee7a4b537b238e559287ff4b00226' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10099 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10103, 'ruRU', 'Откровенно говоря, я ожидал большего, но и для тебя дело найдется. Добро пожаловать на Заставу Болотной Крысы!' FROM `quest_offer_reward` WHERE `ID`=10103 AND MD5(`RewardText`)='9792badc26f5e31dea68d775a612da3e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10103 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10104, 'ruRU', 'Я, разумеется, польщён тем, что твой друг-сломленный считает меня специалистом по реликвиям его народа, но, если честно, с тех пор, как я сюда прибыл, у меня почти не было возможности их изучать. Конечно, я явился сюда именно ради них, но по прибытии обнаружилось, что здесь есть много куда более важных дел...' FROM `quest_offer_reward` WHERE `ID`=10104 AND MD5(`RewardText`)='20525b62438d7e28b3d266708410e73b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10104 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10106, 'ruRU', 'Ты славно потрудился, $N. Благодаря твоим ратным подвигам мы еще долго продержимся на Полуострове Адского Пламени!' FROM `quest_offer_reward` WHERE `ID`=10106 AND MD5(`RewardText`)='e00461733e1229071533055528d50d62' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10106 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10110, 'ruRU', 'Славная работа, $N. Я как наяву слышу звуки битвы, которая там разыгралась. Хотела бы я это видеть своими глазами!' FROM `quest_offer_reward` WHERE `ID`=10110 AND MD5(`RewardText`)='8b8f09476c8a12ed5e0f2fdbb563c564' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10110 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10116, 'ruRU', 'Неплохо! До тебя были и другие, кто надеялся получить награду, но они так и не вернулись за ней. Нетрудно представить, что с ними стало.$b$bЯ рад, что Муммаки и его ублюдки больше не будут нас тревожить.' FROM `quest_offer_reward` WHERE `ID`=10116 AND MD5(`RewardText`)='525cff6a7e148efa9021bdcd363067ba' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10116 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10119, 'ruRU', 'Добро пожаловать в Запределье, $N, добро пожаловать в кошмар! Хотя изначально экспедиционные войска благополучно добрались досюда, ныне Легион пытается отбить Темный портал и не дать нам получать подкрепление с другой стороны.$B$BХотя нам не помешала бы твоя помощь, но все же наши войска и солдаты Орды все еще способны дать отпор взводам Легиона, которые постоянно пытаются захватить этот плацдарм.$B$BТвои таланты необходимы там, где им найдется наилучшее применение.' FROM `quest_offer_reward` WHERE `ID`=10119 AND MD5(`RewardText`)='24788c1dc265eda069a6b73cf4b75c72' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10119 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10120, 'ruRU', 'Значит, теперь ты новый посланник Ориона. Надеюсь, ты стоишь больше, чем предыдущие, |3-6($C). Легион постоянно нас атакует, и идти пешком до Траллмара лучше даже не пробовать. Ничего, моя испытанная виверна доставит тебя, куда скажешь, и волос с головы не упадет.' FROM `quest_offer_reward` WHERE `ID`=10120 AND MD5(`RewardText`)='5f21b9b6b187ba5f5b0709d76e1d1f92' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10120 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10121, 'ruRU', 'Несомненно, ты видел войска Легиона с воздуха, когда летел от Темного портала. Лет пять назад мы разгромили их в битве за гору Хиджал, но проклятые демоны снова ползут сюда, как тараканы. Если они хотят войны, то они ее получат!\n\nУ нас, орков, солидный счет к Легиону. Что, $N? Рассказать тебе о наших врагах?' FROM `quest_offer_reward` WHERE `ID`=10121 AND MD5(`RewardText`)='b74116e3d46f35aec9d4390151d023a4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10121 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10123, 'ruRU', 'Славная работа, солдат! Могу сказать точно, частота атак сократилась, – хотя бы на время, пока они не призовут новых повелителей Ужаса.\n\nА теперь плохие новости: у меня для тебя новое задание.' FROM `quest_offer_reward` WHERE `ID`=10123 AND MD5(`RewardText`)='b9366ce2a1efc55afd139421862a8594' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10123 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10124, 'ruRU', 'Да ты, оказывается, один из тех, кто участвовал в зачистке лощины Вспышки Скверны? Приятно слышать. Нам нужны солдаты, способные отправить демонов обратно в Преисподнюю!' FROM `quest_offer_reward` WHERE `ID`=10124 AND MD5(`RewardText`)='84fc75c5979128acf31afff25c3fa90e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10124 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10129, 'ruRU', 'Теперь они долго не сумеют оклематься! Просто фантастика, $N Такого яростного сопротивления Легион точно не ждал!' FROM `quest_offer_reward` WHERE `ID`=10129 AND MD5(`RewardText`)='c8f99b2b7ab94920afada0956f2ca304' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10129 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10132, 'ruRU', 'Хорошо сработано.$B$BЯ считаю, что если мы уничтожим достаточно горных великанов, то можно не беспокоиться о кристалле, который свалился на самую середину хребта.$B$BПрими этот небольшой дар от Кенарийской экспедиции.' FROM `quest_offer_reward` WHERE `ID`=10132 AND MD5(`RewardText`)='e782d9ea01a4760ef94703268515ad17' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10132 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10134, 'ruRU', 'Хммм... На вид просто глыба необработанного кристалла.$B$BПравда, я чувствую некую ауру зла, которая его окружает, но такими вещами я не занимаюсь. Я должен очистить это место от горных великанов, остальное – не мое дело.' FROM `quest_offer_reward` WHERE `ID`=10134 AND MD5(`RewardText`)='ceddc22a789b04361393805b3b5cc01e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10134 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10140, 'ruRU', 'Наша экспедиция едва сдвинулась с места в этом заброшенном, проклятом мире, $n. Мы оказались не готовы к сопротивлению.$B$BСтолкнуться лицом к лицу с Пылающим Легионом еще не так страшно – ужасы этой земли превосходят все, что нам раньше встречалось.' FROM `quest_offer_reward` WHERE `ID`=10140 AND MD5(`RewardText`)='8db62475abd0823e8bcc26dcff96e737' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10140 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10141, 'ruRU', 'Должно быть, командир армии Данат не получил моей просьбы о подкреплении. Ты выглядишь $gгодным:годной; для службы, но я просила целый батальон!$B$BПонимаешь, у нас тут небольшая проблема с демонами...' FROM `quest_offer_reward` WHERE `ID`=10141 AND MD5(`RewardText`)='8335b41b31e4b66d100642e6904e59c5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10141 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10142, 'ruRU', 'Славная работа, солдат! Могу сказать наверняка, что частота атак сократится, – по крайней мере до тех пор, пока они не призовут новых повелителей Ужаса.$B$BА теперь плохие новости: у меня есть для тебя новое задание.' FROM `quest_offer_reward` WHERE `ID`=10142 AND MD5(`RewardText`)='16b4b1c453c7f6b09614492b5097504b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10142 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10143, 'ruRU', 'Рад тебя видеть, солдат!$B$BОднако хватит болтовни, слушай меня внимательно – для тебя есть важное задание, и я хочу, чтобы ты не только его успешно $gвыполнил:выполнила;, но еще и $gвернулся живым:вернулась живой;!' FROM `quest_offer_reward` WHERE `ID`=10143 AND MD5(`RewardText`)='a574438a8aa7ddba7e1e4572e64c3504' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10143 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10144, 'ruRU', 'Отлично, $n. Без порталов к Легиону не скоро придет подкрепление.$B$BНо мы не можем позволить себе отдыхать...' FROM `quest_offer_reward` WHERE `ID`=10144 AND MD5(`RewardText`)='20e566d9633f6159f059b07acf627d71' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10144 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10159, 'ruRU', 'Теперь, когда опустошителей не стало, добираться до Кенарийского оплота в Зангартопи стало куда безопасней.$B$BКенарийская экспедиция в долгу перед тобой.' FROM `quest_offer_reward` WHERE `ID`=10159 AND MD5(`RewardText`)='3a048303524e5254c60825f6150b32e7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10159 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10160, 'ruRU', '*Лейтенант Амади кивает.*$B$BОтлично, мы рады любой помощи. Меня беспокоит увеличение численности орков Скверны в Южном бастионе. Я отправила туда разведчика, но он до сих пор не вернулся.' FROM `quest_offer_reward` WHERE `ID`=10160 AND MD5(`RewardText`)='2f847f58505cd4e39520b7890be93f7c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10160 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10161, 'ruRU', 'Часть из них в ужасном состоянии, но с остальными можно работать. Немного фантазии, и я уверен, эта штука еще поднимется в воздух!' FROM `quest_offer_reward` WHERE `ID`=10161 AND MD5(`RewardText`)='8ac347053b56f5ba6062c16dbff65c06' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10161 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10162, 'ruRU', 'Ты летаешь так, будто занимался этим всю жизнь, $N Я восхищаюсь твоим умением! На вивернах ни царапины!' FROM `quest_offer_reward` WHERE `ID`=10162 AND MD5(`RewardText`)='6b065753e5c5f22e7b1dac8a428d97c9' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10162 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10177, 'ruRU', 'Ты появился очень вовремя.\n\nМелиcа давным-давно обещала прислать подкрепление. А сражаемся мы здесь еще дольше...' FROM `quest_offer_reward` WHERE `ID`=10177 AND MD5(`RewardText`)='10d4f1b2f9b7cf580ddaa6ce5d9dbaf8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10177 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10180, 'ruRU', 'Я должен был догадаться, что это он отправил тебя за мной. Он пытался отговорить меня от возвращения в Сетеккские залы, но разве я смогу жить спокойно, если позволю Лакке погибнуть там?' FROM `quest_offer_reward` WHERE `ID`=10180 AND MD5(`RewardText`)='836e8ca14f81a504c7611d4e9813e76a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10180 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10185, 'ruRU', 'Блюститель выглядит встревоженным.\n\nЯ уже вижу новую волну, вздымающуюся на горизонте. Истребление этих тварей поможет лишь на некоторое время, однако нужны более действенные меры.' FROM `quest_offer_reward` WHERE `ID`=10185 AND MD5(`RewardText`)='64c90261271a9ea454a6c04f08ccf1e3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10185 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10186, 'ruRU', 'Ха! Выглядят достаточно грубо. Может быть, мы сможем их использовать в многоцелевой камере третьей ступени двигателя. \n\nИ все же это хорошая работа, младший лаборант 3-ей степени! Похоже, ты очень скоро заслужшь 2-ю степень!' FROM `quest_offer_reward` WHERE `ID`=10186 AND MD5(`RewardText`)='00bb6543194fd4a8375eeb30db3a8018' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10186 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10188, 'ruRU', 'О, эта печать осталась такой же великолепной, какой я ее запомнил. Разве ты не чувствуешь силу, которую она излучает?\n\nКонечно, нужно сделать еще очень многое, но я благодарен тебе за возвращение печати.' FROM `quest_offer_reward` WHERE `ID`=10188 AND MD5(`RewardText`)='93785174b314de3d18585c6d862b62b9' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10188 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10208, 'ruRU', 'Просто прекрасно! Я, можно сказать, чуть ли не самолично почувствовал, как земля содрогнулась от взрыва!\n\nКак насчет еще одной подрывной работенки?' FROM `quest_offer_reward` WHERE `ID`=10208 AND MD5(`RewardText`)='9bb2a841a1e6b5c11bfdeab57508c17d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10208 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10210, 'ruRU', 'Когда вы приблизились к А\'далу, вас пронизал внутренний свет, а когда вы обратились к нему, свет усилился и в голове зазвучала нежная мелодия.\n\nЗдесь вы в безопасности.' FROM `quest_offer_reward` WHERE `ID`=10210 AND MD5(`RewardText`)='779f8aa6d1ec879023a5ecf60f55a492' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10210 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10213, 'ruRU', 'Нас подбил Пылающий Легион, хотя мы и размахивали белым флагом. Кто же знал, что они там такие тупые ублюдки?\n\nК сожалению, мы не сможем отправиться на Заставу Хребтолома. Надо чиниться и двигаться дальше.' FROM `quest_offer_reward` WHERE `ID`=10213 AND MD5(`RewardText`)='bf00bbed2d32037e6fa17d7ac597f7f4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10213 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10220, 'ruRU', 'Пусть эти Непреклонные знают, как иметь дело с Ордой! Не сомневаюсь, скоро они согласятся перейти на нашу сторону.' FROM `quest_offer_reward` WHERE `ID`=10220 AND MD5(`RewardText`)='bc4a9f0b52e22df70b1df273588ce32b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10220 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10222, 'ruRU', 'Пусть даже сделанное тобой не сможет вернуть к жизни павших, но, быть может, даст покой их душам. Хотя, правду сказать, даже море крови не угасит мой гнев, вызванный деяниями Кель\'таса.' FROM `quest_offer_reward` WHERE `ID`=10222 AND MD5(`RewardText`)='c8c32998ecc7bd51b33192c29ee3f4ca' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10222 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10223, 'ruRU', '<Может быть, тебе и кажется, но похоже, что комендант Смертехрон с трудом сдерживает слёзы.>$B$BНаконец-то это свершилось. Если бы я мог по собственной воле завершить свое существование, я бы сделал это, но истина в том, что я не знаю, как уйти. Для обитателей деревни это сложно, однако всё впереди. Я полагаю, такова цена, которую мы платим за сильную привязанность к этому месту.' FROM `quest_offer_reward` WHERE `ID`=10223 AND MD5(`RewardText`)='1c08026270485bb78025453bea9c360e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10223 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10224, 'ruRU', 'Ого, тут полно эссенции!\n\nОтлично, посмотрим, что будет, когда я смешаю ее с астраллитиевыми матричными кристаллами.' FROM `quest_offer_reward` WHERE `ID`=10224 AND MD5(`RewardText`)='f15ddabab80bae2d3e4d51a6e761ebc7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10224 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10227, 'ruRU', 'Ребёнок прав. Когда-то я в самом деле был "жрецом мертвых".$B$B<Рамдор кривится.>$B$BМалоприятный титул.$B$BЭтот коридор ведёт в Аукенайские гробницы. Там, внутри, ты найдёшь то, что осталось от моей паствы. Разумеется, теперь все они совершенно безумны. Сошли с ума, все до единого. Очевидно, я слишком выделялся среди них, будучи единственным, кто сохранил хотя бы остатки здравого смысла. Конечно же, меня изгнали за мои убеждения.$B$BХочешь знать, за какие?' FROM `quest_offer_reward` WHERE `ID`=10227 AND MD5(`RewardText`)='e2da18f891b267cda1da08be7a96af3e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10227 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10228, 'ruRU', 'Книга мертвых? Никогда о такой не слышал... О чем вообще речь? Кто тебя прислал?' FROM `quest_offer_reward` WHERE `ID`=10228 AND MD5(`RewardText`)='1de80d43b3fc5bc817e25128e4ef3913' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10228 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10229, 'ruRU', 'Я изучаю историю древних всю свою жизнь, но не видел ничего похожего на эту книгу. В ней изложена вся история Оружейной, даже то, что произошло после ее разрушения.\n\nТела Непреклонных остались лежать на поле сражения, но они все равно продолжали вести свою летопись. Эта книга должна нам помочь понять Непреклонных, и уговорить их вступить в наши ряды.' FROM `quest_offer_reward` WHERE `ID`=10229 AND MD5(`RewardText`)='3f6aca0cd77af83c112f2127d1b4ad86' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10229 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10230, 'ruRU', 'Ты хорошо потрудился, $N Этот древний рог позволит нам призывать Непреклонных.\n\nКонечно, если они согласятся.' FROM `quest_offer_reward` WHERE `ID`=10230 AND MD5(`RewardText`)='babfbd5384cecc1f8b95dcdf7688ef00' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10230 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10231, 'ruRU', 'Ладно, хватит, больно же! У нас была какая-то книга, но мы ее сбагрили...' FROM `quest_offer_reward` WHERE `ID`=10231 AND MD5(`RewardText`)='23a5f660ab55433af69907c5b5108fbc' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10231 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10241, 'ruRU', 'Превосходная работа, $N! Благодаря твоим отвлекающим действиям Провидцы сумели добыть ценные сведения. Может быть, на этот раз они действительно поделятся этими сведениями с нами.' FROM `quest_offer_reward` WHERE `ID`=10241 AND MD5(`RewardText`)='2a02568f23a021f0bbc46b7b8656c4b9' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10241 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10242, 'ruRU', 'Протестировать образец крови, да? С превеликим удовольствием! Работать с кровью всегда приятно...' FROM `quest_offer_reward` WHERE `ID`=10242 AND MD5(`RewardText`)='a8d7c5b465ea058349c581f71b33d877' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10242 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10243, 'ruRU', 'Ты разворачиваешь символ и готовишься скопировать странные символы.' FROM `quest_offer_reward` WHERE `ID`=10243 AND MD5(`RewardText`)='b987b17eae3a9f70e4555df4e9bd542e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10243 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10245, 'ruRU', 'Неплохая работа, $N. Подожди минуту, я прогляжу это описание. \n\nЖречество благодарно тебе, $C.' FROM `quest_offer_reward` WHERE `ID`=10245 AND MD5(`RewardText`)='ea33a962517e9abe5df963a587c8ccbb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10245 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10250, 'ruRU', 'Я рад слышать, что Непреклонные присоединились к тебе в битве. Я предполагал, что они придут на звук своего старого боевого рога, но не был в этом уверен. Возможно, мы дали им насытиться местью, которой они так жаждали.\n\nО твоей победе над Уртраком необходимо доложить командиру Хогарту в Оружейную Экспедиции. Он должен знать, чем ты рисковал ради нас.' FROM `quest_offer_reward` WHERE `ID`=10250 AND MD5(`RewardText`)='118365b07ddf0fceb1ce48c2ab7942a0' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10250 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10251, 'ruRU', 'Я видел, к чему все идет, но предпочитал не обращать внимания.\n\nС каждым днем влияние Легиона все усиливается... даже в наших краях.\n\nЕсли бы я знал... Если бы я знал, что мой мальчик свяжется с демонами... Они пообещали ему силу и дали вкусить ее... Этого ему хватило.\n\nИ вот, книга утеряна для нас. Теперь она у Левиксуса. Об его планах известно только мне и его темному владыке.\n\nО странник, я не знаю, следуешь ли ты путем добра, но того, кто служит демонам, надо остановить любой ценой!' FROM `quest_offer_reward` WHERE `ID`=10251 AND MD5(`RewardText`)='cc6271f20ea5b5229f15b55d67abf824' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10251 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10252, 'ruRU', 'Странник... Я не сказал тебе всей правды. Как только ты выпьешь это зелье, ты отныне и навсегда обретешь способность видеть мир духов. Это питье давали жрецам мертвых Аукиндона во время инициации. Многие после этого сходили с ума... Видеть мертвых – это тяжелое испытание для живущего.\n\nНитрин подносит зелье к вашим губам\n\nТы не боишься?' FROM `quest_offer_reward` WHERE `ID`=10252 AND MD5(`RewardText`)='30cbb075dfb5a5cb76f40336a60b51a5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10252 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10253, 'ruRU', 'Старый дреней велел тебе уничтожить книгу. Так почему ты этого не сделал, а?\n\nРамдор бросает на вас мрачный взгляд\n\nА-а... Вот в чем дело. Может быть, ты и жадный, зато честный.\n\nЯ же, надо сказать... Я солгал, чтобы завладеть этой книгой. Понятия не имею, где эти бедные духи хранят свои сокровища, а если знал бы – все равно не сказал. Впрочем, у меня найдется кое-что для тебя. Возможно, кое-что весьма стоящее. Не бойся, ты не останешься без награды.\n\nКстати, добро пожаловать в нашу компанию!\n\nРамдор указывает на духов.' FROM `quest_offer_reward` WHERE `ID`=10253 AND MD5(`RewardText`)='bb1d52dcc7ee329e00a1e960ca4db27f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10253 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10254, 'ruRU', 'Добро пожаловать, $gбрат:сестра;. Я рад тебя видеть. Мое имя Данат, я предводитель Сынов Лотара и боевой командир этой крепости.' FROM `quest_offer_reward` WHERE `ID`=10254 AND MD5(`RewardText`)='038994377f4c6ba64cba263a3826501b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10254 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10258, 'ruRU', 'Когда-то давно мы потерпели поражение от орков Скверны. Убив Уртрака, ты вернул нам хотя бы часть утраченной славы.\n\nПрими в награду это оружие. Обнажи его, когда будешь сражаться с нашими злейшими врагами, и тогда те из нас, кто свободен от проклятья, придут тебе на помощь.\n\nПока ты еще не ушел, – погибшие во время осады тоже хотят поблагодарить тебя.' FROM `quest_offer_reward` WHERE `ID`=10258 AND MD5(`RewardText`)='8ca9884773db2182a47f7d3ca0cb70af' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10258 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10262, 'ruRU', 'Эти знаки отличия – хорошее начало.\n\nК несчастью, за время твоего пребывания в Груде еще один мой агент в Заксис сообщил мне, что астральный налетчик Несаад все еще жив!' FROM `quest_offer_reward` WHERE `ID`=10262 AND MD5(`RewardText`)='8a1b64d4a8c2d362f7a5732867ea73eb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10262 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10278, 'ruRU', 'Невероятно. Тебе удалось прикоснуться к самой пустоте! $N ты спас дело всей моей жизни. Но, если ты и правда хочешь помочь мне, мы должны сделать еще многое и многое.' FROM `quest_offer_reward` WHERE `ID`=10278 AND MD5(`RewardText`)='939c2d9df8850251522084bf917ff0f1' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10278 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10284, 'ruRU', 'Тебе удалось совершить невозможное, $N. К сожалению, юный вождь этого не запомнит. В его памяти должны остаться только те события, которые случились бы, не будь искажения линии времени... Андорму ждет тебя в логове нашего господина.' FROM `quest_offer_reward` WHERE `ID`=10284 AND MD5(`RewardText`)='24aac0cf4574e2820f4ff135cdc6e193' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10284 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10285, 'ruRU', 'Прими этот дар от бронзовых драконов. Он поможет тебе в путешествиях во времени.' FROM `quest_offer_reward` WHERE `ID`=10285 AND MD5(`RewardText`)='15f58fbd95d28b61d4ed58472fb89bd5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10285 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10286, 'ruRU', 'Я все расскажу, $C. Опусти оружие, у меня и так проблем хватает.' FROM `quest_offer_reward` WHERE `ID`=10286 AND MD5(`RewardText`)='f2997de443d1e7b3bac57b8faebe5aed' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10286 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10287, 'ruRU', 'Виера Шепот Солнца? Эта маленькая дрянь?\n\nНу я ей покажу, как переходить мне дорогу!' FROM `quest_offer_reward` WHERE `ID`=10287 AND MD5(`RewardText`)='962e7d94e7fc5c4c3563da498dc74b12' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10287 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10288, 'ruRU', 'Донесение в Оплот Чести? Без проблем. Мой грифон доставит тебя туда в целости и сохранности.' FROM `quest_offer_reward` WHERE `ID`=10288 AND MD5(`RewardText`)='c6688bfddde7154b5c492645f1b6e9f5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10288 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10289, 'ruRU', 'Я соберу все доступные резервы и отправлю их к Темному порталу, на помощь Ориону. Легион не скоро забудет боевой клич Орды! Что касается тебя, $N, то ты оказал Траллмару великую услугу. Я надеюсь, ты сможешь помочь нам и здесь... Если у тебя хватит ума остаться в живых, конечно же...' FROM `quest_offer_reward` WHERE `ID`=10289 AND MD5(`RewardText`)='b758467377530c5e92ae0c04c1fee13f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10289 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10295, 'ruRU', 'Ты спасла работу всей моей жизни, $N.\n\nМеня называют безумцем и смеются надо мной, говорят, что я одержим Пустынной Грядой и Кривыми Полями. Теперь, с этим осколком души, я открою все секреты демонов Бездны. Силы Бездны будут повиноваться мне!' FROM `quest_offer_reward` WHERE `ID`=10295 AND MD5(`RewardText`)='0c87e3b45104aa52285d7ff0070c0fbd' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10295 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10296, 'ruRU', 'На самом деле, если бы в Азерот не пришли орки, то никакого Альянса и не было бы. В конечном итоге началась бы гражданская война, которая ослабила бы человеческие королевства.\n\nИ Пылающий Легион захватил бы растерзанный междоусобицами беззащитный Азерот.' FROM `quest_offer_reward` WHERE `ID`=10296 AND MD5(`RewardText`)='4640859cd21a33fc1d27e0d377f65b58' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10296 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10298, 'ruRU', 'Ты снова спас прошлое и будущее этого мира, $N. Мы благодарны тебе и просим принять эту скромную награду.' FROM `quest_offer_reward` WHERE `ID`=10298 AND MD5(`RewardText`)='0e601c187673787e5546359b8133aa86' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10298 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10299, 'ruRU', 'Свет улыбается тебе, $N. Мы все молились за твой успех.' FROM `quest_offer_reward` WHERE `ID`=10299 AND MD5(`RewardText`)='406cd65b3d39582809287f7ea2df9cd0' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10299 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10302, 'ruRU', 'Так быстро? Что ж, отлично. Надеюсь, скоро я придумаю, как справляться с этими мутантами, не убивая их.$b$bУ меня появилась пара идей, но без твоей помощи мне не обойтись.' FROM `quest_offer_reward` WHERE `ID`=10302 AND MD5(`RewardText`)='bc731d9b6d5894adf448bb61d912369d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10302 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10303, 'ruRU', 'Эльфы крови хотят убить нас всех. Как бы им помешать?' FROM `quest_offer_reward` WHERE `ID`=10303 AND MD5(`RewardText`)='47cdbf946f597f81c6aa6537a70cdbdc' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10303 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10304, 'ruRU', 'Тебя $n зовут, верно? Я слышал про тебя много хорошего. Ты успел принести своему народу немало пользы.$b$bИ нам без твоей помощи тоже не обойтись. Например, Жанае срочно нужен подручный. Вон она стоит.' FROM `quest_offer_reward` WHERE `ID`=10304 AND MD5(`RewardText`)='d2c7c769d4eafa5a9730d8beb6795f2d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10304 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10305, 'ruRU', 'Ах, да. Я слышал, что у клятвопреступницы Белмары была древняя книга историй, но я и понятия не имел, что она взяла ее с собой в Запределье. Я уверен, что душа Белмары будет спать спокойно, зная, что книга нашлась и возвращена на свое место.' FROM `quest_offer_reward` WHERE `ID`=10305 AND MD5(`RewardText`)='6e39bf34ad999f666aa373ba8a67a65d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10305 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10306, 'ruRU', 'Мы всегда отмечали, что Люминрат носит этот плащ поверх практически любой одежды. Красный цвет для него в равной степени сочетался с белым, черным, пурпурным, синим, желтым, оранжевым и зеленым. Он никогда не носил одно облачение два дня подряд, но плащ был на нем всегда...' FROM `quest_offer_reward` WHERE `ID`=10306 AND MD5(`RewardText`)='0a3f353aa71d582c4f5818f6c353544c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10306 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10307, 'ruRU', 'Блюститель улыбается при упоминании имени Колиена.\n\nНасчет шляпы – все именно так. Он все время носил ее, а если снимал, то не спускал с нее глаз.\n\nПару раз один из его товарищей-магов, оставшийся неизвестным, "заимствовал" шляпу и прятал ее – просто в шутку. Но угроза получить от Колиена одну из его ледяных стрел заставила его отказаться от подобных шуток.\n\nЯ буду скучать по маленькому Колиену. Он умел найти подход к эльфийским дамам.' FROM `quest_offer_reward` WHERE `ID`=10307 AND MD5(`RewardText`)='d04bdde292161627a48254076342e180' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10307 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10313, 'ruRU', 'Это мрачные новости, $N. Уровень энергии Искажения, излучаемой трубопроводами, опасно высок.\n\nМы должны найти способ закрыть Манагорн, иначе то немногое, что осталось от Запределья, разлетится на кусочки.' FROM `quest_offer_reward` WHERE `ID`=10313 AND MD5(`RewardText`)='4e3bf849f9dbea60d1d575bc888fcb02' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10313 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10316, 'ruRU', 'Светящийся шар установлен на вершине квадратного пьедестала. С первого взгляда он кажется просто вместилищем магической энергии, однако какой именно энергии? И кто ею пользуется?' FROM `quest_offer_reward` WHERE `ID`=10316 AND MD5(`RewardText`)='203a18f7196af654875847c14e1b0047' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10316 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10324, 'ruRU', 'Чудесно! Ты становишься настоящим охотником, $n.$B$BХочешь выглядеть, как я? Почему бы и нет! Пока ты $gохотился:охотилась;, я сделал несколько предметов из оленьих шкур. Выбирай любой!' FROM `quest_offer_reward` WHERE `ID`=10324 AND MD5(`RewardText`)='0d9f6c79a097ef92dd480089935014a4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10324 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10325, 'ruRU', 'Сражаться с демонами Пылающего Легиона и культистами, которые им поклоняются, – задача не из легких, $N, но у вас достаточно смелости и решительности. Продолжайте в том же духе, и отношение Алдоров к вам будет постоянно улучшаться.' FROM `quest_offer_reward` WHERE `ID`=10325 AND MD5(`RewardText`)='dd019315aad62ff19f50db27c1fa2c76' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10325 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10331, 'ruRU', 'Хвала небесам! Теперь я могу вернуться к работе. Я знаю, ты думаешь, будто я сумасшедший, поскольку работаю над изделием, которое принесет мне статус подмастерья, не в кузнице, как положено, а едва ли не в чистом поле. Но я не могу рисковать – вдруг остальные ученики скопируют мою разработку?' FROM `quest_offer_reward` WHERE `ID`=10331 AND MD5(`RewardText`)='d9323256a6bd1180bba3164112775118' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10331 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10332, 'ruRU', 'Мастер Ронсус научил меня всему, что я знаю о моем ремесле. Я почту его память тем, что использую свои умения на службе у живущих в Кирин\'Варе.' FROM `quest_offer_reward` WHERE `ID`=10332 AND MD5(`RewardText`)='8f238162c2fdff4bfe20cd39144afa42' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10332 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10334, 'ruRU', 'Достав колокольчик, ты несколько раз звонишь в него, потом показываешь его Бесси, которая, похоже, узнает этот предмет. Корова позволяет тебе завязать у нее вокруг шеи веревку и выжидательно смотрит на тебя.' FROM `quest_offer_reward` WHERE `ID`=10334 AND MD5(`RewardText`)='6436bc53256b3cb1ab235e711c2fc50d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10334 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10340, 'ruRU', 'Ха-ха-ха! $GСвеженький:Свеженькая:r; |3-6($r) с большой земли! Не боись, сначала тебя малость поукачивает, а потом перестанет.$B$BНа моем веку застава опрокидывалась только один раз. Ну... максимум два.' FROM `quest_offer_reward` WHERE `ID`=10340 AND MD5(`RewardText`)='10bde79cc1fb055d5cc101080e3fad4e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10340 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10343, 'ruRU', 'Мана-бомба?\n\nМорран вертит фрагмент в руках.\n\nЭто непредставимо! Даже самые светлые умы Даларана не могли придумать подобное оружие. Резкое усиление возмущений, должно быть, создало разрыв в Пустоте, позволив этим тварям проникнуть в наши земли.' FROM `quest_offer_reward` WHERE `ID`=10343 AND MD5(`RewardText`)='0aa8fc23d319f5ea02ab184f5fa48e07' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10343 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10344, 'ruRU', 'Ты $gговорил:говорила; c Рунтогом? Отличный дворф! Он хорошенько следит за своими грифонами, они должны быть всегда готовы к бою.$B$BЯ Грифонгар, я здесь самый главный. Может, тут не очень уютно, зато эта скала – важнейший опорный пункт для налетов на полуостров. Видишь грифонов, которые все время снуют туда-сюда?$B$BМогу дать совет, если хочешь. Держи вещмешок наготове, желудок впроголодь и не спускай глаз с горизонта. А когда Парящую заставу начнет раскачивать, хватайся за то, что хорошо приколочено!' FROM `quest_offer_reward` WHERE `ID`=10344 AND MD5(`RewardText`)='e5d513c4541d254d82ba8cf6a5f6194a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10344 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10348, 'ruRU', 'Интересный выбор, не так ли? Эти целительные свойства должны быть поистине чудотворными. Я вкладываю кучу денег в такую невзрачную травку.' FROM `quest_offer_reward` WHERE `ID`=10348 AND MD5(`RewardText`)='fe0a9227dee854e61430e5d7d882dd6d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10348 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10349, 'ruRU', 'О, прекрасно! Я давно хотела заполучить кусок этого кристалла, но Тола\'тион все время ставил мне палки в колеса.$B$BОн должен помочь мне понять, что случилось на Гряде Упавшего неба, но способен лишь посылать простофиль вроде тебя – только без обид – на убой.$B$BОтдай мне этот кристалл. Думаю, я смогу найти связь между ним и горными гигантами.' FROM `quest_offer_reward` WHERE `ID`=10349 AND MD5(`RewardText`)='773620a45b7b136a37ad27491784c8cd' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10349 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10366, 'ruRU', 'Я давно тебя поджидаю, $n.$b$bТуллас превозносит тебя до небес, и я с радостью продолжу учить тебя пути Света. Я помогу тебе лучше разобраться в своих способностях и скрытом могуществе, когда ты будешь $gготов:готова;.' FROM `quest_offer_reward` WHERE `ID`=10366 AND MD5(`RewardText`)='6a84afb18a581fb0671898106952f962' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10366 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10382, 'ruRU', 'Рад встрече, |3-6($c). Наконец-то этот твердолобый Хрустик решил прислать нам хоть какую-то помощь!' FROM `quest_offer_reward` WHERE `ID`=10382 AND MD5(`RewardText`)='4da2d875dc5126eff8b3f37d1eb78cbc' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10382 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10388, 'ruRU', 'О, $N, ты как раз вовремя. Наши разведчики обнаружили, что Легион установил на гребне так называемые "Лагеря Легиона". Именно там демоны собирают своих адских скверноботов. Если мы проведем быструю атаку, то уничтожим все, что они успели сделать.' FROM `quest_offer_reward` WHERE `ID`=10388 AND MD5(`RewardText`)='059d58b4b7ecd11d2989a19594a76aa7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10388 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10390, 'ruRU', 'Отлично, $C. Одной головной болью меньше. У Пылающего Легиона займет немало времени снова доставить оборудование и наладить производство. А именно время и нужно нам больше всего.' FROM `quest_offer_reward` WHERE `ID`=10390 AND MD5(`RewardText`)='0256ca116f942fc4fa853bcfde714403' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10390 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10391, 'ruRU', 'Я знал, что на тебя можно положиться, $N, но на этот раз ты превзошла саму себя. Мы аж отсюда слышали, как взрываются эти проклятые пушки. Надеюсь, это научит Пылающий Легион не связываться с Сынами Дуротара!' FROM `quest_offer_reward` WHERE `ID`=10391 AND MD5(`RewardText`)='e195006fbf0c9f4eccfa44a92c1af709' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10391 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10392, 'ruRU', 'Хвала предкам, ты сделала это, $N! Легион потерпел сокрушительное поражение, Траллмар снова спасен! О, если бы у меня было сто воинов, обладающих подобной ловкостью и несгибаемым духом, я бы уже очистил от скверны эти проклятые земли! Позволь выразить мое восхищение.\n\n Назгрел отдает вам салют. ' FROM `quest_offer_reward` WHERE `ID`=10392 AND MD5(`RewardText`)='da17b7e85296b2b1901a0d05274bc525' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10392 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10393, 'ruRU', 'Молодец, что обратила мое внимание на это письмо. Это может быть заказ на дополнительное производство скверноботов, или даже планы новой атаки! Правда, расшифровка займет некоторое время. Ступай. Я повозу тебя, как только что-нибудь узнаю.\n\n Магистр кивает вам и оборачивается, чтобы уйти. \n\nА ты не промах, $N. Понаблюдать за тобой будет интересно.' FROM `quest_offer_reward` WHERE `ID`=10393 AND MD5(`RewardText`)='a6c649c0e176273d4f851385a58eddc5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10393 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10418, 'ruRU', 'Этот район уже выглядит более чисто. Эти сферы довольно полезны, но у них есть недостатки – они ускоряют рост некоторых местных видов животных и растений.' FROM `quest_offer_reward` WHERE `ID`=10418 AND MD5(`RewardText`)='7dad50ef151df69e24a254885503e924' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10418 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10424, 'ruRU', 'Эти результаты точно совпадают с тем, что получил Мердад. Но почему? Единственное возможное объяснение, которое приходит мне в голову – это то, что часть деталей генераторов сферы вышла из строя или пропала. Это может значительно ослабить защитное поле сферы и вызвать дисбаланс, как указывают все результаты диагностики.' FROM `quest_offer_reward` WHERE `ID`=10424 AND MD5(`RewardText`)='e39067031e025aa7e818b0903ea42b2b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10424 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10428, 'ruRU', 'Моя семья... Что я наделал... Но что я мог сделать?$b$BЗа что мне такие мучения?' FROM `quest_offer_reward` WHERE `ID`=10428 AND MD5(`RewardText`)='69098717f98c6d47a4ecc33b5240985d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10428 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10442, 'ruRU', 'О, слава богам, должно быть, тебя прислал на помощь Соколиный Дозор! \n\nОчень рада тебя видеть. У нас тут столько работы! У меня как раз есть дело, которое будет тебе по плечу для начала...' FROM `quest_offer_reward` WHERE `ID`=10442 AND MD5(`RewardText`)='b94241e07cc7affb559d0f35edfcfc6b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10442 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10443, 'ruRU', 'О, слава богам, должно быть, тебя прислали на помощь из Храма Телхамата! Я туда обращалась.$B$B' FROM `quest_offer_reward` WHERE `ID`=10443 AND MD5(`RewardText`)='705140507bea9d11925e26103f12c6d1' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10443 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10449, 'ruRU', 'А, да. Кровь орков из клана Костеглодов. Они вызывают у меня недоумение... С одной стороны, в них все еще чувствуется демоническая скверна, но их сила и мощь превосходит всякое разумение... \n\nХорошо, давайте приступим...' FROM `quest_offer_reward` WHERE `ID`=10449 AND MD5(`RewardText`)='a3abdac3a3bedea8812adf794784d5b3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10449 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10450, 'ruRU', 'Ага! Тебе все-таки повстречались наши ублюдочные сородичи Костеглоды. Похвально, $N. Одно плохо – их умерло слишком мало, чтобы пролитая кровь могла охладить мою ярость.' FROM `quest_offer_reward` WHERE `ID`=10450 AND MD5(`RewardText`)='c954e6d258e6c3ecb62232bf2da4093a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10450 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10482, 'ruRU', 'Очень хорошо. Я уверена, Цитадель Адского Пламени вскоре заметит эту потерю. Ее неприступная тень нависает над нами, но пока у нас есть подобные воины, есть и надежда на победу!' FROM `quest_offer_reward` WHERE `ID`=10482 AND MD5(`RewardText`)='5235c7f8a4057ccf5e22e48650288691' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10482 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10483, 'ruRU', 'Ты $gотбил:отбила; наш знак у орков Кровавой Глазницы? Это делает тебе честь. Отвратительно, эти краснокожие твари осмеливаются использовать против нас наши же знаки!' FROM `quest_offer_reward` WHERE `ID`=10483 AND MD5(`RewardText`)='573fcc790ee4ff01cf749cdf4a90f50b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10483 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10487, 'ruRU', 'Ты не только ослабил их оборону! Мы используем эту пыльцу для усиления собственной защиты от сил Альянса!' FROM `quest_offer_reward` WHERE `ID`=10487 AND MD5(`RewardText`)='26c8f610b0262d3a450e4b283cb621a0' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10487 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10488, 'ruRU', 'Теперь, когда ствоей помощью волки стали сильнее, а оборона Зазубренной гряды крепче, не обратиться ли нам к более трудным проблемам, вроде огров?\n\nТы нам тут хорошо помог. Если решишь остаться, то мы бы охотно еще не раз воспользовались твоей помощью.\n\nНо что бы ты ни решил, ты уже заслужил мое уважение и почет.' FROM `quest_offer_reward` WHERE `ID`=10488 AND MD5(`RewardText`)='16ff7b3a72516dd59d5277426fb01580' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10488 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10538, 'ruRU', 'Очень хорошо...Теперь проводить тесты станет гораздо проще...\n\nСпасибо, $N Твои таланты заслуживают уважения.' FROM `quest_offer_reward` WHERE `ID`=10538 AND MD5(`RewardText`)='49cec0a43cdaa28c1a2ae731deb581df' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10538 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10542, 'ruRU', 'Да, Тчали как раз об этом и говорил! Хотя я и не знаю, чего это огры туда намешали – в кальяне не любимый табачок Тчали.\n\nЛадно, Тчали все равно рад. Настолько рад, что готов попросить тебя еще кое-о чем.' FROM `quest_offer_reward` WHERE `ID`=10542 AND MD5(`RewardText`)='d0578737e39f89af1ff1cada083f4b54' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10542 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10543, 'ruRU', 'Т\'чали так рад, что Коргаах и Гримнок откинули копыта, как и он сам!\n\nНо Т\'чали еще не утолил жажду мести. Тебе надо сделать еще одну вещь!' FROM `quest_offer_reward` WHERE `ID`=10543 AND MD5(`RewardText`)='d6f8a5b2b46e6d92ca9a2a790d9f2454' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10543 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10544, 'ruRU', 'Ахххха, как сладка месть!\n\nНо Тчали видит, что ты хочешь уйти теперь, когда помог Тчали отомстить. Понимаю тебя... Жизнь для живых.\n\nВот что я тебе скажу – у Тчали в могиле есть еще много хороших штучек. Выбирай то, что тебе больше всего нравится!' FROM `quest_offer_reward` WHERE `ID`=10544 AND MD5(`RewardText`)='fdfb97482aa0fc38aacde12505b22af0' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10544 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10545, 'ruRU', 'Хорошие новости! Это пойло очень подойдет для следующей задумки Тчали, на которую тебя сейчас Тчали подобьет.' FROM `quest_offer_reward` WHERE `ID`=10545 AND MD5(`RewardText`)='bb753787df04b33e538cd4673ba34a23' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10545 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10553, 'ruRU', 'Кадгар прислал $Gновенького:новенькую;? Что ж, за работу, $C!' FROM `quest_offer_reward` WHERE `ID`=10553 AND MD5(`RewardText`)='72e1d1a7cd286fd56cf1aa1db66c949b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10553 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10554, 'ruRU', 'Добро пожаловать, $N. Я очень рада, что вы решили помочь нам. Да хранит вас Свет.' FROM `quest_offer_reward` WHERE `ID`=10554 AND MD5(`RewardText`)='abcfaea5a38f0e9e33434b914a34ca62' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10554 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10565, 'ruRU', 'Ах, посмотри, как он светится! Надо поработать над ним.' FROM `quest_offer_reward` WHERE `ID`=10565 AND MD5(`RewardText`)='11f4b043dcdf0207de4e717dc75e3453' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10565 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10566, 'ruRU', 'Эти сведения очень нам пригодятся, $N. Я улучшу свое изобретение, и посмотрим, не сумеем ли мы увеличить диапазон его действия.' FROM `quest_offer_reward` WHERE `ID`=10566 AND MD5(`RewardText`)='f0e193b7056173eae4f152f80b89ef22' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10566 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10568, 'ruRU', 'Таблички Баа\'ри! Это же неоценимый источник информации!' FROM `quest_offer_reward` WHERE `ID`=10568 AND MD5(`RewardText`)='da9b6c18e6f1c5832ac48e1e458a99be' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10568 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10615, 'ruRU', 'А, да, Дертрок. Мы с ним мимоходом говорили об этих араккоа. Должен сказать, что причина нашего... интереса к ним сильно различается.' FROM `quest_offer_reward` WHERE `ID`=10615 AND MD5(`RewardText`)='175110bc4313aab47cbb4eac30ac3681' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10615 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10617, 'ruRU', 'Хорошие коконы. Вижу, ты навострился их собирать.\n\nМы пробовали выращивать личинок шелкокрыла сами, но, к сожалению, эти малышки не могли вырабатывать достаточно шелка.' FROM `quest_offer_reward` WHERE `ID`=10617 AND MD5(`RewardText`)='cbacd5a29fe475c494aea5c700fe9323' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10617 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10618, 'ruRU', 'Спасибо тебе, $N. Мы сразу пустим их в дело – и глазом моргнуть не успеешь!' FROM `quest_offer_reward` WHERE `ID`=10618 AND MD5(`RewardText`)='e1e32dbba2059b56b08353cb3ccfdfc9' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10618 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10630, 'ruRU', 'Уф, все ган\'арги наконец убрались отсюда. Уже через неделю я собираюсь помахать всем платочком и отбыть в Пиратскую бухту. Жду не дождусь, когда наконец снова смогу отправиться на рыбалку. Приехав в Запределье, я совершил огромную ошибку! Послушай моего совета, убирайся и ты подальше отсюда. Можно приятно провести время в Тернистой долине, или, если любишь приключения, отправиться в Кратер Ун\'Горо. Главное, только не оставаться здесь!' FROM `quest_offer_reward` WHERE `ID`=10630 AND MD5(`RewardText`)='38df0b508b6e56e215c930fcec8b5a78' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10630 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10653, 'ruRU', 'Сражаться с демонами Пылающего Легиона и культистами, которые им поклоняются, – задача не из легких, $N, но у вас достаточно смелости и решительности. Продолжайте в том же духе, и отношение Алдоров к вам будет постоянно улучшаться.' FROM `quest_offer_reward` WHERE `ID`=10653 AND MD5(`RewardText`)='dd019315aad62ff19f50db27c1fa2c76' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10653 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10752, 'ruRU', 'Значит, Тандрис Ветропряд все еще считает, что мне нужна нянька? Надо бы ему напомнить, кто кого спасал – похоже, он забыл, что это я вытащила его из беды.$B$BНо хорошо, что ты сейчас здесь, |3-6($r), возможно, я найду для тебя дело.' FROM `quest_offer_reward` WHERE `ID`=10752 AND MD5(`RewardText`)='e4ae43735fa09fcf7b44382a94db44d7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10752 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10792, 'ruRU', 'Ха! Я вижу огонь и чую дым, поднимаюшиеся над Зет\'Гором, даже отсюда! Пусть эти дьяволы из Кровавой Глазницы сгорят дотла, а их пепел развеет ветер, так, чтобы на земле, по которой ходят настоящие орки, даже следа не осталось!\n\nСпасибо тебе, $N Ты помог нам очистить огнем наши души.' FROM `quest_offer_reward` WHERE `ID`=10792 AND MD5(`RewardText`)='96824839c02e392d33e2d4cade2d7bef' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10792 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10809, 'ruRU', 'Ага, ты убил этого негодяя Крууша! Отлично, $N Отлично! Можно сказать, вырвал зубы этим проклятым наездникам на воргах. Надеюсь, тебе удалось уложить хотя бы несколько штук во время налета на Зет\'Гор?\n\nВот, возьми награду. Ты ее заслужил.' FROM `quest_offer_reward` WHERE `ID`=10809 AND MD5(`RewardText`)='bb983601bcf3aed6c27788c91ddf64e5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10809 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10813, 'ruRU', 'Я в долгу перед тобой, $N Ты снова мужественно проник в Зет\'Гор, преодолев его тьму. Я исследую этот Глаз, возможно, он раскроет нам секреты своего хозяина Гриллока.\n\nБудем надеяться, что его магия больше никому не послужит!' FROM `quest_offer_reward` WHERE `ID`=10813 AND MD5(`RewardText`)='3ccb6e6967a2fa23cc6c22711e33da44' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10813 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10834, 'ruRU', 'О, да. У воинов, потерявших в боях руку или ногу, отсутствующая конечность часто болит. Хотел бы я знать, что чувствует Гриллок, и мечтает ли он, глубоко-глубоко в душе, вернуть свой глаз обратно.\n\nЯ много думал об этом. Может быть, когда-нибудь я смогу узнать, что заставило Гриллока и орков Кровавой Глазницы предаться демонам.' FROM `quest_offer_reward` WHERE `ID`=10834 AND MD5(`RewardText`)='055d8f3632f183f8f461cd9ea5f40b8e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10834 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10835, 'ruRU', 'А-а, послание Албрека! Очень хорошо. Королевское Фармацевтическое Общество работает день и ночь, чтобы определить, как же орки Скверны стали орками Скверны. Их предательству нет прощения... Мы должны гарантировать, что сумеем защитить от подобной напасти наших друзей-орков.' FROM `quest_offer_reward` WHERE `ID`=10835 AND MD5(`RewardText`)='d380ad0e3d71bf20551da9e816d25103' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10835 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10843, 'ruRU', 'Леорокс меряет вас проницательным взглядом.\n\nСмерть Гноша Брогната – большое благо для всех Мок\'Натал. И для тебя это благо.\n\nПосмотрим, не сможещи ли ты нам помочь в еще более важном деле.' FROM `quest_offer_reward` WHERE `ID`=10843 AND MD5(`RewardText`)='e7bfcb858dfc34455381f510f5e0eaff' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10843 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10845, 'ruRU', 'Нет? Так ты убил Крыло Ужаса? Видать, я ошибался в тебе, |3-6($C).\n\nМожет быть и так.\n\nИ все же ты убил предводителей трех сильнейших наших врагов. Этим можно гордиться.\n\nЯ предлагаю тебе знак моей признательности, но не зазнавайся. Ты еще не понимаешь до конца что такое быть Мок\'Натал, так что мы еще можем воспользоваться твоими умениями!' FROM `quest_offer_reward` WHERE `ID`=10845 AND MD5(`RewardText`)='e9e2ea06377abfd23d289289b8e158d3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10845 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10846, 'ruRU', 'Векх\'нир – вовсе не самые страшные наши враги.\n\nНу, знаешь ты теперь, как разделаться с птицей-переростком. Истинным воином ты от этого не стал. И до конца нас не поймешь.\n\nНо это только начало.' FROM `quest_offer_reward` WHERE `ID`=10846 AND MD5(`RewardText`)='87bb8de705d6c461fe5bd741e47681df' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10846 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10849, 'ruRU', 'Рилак прислал дурные вести, странник. Взгляните на наш караван и сами поймете, что лес Тероккар сейчас полон скорби и тьмы.' FROM `quest_offer_reward` WHERE `ID`=10849 AND MD5(`RewardText`)='df83d114a68431cf04e52ad898f1f555' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10849 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10851, 'ruRU', 'Хорошая подборка. Мы сумеем достойно использовать одного-двух.\n\nИ я, кстати, знаю, как это сделать!' FROM `quest_offer_reward` WHERE `ID`=10851 AND MD5(`RewardText`)='b46ef8dc27d783ed2b443f0f62884cdd' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10851 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10853, 'ruRU', 'Ты сегодня сделал доброе дело, |3-6($C). Теперь освобожденные души драконов воистину воспоют. А та остаточная часть души, которую они оставили после себя – могучее лекарство.\n\nХочу спросить – а не собираешься ли ты на север? Там есть кое-что весьма любопытное для меня, связанное с деятельностью духов Астрала.\n\nЯ чувствую, оттуда будет много лиха.' FROM `quest_offer_reward` WHERE `ID`=10853 AND MD5(`RewardText`)='e4d517646ff536aebbf3685418b0010d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10853 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10859, 'ruRU', 'Что-то тут не так.\n\nДай мне, пожалуйста, тотем, $N. Я должен посмотреть на эти шары!' FROM `quest_offer_reward` WHERE `ID`=10859 AND MD5(`RewardText`)='489315a8454ade754f06266adf78bbf2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10859 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10860, 'ruRU', 'Мммм, уже прямо чувствую вкус. Ну, давай побыстрее... Сейчас порежу – и на огонь!\n\nТебе повезло – это блюдо долго хранится! Вот, бери, и полагаю ты еще и рецепты получишь, если будешь пополнять запасы в моем мясном погребе.' FROM `quest_offer_reward` WHERE `ID`=10860 AND MD5(`RewardText`)='94a1eb0f5655ade517a729b62b90ed8f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10860 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10864, 'ruRU', 'Неплохо, $N. Эти души обременены грузом многих смертей... А демонический кристалл готов к работе.\n\nБудем надеяться, что ты успешно пройдешь это испытание...' FROM `quest_offer_reward` WHERE `ID`=10864 AND MD5(`RewardText`)='9e5b7e850ee2da5222c778e8ffa2350f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10864 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10865, 'ruRU', 'Да что ты говоришь! Разве возможно такое? Да что я говорю! Конечно, возможно, если уж вызыватель духов так говорит!\n\nПомнишь, я говорил, что нам еще может понадобиться твоя помощь? Похоже, этот час настал.' FROM `quest_offer_reward` WHERE `ID`=10865 AND MD5(`RewardText`)='3840eda2f06d496f2f8911ec4f48a071' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10865 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10866, 'ruRU', 'Свободен! Ты спас нас, $N!' FROM `quest_offer_reward` WHERE `ID`=10866 AND MD5(`RewardText`)='820bca01b36cef73451d936571970ff5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10866 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10867, 'ruRU', 'Славно, что эти мерзкие духи Астрала и их вождь мертвы. тысяча проклятий на головы их собратьев!\n\nЯ награжу тебя за твои подвиги от имени всех Мок\'Натал, $N! Воистину, ты теперь один из наших героев.\n\nДавай же выпустим души наших предков и предадим их очистительному пламени.' FROM `quest_offer_reward` WHERE `ID`=10867 AND MD5(`RewardText`)='55dca20655290ccb70ad33d6cb55c6bb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10867 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10870, 'ruRU', 'Ты $gдоказал:доказала;, что являешься настоящим другом Крыльям Пустоты. Наша мать свободна, мои братья и сёстры спасены.\n\nВозможно когда-нибудь нам ещё потребуется твоя помощь, но знай, что когда бы ты ни $Gпришёл:пришла;, тебя встретят с распростёртыми объятьями, $Gбрат:сестра;!' FROM `quest_offer_reward` WHERE `ID`=10870 AND MD5(`RewardText`)='deeb30ba22d4fb032fa53cc6cd5bbad1' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10870 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10874, 'ruRU', 'Мы видели, как оттуда поднимался столб дыма. Вы очень смелы, |3-6($c).' FROM `quest_offer_reward` WHERE `ID`=10874 AND MD5(`RewardText`)='68aaed60e40e134d44360df71f84ec3d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10874 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10875, 'ruRU', 'Я рад слышать о твоих победах над орками Скверны, $N. Аптекари потратили много времени и ресурсов, изучая причину их изменения, но все равно нам жизненно важна любая информация. Мои орки горят желанием как следует проучить этих предателей!\n\nСлушай внимательно, я расскажу тебе о новом задании...' FROM `quest_offer_reward` WHERE `ID`=10875 AND MD5(`RewardText`)='735cb9acaeae4236e910bceb881e4e93' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10875 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10877, 'ruRU', 'Поверить не могу, что вам это удалось. Реликвия Ужаса еще сильнее, чем я думал. Только истинный герой мог выжить в этом путешествии и вернуться назад, неся с собой эту проклятую вещь.' FROM `quest_offer_reward` WHERE `ID`=10877 AND MD5(`RewardText`)='36c45fad577b23b2a734804af6bb55a1' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10877 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10880, 'ruRU', 'Ах да... Это написано основным теневым шифров. Я не очень хорошо его знаю, но это перевести смогу.\n\nЧему только не научишься, живя среди изгнанников и беженцев в Нижнем Городе...' FROM `quest_offer_reward` WHERE `ID`=10880 AND MD5(`RewardText`)='7d9b9156408612d735f5fcbbaf8e5050' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10880 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10891, 'ruRU', 'Конечно, я научу тебя ковать имперские латы! И обойдется это тебе в толику золота... в форме ториевых слитков!' FROM `quest_offer_reward` WHERE `ID`=10891 AND MD5(`RewardText`)='9eb6b81e679c7e01779036029d2447a5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10891 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10895, 'ruRU', 'Даже отсюда я вижу дым и пламя! Отличная работа, $N! Наши всадники на грифонах будут от души тебе благодарны. Сделанная тобой работа требовала изрядного мужества…' FROM `quest_offer_reward` WHERE `ID`=10895 AND MD5(`RewardText`)='832629cd01b6b53243d3325408df0d10' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10895 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10903, 'ruRU', 'Да, это так. За последние несколько дней состояние полковника Джулса снова ухудшилось. Анахорет Берада день и ночь возносит за него молитвы. Будем надеяться, что полковник все-таки поправится.' FROM `quest_offer_reward` WHERE `ID`=10903 AND MD5(`RewardText`)='ec5e458eed52efd35a140aa897fdc9f7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10903 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10909, 'ruRU', 'Души орков Изувеченной Длани нечисты, и нет надежды на их исцеление, но мое сердце скорбит о том, что мы вынуждены использовать столь кровавый путь, чтобы вернуть покой душе полковника Джулса.' FROM `quest_offer_reward` WHERE `ID`=10909 AND MD5(`RewardText`)='682ed4595d5d2b6b62fe8f19a2eeb860' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10909 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10913, 'ruRU', '<Командир Ра\'вадж хватается за голову>$B$BЭтого мало... Этого совершенно недостаточно.' FROM `quest_offer_reward` WHERE `ID`=10913 AND MD5(`RewardText`)='ce85b869b3f36b17d924680b28e37300' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10913 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10915, 'ruRU', 'Победа за нами! Теперь Аукенай несколько недель не даст о себе знать!' FROM `quest_offer_reward` WHERE `ID`=10915 AND MD5(`RewardText`)='dd6be2295c6e9978acbb0111f02f99a1' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10915 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10916, 'ruRU', 'О, мои четки нашлись! Спасибо тебе, $n. Ты, можно сказать, творишь настоящие чудеса, – мановением одной руки рассеиваешь ужасы Полуострова Адского Пламени, мановением другой возвращаешь утраченные сокровища.$B$BЭто очень хорошо, что ты $gвернул:вернула; мне четки. Без них не удалось бы провести обряд экзорцизма.' FROM `quest_offer_reward` WHERE `ID`=10916 AND MD5(`RewardText`)='f4a3dcaf955fd9482a962cc355d9bdc0' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10916 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10924, 'ruRU', 'Этого будет вполне достаточно для моих нужд.\n\nНадеюсь, бес не доставил тебе слишком много хлопот. Вообще-то он изрядный пакостник.' FROM `quest_offer_reward` WHERE `ID`=10924 AND MD5(`RewardText`)='9b32cd47699cff094c4d813b2262ad54' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10924 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10929, 'ruRU', 'Песчаные гномы? Ага, конечно... Чего только пустыня не делает с народом.\n\nА мы, кажется, на грани величайшего открытия касательно этих червей!' FROM `quest_offer_reward` WHERE `ID`=10929 AND MD5(`RewardText`)='1fee8b7df4adcd420147fbef2cbc7f22' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10929 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10930, 'ruRU', 'Потрясающе! Вы только посмотрите! Вот в этой как-же-ее-штуке есть как-его-там-пузырь, а в нем – какая-то пыль! Ладно, не буду утомлять вас научным жаргоном. Я тут выдернул немного зубов из маленьких червей, и изготовил из них довольно острые ножички. Хотите такой?' FROM `quest_offer_reward` WHERE `ID`=10930 AND MD5(`RewardText`)='fe86c53289c5c837d1034665acd3a78b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10930 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10935, 'ruRU', 'Тебе удалось сделать это, $n. Ты $gспас:спасла; душу полковника Джулса и $gизгнал:изгнала; тьму туда, откуда она пришла. Это дело, достойное героя.' FROM `quest_offer_reward` WHERE `ID`=10935 AND MD5(`RewardText`)='767ee640f1a33f277ee4a4de6ed1f255' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10935 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10936, 'ruRU', 'Очень вовремя! Я слышал о твоих приключениях с тем дренейским жрецом. Мой посланник изрядно перепугался!$B$BТеперь, когда ты $gразделался:разделалась; с предыдущим делом, у меня есть для тебя небольшая работенка в Цитадели Адского Пламени...' FROM `quest_offer_reward` WHERE `ID`=10936 AND MD5(`RewardText`)='159dcc1804f767752d6a270b88e5b712' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10936 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10938, 'ruRU', 'Итак, ты $gсобрал:собрала; колоду Благословений. Отныне между тобой и ярмаркой установится прочная связь, и память о ней сохранится надолго. В знак этого я вручаю тебе одну из старших карт Новолуния.' FROM `quest_offer_reward` WHERE `ID`=10938 AND MD5(`RewardText`)='af267d41c668ef13742a717c44641a41' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10938 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10939, 'ruRU', 'Итак, ты $gсобрал:собрала; колоду Ураганов. Отныне между тобой и ярмаркой установится прочная связь, и память о ней сохранится надолго. В знак этого я вручаю тебе одну из старших карт Новолуния.' FROM `quest_offer_reward` WHERE `ID`=10939 AND MD5(`RewardText`)='8b45312cc6563cc131c3f80bdeed8bdd' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10939 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10984, 'ruRU', 'Ты помогать Гроку? Гроку надо помогать! Кровавому Молоту надо помогать!' FROM `quest_offer_reward` WHERE `ID`=10984 AND MD5(`RewardText`)='e92e8837c812a3136a4409adb2305d11' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10984 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10989, 'ruRU', 'Наконец-то Фырк прислал ко мне того, кто, похоже, может помочь. Я пытаюсь спасти Кровавый Молот от уничтожения кланом Камнерогов и сынов Груула, которые стоят за ними.\n\nЯ верю, что ты поможешь нашему тайному обществу и приведешь нас к свободе!' FROM `quest_offer_reward` WHERE `ID`=10989 AND MD5(`RewardText`)='0a9869275cb9f0bb139998a47c44b91e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10989 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10996, 'ruRU', 'Говоришь, он пуст? Жаль – но ты $gсам:сама; видишь ту тупую жестокость, с которой нам приходится сталкиваться.\n\nТеперь, когда Маггок мёртв, мы на шаг приблизились к осуществлению моей мечты о доме для огров и о том времени, когда мы сами будем определять нашу судьбу.' FROM `quest_offer_reward` WHERE `ID`=10996 AND MD5(`RewardText`)='33b05a922441f9a699a4b6c8b6c13a3e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10996 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 10998, 'ruRU', 'Мне боязно даже прикасаться к этой нечестивой книге. Но нам придется ее читать, если мы хотим проникнуть в суть знаний, что в ней имеются, и выманить Скуллока из укрытия!' FROM `quest_offer_reward` WHERE `ID`=10998 AND MD5(`RewardText`)='2cc475449cc52776895905751ca235bc' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=10998 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11013, 'ruRU', '<Моргор читает письмо и смеется.>\n\nРыцарь смерти? Да ты сапоги им лизать недостоин, салага.\n\nМогор оглядывает тебя с ног до головы.\n\nОднако... Ты сможешь начать с раба, либо я просто брошу тебя в яму и оставлю подыхать...' FROM `quest_offer_reward` WHERE `ID`=11013 AND MD5(`RewardText`)='81b6ef6a5f11dc22bb6f62e04d68b39b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11013 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11014, 'ruRU', 'Варкул, пристроит тебя к делу, рядовой, будешь заниматься тем, что лучше всего для тебя и копей Крыльев Пустоты. Задания будешь получать по одному в день.\n\nРаботенка преимущественно грязная, но кто-то же должен ее делать…' FROM `quest_offer_reward` WHERE `ID`=11014 AND MD5(`RewardText`)='dfa1c7f7c13fee06e67825acd035816d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11014 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11015, 'ruRU', 'На сегодня достаточно, детка. Приходи завтра, если переживешь эту ночь.' FROM `quest_offer_reward` WHERE `ID`=11015 AND MD5(`RewardText`)='acb273eb12031c4a9a9389ae670168c7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11015 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11017, 'ruRU', 'На сегодня достаточно, детка. Приходи завтра, если переживешь эту ночь.' FROM `quest_offer_reward` WHERE `ID`=11017 AND MD5(`RewardText`)='acb273eb12031c4a9a9389ae670168c7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11017 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11018, 'ruRU', 'На сегодня достаточно, детка. Приходи завтра, если переживешь эту ночь.' FROM `quest_offer_reward` WHERE `ID`=11018 AND MD5(`RewardText`)='acb273eb12031c4a9a9389ae670168c7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11018 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11041, 'ruRU', 'Как докладывает один из моих наблюдателей, ты получил приказ и взял дело в свои собственные руки? Хм... Неплохо. Тебе удалось удивить меня.' FROM `quest_offer_reward` WHERE `ID`=11041 AND MD5(`RewardText`)='c4bc59a1ae869d014a34f3aa193dbd62' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11041 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11045, 'ruRU', 'Фантей говорит правду: я действительно с радостью приму вашу помощь.' FROM `quest_offer_reward` WHERE `ID`=11045 AND MD5(`RewardText`)='52af4baec2003a51df2a96f5d54bd67a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11045 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11054, 'ruRU', 'Аррр! Теперь-то ты настоящий инспектор. Эта ящерица-переросток была грозой многих орков!$B$B*Надзиратель Грязевик начинает мастерить оружие.*' FROM `quest_offer_reward` WHERE `ID`=11054 AND MD5(`RewardText`)='bc1b081c8cf3f8ec6c9714a944872c96' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11054 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11063, 'ruRU', 'Так ты хочешь примкнуть к Усмирителям небес? Ты неплохо себя показал в клане Драконьей Пасти, но это ничего не значит тут, в небесах Запределья. Вопрос в том, умеешь ли ты летать?$B$BПолет – это не просто взгромоздиться на спину дракону Пустоты и отвезти в форт партию кристаллов, с этим-то любой дурак справится. Полет, это быть лучшим, первым среди орков.$B$BК западу отсюда есть шесть пилотов, победи их всех – и я пожалую тебе крылья Усмирителя небес.' FROM `quest_offer_reward` WHERE `ID`=11063 AND MD5(`RewardText`)='b7c323957739e6e44a02bfda83810669' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11063 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11064, 'ruRU', 'Тыквы?! Да-а, вот так проходит мирская слава... Я уверен, что другие наездники будут посильнее Старины.' FROM `quest_offer_reward` WHERE `ID`=11064 AND MD5(`RewardText`)='daadf0c137afa6fd495fc89b2f9e44d1' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11064 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11067, 'ruRU', 'Интересно... Твой следующий заезд, безусловно, будет сложнее. Корлока неуклюжим не назовешь.' FROM `quest_offer_reward` WHERE `ID`=11067 AND MD5(`RewardText`)='4df88e4029b2141fa0fb53a43ad85d91' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11067 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11068, 'ruRU', 'Следующие два всадника – лучшие наездники среди дворфов и орков Азерота. У тебя нет против них ни единого шанса!' FROM `quest_offer_reward` WHERE `ID`=11068 AND MD5(`RewardText`)='2c496f82d5fc5508ca148a29e7b2b0d8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11068 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11069, 'ruRU', 'Глазам своим не верю! Теперь тебе нужно обойти Маэстра, а уж тут-то у тебя нет никаких шансов.' FROM `quest_offer_reward` WHERE `ID`=11069 AND MD5(`RewardText`)='f5b1a7f33d13e5472bfb4e0d0d29a8b8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11069 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11070, 'ruRU', 'Похоже, между тобой и победой остался только капитан, парень. Удачи! Она тебе пригодится.' FROM `quest_offer_reward` WHERE `ID`=11070 AND MD5(`RewardText`)='81f25ca579e78f9e23be1991e6ad20b3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11070 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11075, 'ruRU', 'Шахтеры упорно трудятся, но ни один не осмеливается ступить в эту шахту. Они предпочитают умереть, но не спускаться в ее глубины. Теперь в твои обязанности будет входить выполнение всех тех заданий, с которыми не справились они.' FROM `quest_offer_reward` WHERE `ID`=11075 AND MD5(`RewardText`)='1b1ca4eefcf9d3eed94e4ead90cdef29' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11075 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11076, 'ruRU', 'Отлично, $N. Возвращайся завтра, за новым заданием.' FROM `quest_offer_reward` WHERE `ID`=11076 AND MD5(`RewardText`)='5bad45c02f7dc8eb8943bb0d16e87650' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11076 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11077, 'ruRU', 'На сегодня достаточно, инспектор. Возвращайся завтра для нового раунда зачистки.' FROM `quest_offer_reward` WHERE `ID`=11077 AND MD5(`RewardText`)='a3135804451cc9f26bcab51c24d211b3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11077 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11081, 'ruRU', 'Отличная работа Инспектор. Мор\'гор услышит о твоей верной службе клану Драконьей Пасти.$B$BТеперь возвращайся к этим собакам из Темной Крови. Планируют побег, говоришь? Надеются противостоять истиному Лорду Запределья? Их лидеры заплатят за это!' FROM `quest_offer_reward` WHERE `ID`=11081 AND MD5(`RewardText`)='a69bf8eb0bb61904466edd67967166bd' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11081 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11082, 'ruRU', 'Нечего сказать? Возможно, когда он будет истекать кровью на полу этой шахты, он вспомнит... Вспомнит, что значит идти против сил Иллидана!' FROM `quest_offer_reward` WHERE `ID`=11082 AND MD5(`RewardText`)='aeccadde46fbc87f8d23f83304470d08' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11082 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11083, 'ruRU', 'Да, я такого не понимаю... Кто бы мог подумать, что они так оголодают всего за два дня. Клан Темной Крови...\n\nРонаг качает головой.\n\nКакие же они все-таки тупые...' FROM `quest_offer_reward` WHERE `ID`=11083 AND MD5(`RewardText`)='c2322be6020970a29f9dc36ba8fb6e76' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11083 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11084, 'ruRU', '*Мор\'гор кивает*$B$BВерно, я сказал Капитан. Ты заработал повышение, $N.$B$BРаботаешь лучше, чем любой орк Скверны, которого я когда-либо видел. Продолжай в том же духе и когда-нибудь станешь и властителем.$B$BТеперь иди и принимай командование. Я предлагаю тебе попробовать заработать крылья Усмирителя небес.' FROM `quest_offer_reward` WHERE `ID`=11084 AND MD5(`RewardText`)='321c09cf1dc34522cfb63abd706b028c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11084 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11086, 'ruRU', 'Отличная работа, капитан! Владыка Иллидан узнает о твоем подвиге!' FROM `quest_offer_reward` WHERE `ID`=11086 AND MD5(`RewardText`)='2a1c9007f2358c1aff7c21b2f24582a3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11086 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11089, 'ruRU', 'Балтаз, умело соединяет компоненты, принесенные тобой. Настало время для второй части нашего плана, капитан.' FROM `quest_offer_reward` WHERE `ID`=11089 AND MD5(`RewardText`)='4ecc49328a7ca705c67a8d1bae706145' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11089 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11090, 'ruRU', 'Он вернется, но теперь силы Легиона, посланные против владыки Иллидана, ослаблены. Иллидан непременно узнает о твоих заслугах. Капитан.' FROM `quest_offer_reward` WHERE `ID`=11090 AND MD5(`RewardText`)='67a21f0c9db8749d11752fb9207b44a5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11090 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11092, 'ruRU', 'Сам Владыка Иллидан велел, чтобы я возвел тебя в ранг командира. Это неслыханно, ты будешь $gпервым: первой; из этого клана, получившим такой высокий ранг вне стен Черного храма.' FROM `quest_offer_reward` WHERE `ID`=11092 AND MD5(`RewardText`)='63fdc9fe60aeaddab9f3239937566b53' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11092 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11094, 'ruRU', 'Хорошо, что ты пришел к нам, возможно, мы сможем использовать эту атаку в своих целях и побить клан Драконьей Пасти его же оружием.' FROM `quest_offer_reward` WHERE `ID`=11094 AND MD5(`RewardText`)='96282faf3bac4aa9d2aeed906e79ba1f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11094 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11095, 'ruRU', '*Хобб ухмыляется.*$B$BНеплохая получится ловушка...' FROM `quest_offer_reward` WHERE `ID`=11095 AND MD5(`RewardText`)='cb95f65ebd0ee617dcdb46646122df24' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11095 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11097, 'ruRU', '<Мор\'гор смеется.>$B$BХа! Я знал, что ты меня не подведешь, командир! Я хочу, чтобы ты устраивал набеги на Святилище Звезд как минимум один раз в день, Они поймут, что у них нет выбора, кроме как покинуть Лунную Тень!' FROM `quest_offer_reward` WHERE `ID`=11097 AND MD5(`RewardText`)='22d489d441fb7534dc23571b6930e53a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11097 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11124, 'ruRU', 'Инспектор смотрит на вас с нескрываемым недоверием.\n\nМне сказали, что ты будешь... помогать в расследовании. Что же, хорошо.\n\nЯ обработал тут все вот этим порошком, чтобы узнать, кто напал на гостиницу. Он поможет выявить улики, связанные с эти нападением. Обследуй все, что покажется подозрительным.' FROM `quest_offer_reward` WHERE `ID`=11124 AND MD5(`RewardText`)='f2193ae326bbe78dec2ee4633814ae6c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11124 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11126, 'ruRU', 'Очень хорошо, $N. Думаю, нам удалось застать их врасплох. Похоже, эти агенты считали себя в безопасности за городскими стенами.$B$BСо временем подстрекатели вернутся и снова будут распространять дезинформацию. А мы пока воспользуемся тем временем, что ты для нас выиграл, чтобы отогнать их как можно дальше.' FROM `quest_offer_reward` WHERE `ID`=11126 AND MD5(`RewardText`)='bdf998662c2dfc581e75661eb9402bc5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11126 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11128, 'ruRU', 'Агент ШРУ одобрительно кивает. $B$BБлестяще. Остается только дискредитировать вражескую агентуру так, чтобы они больше в Терамор сунуться не смели, и на этот счет у меня созрел план.' FROM `quest_offer_reward` WHERE `ID`=11128 AND MD5(`RewardText`)='cccaf969f8a5e5eb908d451a9ec37f2a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11128 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11130, 'ruRU', 'Бадд читает записку.\n\nА, друг Жуля? Добро пожаловать!\n\nКак раз вовремя. По роковому стечению обстоятельств я недавно лишился своих партнеров. Настоящая трагедия, но большой выигрыш стоит больших затрат. Но лучше не думать о плохом!\n\nТы несомненно уже знаешь о моих бесчисленных изобретениях и открытиях, но все они ничто по сравнению вот с этим! Честно говоря, мы тут в Зул\'Амане, можно сказать, творим историю и, по велению судьбы, ты вступаешь в дело с самого начала!' FROM `quest_offer_reward` WHERE `ID`=11130 AND MD5(`RewardText`)='6a7ac0b1873a1fe6ba941c77dd9f1759' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11130 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11143, 'ruRU', 'Капитан Ваймс считает, что племя Зловещего Тотема повинно в преступлении, совершенном в таверне "Последний привал"? Я бы не ставил их первыми в списке подозреваемых, но раз капитан Ваймс прислал тебя для дальнейшего расследования, должно быть, у него были на то причины. В любом случае, племя Зловещего Тотема давно у нас как заноза в пятке, и мы всегда рады принять любую помощь.' FROM `quest_offer_reward` WHERE `ID`=11143 AND MD5(`RewardText`)='9a514e882ad8f5c02787c376808bf14c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11143 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11144, 'ruRU', '<Капитан Дарилл просматривает боевой план.>$B$BЯ бы сказал, что все яснее ясного. Они берут на себя уничтожение людских поселений в этих краях, и я не сомневаюсь, что следующим в списке будет Терамор.' FROM `quest_offer_reward` WHERE `ID`=11144 AND MD5(`RewardText`)='fc73ab55616d4791ad7db1b988e99b86' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11144 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11148, 'ruRU', '<Капитан Дарилл осматривает принесенное вами из деревни Черного Копыта вооружение.>$B$BСомневаться не приходится – вооружение в точности соответствует описанию. Но дело в том, что оно ни разу не побывало в бою. Должно быть, деревня Черного Копыта – не единственный аванпост племени Зловещего Тотема в топях.' FROM `quest_offer_reward` WHERE `ID`=11148 AND MD5(`RewardText`)='880ef2bbc2ae5067c22beb0f87f31a2f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11148 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11149, 'ruRU', 'Значит, ты хочешь, чтобы я предсказала будущее племени Зловещего Тотема? А если я скажу, что нужды в том нет?' FROM `quest_offer_reward` WHERE `ID`=11149 AND MD5(`RewardText`)='20494d09643d28f6a641fe0a958be026' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11149 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11150, 'ruRU', 'Надеюсь, племя Зловещего Тотема усвоило урок. Попытаются вернуться – мы их встретим не только факелом. Мои ученики помогут мне дать отпор.' FROM `quest_offer_reward` WHERE `ID`=11150 AND MD5(`RewardText`)='0d9336e27de7d67fa45fdc095cd1643e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11150 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11151, 'ruRU', '<Капитан внимательно выслушивает ваш доклад.>$B$BМы отомстили за Джеймса и его семью, но это их не вернет.' FROM `quest_offer_reward` WHERE `ID`=11151 AND MD5(`RewardText`)='36f8abd1357f4f6b1b46c798d5155494' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11151 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11152, 'ruRU', '<Капитан Ваймс мягко улыбается, слушая ваш рассказ о событиях, произошедших у памятника семейству Хьяль.>$B$BПриятно знать, что они все видят. Ты же не рассказал им о Джеймсе, правда?$B$BЯ отправлю ему послание жены, хотя сомневаюсь, что он поймет.' FROM `quest_offer_reward` WHERE `ID`=11152 AND MD5(`RewardText`)='5804c1a45adbf6b8af52aa2517e79060' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11152 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11156, 'ruRU', '<Ученик Морланн кивает.>$B$BЭто хорошо. И не могу сказать, что буду страдать без их общества. А то даже в сердце трясин уединения не найдешь!' FROM `quest_offer_reward` WHERE `ID`=11156 AND MD5(`RewardText`)='184010baca8e64617a3563283e704b65' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11156 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11158, 'ruRU', 'Брогг принимает перья.\n\nБрогг рад этим перьям. Очень сильная магия. Брогг не знает, что делают ящеры для придания силы перьям, но для обряда лучше не сыскать.' FROM `quest_offer_reward` WHERE `ID`=11158 AND MD5(`RewardText`)='82e130e256ca3e6eefe8ac628c4d30dc' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11158 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11159, 'ruRU', 'Брогг благодарит тебя за помощь, хотя и знает, что от властителя Мок\'Морокка ты не дождешься слов благодарности. Но теперь, по крайней мере, выжившие члены клана могут наконец заняться насущными делами, и мертвые им больше досаждать не будут. А Броггу осталось сделать одну вещь.' FROM `quest_offer_reward` WHERE `ID`=11159 AND MD5(`RewardText`)='6d3cbe0f0c264587507290de2d5720d1' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11159 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11160, 'ruRU', 'Брогг тебе благодарен, $n. У Брогга большие планы на клановое знамя.' FROM `quest_offer_reward` WHERE `ID`=11160 AND MD5(`RewardText`)='9f00fb38aeaf0829bf6c12a2182c7a4f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11160 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11161, 'ruRU', 'Ты получаешь благодарность Брогга, $n. Как только Брогг отдает свою магию тотему, тотем освобождает духов убитых друзей Брогга.' FROM `quest_offer_reward` WHERE `ID`=11161 AND MD5(`RewardText`)='fb0e9b9008dfc74b6f5bf7c1bfac536a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11161 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11162, 'ruRU', '<Брогг слушает ваш рассказ о том, что произошло у входа в Логово Ониксии.>$B$BБрогг так и знал, что Ониксия побоится биться с тобой. Все черные драконы нападают, только когда победа однозначна.$B$BБрогг благодарен тебе за помощь, $N. Он никогда не забудет, что ты для него сделал. Брогг никогда не отступит от своей цели вернуть Каменный Молот на родину!' FROM `quest_offer_reward` WHERE `ID`=11162 AND MD5(`RewardText`)='4ab950f77d5143fef3634fe3c9386526' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11162 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11169, 'ruRU', '<Вы подробно рассказываете о ходе эксперимента.>$B$BТуман и молния? И все? Но ведь этот тотем должен вызывать еще какие-то эффекты! Тотем бы не стали нести на поле брани, не будь у него каких-то полезных свойств.' FROM `quest_offer_reward` WHERE `ID`=11169 AND MD5(`RewardText`)='c2de531344585fa5dbcb1c538d4e3b1a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11169 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11170, 'ruRU', 'Хммм...результаты не очень впечатляющие...' FROM `quest_offer_reward` WHERE `ID`=11170 AND MD5(`RewardText`)='ef7c677a2f20e82733023fec7c061c2b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11170 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11172, 'ruRU', 'Так тебя послали эти маги-отшельники? И с чего я тебе должна доверять?\n\nВпрочем, помощь мне не помешала бы. Да и нет тут ничего интересного для мага.' FROM `quest_offer_reward` WHERE `ID`=11172 AND MD5(`RewardText`)='c9a54d291e2e172e014af15ecd3e22e6' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11172 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11173, 'ruRU', '<Ученик Гарион изучает яд.>$B$BПросто прекрасные образцы! Он и не отличит.' FROM `quest_offer_reward` WHERE `ID`=11173 AND MD5(`RewardText`)='26bf36e1a83dc81c3ae9b0d5a471a70f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11173 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11174, 'ruRU', 'Ну, похоже, там и правда стало немного почище...$B$BПолагаю, пора заняться делом и основательно порыться в обломках.' FROM `quest_offer_reward` WHERE `ID`=11174 AND MD5(`RewardText`)='0b30c3ec3f820d13efd6ee89c20a81cc' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11174 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11180, 'ruRU', 'Моргант достает листок бумаги и перо и набрасывает какие-то заметки по ходу вашего рассказа.\n\nСудя по твоим словам, духами этого места должны стать все, кто тут когда-либо жил, и не только прежние владельцы.\n\nЧто-то завладевает ими и убивает их. Те, кто приезжает на это место, узнает правду слишком поздно. Мы должны положить этому конец, $N!' FROM `quest_offer_reward` WHERE `ID`=11180 AND MD5(`RewardText`)='da16d55691c19b8bd12ace65c9f0c00c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11180 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11181, 'ruRU', 'Моргант берет у вас пучок травы.\n\nТочно подходит под описание! Пока тебя не было, я приготовил факел. Остается только сунуть в него траву.' FROM `quest_offer_reward` WHERE `ID`=11181 AND MD5(`RewardText`)='28620f3d51203c13a86afaac00080dd2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11181 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11182, 'ruRU', 'К несчастью, я вынужден бы послать одного хищника, чтобы тот убил другого, но таков естественный порядок вещей. \n\nВозможно, теперь протодраконы и их детеныши смогут обрести мирное пристанище в наших краях. Меня беспокоят только пробужденные врайкулы.' FROM `quest_offer_reward` WHERE `ID`=11182 AND MD5(`RewardText`)='b321ba344b53bd2cf45d12bbb35de84e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11182 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11183, 'ruRU', 'Получилось?\n\nМоргант прокашливается.\n\nТо есть... получилось! Мы с Ярлом перед тобой в долгу, $N. Единственной проблемой осталась разборчивость моего приятеля в мебели, и, боюсь, ее так просто я не решу.' FROM `quest_offer_reward` WHERE `ID`=11183 AND MD5(`RewardText`)='b1fdbd6a054a153c5aaf481fa50b6599' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11183 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11184, 'ruRU', 'Хвала небесам, наконец кто-то откликнулся на это объявление! Я уж думал, что придется утроить награду за голову этого дурацкого ящера, а наш бюджет такого не потянет!' FROM `quest_offer_reward` WHERE `ID`=11184 AND MD5(`RewardText`)='52dd278052cd6ac1c7d54d0488cfbb90' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11184 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11185, 'ruRU', '<Анделло читает письмо, потрясенный его содержанием.>$B$BМы давно подозревали, что Орда и Отрекшиеся в союзе, и это письмо подтверждает наши подозрения. При помощи магии и оружия Отрекшихся племя Зловещего Тотема станет еще более страшным врагом. Баланс сил в Калимдоре может сильно измениться.' FROM `quest_offer_reward` WHERE `ID`=11185 AND MD5(`RewardText`)='bfbd392c5db36c4382cbdc45739cd7c8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11185 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11186, 'ruRU', 'Если все и вправду так, то Отрекшимся придется объясниться!\n\nТаурены из Зловещего Тотема своими выходками давно испытывает терпение вождя. Мы обычно оставляли такие дела улаживать самим тауренам, но это письмо может все изменить.\n\nЭти подозрения еще надо проверить, так что никому не рассказывай о том, что видел сегодня.' FROM `quest_offer_reward` WHERE `ID`=11186 AND MD5(`RewardText`)='2275a921f223a95b999610d26f9a184b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11186 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11200, 'ruRU', 'Крог рассматривает оружие, принесенное вами из деревни Черного Копыта.\n\nЯвно работа Мозарна. Дальнейшее расследование привлечет слишком много внимания, но теперь у нас развязаны руки для борьбы со Зловещим Тотемом.' FROM `quest_offer_reward` WHERE `ID`=11200 AND MD5(`RewardText`)='4c8e326dbe97be99afebd3fc5eb15e04' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11200 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11201, 'ruRU', 'Крог читает боевые планы.\n\nВ том, что Зловещий Тотем двинется на людей, сомнений нет. Но что он замышляет против нас? Действия этого клана давно вызывают беспокойство в рядах Орды, но вождю до сих пор удавалось рассеивать его.' FROM `quest_offer_reward` WHERE `ID`=11201 AND MD5(`RewardText`)='eb69c0e3e4073a18453c85bd4261cd5a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11201 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11203, 'ruRU', 'Табета еле заметно улыбается.\n\nКрог хочет, чтобы я погадала ему насчет Зловещего Тотема? Ну, тут мне магия не нужна.\n\nПохоже, у нас общий враг. Зловещий Тотем устроил заставу по соседству, и теперь житья от него нет ни мне, ни моим ученикам.' FROM `quest_offer_reward` WHERE `ID`=11203 AND MD5(`RewardText`)='94ecacb96e7cc3af0c2871d8332ee4be' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11203 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11204, 'ruRU', 'Он действительно сказал, что Зловещий Тотем – самый крупный его заказчик? Мозарн помог нам куда больше, чем думает. Против Зловещего Тотема столько улик, что мы спокойно можем огласить их первыми подозреваемыми.' FROM `quest_offer_reward` WHERE `ID`=11204 AND MD5(`RewardText`)='53d16dbdc6489d920b22d84165e3966d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11204 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11205, 'ruRU', 'Надеюсь, в Зловещем Тотеме без труда уразумеют, что им хотели сказать.\n\nА что касается тебя, то твой осведомитель в Деревне Гиблотопь захочет узнать, каковы твои успехи. Я понимаю, что разрушение таверны "Последний привал" может вызвать напряжение между Ордой и Альянсом. Если я встречу следователей из Терамора, то с радостью сообщу, что Зловещий Тотем действовал по собственной инициативе.' FROM `quest_offer_reward` WHERE `ID`=11205 AND MD5(`RewardText`)='80dce1c315094cb75d40cfafb99df261' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11205 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11206, 'ruRU', 'Крог выслушивает ваше донесение.\n\nОчень впечатляет, $N. Мне казалось, что этих преступников из клана Зловещий Тотем будет труднее найти. \n\nСлово Табеты было услышано, но не мне карать этот клан. Конечно, я доложу об этом вождю. Никому об этом не рассказывай, пока Тралл не разберется со Зловещим Тотемом. Ты славно потрудился, распутав тайну "Последнего привала" и сняв с нас подозрения Терамора.' FROM `quest_offer_reward` WHERE `ID`=11206 AND MD5(`RewardText`)='efb874cbc6efb42cddbce7fc3e02630a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11206 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11207, 'ruRU', 'Ого! Ты нашел намного больше, чем я ожидала! Не знаю уж, на какую часть груза рассчитывал Драззит, отправляя нас сюда, но он будет просто вне себя от восторга.' FROM `quest_offer_reward` WHERE `ID`=11207 AND MD5(`RewardText`)='c092bd9e6863c468c59a303191c3d409' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11207 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11208, 'ruRU', '*Драззит принимает от вас груз.*\n\nЯ так проголодался, что целого дракона бы съел! Наконец-то Дерзи доставила часть груза сюда. А то я уже было начал играть в кости с огром на то, что ему удавалось добыть на охоте!' FROM `quest_offer_reward` WHERE `ID`=11208 AND MD5(`RewardText`)='b181d61f7b88d398df93af11c7fea082' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11208 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11211, 'ruRU', 'Хорошо, что Табета прислала тебя. Неплохо было бы, если б она передала каких-то припасов, пока сюда не доставят груз с разбившегося дирижабля, но, как мне известно, сейчас ей просто нечем поделиться. Если у тебя есть вкус к приключениям, то я назначил награду за одного особенно противного ящера.' FROM `quest_offer_reward` WHERE `ID`=11211 AND MD5(`RewardText`)='8751697de36a620683c7899b2e0dc35b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11211 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11212, 'ruRU', 'Хорошо, что Терамор прислал кого-то. Подозрения вашего друга-охранника были верны. У нас есть новые соседи, и они не из тех, кто приносит запеканку.' FROM `quest_offer_reward` WHERE `ID`=11212 AND MD5(`RewardText`)='25d051f9d88fb8bcf15c4f32d4059919' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11212 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11213, 'ruRU', 'Назир очень кстати решил послать кого-нибудь сюда. У нас появились новые соседи, и с тех пор жить стало просто невыносимо.' FROM `quest_offer_reward` WHERE `ID`=11213 AND MD5(`RewardText`)='bdcafc14df7ddd0218b24538a35221ba' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11213 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11215, 'ruRU', 'Я не откажусь от любой помощи! Мы тут как раз обживаемся, поэтому используем все доступные средства на полную катушку, пока дирижабль не доставил груз.' FROM `quest_offer_reward` WHERE `ID`=11215 AND MD5(`RewardText`)='0798ef20ebcfe564f674fc44082bc532' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11215 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11217, 'ruRU', 'Спасибо тебе! Теперь наши парни продержатся в поле, пока Мокси не доставит груз, оставшийся после крушения дирижабля.' FROM `quest_offer_reward` WHERE `ID`=11217 AND MD5(`RewardText`)='1065c3dcdc150d5b01b182b2e7238b9a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11217 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11262, 'ruRU', 'Отличная работа, $N. После смерти предводителя врайкулов мы должны добиться более впечатляющих успехов в войне против этих тварей. \n\nТакой подвиг должен быть достойно вознагражден!' FROM `quest_offer_reward` WHERE `ID`=11262 AND MD5(`RewardText`)='df7a9b7e810ed42e9172005e12035b1f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11262 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11266, 'ruRU', '$N, мы не можем допустить, чтобы эти планы осуществились!' FROM `quest_offer_reward` WHERE `ID`=11266 AND MD5(`RewardText`)='51952df315af02649b3e07f34a3c9030' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11266 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11271, 'ruRU', 'С твоей помощью мы сможем хорошо подготовиться к этому нелегкому путешествию. Мне почти нечем тебя отблагодарить, но все же возьми одну из этих вещей, лежащих у меня без дела.' FROM `quest_offer_reward` WHERE `ID`=11271 AND MD5(`RewardText`)='dfcf30d4dd8586b41edb9aa1d26e94cd' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11271 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11272, 'ruRU', 'Ах, месть сладка. Подумать только – и это лишь начало!\n\nСкоро Артас получит по заслугам. Тогда и только тогда я умру счастливым.' FROM `quest_offer_reward` WHERE `ID`=11272 AND MD5(`RewardText`)='1476b7baec8b981c4025c6de8d03373d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11272 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11293, 'ruRU', 'Молодец! Надеюсь, мы к себе переманили клиентов.$b$bА вот и обещанная награда. Мы, Ячменевцы, держим слово.$b$bАх да, заходи завтра, можешь еще раз поработать зазывалой.' FROM `quest_offer_reward` WHERE `ID`=11293 AND MD5(`RewardText`)='db9b1f91b148b4c8722f6d8454d9c1cc' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11293 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11311, 'ruRU', 'Влияние стихий уменьшилось, но элементали еще вернутся. К счастью, мы успели выиграть время для приготовлений к уходу.' FROM `quest_offer_reward` WHERE `ID`=11311 AND MD5(`RewardText`)='2e68e3ec2624adeaabc38d7bbdc38c39' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11311 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11314, 'ruRU', 'Значит, для моих сестер еще не все потеряно?\n\n<Луриэль отворачивается и печально смотрит вдаль.>\n\nЯ должна была сразу вспомнить про подвеску. Возможно, тогда мы могли бы спасти всех моих сестер.' FROM `quest_offer_reward` WHERE `ID`=11314 AND MD5(`RewardText`)='8f88a8619710174e3bba8be25edb863e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11314 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11318, 'ruRU', 'Неплохо, неплохо! Не так-то просто справиться с бараном. Но как уж научишься им управлять, сразу захочешь, чтобы все бараны были верховыми.$b$bЧто-что? Где твоя награда? Ха-ха-ха! Тебе разрешили покататься на самом быстром баране в округе! Мало? Тогда так...$b$bТебе выпал шанс помочь другим участникам Фестиваля пива. Молодому наезднику на баранах хватит и работы, и наград.' FROM `quest_offer_reward` WHERE `ID`=11318 AND MD5(`RewardText`)='7719ce2c6d1a2fb317f124a4d668e271' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11318 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11319, 'ruRU', 'Ледяное ядро сработало? Хорошо. Боюсь, мне еще не раз придется его применить. Я уверена, что хранители не остановятся и будут продолжать засеивать поляну.' FROM `quest_offer_reward` WHERE `ID`=11319 AND MD5(`RewardText`)='faa8637ee293a5d0c498ccd2e803dd36' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11319 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11323, 'ruRU', 'Ты как-то странно выглядишь, и запах у тебя необычный... ты не из моей стаи. Расскажи, что привело тебя сюда. Все равно мне больше нечем заняться, пока я заперт в этом месте.' FROM `quest_offer_reward` WHERE `ID`=11323 AND MD5(`RewardText`)='d445af6aa102da61a7fda7eec47fd22a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11323 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11335, 'ruRU', 'Прекрасная новость, $C! Если наши тактические действия будут и впредь столь же успешны, Орде очень скоро придется отступать по всем фронтам!' FROM `quest_offer_reward` WHERE `ID`=11335 AND MD5(`RewardText`)='19cc9b2c0f6c4fe679493a61be4ab30c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11335 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11337, 'ruRU', 'Мы на шаг приблизились к полной победе над Ордой! Мы не можем позволить врагу завоевать плацдарм ни в этом мире, ни в каком другом!' FROM `quest_offer_reward` WHERE `ID`=11337 AND MD5(`RewardText`)='f927369b01c78288bbb3b5e9c00fcdbc' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11337 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11338, 'ruRU', 'Славная работа, $N. Мы должны любой ценой обеспечить нерушимость наших границ!' FROM `quest_offer_reward` WHERE `ID`=11338 AND MD5(`RewardText`)='0856929fd7d9de0e3ff38fa77f8c97ca' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11338 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11339, 'ruRU', 'Ты принес великую славу Орде, $N. Твоя победа сегодня принесет тысячу побед завтра!' FROM `quest_offer_reward` WHERE `ID`=11339 AND MD5(`RewardText`)='c3aa97e63b70aff4c15f9bafe81da958' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11339 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11340, 'ruRU', 'Нет высшей чести, чем изгнать захватчиков с земель Орды! Мы ныне славим твою великую отвагу в помощи нашим войскам!' FROM `quest_offer_reward` WHERE `ID`=11340 AND MD5(`RewardText`)='3e11927d4ef9eb273ed4e95edc4d345e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11340 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11342, 'ruRU', 'Орда в долгу перед тобой, $N. Твой народ гордится твоей отвагой на защите наших земель.' FROM `quest_offer_reward` WHERE `ID`=11342 AND MD5(`RewardText`)='9d6cdf17d8d88166b17490bfa85cb850' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11342 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11356, 'ruRU', 'Вы пришли к детишкам! Замечательно! Они столько горя испытали за свою недолгую жизнь... Хорошо, что они посмотрят на настоящих героев, вроде вас. Это так поднимет их дух!' FROM `quest_offer_reward` WHERE `ID`=11356 AND MD5(`RewardText`)='5dbbe6f7c21c8a3e0f77887bfe1e4368' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11356 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11360, 'ruRU', 'Вы вымокли до нитки и перемазались в саже! Вы наверняка боролись с огнем!\n\nОчень хорошо! Как почетного представителя Пожарной Бригады, прошу вас прийти нам на помощь, как только деревня окажется в беде!' FROM `quest_offer_reward` WHERE `ID`=11360 AND MD5(`RewardText`)='918c1c0a82c9c5b840e9e64b9f1a4bb6' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11360 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11415, 'ruRU', 'Меня радует запах их крови на твоей морде. Братья не должны предавать друг друга.' FROM `quest_offer_reward` WHERE `ID`=11415 AND MD5(`RewardText`)='de711b07b5e5041c7a1b1efb6a155c7e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11415 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11440, 'ruRU', 'Вы вымокли до нитки и перемазались в саже! Вы наверняка боролись с огнем!$B$BОчень хорошо! Как почетного представителя Пожарной Бригады, прошу вас прийти нам на помощь, как только деревня окажется в беде!' FROM `quest_offer_reward` WHERE `ID`=11440 AND MD5(`RewardText`)='cc26c3794ab5056f77738c5572a0d916' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11440 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11441, 'ruRU', 'Хо-хо! Думаешь, бесплатное пиво вкуснее?' FROM `quest_offer_reward` WHERE `ID`=11441 AND MD5(`RewardText`)='65d33983092e7324106029b348b480ea' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11441 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11447, 'ruRU', 'Что?! Бесплатное пиво?\n\nДа,да... Я помню... мы вроде бы обещали его в это в этом году...' FROM `quest_offer_reward` WHERE `ID`=11447 AND MD5(`RewardText`)='c9c354428dc4cbd0632b3f1948ad6161' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11447 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11455, 'ruRU', 'Ай, молодчина! Может быть, это не столь захватывающе, как грабить корабли, но я буду последней сухопутной крысой, если упущу возможность обогатиться.' FROM `quest_offer_reward` WHERE `ID`=11455 AND MD5(`RewardText`)='bb158af3a3fc7e9e3ef0282c336c482c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11455 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11459, 'ruRU', 'Говоришь, ты ничего не $gпонял:поняла; из того, что сказал Зех\'ген? Не удивительно.$B$BНу-ка, посмотрим...' FROM `quest_offer_reward` WHERE `ID`=11459 AND MD5(`RewardText`)='3265d5356e50e7653ed0f7d05747ee4b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11459 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11467, 'ruRU', 'Конрад задолжал мне только золото - его-то я и заберу. Остальное можешь оставить себе.$B$BКстати, если тебе вдруг захочется подзаработать, обращайся ко мне. Пожалуй, я смогу найти для тебя дельце. Попутного тебе ветра, дружище!' FROM `quest_offer_reward` WHERE `ID`=11467 AND MD5(`RewardText`)='a4138849301ed1e7b7dbc8b4004465ee' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11467 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11469, 'ruRU', 'Фу, какой мерзкий запах!$B$BДавай, клади сюда эту штуку. Сейчас я произнесу нужное заклинание - и мыло появится само собой!' FROM `quest_offer_reward` WHERE `ID`=11469 AND MD5(`RewardText`)='0607cfcff0b7aa68aaba9b348e733fb8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11469 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11472, 'ruRU', 'Это замечательно! За этим буйволом последуют другие самцы, и вскоре в наших водах будут плавать маленькие морские львята!$B$BСпасибо, $gдорогой:дорогая; |3-6($r). Этим поступком ты $gискупил:искупила; все злодеяния, совершенные тобой в прошлом.$B$BНо мы должны позаботиться о том, чтобы наши труды принесли плоды. Приходи ко мне завтра - возможно, нам удастся приманить еще одного буйвола.' FROM `quest_offer_reward` WHERE `ID`=11472 AND MD5(`RewardText`)='cf65f8669aa864d2facab670c6d10d31' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11472 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11473, 'ruRU', 'Дуй сюдыть, дружище. Шта, ко мне $gпричухал:причухала;?' FROM `quest_offer_reward` WHERE `ID`=11473 AND MD5(`RewardText`)='81fa453e81990106c2eb50ce0400c0b4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11473 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11476, 'ruRU', 'Мучо спасибос, $gпарниша:девчуха;. Ну и зенки у квакухи!' FROM `quest_offer_reward` WHERE `ID`=11476 AND MD5(`RewardText`)='388896b7052e6d0590565d87441f32bb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11476 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11479, 'ruRU', 'Какая жалость... Дэн был моим другом... И к тому же был должен мне кучу денег! Впрочем, если он действительно спутался с шайкой Южных морей, то он получил по заслугам.$B$BЧто же касается тебя, $gдружище:подружка; - тебя ждет большое будущее. В буквальном смысле.' FROM `quest_offer_reward` WHERE `ID`=11479 AND MD5(`RewardText`)='2bfdaec6c51e55299c29737025c67564' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11479 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11504, 'ruRU', '<Усы Орфуса гневно топорщатся.>$B$BПираты... Кто положит конец их бесчинствам?$B$BМы должны разыскать украденные артефакты и вернуть их на место. Только тогда мой народ будет в безопасности.' FROM `quest_offer_reward` WHERE `ID`=11504 AND MD5(`RewardText`)='a408979f0e1a769a3a93852489c318d8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11504 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11506, 'ruRU', 'Теперь духи стали ближе к умиротворению. Они благосклонны к нам.$B$BКакое унижение для наших врагов – знать, что души их предков обернулись против них, пусть и на время!' FROM `quest_offer_reward` WHERE `ID`=11506 AND MD5(`RewardText`)='d5ead500d1ec824cb79ad09033abf31f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11506 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11508, 'ruRU', 'Хай, дружище. Греззикс никогда не любил связываться с грязными делишками! Всем хороша пиратская доля - пока не приходится пачкать руки в крови.$B$BВидел я эти артефакты - потому и сбежал из Лагеря Скалаваг. Плохие это штуки, очень плохие... $B$BВпрочем, это же твоя жизнь, верно? Хочешь пролезть в Скалаваг - пожалуйста, Греззикс тебе поможет.' FROM `quest_offer_reward` WHERE `ID`=11508 AND MD5(`RewardText`)='d599a90add243fbbef1ea2157985b768' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11508 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11509, 'ruRU', '<Гарри удивленно смотрит на вас.>$B$BА, еще один чудик в нашу команду. Добро пожаловать в клуб!$B$B<Гарри понижает голос.>$B$BЗнаешь, кроме нас тут никто не носит такие шмотки.$B$BА что касается артефактов... Все прикасавшиеся к этим штуковинам либо померли, либо пропали без вести.$B$BНеужели тебе все еще интересно о них узнать? Если что, я могу помочь - конечно, не за доброе слово, а за звонкую монетку.$B$B<Гарри подмигивает.>$B$BРука руку моет, да ножом не колет.' FROM `quest_offer_reward` WHERE `ID`=11509 AND MD5(`RewardText`)='fadcf4eb2da1e4df4d7fe561dc0701c2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11509 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11510, 'ruRU', '<Гарри бережно принимает кристалл из ваших рук и поглаживает его.>$B$BАх, ты моя прелесть! Этот мерзкий кит тебя обидел? Ничего, теперь все будет хорошо. Больше я никому тебя не отдам!$B$B<Гарри отрывается от созерцания шара и смотрит на вас.>$B$BТак на чем мы остановились?' FROM `quest_offer_reward` WHERE `ID`=11510 AND MD5(`RewardText`)='0d36977a8c74f8b2a539e5f910aa2c9a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11510 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11514, 'ruRU', 'Эти контейнеры помогут нам поддерживать портал.\n\nПриходи завтра, и я попрошу тебя добыть еще.' FROM `quest_offer_reward` WHERE `ID`=11514 AND MD5(`RewardText`)='db9bcfacd51fc2a03977e47b9e23c7c9' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11514 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11515, 'ruRU', 'Глупцы. Они научились высасывать энергию Скверны, но не умеют ее накапливать.\n\nНам повезло, $N. Опытный эльф Крови Скверны – страшный противник.' FROM `quest_offer_reward` WHERE `ID`=11515 AND MD5(`RewardText`)='1912daca6628242f85ea57555e2d713a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11515 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11516, 'ruRU', 'Замечательная работа, $N. Демоны, конечно, со временем восстановят врата. Ну, ничего, снова взорвем.' FROM `quest_offer_reward` WHERE `ID`=11516 AND MD5(`RewardText`)='421be39f6930315778fff7a3004362f8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11516 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11519, 'ruRU', 'Ну да, мои салаги прибрали этот щит к рукам! Да вот только проклятый сухопутный шакал Сорлоф спер его у нас. Мож, ты поможешь его отобрать, а?$B$BА то $gсам:сама; видишь, что у меня за команда!$B$B<Капитан Эллис смеется.>$B$BМне на борту требуется еще один салага - заряжать вон те большие дуры на палубе. Справишься с работенкой, дорогуша?$B$BЯкорь мне в глотку! Если свалим Сорлофа - добычу пополам! Тебе щит, мне все остальное!' FROM `quest_offer_reward` WHERE `ID`=11519 AND MD5(`RewardText`)='e618509e99534b0caa1700f5729d538d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11519 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11521, 'ruRU', 'Замечательно, $N.\n\nЕще раз благодарю за помощь!' FROM `quest_offer_reward` WHERE `ID`=11521 AND MD5(`RewardText`)='16ab1b6417eebb7a0abb0f1e5aa765a9' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11521 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11525, 'ruRU', 'Замечательно. Перенастроенные стражи помогут нам защитить наш периметр.' FROM `quest_offer_reward` WHERE `ID`=11525 AND MD5(`RewardText`)='32a10f48b38e334e0cb4701b5dc031af' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11525 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11527, 'ruRU', 'Надеюсь, ты хорошенько $gпроучил:проучила; этих вероломных трюмных крыс! А теперь пора зарядить нашу пушенцию, дружище!' FROM `quest_offer_reward` WHERE `ID`=11527 AND MD5(`RewardText`)='1d915bcf85a345885da08bc225c26218' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11527 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11529, 'ruRU', 'Уговор есть уговор!' FROM `quest_offer_reward` WHERE `ID`=11529 AND MD5(`RewardText`)='17705b95818c6cebff270df1b04b8286' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11529 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11533, 'ruRU', 'Если можешь убить демона сегодня, не откладывай на завтра. Продолжай в том же духе.' FROM `quest_offer_reward` WHERE `ID`=11533 AND MD5(`RewardText`)='da025bf17acb40f3f3f510c2215910e8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11533 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11536, 'ruRU', 'Великолепно! Это поможет мне снабжать наших воинов оружием и доспехами.\n\nТвоя помощь просто неоценима!' FROM `quest_offer_reward` WHERE `ID`=11536 AND MD5(`RewardText`)='0d76a46411820d82b341e726259bb71f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11536 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11537, 'ruRU', 'Твоя преданность достойна быть примером, $N. Мы покажем силам Пылающего Легиона, на что мы способны!' FROM `quest_offer_reward` WHERE `ID`=11537 AND MD5(`RewardText`)='3c96bfe29f243d237561c413a6ecc315' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11537 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11543, 'ruRU', 'Хорошая работа, $N. Нескоро теперь гавань получит подкрепление.' FROM `quest_offer_reward` WHERE `ID`=11543 AND MD5(`RewardText`)='64adbb16fdfcbfc3a334ba04208ebd99' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11543 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11546, 'ruRU', 'Замечательно, $N.\n\nНадеюсь, это поможет тебе в твоих трудах.' FROM `quest_offer_reward` WHERE `ID`=11546 AND MD5(`RewardText`)='0deb86dc250fd6564af14e72f6d5e064' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11546 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11547, 'ruRU', 'Да-да, давай-ка посмотрим...\n\nВроде все в порядке. Хорошо. Вот твой транслокатор.\n\nЕсли полученные тобой данные ошибочны, то куда тебя занесет – никто не знает, и виноват будешь только ты.' FROM `quest_offer_reward` WHERE `ID`=11547 AND MD5(`RewardText`)='d588b19a2600376fe1d584c4e6aee233' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11547 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11548, 'ruRU', 'У вас благородная душа, $N. Среди грохота войны или ликования победы легко забыть о павших. Друзья и родственники погибших благодарят вас.' FROM `quest_offer_reward` WHERE `ID`=11548 AND MD5(`RewardText`)='822158af232741ceeb2467b4f1024979' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11548 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11574, 'ruRU', 'Можешь сказать своей подруге, что ее спасение было нашей обязанностью, и притом приятной обязанностью.\n\nЕе случай был лишь маленьким фрагментом большой головоломки.\n\nДаларан не жалеет усилий для раскрытия этой тайны, и, честно говоря, нам не помешала бы кое-какая помощь...' FROM `quest_offer_reward` WHERE `ID`=11574 AND MD5(`RewardText`)='ff83853b7d8c08deb182a2fe1706fb17' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11574 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11576, 'ruRU', 'Поразительно! Это пока что самая большая аномалия.\n\nНо, боюсь, худшее еще впереди.' FROM `quest_offer_reward` WHERE `ID`=11576 AND MD5(`RewardText`)='36f49af13ae27a08e27de5cbe605f98d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11576 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11582, 'ruRU', 'Какая-какая она по размеру?!\n\nНевероятно! Я должен немедленно сообщить в Даларан!' FROM `quest_offer_reward` WHERE `ID`=11582 AND MD5(`RewardText`)='61be7ed2260b17435b2cf9c88288505c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11582 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11586, 'ruRU', 'Не думай, что я забыл, что ты сделал для моего народа в Награнде, $N. Адский Крик ничего не забывает.\n\nС тех пор я в долгу у тебя, и поэтому сейчас я даю тебе этот шанс: беги. Покинь это место и не оглядывайся.\n\nВозвращайся домой и молись за тех, кто погибнет.' FROM `quest_offer_reward` WHERE `ID`=11586 AND MD5(`RewardText`)='e13ffae73e3eb055c7035937771216ea' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11586 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11587, 'ruRU', 'Молодец, $N! Кирин-Тор благосклонно принимает оказанную тобой помощь. Знай, что ни одна твоя услуга не останется без награды!\n\nПрошу тебя, прими этот скромный дар в знак признательности Даларана.' FROM `quest_offer_reward` WHERE `ID`=11587 AND MD5(`RewardText`)='4fb6467b8c7cfde80de6f04c43076b14' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11587 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11590, 'ruRU', 'Отличная работа, $N.\n\nСейчас он будет готов к допросу.' FROM `quest_offer_reward` WHERE `ID`=11590 AND MD5(`RewardText`)='177357113fcf1592f3cd19870b5318c3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11590 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11596, 'ruRU', 'Как раз вовремя... Нерубы, кажется, удвоились в числе буквально за неделю. Мы ни от чьей помощи не откажемся.' FROM `quest_offer_reward` WHERE `ID`=11596 AND MD5(`RewardText`)='4d609fafe3eb587042a621d7552f83de' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11596 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11598, 'ruRU', 'Тебе удалось замедлить их продвижение, но все равно скоро в битву вступит еще больше. Тебе случайно не удалось найти ни одной их кладки, пока ты был в карьере?' FROM `quest_offer_reward` WHERE `ID`=11598 AND MD5(`RewardText`)='d5a45427c5e02dd3a972d7f16a7bf05c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11598 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11602, 'ruRU', 'Что бы мы ни делали, они все прибывают. Еще немного, и мы можем не выдержать, $N.' FROM `quest_offer_reward` WHERE `ID`=11602 AND MD5(`RewardText`)='17d9fa459fcd1401ccedc692e6a0664d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11602 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11609, 'ruRU', '<Вы принесли предметы к статуе старейшины Атканока.>\n\nЭтого должно быть достаточно, хотя они и в жалком состоянии, увы! А ведь некоторые из них прослужили сотни лет – и все лишь затем, чтобы их терзали и трепали какие-то варвары!' FROM `quest_offer_reward` WHERE `ID`=11609 AND MD5(`RewardText`)='9f751c87b2847e9db7dc654c2678a62f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11609 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11611, 'ruRU', 'Большинству из них удалось вернуться. По крайней мере, тем, у кого хватило ума сообразить, что мы внутри этих гигантских зданий из камня и металла…\n\nКак бы там ни было, ты хорошо справился с работой. Я слышал, тебе удалось освободить немало батраков.\n\nО да, ты теперь – первый парень на... ну... на крепости.' FROM `quest_offer_reward` WHERE `ID`=11611 AND MD5(`RewardText`)='61e4c63379fe5e18f18739f85a76f4de' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11611 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11617, 'ruRU', 'Охотники на магов поймут, что разорить наш карьер и разграбить наши артефакты не так просто, как они думали. С твоей помощью мы отвоюем карьер и все восстановим.' FROM `quest_offer_reward` WHERE `ID`=11617 AND MD5(`RewardText`)='405b8d2747db7409499fe9983e55760d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11617 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11618, 'ruRU', 'И это все?! Один-единственный |3-6($R)? \n\nБудь моя челюсть на месте, я уронил бы ее на пол!' FROM `quest_offer_reward` WHERE `ID`=11618 AND MD5(`RewardText`)='a2c70b3ae1b8b1d3f2dca0baeb7c16e4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11618 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11624, 'ruRU', 'Не глупо ли было являться сюда, маленький |3-6($R)? Чего ты ищешь?' FROM `quest_offer_reward` WHERE `ID`=11624 AND MD5(`RewardText`)='d1f0f1c8e82857435e814b9fe86eab2b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11624 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11627, 'ruRU', 'Я довольна, хотя, конечно, они еще некоторое время будут ссориться.\n\nОднако тебе, прежде чем вернуться к твоей говорящей с духами, придется выполнить кое-что еще.' FROM `quest_offer_reward` WHERE `ID`=11627 AND MD5(`RewardText`)='c5e44caef6843c4dd5926d38978b4838' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11627 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11629, 'ruRU', 'Империан дала тебе свою собственную изначальную сущность? Да, я слышу, как ревут ее ветры!\n\nЯ знаю ритуал, который нам поможет. Но надо спешить, пока ее изначальная сущность не взорвалась изнутри!' FROM `quest_offer_reward` WHERE `ID`=11629 AND MD5(`RewardText`)='ef03278a7093f4b15631031af8fd3898' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11629 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11632, 'ruRU', '<Саурфанг ухмыляется.>\n\nЧто-то знакомое... Армия Калимдора раздавила тысячи таких жуков, как этот, в пустынях Силитуса.\n\nЭто иное место – иная среда – но результат будет тем же самым.\n\n<Саурфанг внимательно смотрит на вас.>\n\nВ Нордсколе ты принесешь Орде честь и славу, $N.\n\n<Саурфанг кивает.>' FROM `quest_offer_reward` WHERE `ID`=11632 AND MD5(`RewardText`)='a02fb9245dd0f647cb2037e096904d7a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11632 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11634, 'ruRU', 'Привет! Я ждал тебя\n\n<То\'бор указывает на запад.>\n\nГлянь-ка туда. Там, за тундрой – смерть. Смерть, понимаешь?' FROM `quest_offer_reward` WHERE `ID`=11634 AND MD5(`RewardText`)='f917414bd660b2880377412457d42843' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11634 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11635, 'ruRU', 'Спасибо за отсрочку, |3-6($C). Ах, если бы столь же легко достижимой была моя истинная свобода!..' FROM `quest_offer_reward` WHERE `ID`=11635 AND MD5(`RewardText`)='a0d6d7e06457b5b5069a2cea986af0fe' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11635 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11636, 'ruRU', 'НИКАКОЙ ПОЩАДЫ МЕРТВЫМ!\n\nНи у кого из них не хватит сил стоять позади и защищать наши прославленные танки после того, как Адский Крик решил, что судьба побережья определена. Здесь обычно спокойно, и можно наблюдать, как Плеть формирует ряды для штурма крепости Песни Войны. Иногда мне удается наткнуться на заблудившегося зомби или вурдалака, но их надолго не хватает.\n\n<Обжора поглаживает свой топор.>\n\nИ, конечно, здесь туман...\n\n<Обжору кидает в дрожь.>' FROM `quest_offer_reward` WHERE `ID`=11636 AND MD5(`RewardText`)='210d277634970b334c6d2efa25865fbf' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11636 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11642, 'ruRU', 'А, так ты новый водитель танка, дружище? Сойдет! Нам нужно просто снова заставить эти штуковины ехать. Да уж, только попробуй забраться на равнины Назама без танка – и ты, считай, труп.' FROM `quest_offer_reward` WHERE `ID`=11642 AND MD5(`RewardText`)='de53d06c093eae519a72ea09e06abd47' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11642 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11643, 'ruRU', 'Отличная работа, дружище! Ммм, и куда ж я задевал запчасти-то...' FROM `quest_offer_reward` WHERE `ID`=11643 AND MD5(`RewardText`)='5b2d28933c324f73420905b1257ee48a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11643 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11644, 'ruRU', 'Отличная работа, дружище! Тэкс, куда ж я задевал эту пневматическую трансзажиматрицу для танков?' FROM `quest_offer_reward` WHERE `ID`=11644 AND MD5(`RewardText`)='e2fb53084c4149abc8af74abd5aa49b6' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11644 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11646, 'ruRU', 'Донатан мудро поступил, прислав тебя, |3-6($C).\n\nТеперь выясняется, что мне понадобится кто-то, не входящий в Кирин-Тор.' FROM `quest_offer_reward` WHERE `ID`=11646 AND MD5(`RewardText`)='562a35a8b0aa66b9712de01aed6b2ad3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11646 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11648, 'ruRU', 'Отлично! Эти сведения были жизненно важными!\n\nМолодец, друг мой!' FROM `quest_offer_reward` WHERE `ID`=11648 AND MD5(`RewardText`)='393e53ecbb1824c2e165da5d1be482ec' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11648 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11649, 'ruRU', 'Я сожалею о гибели этих бурь, но слово мое крепко... даже данное смертному существу вроде тебя.\n\nТеперь посмотрим, смогу ли я сделать что-то, что окажется тебе полезным.' FROM `quest_offer_reward` WHERE `ID`=11649 AND MD5(`RewardText`)='91d30c63ab272e506a4c2817eee41f0d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11649 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11651, 'ruRU', 'При нынешнем состоянии наших кораблей и морских путей мы никак не могли доставить эту проклятую боевую машину в Песню Войны. Эти танки – все, что у нас осталось от первоначальной экспедиции. Теперь, когда они пригодны к работе, вы можете использовать их, чтобы стереть в порошок войска Плети на равнинах Назама.' FROM `quest_offer_reward` WHERE `ID`=11651 AND MD5(`RewardText`)='4a31a1acda2ae939a66634ae781f062e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11651 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11654, 'ruRU', '<Снежный следопыт таунка плохо выглядит и еле-еле отвечает вам.>\n\nЯ не... долго. Может... может, ты сможешь остановить их... прежде чем...' FROM `quest_offer_reward` WHERE `ID`=11654 AND MD5(`RewardText`)='4fb5159554a851e88801d8c0bd443722' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11654 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11655, 'ruRU', '<Печаль охватывает Вальтора.>\n\nРуины... Это все, что квалдиры оставляют после себя. Им надо преподать урок.' FROM `quest_offer_reward` WHERE `ID`=11655 AND MD5(`RewardText`)='e8dc7ec61a62efa0c769dc8b5a2877fe' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11655 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11656, 'ruRU', 'Демонстрация нашего сопротивления квалдирским дикарям – может быть, именно это и нужно, чтобы спасти моих соплеменников в других лагерях. Может быть, квалдирцы пересмотрят свои действия, если уверятся, что возмездие неизбежно.' FROM `quest_offer_reward` WHERE `ID`=11656 AND MD5(`RewardText`)='b95ff2ddf9e06fc27815f59772eb4bb9' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11656 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11660, 'ruRU', 'Ты должен призвать Орабуса с помощью рога старого морехода.' FROM `quest_offer_reward` WHERE `ID`=11660 AND MD5(`RewardText`)='779887a9a78418e1d1d5e4b820a3b287' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11660 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11661, 'ruRU', 'Похоже, убийство их лейтенанта только разворошило осиное гнездо. Они стали еще злее и агрессивнее, чем раньше!\n\n<Вальтор вздыхает.>\n\nЧто ж, дружище, ты сделал здесь все, что мог. Тебе как минимум полагается компенсация за уменьшение их числа.' FROM `quest_offer_reward` WHERE `ID`=11661 AND MD5(`RewardText`)='ac0ebbfa15be5a373d507fe1de557c8e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11661 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11663, 'ruRU', 'Прошу прощения, $N. Я знаю, что это была малоприятная работа.\n\nЕсли бы не то отчаянное положение, в каком мы оказались, я бы никогда не просил тебя помочь таким образом.\n\nИтак... что тебе удалось выяснить?' FROM `quest_offer_reward` WHERE `ID`=11663 AND MD5(`RewardText`)='6a6690fc82ba5ee43517140dd533a176' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11663 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11664, 'ruRU', 'Об этом шепчутся ветра, друг. Твое имя известно стихиям. Муту не забудут твоей услуги!' FROM `quest_offer_reward` WHERE `ID`=11664 AND MD5(`RewardText`)='6bc986f60cf715d23781262bebd7eb95' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11664 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11665, 'ruRU', 'Вот убогая тварь! Уверен, Скалл сумеет из него сделать что-нибудь вкусненькое.\n\nДа шучу, шучу.\n\nСтарина Барло хитренько подмигивает.' FROM `quest_offer_reward` WHERE `ID`=11665 AND MD5(`RewardText`)='a2d2bcc6ac85f8d380822d14412538f6' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11665 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11666, 'ruRU', 'Приятно посмотреть... Ты крупную рыбку выудила! Сегодня старику достанется королевский ужин.' FROM `quest_offer_reward` WHERE `ID`=11666 AND MD5(`RewardText`)='3b189298dec3463e2934479aeafb6ae3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11666 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11668, 'ruRU', 'Ты и с крючком, и с ножом славно управляешься. Давай-ка сюда этих миленьких креветочек, и я дам тебе попробовать блюдо.' FROM `quest_offer_reward` WHERE `ID`=11668 AND MD5(`RewardText`)='d44cfce43e14b78b29bd71fd8b88f42b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11668 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11671, 'ruRU', 'Сломан??\n\nДай-ка взглянуть...' FROM `quest_offer_reward` WHERE `ID`=11671 AND MD5(`RewardText`)='94f76ff58746527a13cad1edbf04f7b0' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11671 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11676, 'ruRU', 'Каждый спасенный пленник – это одной аберрацией меньше, $N. Орда тебе многим обязана.' FROM `quest_offer_reward` WHERE `ID`=11676 AND MD5(`RewardText`)='bed7a219a03eeed1a9c1cd6727536d64' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11676 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11678, 'ruRU', 'Мне… недолго… осталось, |3-6($R)…' FROM `quest_offer_reward` WHERE `ID`=11678 AND MD5(`RewardText`)='eb9bf91e79e9d86ab9f21420e0d28fbb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11678 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11679, 'ruRU', 'Эти детские игры, в которые вы здесь играете, не имеют никакого значения…\n\nТы вместе со своими даларанскими друзьями – вы хватаетесь за отдельные болтающиеся ниточки, когда рвется ткань мироздания.\n\nОднако для моих драконов это может оказаться неплохим развлечением, в котором они нуждаются.\n\nПокажи-ка мне этот ключ...' FROM `quest_offer_reward` WHERE `ID`=11679 AND MD5(`RewardText`)='d6dd1657c6631ba020bd43f758bb2065' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11679 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11680, 'ruRU', 'Вот он! Ключ – наш!' FROM `quest_offer_reward` WHERE `ID`=11680 AND MD5(`RewardText`)='d2339e93a6dfb5a12b185cf800445102' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11680 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11681, 'ruRU', 'Ваши героические деяния не будут забыты, |3-6($C)!\n\nПрошу вас, примите это вместе с моей искренней благодарностью.' FROM `quest_offer_reward` WHERE `ID`=11681 AND MD5(`RewardText`)='c8f7b2013fff8532344ba8c0d7823f39' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11681 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11682, 'ruRU', 'А, |3-6($R), вот и довелось нам встретиться снова!\n\nВпрочем, когда ты услышишь мои слова, ты пожалеешь об этом.' FROM `quest_offer_reward` WHERE `ID`=11682 AND MD5(`RewardText`)='6aaf599d6fa41cb200f20b5cabb014c5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11682 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11685, 'ruRU', 'Этого должно хватить, чтобы создать основу для могущественного элементаля, однако одного камня недостаточно, чтобы вдохнуть в него жизнь…' FROM `quest_offer_reward` WHERE `ID`=11685 AND MD5(`RewardText`)='cf51e118adcf89946afd1b3f7b98f2ce' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11685 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11688, 'ruRU', 'Кажется, получилось, |3-6($R)!' FROM `quest_offer_reward` WHERE `ID`=11688 AND MD5(`RewardText`)='6cd52a59bc16bbc982a8e790ef212aaa' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11688 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11690, 'ruRU', 'Ты настоящий герой, $N! Если бы не ты, мои кодо бы все перемерли. Я тебе признателен, как и все солдаты и путники, которым эти кодо пригодятся в Нордсколе!' FROM `quest_offer_reward` WHERE `ID`=11690 AND MD5(`RewardText`)='0c0afd319f284b084b6b21b86522524a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11690 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11702, 'ruRU', 'Наконец-то прибыла помощь! Судя по твоему виду, ты из Орды?\n\nЭто неплохо… ваши – хорошие воины. Именно это нам и нужно, причем в больших количествах.' FROM `quest_offer_reward` WHERE `ID`=11702 AND MD5(`RewardText`)='147df99f1915c566e6494512c40365a6' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11702 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11703, 'ruRU', '<Гетри скептически осматривает вас.>\n\nА получше у Икориса никого не нашлось?' FROM `quest_offer_reward` WHERE `ID`=11703 AND MD5(`RewardText`)='d5e68b79b8883c50d3da893e4b794c70' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11703 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11705, 'ruRU', 'И ты возвращаешься с победой, как я и думал! Я же говорил Саурфангу, что с тобой все будет в порядке!\n\n<Адский Крик хмыкает.>\n\nМожет быть, этот старый пес хоть теперь поймет, что он не всеведущ?' FROM `quest_offer_reward` WHERE `ID`=11705 AND MD5(`RewardText`)='13ddf06caa7ce0484bc626985db61ecb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11705 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11709, 'ruRU', '<Нок фыркает.>\n\nПленные? Да какие это пленные! Это трусливые шавки! Ты только взгляни на них! Ты знаешь, что все они – все без исключения! – явились под стены нашей крепости и добровольно сложили оружие?\n\nНасколько мы поняли, если они попадают в плен, их потом разжалуют и отпускают по домам!\n\n<Нок плюется.>\n\nЖалкие твари!' FROM `quest_offer_reward` WHERE `ID`=11709 AND MD5(`RewardText`)='0302d0267c4f3e270e50099476686597' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11709 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11716, 'ruRU', 'Великолепно! Просто великолепно!\n\n<Лаурит посыпает пыльцой один из кровоспоровых плодолистиков и произносит заклинание.>\n\nХм-м… Ничего не понимаю. Разве что… Ну да, конечно!' FROM `quest_offer_reward` WHERE `ID`=11716 AND MD5(`RewardText`)='f9728d7dd332b959638d5bed8e13d9a0' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11716 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11717, 'ruRU', 'Агааа!\n\n<Лаурит посыпает пыльцой кровоспоровые плодолистики.>\n\nПогляди-ка!' FROM `quest_offer_reward` WHERE `ID`=11717 AND MD5(`RewardText`)='5f597baaf53e17ec355739ecbb14c417' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11717 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11719, 'ruRU', 'Старец Крутой Рог будет просто в восторге! Все даже лучше, чем я ожидала!\n\nМожет быть, настало время открыть тебе правду.' FROM `quest_offer_reward` WHERE `ID`=11719 AND MD5(`RewardText`)='81da19855cc25ff7b14af80bee7ce611' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11719 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11720, 'ruRU', 'Кровоспор, что ты собрал, должно как раз хватить, чтобы дать нам шанс против магнатавров Гаммота – конечно же, с твоей помощью.' FROM `quest_offer_reward` WHERE `ID`=11720 AND MD5(`RewardText`)='182101b40c4dbc1af16246ed1ab90756' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11720 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11733, 'ruRU', 'Добро пожаловать в Хладарру, |3-6($C)! \n\nМаскировочный щит скрывает нас от Нексуса, твердыни великого аспекта Малигоса и его синих драконов, но на самом деле туда рукой подать.\n\nРасполагайся поудобнее…' FROM `quest_offer_reward` WHERE `ID`=11733 AND MD5(`RewardText`)='44b36d64d5b3507666dda3ce713b3c23' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11733 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11875, 'ruRU', 'Благодарю за помощь, $N. Любая помощь в час войны бесценна. Наши воины не должны упускать ни единого преимущества в этой войне.' FROM `quest_offer_reward` WHERE `ID`=11875 AND MD5(`RewardText`)='3f9127d65fb7e349f0419cd5ba0be71d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11875 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11876, 'ruRU', '<Верховный друид утирает слезы с глаз.>$B$BШансы их невелики. Осиротевшие, они все равно умрут...' FROM `quest_offer_reward` WHERE `ID`=11876 AND MD5(`RewardText`)='3f6efda2cf0f005cbb5af7424be280dd' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11876 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11880, 'ruRU', 'Спасибо за помощь. Ты понятия не имеешь, каково общаться с этим "Доктором" Ваффелем. Когда он не "проверяет", как идут у меня дела, он треплется о том или другом прибамбасе, который можно получить в результате его военно-технических изысканий.' FROM `quest_offer_reward` WHERE `ID`=11880 AND MD5(`RewardText`)='9b7e4b4e993ba93ca30807f5f0ff8567' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11880 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11881, 'ruRU', '<Феззикс разглядывает добычу.>\n\nДженни немного стерла себе спину, но это ничего, заживет. А вот останки летательного аппарата пострадали несколько более, чем я ожидал… Ну да ничего, как-нибудь разберусь. Ты пока не уходи, еще пригодишься. Надо же восстановить эту игрушечку!' FROM `quest_offer_reward` WHERE `ID`=11881 AND MD5(`RewardText`)='cd5a5f2cc275854ed383e39091cfc00c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11881 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11887, 'ruRU', 'Гномьи ремнаборы? Это мне? Теперь чинить машины станет еще проще!' FROM `quest_offer_reward` WHERE `ID`=11887 AND MD5(`RewardText`)='86a26f03537ce3ed1b5c5aaf4909b7d8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11887 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11888, 'ruRU', 'Меня не удивляет, что у вождя орков нет времени выслушивать наши проблемы. Усилия посла – как туман, рассеивающийся по ветру…\n\nНо теперь здесь ты. Посмотрим, сделал ли он правильный выбор, прислав тебя.' FROM `quest_offer_reward` WHERE `ID`=11888 AND MD5(`RewardText`)='7e21516106a2e2d73092d60aa8afe73c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11888 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11890, 'ruRU', 'Тревожные новости.\n\nМой народ скоро покинет эти места. Мы собираемся прорваться через боевые порядки Плети, чтобы добраться до нашей столицы, Ледяной Пыли, что на Драконьем Погосте.\n\nНо прежде чем мы сделаем это, нужно разобраться с тем, что натворили гномы в своем безумии.' FROM `quest_offer_reward` WHERE `ID`=11890 AND MD5(`RewardText`)='2654e70e754756442a0b74d4b85ea062' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11890 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11893, 'ruRU', '<Дорейн кивает.>\n\nХорошо. Этого должно хватить, чтобы продемонстрировать Феззиксу то, что я пытаюсь ему объяснить.' FROM `quest_offer_reward` WHERE `ID`=11893 AND MD5(`RewardText`)='3330bac35b18fd00baf8d4a8fd5b47d3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11893 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11894, 'ruRU', 'Фантастика! Еще несколько таких трюков – и я стану настоящим воздушно-десантным гоблином!' FROM `quest_offer_reward` WHERE `ID`=11894 AND MD5(`RewardText`)='6ce44ae7786077d079d49a3526b48375' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11894 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11896, 'ruRU', 'Теперь, когда с роботами покончено, пора взяться за добычу покрупнее! Увы, я чувствую, что ярость шторма в тебе уже убывает. \n\nТем не менее свое дело она сделала, и думаю, что тебе вполне по плечу сделать следующий шаг и без нее.' FROM `quest_offer_reward` WHERE `ID`=11896 AND MD5(`RewardText`)='e308bc4a8c473e54f24c64045e621e17' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11896 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11898, 'ruRU', 'Теперь, когда принц побежден, владычеству Плети в Борейской тундре на время пришел конец. Конечно, это ненадолго – вскоре они вернутся. Поэтому я буду готовить Дурма к тому, чтобы увести жителей деревни в Ледяную Пыль.\n\n<Вождь медленно качает головой.>\n\nПри всех наших разногласиях с Дурмом, я доверяю его уму и способностям. А сам я не смогу заставить себя уйти из Таунка\'ле. Я буду оборонять деревню, пока не погибну.' FROM `quest_offer_reward` WHERE `ID`=11898 AND MD5(`RewardText`)='53026dec7adc6546c0a22f1d138e760e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11898 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11899, 'ruRU', 'Теперь освободим пойманные тобой души…' FROM `quest_offer_reward` WHERE `ID`=11899 AND MD5(`RewardText`)='2cba3f1bf6f05f9f461affffe375945e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11899 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11900, 'ruRU', 'Ситуация еще хуже, чем я ожидал.\n\nМалигос вливает слишком много энергии в это место. Если его не остановить, Азерот станет вторым Запредельем!\n\nК счастью, я, кажется, выработал временное решение...' FROM `quest_offer_reward` WHERE `ID`=11900 AND MD5(`RewardText`)='2837a7b530d836226a8092d1999e136c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11900 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11905, 'ruRU', 'Отличная работа, $N! Колебания уже начали слабеть.\n\nЕсли повезет, благодаря твоим усилиям мы получим отсрочку, достаточно долгую, чтобы успеть помешать планам Малигоса.' FROM `quest_offer_reward` WHERE `ID`=11905 AND MD5(`RewardText`)='74fe31d8e1d583360eda37c7a774a8d0' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11905 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11906, 'ruRU', 'Таунка считают справедливым оставить землю девственно чистой, когда уходят жить в другое место.\n\nМы отправимся в нашу столицу, Ледяную Пыль, и очень скоро. Твоя помощь поможет нам ускорить переселение.\n\nСпасибо тебе.' FROM `quest_offer_reward` WHERE `ID`=11906 AND MD5(`RewardText`)='6c7d2681e12ed4c5874a8d17ab533371' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11906 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11910, 'ruRU', 'Да-да. Вот эти отлично подойдут.\n\nСпасибо тебе, |3-6($R).' FROM `quest_offer_reward` WHERE `ID`=11910 AND MD5(`RewardText`)='1f366fa19cef9bee0d16546d75b7366d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11910 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11912, 'ruRU', 'Ну, конечно, это немного, но все-таки поможет нам протянуть лишний день.\n\nДумаю, это будет справедливая плата за труды?' FROM `quest_offer_reward` WHERE `ID`=11912 AND MD5(`RewardText`)='09ef3544132efe5e17db553f95c30bd6' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11912 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11914, 'ruRU', 'Твои услуги Даларану не останутся незамеченными, |3-6($R).\n\nЯ надеюсь, ты сочтешь эту плату достаточной.' FROM `quest_offer_reward` WHERE `ID`=11914 AND MD5(`RewardText`)='1cce25b6cfa416364dcb35fed3ff31fe' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11914 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11916, 'ruRU', 'Боюсь, твоя помощь пришла слишком поздно. Многие из моих собратьев уже оставили Таунка\'ле. Они ищут убежища в Драконьем Погосте, далеко на востоке.\n\nОднако тут у нас еще много работы, и мало рук, чтобы ее выполнить…' FROM `quest_offer_reward` WHERE `ID`=11916 AND MD5(`RewardText`)='d603cec479921e9f6cbd18c4b522257e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11916 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11918, 'ruRU', 'Ну хорошо, |3-6($C), теперь, после первого знакомства с врагом, пришло время браться за работу.' FROM `quest_offer_reward` WHERE `ID`=11918 AND MD5(`RewardText`)='53d800ce7066834b3b44a32ba70d21ce' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11918 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11919, 'ruRU', 'Судьба этих юных драконов не должна лежать бременем на твоей совести, |3-6($R). За все это несет ответственность Малигос.\n\nЯ без устали тружусь над раскрытием тайн этих рун. И, конечно, мы не собираемся отнимать больше жизней, чем это необходимо.' FROM `quest_offer_reward` WHERE `ID`=11919 AND MD5(`RewardText`)='24d6d770b16739207ce24427068d9a98' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11919 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11929, 'ruRU', '<Мать Тауранук утирает слезы.>\n\nБыло время, когда я могла бродить по этой тундре, и только бесконечные снега открывались моему взору.\n\nНо снег покинул нас – это знак, что наше время здесь тоже подошло к концу. Мы оставляем позади себя деревню Таунка\'ле, Борейскую Тундру и много-много счастливых воспоминаний...\n\n<Мама Тауранук всхлипывает.>\n\nБыть может, в будущем нам доведется узнать радость возвращения – вместе со снегом.' FROM `quest_offer_reward` WHERE `ID`=11929 AND MD5(`RewardText`)='6459e3f2a9240a45b2268300b87f395b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11929 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11930, 'ruRU', '<Вартук бросает на вас мрачный взгляд.>\n\nЛедяной Пыли более не существует...' FROM `quest_offer_reward` WHERE `ID`=11930 AND MD5(`RewardText`)='3726dcb2440f673e04d6539f632b828c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11930 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11931, 'ruRU', 'Ты отлично справился, |3-6($R).\n\nБудем надеяться, что мы найдем ключ, который можно будет использовать против Малигоса.' FROM `quest_offer_reward` WHERE `ID`=11931 AND MD5(`RewardText`)='4d28dcfc0133e74cadbfc12ef5bae24d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11931 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11936, 'ruRU', 'Мне очень жаль уничтожать яйца драконов, пусть даже вражеских.\n\nНо увы, на войне как на войне…' FROM `quest_offer_reward` WHERE `ID`=11936 AND MD5(`RewardText`)='a6d3260ce84b3e635bc89e5b1309b8a5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11936 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11940, 'ruRU', 'Судьба этих юных драконов не должна лежать бременем на твоей совести, |3-6($R). За все это несет ответственность Малигос.\n\nЯ без устали тружусь над раскрытием тайн этих рун.\n\nИ уж конечно, мы не собираемся отнимать больше жизней, чем это необходимо.' FROM `quest_offer_reward` WHERE `ID`=11940 AND MD5(`RewardText`)='ef82a5c173fb3aed776796e42d66bbb6' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11940 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11941, 'ruRU', 'С твоей стороны было мудро принести эту вещь мне, $N.\n\n<Релораз рассматривает обломок и медленно кивает.>\n\nЕсли ты и вправду хочешь внести свой вклад в наши усилия, то, сколь бы это ни было рискованно, я расскажу тебе о том, что это и для чего оно нужно.' FROM `quest_offer_reward` WHERE `ID`=11941 AND MD5(`RewardText`)='d6891f3546af5609ae2126ee1999a2ae' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11941 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11943, 'ruRU', '<Когда Релораз берет в руки собранные вами фрагменты, они начинают ярко светиться.>\n\nГотово!\n\nЯ чувствую, что в этой тюрьме заточено могущественное существо. Будем надеяться, что оно окажется союзником…' FROM `quest_offer_reward` WHERE `ID`=11943 AND MD5(`RewardText`)='eaa082205f8fce563cef0e38480ef3a5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11943 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11946, 'ruRU', 'Мы не можем ждать, пока ко мне вернутся силы. \n\nЯ должна положиться на тебя в процессе подготовки...' FROM `quest_offer_reward` WHERE `ID`=11946 AND MD5(`RewardText`)='2b9ba40556104c08525627372f55dcf9' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11946 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11951, 'ruRU', 'Спасибо тебе, $N.\n\nЗаточение измотало меня, и силы возвращаются ко мне очень медленно.\n\nЯ буду расходовать энергию этих кристаллов очень осторожно. Это побочный продукт коварных замыслов Малигоса. Но, если удача нам улыбнется, они же помогут нам победить его!' FROM `quest_offer_reward` WHERE `ID`=11951 AND MD5(`RewardText`)='b3908f9cbf677e9977812e8e5a57af6f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11951 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11968, 'ruRU', 'Ты оказал нам большую услугу, |3-6($R). Битва еще не выиграна, но теперь у моего народа есть шанс.' FROM `quest_offer_reward` WHERE `ID`=11968 AND MD5(`RewardText`)='03c47c953995e21319f946f3245540ba' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11968 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11977, 'ruRU', 'То, что ты видишь, – это все, что осталось от таунка Борейской тундры и Драконьего Погоста. Это сломленный народ… измученный Плетью и поставленный ею же на грань уничтожения.\n\n<Светлое Копыто печально качает головой.>\n\nТолько Орда может теперь их спасти. Только Орда может поднять их сломленный дух. Мы будем заботиться о них, чтобы помочь им выздороветь, а они, в свою очередь, усилят позиции Орды в Нордсколе.' FROM `quest_offer_reward` WHERE `ID`=11977 AND MD5(`RewardText`)='9f9cb46f5d23b2e587cd900ef44a5f65' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11977 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11979, 'ruRU', 'То, что ты видишь, – это все, что осталось от таунка Борейской тундры и Драконьего Погоста. Это сломленный народ… измученный Плетью и поставленный ею же на грань уничтожения.\n\n<Светлое Копыто печально качает головой.>\n\nТолько Орда может теперь их спасти. Только Орда может поднять их сломленный дух. Мы будем заботиться о них, чтобы помочь им выздороветь, а они, в свою очередь, усилят позиции Орды в Нордсколе.' FROM `quest_offer_reward` WHERE `ID`=11979 AND MD5(`RewardText`)='206b0f889106bf2330c5f17677178e54' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11979 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11984, 'ruRU', 'Ай, молодчина, |3-6($C). Пожалуй, старина Бадд нам еще пригодится.\n\nСейчас я распоряжусь насчет клетки с троллем и выдам тебе твою часть награды.\n\nКстати, я же еще не поприветствовал тебя в нашем лагере! Не убегай далеко – тут для тебя всегда найдется работа...' FROM `quest_offer_reward` WHERE `ID`=11984 AND MD5(`RewardText`)='4bcab7f3ab4d98b538f9c9d7f42063a8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11984 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11989, 'ruRU', 'Отлично!\n\nОтныне ты $Gмой брат:моя сестра; по крови. Такую связь разорвать невозможно.\n\nА теперь слушай и запоминай, что тебе скажет Дракуру, |3-6($R). Нам предстоит многое совершить.' FROM `quest_offer_reward` WHERE `ID`=11989 AND MD5(`RewardText`)='3922d82690d6012f6e742b4d8b27fa5c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11989 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11990, 'ruRU', '<Дракуру берет у вас ингредиенты и смешивает их в пузырьке.>\n\nВот так, $Gдруг:подруга;. А теперь – за работу!' FROM `quest_offer_reward` WHERE `ID`=11990 AND MD5(`RewardText`)='c0debac067280f6c21653813abb35f17' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11990 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11991, 'ruRU', 'Ай, $Gмолодец, друг:умница, подруга;!\n\nОтсюда мне прекрасно видно надписи на стенах...' FROM `quest_offer_reward` WHERE `ID`=11991 AND MD5(`RewardText`)='bc8f438c920654ca3351dca43a543a87' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11991 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11996, 'ruRU', 'Почему так долго? Время останавливается лишь для Аспектов, $R.\n\nУ нас с тобой полно дел.' FROM `quest_offer_reward` WHERE `ID`=11996 AND MD5(`RewardText`)='2de4be84467fccabe327e40275438934' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11996 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 11999, 'ruRU', 'Любопытно. Они хотят заключить договор с Эфириумом? Эфириалы могут оказаться могущественными союзниками для Малигоса с его безумными замыслами…\n\nЭтого нельзя допустить!' FROM `quest_offer_reward` WHERE `ID`=11999 AND MD5(`RewardText`)='ce39194baefd9bde1870e7ce52819f24' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=11999 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12006, 'ruRU', 'Очень хорошо, ты выполнил мою просьбу. \n\nСпасибо тебе, |3-6($R).' FROM `quest_offer_reward` WHERE `ID`=12006 AND MD5(`RewardText`)='1dc83a905c47c75400ac2d889ed80c1f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12006 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12007, 'ruRU', 'Это он!\n\nЕще лучше, чем я надеялся! Вот она, последняя надежда человечества в эти темные времена.\n\nНе будем тратить время зря. Давай-ка найдем следующий артефакт!' FROM `quest_offer_reward` WHERE `ID`=12007 AND MD5(`RewardText`)='b694e80b627d90c69f50b358cde62a92' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12007 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12008, 'ruRU', 'Хотя ты, несомненно, являешься доблестным защитником дела Орды, многие работают не покладая рук над тем, чтобы укрепить и расширить наши позиции в Нордсколе. И сейчас у нас есть силы, организовывающие базы на мерзлых просторах этих пустынных земель.\n\nМы окружаем армию Плети со всех сторон. Победа становится все ближе по мере того, как увеличивается наша армия у подножия Врат Гнева, Ангратара. Скоро мы разнесем врата и ворвемся на Ледяную Корону.\n\nНо еще многое нужно сделать...\n\nДля начала нужно остановить нерубов!' FROM `quest_offer_reward` WHERE `ID`=12008 AND MD5(`RewardText`)='21007cb3db7050f23b654e44a41c1f4d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12008 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12026, 'ruRU', 'А кто такой этот Бранн Бронзобород? Я еще могу понять, почему железные дворфы не стали с ним связываться – но что полезного может поведать нам его дневник?' FROM `quest_offer_reward` WHERE `ID`=12026 AND MD5(`RewardText`)='445954f3499acfc05c4ec8fadd5ddcd5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12026 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12029, 'ruRU', 'Ай, молодца!\n\n<Мак заходится истерическим хохотом.>\n\nАйй... ну что ты так смотришь, смешно же было... ик!' FROM `quest_offer_reward` WHERE `ID`=12029 AND MD5(`RewardText`)='d09f7f670eb0a162761473253dc664ca' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12029 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12033, 'ruRU', '<Торвус кивает вам.>\n\nТак мы поняли друг друга? Я вернусь к своему лорду и скажу ему, что ты согласен.' FROM `quest_offer_reward` WHERE `ID`=12033 AND MD5(`RewardText`)='acda3c11e7a08ab78038d40a585483f7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12033 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12034, 'ruRU', 'Клянусь землей и ветром, мы покончим с угрозой Ануб\'ара!' FROM `quest_offer_reward` WHERE `ID`=12034 AND MD5(`RewardText`)='00cf1a57e379860bbbf5163bffea7fd8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12034 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12036, 'ruRU', 'Эта треклятая воронка, должно быть, напрямую связана с Азжол-Нерубом. Это хуже, чем я думал.\n\n<Юкток замолкает на минуту, раздумывая.>\n\nНайти и уничтожить… это будет нашим следующим ходом.' FROM `quest_offer_reward` WHERE `ID`=12036 AND MD5(`RewardText`)='75b28308e659ccf9125189a1a9495063' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12036 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12038, 'ruRU', 'Ай, молодца!\n\n<Мак заходится истерическим хохотом.>\n\nАйй... ну что ты так смотришь, смешно же было... ик!' FROM `quest_offer_reward` WHERE `ID`=12038 AND MD5(`RewardText`)='b1700153b971fbdf5c78864297c45d8c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12038 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12040, 'ruRU', 'Их еще тысячи и тысячи, и они выползают из каждой темной расщелины в Нордсколе. В одиночку у тебя нет ни единого шанса, но вместе... Может быть...' FROM `quest_offer_reward` WHERE `ID`=12040 AND MD5(`RewardText`)='4be0b27a61c21999c5edf6ef28bfa157' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12040 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12042, 'ruRU', 'Наверное, этот несчастный гоблин нашел Сердце древних во время раскопок.\n\nБедняга даже не понял, что за сокровище попало ему в руки.\n\nНе удивительно, учитывая весь этот бардак, который творится в наших краях.' FROM `quest_offer_reward` WHERE `ID`=12042 AND MD5(`RewardText`)='a8bacec9d9994d4fcc13d92758c91566' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12042 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12043, 'ruRU', 'А... Ну да, нежить. Вот твои деньги - и катись отсюда.' FROM `quest_offer_reward` WHERE `ID`=12043 AND MD5(`RewardText`)='1e9e2ad84f61b2d9e7154e23f6f52fe9' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12043 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12044, 'ruRU', 'Ха! Вот это ты $gнабрал:набрала;! Спину не $gнадорвал:надорвала;?' FROM `quest_offer_reward` WHERE `ID`=12044 AND MD5(`RewardText`)='0270f913c77d6beb69023a9e1fc3e1ac' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12044 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12045, 'ruRU', 'Великолепно! Ой, какие острые-то! Сложу их в снег, пока не доделаю бомбу.$b$bТак: что у нас там дальше:' FROM `quest_offer_reward` WHERE `ID`=12045 AND MD5(`RewardText`)='7ab61b697db9c3a0e610fc5c1bd217a7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12045 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12047, 'ruRU', 'Отлично! Это последнее, чего мне не хватало, чтобы испытать новые бомбы. Минутку, сейчас испробуем!' FROM `quest_offer_reward` WHERE `ID`=12047 AND MD5(`RewardText`)='4e3e94ec183fa79f5f6ad0bb4a5d86d0' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12047 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12049, 'ruRU', 'Ха-ха! Один из кусков мяса прям вон там приземлился! Отлично сработано!' FROM `quest_offer_reward` WHERE `ID`=12049 AND MD5(`RewardText`)='93fcf42c80487a4ec07b5dc60b9109a5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12049 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12050, 'ruRU', 'Если в лесу падает дерево, а ты этого даже не слышишь за визгом пил, то какая разница?' FROM `quest_offer_reward` WHERE `ID`=12050 AND MD5(`RewardText`)='296c07ede763bc9ea65a167de0a1e9a2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12050 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12052, 'ruRU', 'Теперь эти тварюги сначала дважды подумают. Вот... держи свою награду и проваливай отсюда.' FROM `quest_offer_reward` WHERE `ID`=12052 AND MD5(`RewardText`)='c9acd9d3c3e1ea263f38bc56b6236d14' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12052 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12053, 'ruRU', 'Мы разгромили их на земле! А скоро повергнем их и с воздуха!' FROM `quest_offer_reward` WHERE `ID`=12053 AND MD5(`RewardText`)='061e8ecd3f5a923d101c097014cd6eb2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12053 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12056, 'ruRU', '<Горт поднимает голову и долго всматривается в мертвые глаза.>\n\nЯ говорил тебе, что мы тебя достанем…\n\nВот твоя награда, |3-6($C). Теперь у нас одной головной болью меньше.' FROM `quest_offer_reward` WHERE `ID`=12056 AND MD5(`RewardText`)='92b6c15e9c6131cc152249fc4ee79291' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12056 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12058, 'ruRU', '<Ведунья Палуна слушает ваш перевод табличек.>\n\nТак Бранн полагает, что он обнаружил новый город титанов? Колыбель камня и железа...\'\n\n\'Ульдуар в центре бури.\'\n\nНадо попросить вождя отправить гонцов в Грозовую Гряду. Это наш последний шанс найти след сбежавшего дворфа.' FROM `quest_offer_reward` WHERE `ID`=12058 AND MD5(`RewardText`)='69c0beda88ddd0ff83bd2ae51b0cf1d4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12058 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12061, 'ruRU', 'То, что ты описываешь... это же проекция "Чарономикона"!\n\n<Появившееся было тревожное выражение на лице верховного мага тотчас скрывается под бесстрастно-непроницаемой маской.>\n\n"Чарономикон" – это карта всех пересечений магических силовых линий в мире. Синие драконы используют ее для поиска и разрушения так называемых якорей этих силовых линий, чтобы магическая энергия ушла обратно в Нексус.\n\nВопрос в том, почему путь разрушения ведет на восток, когда, по идее, он должен идти в прямо противоположном направлении – на запад?' FROM `quest_offer_reward` WHERE `ID`=12061 AND MD5(`RewardText`)='991af9809cb4e10a72a292ace3a1ba9b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12061 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12063, 'ruRU', 'Мой отец по-прежнему жив! Мы должны спасти его! Я не смогу сделать это в одиночку, |3-6($R). Ты должен мне помочь!' FROM `quest_offer_reward` WHERE `ID`=12063 AND MD5(`RewardText`)='6cfd8a186f472acb7893ffc1f69edf45' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12063 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12064, 'ruRU', 'Да, это сработает.\n\n<Банток умело манипулирует фрагментами.>\n\nКлюч готов, |3-6($C). С его помощью мы освободим моего отца из ануб\'арского узилища.' FROM `quest_offer_reward` WHERE `ID`=12064 AND MD5(`RewardText`)='6056603c62c7b7ccc33d3d4013fda6ab' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12064 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12068, 'ruRU', 'Получилось, $N!\n\nТеперь у нас есть все компоненты для проведения очищающего ритуала.' FROM `quest_offer_reward` WHERE `ID`=12068 AND MD5(`RewardText`)='0d8f04d5f997867683dffd9b80ba1bb4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12068 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12071, 'ruRU', '<Вальнок отдает вам честь.>\n\nТак это ты, стало быть, герой нашего времени, да?' FROM `quest_offer_reward` WHERE `ID`=12071 AND MD5(`RewardText`)='0231189a0d61de589d115ba093f18bdd' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12071 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12072, 'ruRU', '<Валнок отдает вам честь.>\n\nТеперь мы сокрушили их и с воздуха! Может быть, вскоре тебя призовут в Ангратар, герой!' FROM `quest_offer_reward` WHERE `ID`=12072 AND MD5(`RewardText`)='e7cd8502d49b16bb91b29d25050e6896' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12072 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12073, 'ruRU', '<Разведчик Вор\'такх улыбается.>\n\nЗначит, Тор Модан вот-вот падет?\n\nПревосходно. Вскоре мы начнем наступление на Дун Аргол.' FROM `quest_offer_reward` WHERE `ID`=12073 AND MD5(`RewardText`)='37d6892a3afe82b4c250e128eb6f4e71' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12073 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12074, 'ruRU', '<Вы называете себя.>\n\nТак значит, у нас с вами есть общий враг – сыновья железа?\n\nМои войска осадили город железных дворфов, но своими силами нам не взломать их оборону. Не желаешь ли ты нам помочь?' FROM `quest_offer_reward` WHERE `ID`=12074 AND MD5(`RewardText`)='102f15dfe44c22ddf566c1eceb93eb4b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12074 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12075, 'ruRU', 'Отличный образец. Спасибо, |3-6($C).' FROM `quest_offer_reward` WHERE `ID`=12075 AND MD5(`RewardText`)='e6bbefcbe44a918fa75a71581a6ff68b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12075 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12076, 'ruRU', 'Свеженькая! Минутку, сейчас смешаю ее с остальными компонентами…' FROM `quest_offer_reward` WHERE `ID`=12076 AND MD5(`RewardText`)='dbbb714cd3d6ffccb2c8796e9df18741' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12076 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12077, 'ruRU', 'Скажу прямо, малявка: я этой микстуре не доверяю и пользоваться ею не стану. Возьми ее себе… если ты больше моего доверяешь этому зеленому коротышке. Может, она тебе пригодится.' FROM `quest_offer_reward` WHERE `ID`=12077 AND MD5(`RewardText`)='0f92d2180caa6208a6b7a780c9f6fb85' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12077 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12078, 'ruRU', 'Эти вполне подойдут. Может быть, когда я выращу этих червячков до нормальных размеров, то отнесу их обратно и лично представлю их великанам.\n\nПо мне, так они просто бесполезные кучи камней.' FROM `quest_offer_reward` WHERE `ID`=12078 AND MD5(`RewardText`)='588392e03be3519252653e28787505c5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12078 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12079, 'ruRU', 'Приятное зрелище хорошей бойни.' FROM `quest_offer_reward` WHERE `ID`=12079 AND MD5(`RewardText`)='0f6cec0073c6f384f24a84ff2e205a9e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12079 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12082, 'ruRU', 'Говорят, ты выбрался из переделки вместе с нашим старым-добрым дружком?\n\nПожалуй, это само по себе может считаться наградой, но тебе повезло – я сегодня щедрый.' FROM `quest_offer_reward` WHERE `ID`=12082 AND MD5(`RewardText`)='7aa5ea30b1f5d77f4330c61121678229' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12082 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12084, 'ruRU', 'Они увеличивают с их помощью свою собственную силу? Не может быть! Охотники на магов не настолько могущественны.\n\nЭто, должно быть, означает, что они перенаправляют энергию силовых линий куда-то еще!\n\nЕсли мы хотим найти и остановить их, нам потребуются дополнительные сведения!' FROM `quest_offer_reward` WHERE `ID`=12084 AND MD5(`RewardText`)='143a11bab3671aaf0bc205c2d51ecaec' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12084 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12085, 'ruRU', 'Буагагага… ух ты, как трогательно!\n\n<В глубоком, горловом смехе властителя явно чувствуется снисходительность.>\n\nНу, чтото я говорил? Предатели! Правда, Дейно я знал когда-то. По крайней мере она – тролль с чувством чести!\n\nЯ позабочусь о том, чтобы она узнала, что случилось с ее братцем. Я даже забуду сказать ей, что это ты его убил.\n\n<Агмар пристально и оценивающе смотрит на вас.>\n\nНо теперь, |3-6($C), ты у меня в руках!' FROM `quest_offer_reward` WHERE `ID`=12085 AND MD5(`RewardText`)='d82ce93c7fd282230553305a28fc2f7a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12085 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12089, 'ruRU', 'Это был не первый из колдунишек, которые нас предали. И, боюсь, не последний. Жаль, жаль… Это был один из лучших наших магов. Умел творить такие заклинания, что аж слюнки текли и сердце прыгало от радости…\n\nТьфу ты!' FROM `quest_offer_reward` WHERE `ID`=12089 AND MD5(`RewardText`)='6ca3402e30218f634dbfa80beee299bd' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12089 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12090, 'ruRU', 'Тебе удалось достать этого проклятого кобыльего сына, а? Ну, что ж, одной неприятностью для наших солдат в этой мерзлой пустыне меньше.' FROM `quest_offer_reward` WHERE `ID`=12090 AND MD5(`RewardText`)='270ec3e5616653d5ed10b8270e0381fa' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12090 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12093, 'ruRU', 'Хорошо. Теперь нам надо действовать быстро, пока сыны железа не осознали, что их руны не действуют.' FROM `quest_offer_reward` WHERE `ID`=12093 AND MD5(`RewardText`)='b8b63d692afcad74feceb4b021df181c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12093 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12094, 'ruRU', 'Да, я чувствую силу, исходящую от этого камня. Надеюсь, ее будет достаточно для того, чтобы разрушить магию рун.' FROM `quest_offer_reward` WHERE `ID`=12094 AND MD5(`RewardText`)='31632d9fe8bb5268bf91c1999aa74e5d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12094 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12095, 'ruRU', 'И с чего это тебе взбрело в голову, что тебе удастся то, что не по зубам Рокхану, а?' FROM `quest_offer_reward` WHERE `ID`=12095 AND MD5(`RewardText`)='b864a17696b2d9d34f10fa3e51a75cf5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12095 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12096, 'ruRU', 'Благодарю тебя, |3-6($C).\n\nКак только я закончу слежку за этими отвратительными аптекарями и пойму, что они замышляют, я направлюсь в леса, чтобы попробовать убедить древняков присоединиться к нам.\n\nИли, если ничего не выйдет, попробую уговорить их хотя бы не нападать на тех, кто их спас!' FROM `quest_offer_reward` WHERE `ID`=12096 AND MD5(`RewardText`)='59a2a3f6fc0883af7d8f350914095028' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12096 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12100, 'ruRU', 'Мне больно, что животных приходится убивать, но это дело, которое должно быть сделано. А теперь мы приступим к следующему этапу – вакцинации.' FROM `quest_offer_reward` WHERE `ID`=12100 AND MD5(`RewardText`)='8644652bd7d5753c00dc43e066381fd4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12100 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12102, 'ruRU', 'Ну, было не так уж трудно, правда же?\n\nА теперь погоди минутку, дай мне приготовить вакцину.' FROM `quest_offer_reward` WHERE `ID`=12102 AND MD5(`RewardText`)='e174d9412bdea39a5bc552a316db0f00' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12102 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12104, 'ruRU', '<Соар поднимает флакон и изучает на свету его содержимое.>\n\nОсталось выяснить только одно.' FROM `quest_offer_reward` WHERE `ID`=12104 AND MD5(`RewardText`)='9afac0888888b91d3044b50f3bdd7de6' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12104 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12106, 'ruRU', 'Здесь вы обнаружили тело командира охотников на магов.\n\nСудя по его виду и состоянию его павших подчиненных, вы рискнули бы утверждать, что они не захлебнулись. Скорее, когда они призвали силу средоточия, они не ожидали нападения элементалей, поднявшихся из провалов в дне озера.\n\nВыходит, охотники на магов сами обрекли себя на смерть.' FROM `quest_offer_reward` WHERE `ID`=12106 AND MD5(`RewardText`)='3ca5b2c9df09fa6f8af2c5564d374f86' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12106 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12112, 'ruRU', 'Я могу найти тебе кое-какое применение. Проходи-ка вперед и постой минутку.' FROM `quest_offer_reward` WHERE `ID`=12112 AND MD5(`RewardText`)='0b9788ab8d9c24927442250758c2a4af' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12112 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12113, 'ruRU', 'Ух, здорово!\n\nМясо с дымком и кружка с пивком – что может быть лучше?' FROM `quest_offer_reward` WHERE `ID`=12113 AND MD5(`RewardText`)='9150e5d014da2527ab47d75b07fb90ba' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12113 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12114, 'ruRU', 'Ох, спасибочки, |3-6($C).\n\nБудет время – схожу сам посмотрю на это зрелище.' FROM `quest_offer_reward` WHERE `ID`=12114 AND MD5(`RewardText`)='bf8b3b05ce7a218858296cb0cdaff984' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12114 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12116, 'ruRU', 'Внутренности? Странный выбор, |3-6($R).\n\nКраз узнает, что они могут нам поведать. Спасибо тебе за то, что ты отважился войти в этот ужасный склеп.' FROM `quest_offer_reward` WHERE `ID`=12116 AND MD5(`RewardText`)='6923120d3fdfb8b96bd57a363fbb80b8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12116 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12120, 'ruRU', 'Это было лишь начало, $N. Теперь тебя ждет настоящее испытание.' FROM `quest_offer_reward` WHERE `ID`=12120 AND MD5(`RewardText`)='f9869ff07864fd2b730501895abace15' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12120 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12124, 'ruRU', 'Чтобы принести нам эти сведения, потребовалось немалое мужество! А я-то не могла понять, отчего синие драконы так дерзко решились напасть на сам храм. Теперь мы знаем, что они использовали огромные запасы той самой магии, которая, как они считают, угрожает Азероту.\n\n<Королева печально качает головой.>\n\nЛицемерие, конечно, но тут уж ничего не поделаешь. Если Малигос не одумается, у нас не останется выбора: придется напасть на них в ответ!' FROM `quest_offer_reward` WHERE `ID`=12124 AND MD5(`RewardText`)='ed00266ff5ca8794d541f85766eacc2e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12124 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12125, 'ruRU', 'Простое задание для простака. Ты действовал согласно моим ожиданиям.' FROM `quest_offer_reward` WHERE `ID`=12125 AND MD5(`RewardText`)='4addbe525ea6ed1b9614c32626b00566' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12125 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12126, 'ruRU', '<Глаза Кольтиры расширяются от удивления.>\n\nВпечатляюще! Тебе удалось одолеть рыцаря смерти Артаса… не в одиночку, очевидно… но все же…' FROM `quest_offer_reward` WHERE `ID`=12126 AND MD5(`RewardText`)='a9524b6a16245a775b272d7faacaf93d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12126 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12137, 'ruRU', 'Ты молодецl.\n\nА теперь присядь и выслушай, что я тебе скажу. Нам надо многое обсудить.' FROM `quest_offer_reward` WHERE `ID`=12137 AND MD5(`RewardText`)='ef41c6ac97479b5a42e4d7730a011fbf' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12137 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12140, 'ruRU', 'Имея поддержку столь могущественного шамана, мы, несомненно, одержим победу у Врат Гнева!' FROM `quest_offer_reward` WHERE `ID`=12140 AND MD5(`RewardText`)='51d7ce8259ccf90d0a0626176bf478c8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12140 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12144, 'ruRU', 'Избавились от них – и ладно!' FROM `quest_offer_reward` WHERE `ID`=12144 AND MD5(`RewardText`)='6a08157abd18b1ee6f6724204a8e3d62' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12144 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12145, 'ruRU', 'Ледолап, да? Знакомое имечко! Молодчина! Есть надежда, что мы, тролли Черного Копья, сможем теперь вплотную заняться драконами!' FROM `quest_offer_reward` WHERE `ID`=12145 AND MD5(`RewardText`)='f41d19b413378c6b4da3d487966574d4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12145 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12147, 'ruRU', 'Действительно, это очень странно, что такой предмет оказался у магнатавра... странно и очень тревожно. Я очень рада, что ты показал мне это.' FROM `quest_offer_reward` WHERE `ID`=12147 AND MD5(`RewardText`)='b2c5870bfced1c02b86b60101225990b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12147 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12148, 'ruRU', 'Так, значит, это правда. Они не могли выбрать более удачного времени для такого нападения… Разрываясь между армией Плети и синими драконами, вряд ли кто-то что-то мог уже заметить…' FROM `quest_offer_reward` WHERE `ID`=12148 AND MD5(`RewardText`)='d53aefee2678f8ccfc48a8174b19286d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12148 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12149, 'ruRU', 'Отличная работа! Никто не смог сказать мне имя вожака магнатавров, зато мне удалось выяснить имя того, кто знает ответ на наш вопрос.' FROM `quest_offer_reward` WHERE `ID`=12149 AND MD5(`RewardText`)='50c87516a8772a6c0b1ddd715186d35a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12149 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12152, 'ruRU', 'Дело сделано.\n\nТвоя самоотверженность даровала покой многим замученным душам.\n\nПусть это деяние освятит твою душу и снимет тяжесть с твоих плеч, ибо я предвижу, что впереди тебя ждут великие испытания.\n\nПрощай, $N.' FROM `quest_offer_reward` WHERE `ID`=12152 AND MD5(`RewardText`)='2fd0d4db552c6c7553ed7af28545cc4f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12152 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12165, 'ruRU', 'Значит, Тормак одобрил мой план? Да... иначе он не стал бы тебя посылать.\n\nОх, беда, беда-огорчение... Как же мне теперь разобраться, что к чему в этих чертежах, когда Тормак дышит мне в спину?' FROM `quest_offer_reward` WHERE `ID`=12165 AND MD5(`RewardText`)='de0c10b7dac12bb84d633f6fbd2d62c4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12165 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12170, 'ruRU', 'Отличная работа, $N. Мы еще не установили полный контроль над лесопилкой, но эта победа вплотную приблизила нас к цели.' FROM `quest_offer_reward` WHERE `ID`=12170 AND MD5(`RewardText`)='4d9392c228639c12b2040f93a4216ff2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12170 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12177, 'ruRU', 'Скрести пальцы, подруга.' FROM `quest_offer_reward` WHERE `ID`=12177 AND MD5(`RewardText`)='9c4d28facc4e36010a7115d282fc3f8c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12177 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12181, 'ruRU', 'Э... все понятно, можешь не показывать мне образец. Я тебе верю.' FROM `quest_offer_reward` WHERE `ID`=12181 AND MD5(`RewardText`)='2a615c505d6c7214a334c5de160023f3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12181 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12182, 'ruRU', 'О, превосходно! Ты только посмотри – прямо за горой, на северо-востоке, ползет целая армия Плети! С нее-то мы и начнем испытания.' FROM `quest_offer_reward` WHERE `ID`=12182 AND MD5(`RewardText`)='710e28e56deb54210084c9b6abf7f4e9' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12182 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12190, 'ruRU', 'Ух ты! Это от старины Пригмона?\n\nДа тут продуктов на целый пир! Правда, кое-чего не хватает...' FROM `quest_offer_reward` WHERE `ID`=12190 AND MD5(`RewardText`)='60603bc3cca44c490aaba7315cecfd55' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12190 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12193, 'ruRU', 'Аххх, всего лишь за бесплатным пивом... Может, ты просто стесняешься? Ладно-ладно, вот тебе бесплатная кружечка.$b$bЧао, увидимся. Ты ведь захочешь отоварить и другие праздничные жетоны... Помни, я вся твоя...$b$bИли его... $b$bМожет, его...' FROM `quest_offer_reward` WHERE `ID`=12193 AND MD5(`RewardText`)='1e47297f34e60b6cbf88b838216957eb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12193 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12194, 'ruRU', 'Аххх, всего лишь за бесплатным пивом... Может, ты просто стесняешься? Ладно-ладно, вот тебе бесплатная кружечка.$b$bЧао, увидимся. Ты ведь захочешь отоварить и другие праздничные жетоны... Помни, я вся твоя...$b$bИли его... $b$bМожет, его...' FROM `quest_offer_reward` WHERE `ID`=12194 AND MD5(`RewardText`)='3cc0492a78de90ae69e721fd11375b95' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12194 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12195, 'ruRU', 'Да, эти рога вполне сгодятся для настойки. Посмотрим, поможет ли она.' FROM `quest_offer_reward` WHERE `ID`=12195 AND MD5(`RewardText`)='095a31597d764f2223467613467c6804' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12195 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12196, 'ruRU', '<Рокар облегченно утирает пот со лба.>\n\nСлава Свету! Он грозился оставить меня без еды, пока ты не вернешься. Ладно, давай посмотрим, что тебе удалось раздобыть.' FROM `quest_offer_reward` WHERE `ID`=12196 AND MD5(`RewardText`)='4e5a4bd4efae78a3b6e427435e3d5eb6' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12196 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12197, 'ruRU', '<Рокар выхватывает у вас энергобатареи.>\n\nОтлично! Заряд очень низкий, но, во всяком случае, мы сможем запустить голема. Правда, для битвы он еще не готов.' FROM `quest_offer_reward` WHERE `ID`=12197 AND MD5(`RewardText`)='10e16bda489358fedbf48c3940be7be5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12197 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12198, 'ruRU', 'Ну вот – эта штучка готова к бою. Может, Тормак хоть теперь угомонится?\n\nНадеюсь, эта корова-переросток отпустит меня после того, как ты проложишь себе путь в Дун Аргол...' FROM `quest_offer_reward` WHERE `ID`=12198 AND MD5(`RewardText`)='7292755ba6628ac152e9d76f432d3f0c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12198 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12199, 'ruRU', 'Значит, геолог сдержал слово? Это хорошо. Я уж было начал сомневаться в целесообразности его работы.\n\nЖаль, но больше он нам не пригодится.' FROM `quest_offer_reward` WHERE `ID`=12199 AND MD5(`RewardText`)='8f01ac538724a2731eb14648f3d6124f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12199 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12200, 'ruRU', 'Я уверен, что настой порчи теперь готов к полевым испытаниям. По счастливой случайности силы жуткой цитадели Наксрамас осаждают крепость Стражей Зимы. Прямо из-под земли, на которой выстроена крепость, лезут ожившие мертвецы, жаждущие выполнить волю Кел\'Тузада.\n\nСилы Альянса, естественно, уступают и численно, и в отношении вооружения. Люди, упокоенные в усыпальнице Стражей Зимы, восстают из мертвых, алкая плоти!\n\nМожет, дать им испробовать вкус чумы, а?' FROM `quest_offer_reward` WHERE `ID`=12200 AND MD5(`RewardText`)='1cf0cd2aee34898644e096938d6bd17d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12200 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12201, 'ruRU', 'Отлично, эта униформа нам очень пригодится. Но нам понадобится еще кое-какой грим. Иначе даже эти тупоголовые железные дворфы узнают в тебе переодетого шпиона.' FROM `quest_offer_reward` WHERE `ID`=12201 AND MD5(`RewardText`)='12d1bbfca2e58b905473da82cec50549' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12201 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12202, 'ruRU', 'То, что надо! Во имя Гарроша, ну и мерзкие рожи!' FROM `quest_offer_reward` WHERE `ID`=12202 AND MD5(`RewardText`)='46bac78434219c731bcd234352a63468' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12202 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12203, 'ruRU', 'Значит, он собирается развязать гражданскую войну между детьми титанов? Странно...зачем ему город древних богов, Ульдуар? Впрочем, Курун и его великаны постараются не допустить его вмешательства.\n\nЧто ж, я сомневаюсь, что мы в состоянии удержать великанов от распрей, но мы можем воспользоваться этой ситуацией в своих целях. Надо немедленно известить наших командиров!' FROM `quest_offer_reward` WHERE `ID`=12203 AND MD5(`RewardText`)='14db6dfa507c0da5396231a0270d3a02' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12203 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12204, 'ruRU', 'Значит, он руководит военной кампанией железных дворфов? Мы должны узнать, что они замышляют!' FROM `quest_offer_reward` WHERE `ID`=12204 AND MD5(`RewardText`)='12e1cfe8e07cea5132120b4821e4baf7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12204 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12205, 'ruRU', 'Отлично, отлично, |3-6($R)! Полагаю, убитые успели помучиться перед смертью?\n\nНу-ка, сейчас погляжу, что ценного завалялось у нас в гробах… кхм, прошу прощения – у нас в сундуках.' FROM `quest_offer_reward` WHERE `ID`=12205 AND MD5(`RewardText`)='dd8e3ff6bf13718a7e4ad00046ff14b9' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12205 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12206, 'ruRU', 'ЧТО?! Это невозможно. Мы же сделали настой совершенным. У этого состава – стопроцентная смертность!\n\n<Аптекарь заламывает руки, ее лицо нежити охвачено тревогой. Явно расстроенная, она сердито продолжает.>\n\nВсе это очень странно. Передай-ка мне флакон, |3-6($C). Я не желаю, чтобы обо мне говорили как об аптекаре, который провалил все дело!' FROM `quest_offer_reward` WHERE `ID`=12206 AND MD5(`RewardText`)='2b510b9ba150568f0ddde1c2a10408fa' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12206 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12208, 'ruRU', 'Тоже хочешь поохотиться за ледяными троллями?' FROM `quest_offer_reward` WHERE `ID`=12208 AND MD5(`RewardText`)='83b28530475d370b5e869ff619ff25e9' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12208 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12209, 'ruRU', 'Что-то от тебя не слишком свежо пахнет, молодое мясо.\n\nЛадно, весь этот хлам сгодится. Как тебя звать-то, |3-6($C)?' FROM `quest_offer_reward` WHERE `ID`=12209 AND MD5(`RewardText`)='3b00466a3882e53e1a53fa50d7ce0fa2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12209 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12211, 'ruRU', 'Ох! На секунду мне показалось, что придется тестировать этих крыс на ком-то еще, чтобы удостовериться, что они не дефективные.\n\nНаконец-то, хоть какой-то прогресс!' FROM `quest_offer_reward` WHERE `ID`=12211 AND MD5(`RewardText`)='5c0377cbeb63015e48dda626aa7a0490' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12211 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12214, 'ruRU', 'Ну что может быть лучше хорошо выполненной работы?\n\nДобыв этих коней, ты оказал Ядозлоби большую услугу, |3-6($C).' FROM `quest_offer_reward` WHERE `ID`=12214 AND MD5(`RewardText`)='a4268fcdcf4e6722636bbde186373d9c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12214 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12218, 'ruRU', 'Меня, конечно, бесит, что мы невольно помогаем Альянсу, но тем не менее полевые испытания прошли успешно! Тебя ждет Молот Агмара!' FROM `quest_offer_reward` WHERE `ID`=12218 AND MD5(`RewardText`)='15fc809ff46086a439383e7849837bdb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12218 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12230, 'ruRU', '<Страж смерти в предвкушении потирает руки.>\n\nОтлично. Что у них с возу упало, ко мне… ммм, к нам попало!\n\nУ тебя как, проблем не возникло по дороге? Кое-что тут выглядит очень нестабильно. Я, может, и нежить, но своим существованием очень даже дорожу!' FROM `quest_offer_reward` WHERE `ID`=12230 AND MD5(`RewardText`)='5b9e197da9c09e6d3ad22d256ffcf573' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12230 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12232, 'ruRU', 'О, счастливый день!\n\nНе затратив ни времени, ни средств фармацевтов на выполнение задачи, я уж точно привлеку внимание верховного палача!\n\nНестандартное мышление – в этом весь я. Да-да, ты тоже немного помог.\n\nПослушай, если я тебе заплачу, обещаешь не упоминать о своей роли во всем этом деле?' FROM `quest_offer_reward` WHERE `ID`=12232 AND MD5(`RewardText`)='f2af439c4fbc66fc6a8d4338f7b28737' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12232 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12234, 'ruRU', 'Ну, |3-6($R), чего ждешь? Давай их сюда!' FROM `quest_offer_reward` WHERE `ID`=12234 AND MD5(`RewardText`)='50baab38bf7a825d777473caceb6f41b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12234 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12238, 'ruRU', 'Мы совершили великое дело, $Gдружище:подруга;! И это только начало...\n\nКогда придет время, отыщи меня в Зул\'Драке.\n\nМы с тобой выиграем эту битву!' FROM `quest_offer_reward` WHERE `ID`=12238 AND MD5(`RewardText`)='aa37809c6026951d1b31597cf906219e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12238 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12239, 'ruRU', 'У тебя сообщение от госпожи шпионов?\n\n<Агент кладет лопату на землю, попутно оглядываясь, чтобы удостовериться, что никто не смотрит на вас.>\n\nДай-ка мне взглянуть на эти планы.' FROM `quest_offer_reward` WHERE `ID`=12239 AND MD5(`RewardText`)='90a30290d48678338b2743b7bf5addda' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12239 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12243, 'ruRU', 'Уахахахаха!\n\nБез их лоций им больше некуда бежать теперь.\n\nПо мне так Алому Натиску конец – и надо же, как раз тогда, когда они начинали! Какая досада.\n\nХаха.' FROM `quest_offer_reward` WHERE `ID`=12243 AND MD5(`RewardText`)='3860d19746e09ce207eb4b60b4623f4f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12243 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12252, 'ruRU', 'И все это они знали? И кто, лич побери, этот верховный адмирал Вествинд, о котором он говорил?!\n\n<Верховный палач ворчит себе под нос что-то о нелюбви к сюрпризам.>\n\nЛучше, чтобы мы знали, чем нам пришлось бы догадываться. Надеюсь, ты оставил на нем свою... эээ... то есть, МОЮ метку.' FROM `quest_offer_reward` WHERE `ID`=12252 AND MD5(`RewardText`)='c904f34e83f9d0519a18dcbc33140cbd' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12252 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12254, 'ruRU', 'Новое благословение, написанное на последней странице?\n\n<Агент смотрит вам через плечо, пока вы пролистываете книгу до последней страницы.>\n\nДа что б мне провалиться на этом месте! Это же почерк верховного настоятеля! Ручаюсь твоей собственной жизнью.' FROM `quest_offer_reward` WHERE `ID`=12254 AND MD5(`RewardText`)='034a92b0113ffca1bca7dcd7c99c75bb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12254 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12256, 'ruRU', 'Протодраконы подчиняются только владельцам талисманов. Теперь судьба тана решена!' FROM `quest_offer_reward` WHERE `ID`=12256 AND MD5(`RewardText`)='a24c5452a0f72d9277bd54e24a34ac95' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12256 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12257, 'ruRU', 'Молодец, ты выполнила мое поручение в точности. Теперь Потрошители Драконов будут вынуждены обороняться, а у нас будет время, чтобы расправиться с их главой клана.' FROM `quest_offer_reward` WHERE `ID`=12257 AND MD5(`RewardText`)='a0da451c4369ee6dfd32d57e216cc4eb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12257 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12259, 'ruRU', 'Теперь жалкие остатки племени Потрошителей Драконов не осмелятся выступить против нас. Никакой пощады врагам – вот девиз Орды!' FROM `quest_offer_reward` WHERE `ID`=12259 AND MD5(`RewardText`)='5e834a4ef6f66ad48c46106cc83a4ae7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12259 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12260, 'ruRU', 'Неплохо, |3-6($C). Теперь, когда образ жреца пойман зеркалом, есть еще одно дельце.' FROM `quest_offer_reward` WHERE `ID`=12260 AND MD5(`RewardText`)='8ec2daac73f52a663efbbbb0c25dfcdf' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12260 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12271, 'ruRU', 'Так ты говоришь, вот это нашлось у Лекрафта? Все ясно.\n\nЯ знаю этот жезл еще с тех пор, как служил мучителем при дворе короля Теренаса в Лордероне. Он называется жезлом принуждения.\n\n<Верховный палач заламывает руки, тревожимый зловещим предчувствием того, что должно произойти.>\n\nУ меня есть идея, какое ему можно найти применение!' FROM `quest_offer_reward` WHERE `ID`=12271 AND MD5(`RewardText`)='61a85784ae1136dcd764a5f9e83bff12' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12271 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12274, 'ruRU', 'Что за чертовщина?\n\nПрыгнул? Сам? А ты его… не того? Не подтолкнул?\n\n<Агент всматривается в вас с подозрением.>\n\nЛадно… Очевидно, тут все куда более запутанно, чем мы думали сначала.' FROM `quest_offer_reward` WHERE `ID`=12274 AND MD5(`RewardText`)='0674337a5e1c1c0781ea9b71c90ec892' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12274 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12279, 'ruRU', 'Эй! Да ты не Хромоногий Джо!' FROM `quest_offer_reward` WHERE `ID`=12279 AND MD5(`RewardText`)='a4a32c9de8676b6d213e67d04aa135d6' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12279 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12283, 'ruRU', 'Провались оно все! Нет бы принести мне хорошие новости!' FROM `quest_offer_reward` WHERE `ID`=12283 AND MD5(`RewardText`)='da21b092466be4c685f44ff9af12caca' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12283 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12286, 'ruRU', 'Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!' FROM `quest_offer_reward` WHERE `ID`=12286 AND MD5(`RewardText`)='733bff38bc8259d7b195aeaaa8c58cba' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12286 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12303, 'ruRU', '<Интендант раскрывает рот от удивления, но затем его глаза сужаются, и он пару секунд пристально смотрит на вас.>\n\nЯ надеюсь, ты не прихватил ничего с собой? Ты ж не будешь настолько эгоистичен, когда на кону – судьба Ядозлоби?\n\nКроме того, я намереваюсь дать тебе в награду определенный процент от добытого тобой. Не очень много, конечно, но в такие времена всем нам приходится чем-то жертвовать.' FROM `quest_offer_reward` WHERE `ID`=12303 AND MD5(`RewardText`)='bdd2ff03c027a31d48aa63bfd4316ad1' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12303 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12318, 'ruRU', 'Ты из лагеря Хмельного фестиваля? Ну наконец-то! Хмельной фестиваль еще можно спасти.\n\n$N мы должны остановить Корена Худовара! Нельзя допустить, чтобы наш священный праздник был сорван. Мы должны совершить возлияния пивным богам!' FROM `quest_offer_reward` WHERE `ID`=12318 AND MD5(`RewardText`)='495c2124173912f26bb3caeb057175a7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12318 AND x.`locale`='ruRU');
