INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12409, 'ruRU', 'Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!' FROM `quest_offer_reward` WHERE `ID`=12409 AND MD5(`RewardText`)='733bff38bc8259d7b195aeaaa8c58cba' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12409 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12410, 'ruRU', 'Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!' FROM `quest_offer_reward` WHERE `ID`=12410 AND MD5(`RewardText`)='733bff38bc8259d7b195aeaaa8c58cba' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12410 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12420, 'ruRU', 'Отлично, все бумаги в порядке. Добро пожаловать в клуб,$N\n\nТеперь ты будешь получать от нас посылки каждый месяц. Если тебе понравятся наши образцы пива – приходи к нам, и мы продадим тебе еще.' FROM `quest_offer_reward` WHERE `ID`=12420 AND MD5(`RewardText`)='a67863b5aa9a79e785ccfa89b4e177e8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12420 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12448, 'ruRU', 'Неприятная работа, я знаю – и благодарю тебя за ее выполнение.\n\nПлети нельзя позволить продвинуться за пределы святилища, иначе ее воины заполонят все эти земли.' FROM `quest_offer_reward` WHERE `ID`=12448 AND MD5(`RewardText`)='05bb34fb0ce799bbd59be9d944c89ed7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12448 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12449, 'ruRU', 'Преданные земле, мои собратья смогут вновь дарить жизнь. Ты спас их от судьбы куда худшей, чем смерть.\n\nЯ не знаю слов на твоем языке, которые могли бы выразить, как много это значит для меня и мне подобных. Я благодарю тебя, |3-6($R).' FROM `quest_offer_reward` WHERE `ID`=12449 AND MD5(`RewardText`)='f5b00521826703e68681fba0c78a327c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12449 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12451, 'ruRU', '<Вы называете себя и объясняете, что вас послал сержант Назгрим.>\n\nА, тебя прислали нам на помощь. Это хорошо. \n\nЛюди Тормака найдут дело для твоего клинка.' FROM `quest_offer_reward` WHERE `ID`=12451 AND MD5(`RewardText`)='362780fa9af3d19a9c59990539d3d4ea' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12451 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12454, 'ruRU', 'Не сожалей о той роли, которую тебе пришлось сыграть в жизненном цикле. Рождение, смерь и возрождение – все это части естественного хода вещей.' FROM `quest_offer_reward` WHERE `ID`=12454 AND MD5(`RewardText`)='17f27c5c66779339195c60d7d69b9ba3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12454 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12456, 'ruRU', 'Не оплакивай судьбу Алистоса. Он посвятил свою вечную жизнь защите Изумрудного святилища драконов, он возродится.\n\nНадеюсь, когда он вернется к нам, он не окажется во власти Изумрудного кошмара, который, кажется, завладел Спящей.' FROM `quest_offer_reward` WHERE `ID`=12456 AND MD5(`RewardText`)='df7b5918a38ef68944f4c695e4590d29' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12456 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12458, 'ruRU', 'О, я уже чувствую биение пульса природы внутри этих семян!\n\nНужно использовать их с умом.' FROM `quest_offer_reward` WHERE `ID`=12458 AND MD5(`RewardText`)='c4674906ebc1d3449a9f171ac7d6dc9c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12458 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12461, 'ruRU', 'Тебя прислал посол Голлук?\n\nЕсли тебе доведется еще раз говорить с ним, передай ему, что мы весьма признательны за эту помощь. Нам приходится вести борьбу на несколько – слишком много! – фронтов одновременно.' FROM `quest_offer_reward` WHERE `ID`=12461 AND MD5(`RewardText`)='a95ae2a388e2d906619286ea3d855461' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12461 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12469, 'ruRU', 'Ого! Что, значит, мы еще одного потеряли? Как же надоели эти гарпии!\n\nЛадно, неважно. Есть дело. Поможешь, а?' FROM `quest_offer_reward` WHERE `ID`=12469 AND MD5(`RewardText`)='4c00ff0c109873a9063b20ad38666c46' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12469 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12483, 'ruRU', 'Ох, мамочка, неужели я скоро отведаю похлебки из снежных грибов?' FROM `quest_offer_reward` WHERE `ID`=12483 AND MD5(`RewardText`)='5d2b3d5ac7a4df48d68bde5f42d4a02a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12483 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12484, 'ruRU', 'Какое удовольствие – смотреть, как горят эти мерзавцы... <ик>.\n\nЯ даже написал про это маленький сонет. Хочешь послушать? Жил-был когда-то...' FROM `quest_offer_reward` WHERE `ID`=12484 AND MD5(`RewardText`)='e92d6745d2c191af592be908aae43ab9' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12484 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12486, 'ruRU', 'Мистик уже знает? Ты говоришь, он почувствовал, что с предсказателем Печальным Путником случилось нечто ужасное?\n\nЭтого-то я и боялась!..' FROM `quest_offer_reward` WHERE `ID`=12486 AND MD5(`RewardText`)='1ea3940376f76eea7796d3849af87be6' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12486 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12487, 'ruRU', 'Ты кто?\n\nБыстро объясни, почему мне не стоит зарубить тебя на месте!' FROM `quest_offer_reward` WHERE `ID`=12487 AND MD5(`RewardText`)='8c575d7207ada2360bb51bc87d59f148' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12487 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12488, 'ruRU', 'Тебя прислали из Молота Агмара? Как раз вовремя!\n\nНет, помощь нужна не мне. Мне просто некого больше отрядить, поэтому пойдешь ты.' FROM `quest_offer_reward` WHERE `ID`=12488 AND MD5(`RewardText`)='142fb43463aabbe8668fc732ae7a40fa' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12488 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12496, 'ruRU', 'Ты пришел искать моего совета, смертный. Это я знаю, но знаешь ли ты, с чем столкнулся?\n\n<Алекстраза указывает на север.>\n\nК северу отсюда находятся умирающие пространства Галакронда – предка всех драконов. Именно от Галакронда Титаны произвели Аспекты. Вообрази же силу Галакронда! Даже по величине он больше всех Аспектов, вместе взятых! А теперь попробуй понять, что делает Плеть на великом Драконьем Погосте.\n\nЛедяные змеи, смертный, должны меньше всего тревожить тебя.' FROM `quest_offer_reward` WHERE `ID`=12496 AND MD5(`RewardText`)='3c5bd94a61a39d2fad6c7273cd433b4f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12496 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12501, 'ruRU', 'Ну что ж, $N, по крайней мере, ты вернулся целым и невредимым. А это чего-то да стоит...' FROM `quest_offer_reward` WHERE `ID`=12501 AND MD5(`RewardText`)='c3858c60cb67a0f2417c973c537cb856' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12501 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12502, 'ruRU', 'Спасибо, друг.\n\nЗнамя – это всего лишь символ, но на поле боя этот символ творит чудеса.\n\nТеперь отправляйся к капитану Руперту. Его пост – у стены, на северо-востоке отсюда.' FROM `quest_offer_reward` WHERE `ID`=12502 AND MD5(`RewardText`)='2282431330b7c96c234bdf0e1157bb17' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12502 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12509, 'ruRU', 'Ты замечательно справился, $C. И как раз очень вовремя. Мне пришло донесение, что противник готовит контратаку.\n\nТебе пора идти дальше. Следующий форт – на северо-востоке, рядом с Колизеем. Капитан Грондель будет ждать тебя там.' FROM `quest_offer_reward` WHERE `ID`=12509 AND MD5(`RewardText`)='05a6094a5b73fc7c60514cfb74c1fe72' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12509 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12518, 'ruRU', 'Друг мой, ты обладаешь великим талантом! Знай же, что карты таро пользуются большой популярностью на Ярмарке Новолуния, так что если тебе удастся создать еще одну колоду – не стесняйся, обращайся к нам. Среди нас много успешных торговцев, так что без награды ты не останешься.' FROM `quest_offer_reward` WHERE `ID`=12518 AND MD5(`RewardText`)='b073f722a43dbb37e1d93fc790b86c53' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12518 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12519, 'ruRU', 'Вот и славно!\n\nТы мне очень помог, сэкономил мне кучу времени. Большое спасибо. Я обязательно упомяну о твоей верной службе, когда буду писать донесение.\n\nА теперь отправляйся на запад, к Финкльштейну. Он уже наверняка тебя ждет.' FROM `quest_offer_reward` WHERE `ID`=12519 AND MD5(`RewardText`)='f10216f264a858f3a4a131178e738cb3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12519 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12542, 'ruRU', 'Буквально в нескольких шагах отсюда лежит империя Драккари.\n\n<Валус указывает на восток.>\n\nНа протяжении тысячелетий Драккари пребывала в изоляции, держась в границах своих городов-храмов и зиккуратов. Тем более удивительно было обнаружить эти развалины. Дальше, за зловещими лестницами, ведущими в Зул\'драк, находится разрушенная крепость Драк\'Тарон. Весь первый ярус Зул\'Драка, разоренный...\n\nНет, ну почему Плети непременно было нужно напасть именно теперь?' FROM `quest_offer_reward` WHERE `ID`=12542 AND MD5(`RewardText`)='0ee3a414be17ad38ce5976ffb0db62bb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12542 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12545, 'ruRU', 'Как видишь, военная машина Плети все давит, а армии Орды и Альянса остаются разделенными, становясь для Плети легкими жертвами. Именно поэтому мы должны хранить единство.\n\n<Валус на минуту погружается в размышления.>\n\nСеребряному Авангарду может быть полезен такой, как ты. Может, тебя заинтересовала бы перспектива присоединиться к нам? Сражаться и умереть на стороне Испепелителя?' FROM `quest_offer_reward` WHERE `ID`=12545 AND MD5(`RewardText`)='e9dda4004d6e345069dfac0cb39f84b2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12545 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12547, 'ruRU', '<Вы слышите гул и скрежет камня о камень: Этимидиан пробуждается к жизни.>\n\nГде нужна моя помощь?' FROM `quest_offer_reward` WHERE `ID`=12547 AND MD5(`RewardText`)='d0208a599d7c7d7bb8df2b3e45c59033' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12547 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12552, 'ruRU', 'Этого недостаточно!\n\n<Голос сержанта дрожит от скорби по павшим товарищам, оскверненным вражеской магией.>\n\nМы должны сделать больше, чтобы почтить память наших товарищей!' FROM `quest_offer_reward` WHERE `ID`=12552 AND MD5(`RewardText`)='edd664cd4bf4dc803f69a95099447fcb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12552 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12553, 'ruRU', 'Это именно то, что нужно!\n\nНо для того, чтобы собрать катапульту, мне нужны еще и некоторые детали.' FROM `quest_offer_reward` WHERE `ID`=12553 AND MD5(`RewardText`)='59f1a768cd0cfd34b6a1c3cfc8f78040' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12553 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12563, 'ruRU', 'Ну что ж, $N, по крайней мере, ты вернулся целым и невредимым. А это чего-то да стоит...' FROM `quest_offer_reward` WHERE `ID`=12563 AND MD5(`RewardText`)='c3858c60cb67a0f2417c973c537cb856' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12563 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12564, 'ruRU', 'Отличные экземпляры, $N.\n\nБлагодарю тебя от имени всех моих воинов.\n\nТеперь иди на восток, к капитану Руперту. Его пост находится у стены.' FROM `quest_offer_reward` WHERE `ID`=12564 AND MD5(`RewardText`)='cf98ba17e43478cfccc3be40173c4821' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12564 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12568, 'ruRU', 'Спасибо, $N.\n\nЭто не самая славная работа на поле боя, но ее надо делать. Я обязательно упомяну о твоей верной службе, когда буду писать донесение.\n\nКапитан Грондель наверняка уже ждет тебя на северо-востоке, сразу за амфитеатром.' FROM `quest_offer_reward` WHERE `ID`=12568 AND MD5(`RewardText`)='210a9829a67f10bf2c9c65ed5777dee5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12568 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12569, 'ruRU', '<Дебаар выслушивает рассказ о том, что маскировка не помогла.>\n\nЧто значит – наш план не сработал так, как ожидалось?\n\nВ конце концов, тебе удалось прикончить эту тварь – что делает тебе честь. Ты только посмотри, какая здоровенная челюсть! Хеминг может нами гордиться. Этот кроколиск был настоящим чудовищем!' FROM `quest_offer_reward` WHERE `ID`=12569 AND MD5(`RewardText`)='136535935b125dd12e018b172f25d65c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12569 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12585, 'ruRU', 'Спасибо, $N. Большое спасибо.\n\nТеперь иди к капитану Арнату. На запад, прямо за этим холмом.' FROM `quest_offer_reward` WHERE `ID`=12585 AND MD5(`RewardText`)='5aa808d08c86c337280e46a7c829da58' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12585 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12587, 'ruRU', 'Ну что ж, $N, по крайней мере, ты вернулся целым и невредимым. А это чего-то да стоит...' FROM `quest_offer_reward` WHERE `ID`=12587 AND MD5(`RewardText`)='b79e070cd52167b1839206957a9207ed' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12587 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12588, 'ruRU', 'Спасибо, $N, ты нам очень помог. Я обязательно упомяну о твоей верной службе, когда буду писать донесение.\n\nТеперь иди к капитану Руперту. Его пост – у стены, на востоке отсюда.' FROM `quest_offer_reward` WHERE `ID`=12588 AND MD5(`RewardText`)='15c41e90f30c4b4d4db949770fd68ed1' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12588 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12591, 'ruRU', 'Угроза еще существует, но то, что ты сделал, существенно замедлит продвижение неприятеля.\n\nКапитану Гронделю в Драк\'Агале наверняка требуется твоя помощь.\n\nПрощай, $N.' FROM `quest_offer_reward` WHERE `ID`=12591 AND MD5(`RewardText`)='15eb194b5a2ccc26875a41338ef797f3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12591 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12594, 'ruRU', 'Ты уверен, |3-6($R)?\n\nЛично мне кажется, что их стало больше, чем было раньше.' FROM `quest_offer_reward` WHERE `ID`=12594 AND MD5(`RewardText`)='d3be0d3ed8afeb69ddca1159ee371ad9' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12594 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12595, 'ruRU', 'А, так, значит, старина Хеминг еще не забыл про меня? Думаю, он захочет поучаствовать в охоте – конечно, после того, как мы сделаем за него всю грязную работу. Ну, беспокоиться нечего: тут полно всяких драконов, так что Хеминг останется доволен!' FROM `quest_offer_reward` WHERE `ID`=12595 AND MD5(`RewardText`)='41fec791d0e94048bfafd043f282368f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12595 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12603, 'ruRU', 'В твоих словах я слышу уверенность в себе. Что ж, это очень хорошо, приобретенный опыт поможет тебе в битве с Праматерью драконов.' FROM `quest_offer_reward` WHERE `ID`=12603 AND MD5(`RewardText`)='3d30ff48c49af4c8ae93778678a2bfce' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12603 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12605, 'ruRU', 'Отличная работа! Думаю, Любопытсон будет вовсе не против этих дракончиков!' FROM `quest_offer_reward` WHERE `ID`=12605 AND MD5(`RewardText`)='d263a825a3904aeb462c4bf35c301e69' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12605 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12606, 'ruRU', 'Эти нерубы убили немало наших, |3-6($C).\n\nКак бы там ни было, я благодарен тебе за старания.' FROM `quest_offer_reward` WHERE `ID`=12606 AND MD5(`RewardText`)='b82d082f9110d464312c6969d7f336de' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12606 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12609, 'ruRU', 'Замечательные экземпляры, $N. Как раз то, что нужно.\n\nСпасибо за помощь.' FROM `quest_offer_reward` WHERE `ID`=12609 AND MD5(`RewardText`)='bd222cd14a68e9017bb60f62cd5dbbd9' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12609 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12610, 'ruRU', 'Отлично сработано, $N.\n\nБольшое спасибо за помощь.' FROM `quest_offer_reward` WHERE `ID`=12610 AND MD5(`RewardText`)='a2781b0cfc01188960330cd81e6bd18a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12610 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12628, 'ruRU', 'Слушай внимательно, малютка-|3-6($R). У нас мало времени, и дважды я повторять не буду.' FROM `quest_offer_reward` WHERE `ID`=12628 AND MD5(`RewardText`)='4070c343be53d037b68fc8f4a0b3460e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12628 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12630, 'ruRU', 'Знаешь, а ты жутко $gпохож:похожа; на моего Насса.$b$bМожет быть, все дело в форме носа...' FROM `quest_offer_reward` WHERE `ID`=12630 AND MD5(`RewardText`)='b20894e300ecbb6750183f2e89bcc3ea' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12630 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12631, 'ruRU', 'Да, я и вправду знаком с подобными вещицами.$b$b<Стефан смотрит вам в глаза.>$b$bПохоже, $n, что ты... $gизбранный:избранная;.' FROM `quest_offer_reward` WHERE `ID`=12631 AND MD5(`RewardText`)='e8c7063506afcda5f5b7fab6cbeeacf7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12631 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12632, 'ruRU', 'Спасибо, $N. Я никогда не забуду, что ты для меня сделал.' FROM `quest_offer_reward` WHERE `ID`=12632 AND MD5(`RewardText`)='7641b5bdb4b8d54c17a116af9960d34b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12632 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12637, 'ruRU', 'Теперь ты знаешь, какая судьба тебя ожидала.$b$bКак я уже говорил, это все - не случайность. Изготовление подобного устройства - дело достаточно сложное, а значит, его создавали для какой-то конкретной цели. То есть, именно для тебя.$b$bТак что все очень просто: силы Плети хотят тебя заполучить...' FROM `quest_offer_reward` WHERE `ID`=12637 AND MD5(`RewardText`)='a7d0d1dbe96464438502e14ec8aafd6c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12637 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12639, 'ruRU', 'Спасибо, |3-6($C). Этой субстанции хватит для поддержания моих сил на достаточно долгий срок.' FROM `quest_offer_reward` WHERE `ID`=12639 AND MD5(`RewardText`)='ff830839421f856907aef32cf71dc790' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12639 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12640, 'ruRU', 'Ауне надеется очень-очень, что Дагода успеть получить всех защитников, сколько ей нужно. Теперь порталы закрыты, и больше она ничего не получит.' FROM `quest_offer_reward` WHERE `ID`=12640 AND MD5(`RewardText`)='9ce5f4008735d03ef9672a3c19fa8d8a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12640 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12642, 'ruRU', 'Я едва держусь. Тебе надо действовать быстро, иначе все будет потеряно.' FROM `quest_offer_reward` WHERE `ID`=12642 AND MD5(`RewardText`)='526335c197842c753a0950f741c58ced' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12642 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12654, 'ruRU', 'Тебе удалось! Теперь мне только остается сделать трофей. Сохранить его внешний вид будет непросто... чтобы при этом Хеминг не высмеял приложенные мной усилия.' FROM `quest_offer_reward` WHERE `ID`=12654 AND MD5(`RewardText`)='307a1fea3c12d5853405e5fad664d944' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12654 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12688, 'ruRU', 'Спасибо за освобождение Хелис и за ее безопасное возвращение. Мы все беспокоились, когда она не вернулась со своей охоты за кристаллами.' FROM `quest_offer_reward` WHERE `ID`=12688 AND MD5(`RewardText`)='3428f92c9f8b92025f709f5db9577c02' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12688 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12691, 'ruRU', 'Огромный каменный ключ поворачивается со скрежетом, крышка сундука открывается, и вашим глазам предстают сокровища.' FROM `quest_offer_reward` WHERE `ID`=12691 AND MD5(`RewardText`)='e765be6418f64dd43115924d10d766de' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12691 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12692, 'ruRU', 'Приятно видеть тебя снова. Я знал, что ты не предатель, я рад, что Зепек не ошибся в тебе.\n\nСлышал, теперь ты охотишься на личей – это очень хорошо! Харкек тобой гордится.' FROM `quest_offer_reward` WHERE `ID`=12692 AND MD5(`RewardText`)='e17bd37fb01d6a7530e89105e0eea866' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12692 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12702, 'ruRU', 'А ты неплохо их ловишь!\n\nМожет, однажды мы просто утопим Горегека в реке, чтобы тебе больше не приходилось ловить кур.' FROM `quest_offer_reward` WHERE `ID`=12702 AND MD5(`RewardText`)='550a680754bd6f5c9c02c801ee8f4974' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12702 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12703, 'ruRU', 'Как легко прошел для тебя ритуал!\n\nНадеюсь, ту еще вернешься: тут осталось, кого убить.' FROM `quest_offer_reward` WHERE `ID`=12703 AND MD5(`RewardText`)='f8354bf96623ac17ae084bf465b56a12' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12703 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12704, 'ruRU', 'Так много хороших блестящих штуковин! У тебя правда хорошо получается.\n\nПриходи потом еще, ладно?' FROM `quest_offer_reward` WHERE `ID`=12704 AND MD5(`RewardText`)='2d24fe075a68422d1723dcb2c8d0f2e3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12704 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12705, 'ruRU', 'Со-холу сильный, да? Я очень счастлив, что он принял твое тело и разделил с тобой эту битву.\n\nОн больше доверяет тем, кого встречал уже – так что, может, как-нибудь придешь еще разок помочь нам?' FROM `quest_offer_reward` WHERE `ID`=12705 AND MD5(`RewardText`)='7157800f6c44f94e47540da24da97be4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12705 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12707, 'ruRU', 'Так им и надо, дружище!' FROM `quest_offer_reward` WHERE `ID`=12707 AND MD5(`RewardText`)='f3701ca10b71a67d5cf7ddd40e3a624c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12707 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12711, 'ruRU', 'Сверху на почтовом ящике лежит пачка писем и свитков, накарябанных неразборчивым почерком. Какой хлам...$B$BМожет быть, внутри ящика найдется что-то полезное?' FROM `quest_offer_reward` WHERE `ID`=12711 AND MD5(`RewardText`)='e0f93162948102c3f51a29ef5852faf7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12711 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12726, 'ruRU', 'Благодарю тебя, $N Благодаря тебе, великая буря будет милостива к нам.' FROM `quest_offer_reward` WHERE `ID`=12726 AND MD5(`RewardText`)='cb003939ab572398499d61884ee873d4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12726 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12728, 'ruRU', 'Блестяще! Это довершит мой отчет.\n\nЯ непременно расскажу совету о твоих любезных услугах, $N.' FROM `quest_offer_reward` WHERE `ID`=12728 AND MD5(`RewardText`)='5fa4b3e5f8cd5eba519d984af15c3eee' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12728 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12732, 'ruRU', 'Реджек благодарит. Реджек пьет, обретает силу; Реджек будет помнить твой подарок, $N.' FROM `quest_offer_reward` WHERE `ID`=12732 AND MD5(`RewardText`)='26eeb402c65b39ce542eedea33eaca07' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12732 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12734, 'ruRU', 'Реджек видит пятна крови врагов на своем мече. Теперь у Реджека есть могучее оружие, и сам он станет могучим воином!' FROM `quest_offer_reward` WHERE `ID`=12734 AND MD5(`RewardText`)='dfffa80a0c42bf314268bfa9bcbbe32c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12734 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12735, 'ruRU', 'Воды отныне чисты. Да. Все хорошо.\n\nЯ вижу, $N, ты начинаешь нас понимать.' FROM `quest_offer_reward` WHERE `ID`=12735 AND MD5(`RewardText`)='13597f3025116d248165e44335274fd7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12735 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12736, 'ruRU', 'Вот видишь? Ты уже становишься умнее. Ну, если уж не умнее, то счастливее наверняка!' FROM `quest_offer_reward` WHERE `ID`=12736 AND MD5(`RewardText`)='04c8e2bc7c598cce224873201b2a8d3e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12736 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12737, 'ruRU', 'Ты быстро учишься, $N Ты хорошо знаешь эту песнь. Может, в следующий раз я научу тебя еще одной.' FROM `quest_offer_reward` WHERE `ID`=12737 AND MD5(`RewardText`)='313f55cd4761212944740f66ce13753a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12737 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12739, 'ruRU', 'Не правда ли, приятно осознавать, что ты больше не на их стороне, $N. Ты – $gодин:одна; из нас. Солдат Плети, отныне и навсегда...' FROM `quest_offer_reward` WHERE `ID`=12739 AND MD5(`RewardText`)='56dbea4e26e3fccef330e6b722b4189d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12739 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12741, 'ruRU', 'Теперь Реджек покажет трусливым длинноязыким, как нужно использовать силу стихий!' FROM `quest_offer_reward` WHERE `ID`=12741 AND MD5(`RewardText`)='fd8339c8784c1ed9a10ff8098c227c35' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12741 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12742, 'ruRU', 'Не правда ли, приятно осознавать, что ты больше не на их стороне, $N. Ты – $gодин:одна; из нас. Солдат Плети, отныне и навсегда...' FROM `quest_offer_reward` WHERE `ID`=12742 AND MD5(`RewardText`)='40a89b01d9fa1e9681b90f35e95ca29b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12742 AND x.`locale`='ruRU');
