INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12748, 'ruRU', 'Не правда ли, приятно осознавать, что ты больше не на их стороне, $N. Ты – один из нас. Солдат Плети, отныне и навсегда...' FROM `quest_offer_reward` WHERE `ID`=12748 AND MD5(`RewardText`)='56dbea4e26e3fccef330e6b722b4189d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12748 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12749, 'ruRU', 'Не правда ли, приятно осознавать, что ты больше не на их стороне, $N. Ты – $gодин:одна; из нас. Солдат Плети, отныне и навсегда...' FROM `quest_offer_reward` WHERE `ID`=12749 AND MD5(`RewardText`)='56dbea4e26e3fccef330e6b722b4189d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12749 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12750, 'ruRU', 'Не правда ли, приятно осознавать, что ты больше не на их стороне, $N. Ты – $gодин:одна; из нас. Солдат Плети, отныне и навсегда...' FROM `quest_offer_reward` WHERE `ID`=12750 AND MD5(`RewardText`)='56dbea4e26e3fccef330e6b722b4189d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12750 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12751, 'ruRU', 'И снова Плеть празднует победу! Нет спасения псам Алого ордена. Смерть их близка...' FROM `quest_offer_reward` WHERE `ID`=12751 AND MD5(`RewardText`)='2b23dedc0f2a2c2d594d687a95a30efe' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12751 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12754, 'ruRU', '<Орбаз читает депешу.>$B$BТак значит, армии Дольного Очага и Тирисфальских лугов направляются прямо к нам в руки!$B$B<Орбаз ухмыляется.>$B$BОтлично, переходим ко второй части нашего плана. Ты лично доставишь это донесение верховному генералу Аббендис. Для этого-то тебе и пригодятся эти шмотки...' FROM `quest_offer_reward` WHERE `ID`=12754 AND MD5(`RewardText`)='6a0c76d87962e09cf6c4d116e971c255' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12754 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12755, 'ruRU', '<Верховный генерал Аббендис читает депешу.>$B$BПроклятие! Войска Дольного Очага и Тирисфальских лугов нельзя было посылать в Новый Авалон! Плеть разгромит их еще на подходе!' FROM `quest_offer_reward` WHERE `ID`=12755 AND MD5(`RewardText`)='374bd7307fe31238158d77b9b2c569df' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12755 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12756, 'ruRU', '<Орбаз листает журнал.>$B$BКакая чепуха! Так вот что значит "Багровый Рассвет!"$B$BОни плывут прямо в лапы смерти! Впрочем, сейчас мы должны сосредоточиться на устранении идущих к нам армий.' FROM `quest_offer_reward` WHERE `ID`=12756 AND MD5(`RewardText`)='97729d5a30dc1bec25c77e1b981625a3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12756 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12757, 'ruRU', 'Воистину, ты $gстал:стала; рукой самой судьбы, рыцарь смерти! Мы уничтожим эти армии, и их воскресшие солдаты примкнут к нашему войску!' FROM `quest_offer_reward` WHERE `ID`=12757 AND MD5(`RewardText`)='b1a158770a514208c57eea4309ce1ed9' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12757 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12758, 'ruRU', 'Реджек видит, что удача на твоей стороне! А теперь Реджек наденет новый шлем…' FROM `quest_offer_reward` WHERE `ID`=12758 AND MD5(`RewardText`)='0b7519538bc290282c2872f4e42ec248' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12758 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12759, 'ruRU', 'Ты управляешься с этими ловушками почти так же хорошо, как Зепик!' FROM `quest_offer_reward` WHERE `ID`=12759 AND MD5(`RewardText`)='1fa31db669c27d54472ac13ff608ea7a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12759 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12760, 'ruRU', 'А ты боец что надо... Приходи, еще посражаешься! Хорошего боя много не бывает!' FROM `quest_offer_reward` WHERE `ID`=12760 AND MD5(`RewardText`)='1be020cdc270679f8d86ee18b7b47bc4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12760 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12761, 'ruRU', 'Благодарю тебя, сухая шкура.\n\nЭти кристаллы останутся здесь, чтобы мы были в безопасности. Может, вскоре ты вернешься и снова сумеешь помочь нам.' FROM `quest_offer_reward` WHERE `ID`=12761 AND MD5(`RewardText`)='1b12018cb256c78bd2f5f8594b14d78f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12761 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12762, 'ruRU', 'В тебе столько энергии… столько силы Великих!\n\nЯ не лгу, я просто немного завидую тебе.' FROM `quest_offer_reward` WHERE `ID`=12762 AND MD5(`RewardText`)='81834bbe1c010c329170073caff58c76' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12762 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12786, 'ruRU', 'Превосходно! Обе эти чумы смертельно опасны, но нам ли сторониться смерти? Однажды, $N, ты поймешь, что разрушение – это единственный путь к спасению...' FROM `quest_offer_reward` WHERE `ID`=12786 AND MD5(`RewardText`)='52a41cbb0ea0ef8712a24f89aeb197b0' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12786 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12789, 'ruRU', 'Отлично. Должно быть, Валус получил мой отчет.\n\nЗа работу, |3-6($R).' FROM `quest_offer_reward` WHERE `ID`=12789 AND MD5(`RewardText`)='398bd59dd1badf65d052c1f78b4e8bc5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12789 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12798, 'ruRU', 'С каждым днем твое искусство все возрастает, начертатель. Знай же, что карты таро пользуются большой популярностью на Ярмарке Новолуния, так что если тебе удастся нарисовать еще одну колоду – не стесняйся, обращайся к нам. Среди нас много успешных торговцев, так что без награды ты не останешься.' FROM `quest_offer_reward` WHERE `ID`=12798 AND MD5(`RewardText`)='da1cf4c25e55c08ca2925737a73e5fdf' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12798 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12799, 'ruRU', 'Спасибо, |3-6($C).\n\nЭто сэкономит нам время, а время – дорого.' FROM `quest_offer_reward` WHERE `ID`=12799 AND MD5(`RewardText`)='462626059f7e5a38e1eb3b1aa4bfefbb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12799 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12800, 'ruRU', 'Верховный лорд и его верные рыцари смерти готовы нанести удар! Скоро мы опустошим это место.' FROM `quest_offer_reward` WHERE `ID`=12800 AND MD5(`RewardText`)='253a21f644a057fae83286e5da2a6c4f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12800 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12802, 'ruRU', 'Это впечатляет, $Gдружище:подруга;! Похоже, нас свела сама судьба.\n\nСкоро я отомщу моим братьям и очищу Драк\'Тарон, а ты получишь в награду его величайшее сокровище.' FROM `quest_offer_reward` WHERE `ID`=12802 AND MD5(`RewardText`)='2cc813423b3c41f456592e3e80615836' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12802 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12807, 'ruRU', 'То ли по глупости, то ли по недальновидности, Серебряный авангард предпочел не замечать присутствия Алого Натиска. Но мы будем действовать по-другому.\n\nНам все равно, даже если они вдруг решат помогать нам в войне против Короля-лича. Мы искренне верим, что они недостойны топтать эту землю. И мы уничтожим их – раз и навсегда!' FROM `quest_offer_reward` WHERE `ID`=12807 AND MD5(`RewardText`)='7fb24e81ef573552cb6a24fd7858b13c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12807 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12810, 'ruRU', 'Отлично сработано. Ты пока немного обсохни, а потом мы продолжим.' FROM `quest_offer_reward` WHERE `ID`=12810 AND MD5(`RewardText`)='c651465e38c8581f3f4aa84c101e61b0' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12810 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12813, 'ruRU', '<Дренейский рыцарь смерти холодно смотрит на вас. Ее глаза мертвы, как надгробные камни.>\n\nЗавтра мне приготовят еще одну порцию настойки. Итак, я прощаюсь с тобой до завтра.' FROM `quest_offer_reward` WHERE `ID`=12813 AND MD5(`RewardText`)='94e165e4adac23db2425884201ac280f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12813 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12815, 'ruRU', 'Вот это выдержка, я понимаю! Но мне нужно, чтобы ты поднимался в воздух каждый день, пока мы находимся здесь.\n\nНадеюсь, завтра ты тоже придешь. Твой костяной грифон будет ждать.' FROM `quest_offer_reward` WHERE `ID`=12815 AND MD5(`RewardText`)='a8e24a4eb841236176a858e67cd8c6b1' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12815 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12818, 'ruRU', 'Да, эти сгодятся. Спасибо!\n\nТы, случайно, не видела Дима? Я отправил его с поручением уже давно, но он до сих пор не вернулся. Надеюсь, с ним все в порядке.\n\nКстати, о птичках... а где Янкс, интересно...' FROM `quest_offer_reward` WHERE `ID`=12818 AND MD5(`RewardText`)='b38bae3651e377ac73319e3c22f5dfca' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12818 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12819, 'ruRU', 'Ха-ха! Да, это они! Большое спасибо. Надеюсь, ты там не сильно упарился, пробираясь по минному полю.' FROM `quest_offer_reward` WHERE `ID`=12819 AND MD5(`RewardText`)='9d30487a71737b902d2d4e21b32d00f6' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12819 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12820, 'ruRU', 'И вот сижу я тут... вся такая красивая и величественная, и вдруг слышу взрыв вдалеке! И еще! И еще! И еще добрую дюжину! А я сижу и улыбаюсь при мысли о том, что магнатавры и снобольды сами лезут на верную гибель.\n\nЭто поистине великолепно!' FROM `quest_offer_reward` WHERE `ID`=12820 AND MD5(`RewardText`)='7cdc2817569c21968c372e9c59468e17' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12820 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12821, 'ruRU', 'Отлично!\n\n<На лице Рикет появляется свирепая ухмылка.>\n\nСейчас мы им покажем, почем фунт лиха!' FROM `quest_offer_reward` WHERE `ID`=12821 AND MD5(`RewardText`)='d68a51a20a63d8a3259baec9f2d65d2a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12821 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12822, 'ruRU', 'Ха-ха! Теперь эти скоты будут знать, как отнимать у нас время! Отныне и впредь зеленая кожа будет наводить страх и ужас на всех магнатавров!' FROM `quest_offer_reward` WHERE `ID`=12822 AND MD5(`RewardText`)='f501ffe728eeb2d42bdd46659701e198' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12822 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12826, 'ruRU', 'Симпатичные взрывные устройства. Правда, они милые?' FROM `quest_offer_reward` WHERE `ID`=12826 AND MD5(`RewardText`)='860917fd0d07b5eeb0dd3b27dd477ba9' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12826 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12827, 'ruRU', 'Надеюсь, они не очень на нас обидятся. Мы же не обижаемся, когда они роются в нашем мусоре.' FROM `quest_offer_reward` WHERE `ID`=12827 AND MD5(`RewardText`)='3c081b31b37fc90f4e3dd50e857a3c16' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12827 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12828, 'ruRU', 'Все получилось! Все-таки я очень умная, да!\n\nБольшое спасибо!' FROM `quest_offer_reward` WHERE `ID`=12828 AND MD5(`RewardText`)='ad451e82e466d5696766b3b9d8ade17e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12828 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12829, 'ruRU', 'Ха-ха! Работенка, конечно же, грязная, но ты неплохо с ней справился!\n\nБольшое спасибо, дружище!' FROM `quest_offer_reward` WHERE `ID`=12829 AND MD5(`RewardText`)='c6fdc807a54ab411654491dbb1708c03' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12829 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12830, 'ruRU', 'Фу! Ну там и воняет! Как я понимаю, ты все же столкнулся со снобольдами, да?\n\nНо ты замечательно справился!' FROM `quest_offer_reward` WHERE `ID`=12830 AND MD5(`RewardText`)='c12cd69c362647345225391905cebce3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12830 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12831, 'ruRU', 'Вот спасибо... Надеюсь, Рикет сможет сделать мне противоядие. А теперь уходим отсюда! Скорее!' FROM `quest_offer_reward` WHERE `ID`=12831 AND MD5(`RewardText`)='8e6430559af96a45a51000b92c475d71' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12831 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12832, 'ruRU', 'Спасибо, что ты привел нашего минера, $N! Противоядие я сейчас сделаю без проблем.\n\nЕсли снова увидишь Тор, передай ей от меня, что она дура и грымза.' FROM `quest_offer_reward` WHERE `ID`=12832 AND MD5(`RewardText`)='0e049f33279cdeda6968f61a8b60c36f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12832 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12833, 'ruRU', 'Ты мне нравишься. Я бы сказала, ты просто супер!\n\nУра тебе!' FROM `quest_offer_reward` WHERE `ID`=12833 AND MD5(`RewardText`)='6a7a3e65e03a290b0cc4a7027e4d9c29' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12833 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12836, 'ruRU', 'Чудесно! такая |3-6($R), как ты, мне нравится – мой типаж.' FROM `quest_offer_reward` WHERE `ID`=12836 AND MD5(`RewardText`)='4dd2cd4a3e2210958dca6deb298683ec' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12836 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12838, 'ruRU', 'Давай сюда все бумаги. Я их разберу и, если найду что-то важное, я тебя позову.\n\nВ любом случае, приходи завтра. Они, как известно, меняют планы чуть ли не ежедневно.' FROM `quest_offer_reward` WHERE `ID`=12838 AND MD5(`RewardText`)='9a2a5b128ea4c1f981362d02ad547c87' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12838 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12839, 'ruRU', 'Письмо, написанное Западным Ветром? Так бы сразу и сказал!\n\n<Арет вырывает письмо у вас из рук и читает.>\n\nИдиот! Он действительно здесь?!\n\n<Лорд-командир смеется.>\n\nЭто новая информация. Интересно, и как он себе представляет завоевание мира после победы над Королем-личом? Разве что только в мечтах. Да и то у него вряд ли хватит на это воображения!' FROM `quest_offer_reward` WHERE `ID`=12839 AND MD5(`RewardText`)='88bbf9d711122f3106e8352ce13b969b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12839 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12840, 'ruRU', 'Они воскресили Ландргена? Он наверняка должен знать, где верховный адмирал!' FROM `quest_offer_reward` WHERE `ID`=12840 AND MD5(`RewardText`)='16eaf3a7738e5725a8368bab72e11d25' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12840 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12841, 'ruRU', 'У меня не было твердой уверенности, что ты вернешься. Мне страшно даже представить, что могло бы со мной приключиться, если бы я тут осталась еще на какое-то время.' FROM `quest_offer_reward` WHERE `ID`=12841 AND MD5(`RewardText`)='fca47ae37cb5a0de0759876384a74e6d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12841 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12843, 'ruRU', 'У тебя получилось! Наши мальчики вернулись!' FROM `quest_offer_reward` WHERE `ID`=12843 AND MD5(`RewardText`)='8a7d51d80fb19f06e54932bf88f5d9d4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12843 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12846, 'ruRU', 'Ты явно не из хильд... тогда что ты здесь делаешь? А... ты, наверное, ищешь нового пленника!' FROM `quest_offer_reward` WHERE `ID`=12846 AND MD5(`RewardText`)='1d20586d7fcf133d6b6e8116e6f905a4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12846 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12847, 'ruRU', 'Потайные пещеры на той стороне острова. Как интересно.\n\nПо крайней мере, теперь я знаю, где все мои пропавшие шпионы.' FROM `quest_offer_reward` WHERE `ID`=12847 AND MD5(`RewardText`)='f9d3aab716043b6b2d44b3fb3102ec71' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12847 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12849, 'ruRU', 'В Зале Властности тебя ждут учителя школ крови, льда и нечестивости, которые могут обучить тебя этим темным искусствам.$B$BЯ, Лорд Торваль - глава школы крови, леди Алистра занимается нечестивыми практиками, а архилич Амал\'тазад безраздельно правит в школе льда.$B$BПриходи сюда почаще, ибо в этих знаниях заключена великая сила.' FROM `quest_offer_reward` WHERE `ID`=12849 AND MD5(`RewardText`)='09772447b1b9b38d72b008d08e6551e1' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12849 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12851, 'ruRU', 'Быть может, и правда в твоей груди бьется сердце истинной воительницы.\n\nВремя покажет...' FROM `quest_offer_reward` WHERE `ID`=12851 AND MD5(`RewardText`)='2f48c25ee069c0bdc0aa322b56efe73b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12851 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12852, 'ruRU', 'Мал\'Ганис?!\n\n<Лорд-командир громко смеется.>\n\nДемоны вновь приютили этих недоумков, но теперь они уничтожены!\n\nНадеюсь, мой доблестный $C не откажется тут задержаться и помочь нам прикончить всех остальных? Может, какая-то из этих вещиц будет достаточным поводом, чтобы остаться?' FROM `quest_offer_reward` WHERE `ID`=12852 AND MD5(`RewardText`)='21950dba806a02b31be4e4306a515e25' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12852 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12856, 'ruRU', 'Прими мою искреннюю благодарность, сестра.\n\nТы сберегла честь бруннхильдаров!' FROM `quest_offer_reward` WHERE `ID`=12856 AND MD5(`RewardText`)='2f029cb35f9421cbd5ec01ac3fe3ff4b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12856 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12857, 'ruRU', '<Вождь Яростного Когтя плачет.>$B$BОн был еще маленьким, Ярогрив. Я его вырастил, да. Недобрый день для Яростного Когтя. Сначала тролли напали на нас, потом тролли испортили Ярогрива, и он стал нехорошим. Яростный Коготь больше не будет иметь дела с троллями!' FROM `quest_offer_reward` WHERE `ID`=12857 AND MD5(`RewardText`)='36526c9e2f968dc332cd29ca2eaa330c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12857 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12859, 'ruRU', 'Странно. Я знаю, что ты $gпотушил:потушила; пожар, но огонь так и горит до сих пор. Может быть, эта штука не так хороша, как мы думали, а? И все равно Моки заплатит тебе за работу. Надеюсь, и тролли тоже сгорят!' FROM `quest_offer_reward` WHERE `ID`=12859 AND MD5(`RewardText`)='e13c0e05f0625ad27ca87ad2ca2f6ff7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12859 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12882, 'ruRU', 'О, эти отлично подойдут! Весьма признателен! Не хочешь горло прополоскать после тяжких трудов?' FROM `quest_offer_reward` WHERE `ID`=12882 AND MD5(`RewardText`)='4cb126945ee5b455faf1120a457c3b68' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12882 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12883, 'ruRU', 'Если это тот же Дракуру из крепости Драк\'Тарон, нам понадобится: помощь со стороны.$B$BТут неподалеку есть лагерь рыцарей смерти из Акеруса, они явно шли по тому же следу из разрушений, оставленных Плетью, который привел сюда и рыцарей Серебряного Авангарда. Половина нашего войска завязла у Серебряной Заставы, сражается с бешеными троллями драккари, и поэтому нам нужно объединить силы с рыцарями с Черной Заставы.$B$B<Лантинга бормочет что-то себе под нос.>$B$BА я-то надеялся, что после Часовни Последней Надежды больше уже не увижу этих мерзавцев...' FROM `quest_offer_reward` WHERE `ID`=12883 AND MD5(`RewardText`)='2fd249edde51dfbfb9d883527e43f7bd' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12883 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12886, 'ruRU', 'Сиф... это ты?' FROM `quest_offer_reward` WHERE `ID`=12886 AND MD5(`RewardText`)='05dbba98eadad9975788486b416a5693' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12886 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12892, 'ruRU', 'Теперь у нас, может быть, и получится что-то сделать. Только не обольщайся. Король-лич по-прежнему "наблюдает" за нами через приспешников Плети.\n\nСобственно, поэтому тебя и прислали сюда.' FROM `quest_offer_reward` WHERE `ID`=12892 AND MD5(`RewardText`)='bd13bb92c18f676e0ec8780a5cf479d9' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12892 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12894, 'ruRU', 'Все было отлично, пока нас не атаковали воины Плети. Они захватили Даргата, Герка и Бурра и уничтожили наше средство передвижения. Угадай, кто был их предводителем?$B$B<Маккеллар кивает.>$B$BНавариус...$B$BПохоже, весь этот край превратился в одну большую фабрику для сил Плети. И мы находимся посреди открытой разработки сырья для этой проклятой армии нежити!' FROM `quest_offer_reward` WHERE `ID`=12894 AND MD5(`RewardText`)='e2184ab0c27cd0ea93ad972153cb7a18' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12894 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12895, 'ruRU', 'Ну да, с нашим-то счастьем... можно было заранее предугадать, что именно так все и будет. Но просто так он от нас не уйдет. Давай-ка посмотрим, что там в этой записке.' FROM `quest_offer_reward` WHERE `ID`=12895 AND MD5(`RewardText`)='9d61f8fd8ee9ef536a70762e6aa2ad1e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12895 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12897, 'ruRU', 'Генерал Погибель Света уничтожен, и его войско разбито? Склеп Теней взят?' FROM `quest_offer_reward` WHERE `ID`=12897 AND MD5(`RewardText`)='1b81542239c276ef5989d3a08e0d72e2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12897 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12899, 'ruRU', 'Ты молодец, что вернулся. Как видишь, у нас тут на счету каждый боец.' FROM `quest_offer_reward` WHERE `ID`=12899 AND MD5(`RewardText`)='63e5f1a0c8b27fd166379b8aa57fd372' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12899 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12900, 'ruRU', 'Да, эти сгодятся. Я тебе в два счета сбрую сделаю!' FROM `quest_offer_reward` WHERE `ID`=12900 AND MD5(`RewardText`)='040ac74a2345e511bb36fdeeaf35c051' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12900 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12901, 'ruRU', 'Это просто негодный металлолом?! Проклятье! Железо Плети нам не подходит. Что будем делать?' FROM `quest_offer_reward` WHERE `ID`=12901 AND MD5(`RewardText`)='0fdaca4023d9bc8484a6bd6ca8be0101' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12901 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12902, 'ruRU', 'Вы подходите к странному алтарю, над которым парит в воздухе какой-то свиток. Наверное, это именно то, что искал глава рыцарей Лантинга!' FROM `quest_offer_reward` WHERE `ID`=12902 AND MD5(`RewardText`)='9d7243d0f48aa16a13921be427c7b4ff' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12902 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12903, 'ruRU', 'Эти трое пожертвовали собой, и их великая жертва не будет забыта. Их смерть не будет напрасной. Мы победим!' FROM `quest_offer_reward` WHERE `ID`=12903 AND MD5(`RewardText`)='f2d13b2a67f787e9610d56956200dddd' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12903 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12904, 'ruRU', '<Герк умирает.>$B$BГоворят... говорят, эти варгулы - из тех... кого Король-лич счел ни на что непригодными... и недостойными... Ты... ты только представь... какой мощью должны тогда обладать достойные...$B$BЯ буду молиться за тебя в посмертии, $gотважный герой:доблестная воительница;... И пусть тебе никогда не придется столкнуться с ними, когда их будет много.' FROM `quest_offer_reward` WHERE `ID`=12904 AND MD5(`RewardText`)='964c7e0670388c2ff8ffd276ba717320' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12904 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12905, 'ruRU', 'Мне должны были прислать замену для одной из надзирательниц. Так что мы тебя ждали.\n\nДавай сразу же и приступай к работе.' FROM `quest_offer_reward` WHERE `ID`=12905 AND MD5(`RewardText`)='6976310bacf51b910c843def16f44a60' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12905 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12906, 'ruRU', 'Для новенькой – очень даже неплохо. У меня есть еще одно поручение для тебя.' FROM `quest_offer_reward` WHERE `ID`=12906 AND MD5(`RewardText`)='5915e7dd8ba65c414ffc97584d74a9fd' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12906 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12907, 'ruRU', 'Если у меня поначалу и были какие-то сомнения насчет твоей верности, то теперь они все рассеялись. Я думаю, тебе можно доверять. Еще немного – и ты пойдешь на повышение.' FROM `quest_offer_reward` WHERE `ID`=12907 AND MD5(`RewardText`)='25d097a8258b7b216aa73cb5d46bfa5c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12907 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12908, 'ruRU', 'Я знала, что ты вернешься! Сними с меня эти оковы, и я помогу тебе найти гоблина.' FROM `quest_offer_reward` WHERE `ID`=12908 AND MD5(`RewardText`)='a22205a1809ff40d1f758eb34cb7b764' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12908 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12909, 'ruRU', 'Стало быть, Боктар подрядил Ледокуса на задание? Очень надеюсь, что это действительно важное дело. Забирать у охотника его зверя, пусть даже на время, для этого нужны очень веские причины!' FROM `quest_offer_reward` WHERE `ID`=12909 AND MD5(`RewardText`)='f97033434a18ee361aa2d48af3fb50f7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12909 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12914, 'ruRU', 'Хорошо, что у нас есть запасы взрывчатки. Теперь, когда ты $gпринес:принесла; необходимые материалы, изготовить огромный сефориевый заряд не составит труда.' FROM `quest_offer_reward` WHERE `ID`=12914 AND MD5(`RewardText`)='52e59df051bb3c33fdcc53fe7d567bd5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12914 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12915, 'ruRU', 'Стало быть, с ним мы покончили.\n\nБудем надеяться, что этого достаточно.' FROM `quest_offer_reward` WHERE `ID`=12915 AND MD5(`RewardText`)='1701e6c3aab329fb970d788454b83384' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12915 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12917, 'ruRU', 'Должно быть, тебе удастся связаться с дворфом сейчас. Спроси Боктара, что ему от тебя нужно. И не будем терять времени. У нас его и так мало.' FROM `quest_offer_reward` WHERE `ID`=12917 AND MD5(`RewardText`)='0d3b6c4daa7287f1a69846284056f0ba' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12917 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12921, 'ruRU', 'Ты пришла... хорошо. Кажется, я знаю, где может быть твой гоблин.' FROM `quest_offer_reward` WHERE `ID`=12921 AND MD5(`RewardText`)='d1c54148da51f6b8eebb38461392c5ab' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12921 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12922, 'ruRU', 'Вы кладете металл на наковальню, и как только подносите искры, они выжигают руду.\n\nКогда все прогорает до конца, у вас остается большой кусок металла, который светится собственным светом.' FROM `quest_offer_reward` WHERE `ID`=12922 AND MD5(`RewardText`)='49fcc81912cc0c8c73ac0879381f7374' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12922 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12924, 'ruRU', 'Похоже, мое мастерство изрядно возросло. Или в легендах об этой наковальне есть немалая доля истины.\n\nЭти доспехи – они получились гораздо лучше, чем в изначальном своем варианте, а материалов на них ушло меньше.\n\nА из того, что осталось, я хочу сделать тебе подарок. В знак благодарности за помощь.' FROM `quest_offer_reward` WHERE `ID`=12924 AND MD5(`RewardText`)='39bd840b27aa389f24c7a8fbcf537641' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12924 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12925, 'ruRU', 'Большое спасибо. Нельзя допускать, чтобы кто-то поганил священные традиции наших доблестных предков.' FROM `quest_offer_reward` WHERE `ID`=12925 AND MD5(`RewardText`)='53e8c3d10b230e87d688e6ff28f9cc5e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12925 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12926, 'ruRU', 'Как ты быстро! Похвально, похвально... Теперь, когда у нас есть целый диск, нам надо понять, как с его помощью можно открыть первую половину ключа от архива.' FROM `quest_offer_reward` WHERE `ID`=12926 AND MD5(`RewardText`)='d57b35feedba9a189073cebd4a5cb2c5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12926 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12928, 'ruRU', 'Да, это она! Первая половина краеугольного камня Норганнона. Отлично, $N. Дозорные из Лиги Исследователей уже столько времени ищут хотя бы какие-то указания, где она может быть. Они не поверят, когда я скажу, что оболочку нашел неустрашимый $R!' FROM `quest_offer_reward` WHERE `ID`=12928 AND MD5(`RewardText`)='3d0c2a44687d2e43649c5b3e2944c9f7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12928 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12931, 'ruRU', 'Твои подвиги, безусловно, подняли боевой дух моих воинов. Теперь они будут сражаться с удвоенным рвением.' FROM `quest_offer_reward` WHERE `ID`=12931 AND MD5(`RewardText`)='3b1eb1990e9f96721f688cd6c36f92d8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12931 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12933, 'ruRU', 'Ух ты! Когда я впервые увидел Смрадоборода, я подумал, тебе конец! Но ты молодец!' FROM `quest_offer_reward` WHERE `ID`=12933 AND MD5(`RewardText`)='82258385e1bfe005a5eb0d7198a4117c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12933 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12934, 'ruRU', 'Невероятно! Когда он вышел, я думал, что весь Амфитеатр взорвется! Но ты был явно сильнее!' FROM `quest_offer_reward` WHERE `ID`=12934 AND MD5(`RewardText`)='916ae425194947c134338c792edf5db8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12934 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12937, 'ruRU', 'Воины, которых ты исцелил, вновь встанут в строй, и мы сможем сдерживать натиск врага еще какое-то время. Но, если мы хотим победить железных дворфов, нам надо придумать, как ударить в них с тыла.' FROM `quest_offer_reward` WHERE `ID`=12937 AND MD5(`RewardText`)='1a2185192213f4cfe32dc8a51f72a4bb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12937 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12940, 'ruRU', 'Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!' FROM `quest_offer_reward` WHERE `ID`=12940 AND MD5(`RewardText`)='733bff38bc8259d7b195aeaaa8c58cba' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12940 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12941, 'ruRU', 'Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!' FROM `quest_offer_reward` WHERE `ID`=12941 AND MD5(`RewardText`)='733bff38bc8259d7b195aeaaa8c58cba' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12941 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12942, 'ruRU', 'Валь\'киры, эти комнатные собачонки Короля-лича... бесчестные, ничтожные твари! Они сами сделали свой выбор, а теперь пусть пожинают его плоды!' FROM `quest_offer_reward` WHERE `ID`=12942 AND MD5(`RewardText`)='41ebd281826ed9d351b2c6e0a627608b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12942 AND x.`locale`='ruRU');
