INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12953, 'ruRU', 'Вот это мне нравится! Да, у этих предательниц теперь новый хозяин, но они никогда не забудут прощальный подарок своих сестер.' FROM `quest_offer_reward` WHERE `ID`=12953 AND MD5(`RewardText`)='1aba02db251e8424fccd8e96a62abbc4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12953 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12954, 'ruRU', 'Слушай, а я тебя знаю! Разговоры о твоей блестящей победе в Кольце Крови не умолкали в течение нескольких месяцев! Жалко, что ты не явился на следующий чемпионат, чтобы подтвердить свое звание чемпиона! Хотя, может, оно и правильно. Как говорится, как нажито, так и прожито. По крайней мере, ты до сих пор жив.' FROM `quest_offer_reward` WHERE `ID`=12954 AND MD5(`RewardText`)='1e93487f2cc75055aa9d80c9f9cbf1fd' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12954 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12956, 'ruRU', 'Угрюмое лицо Торима озаряется радостью, когда он понимает, что именно вы ему принесли.' FROM `quest_offer_reward` WHERE `ID`=12956 AND MD5(`RewardText`)='035c67433c11dc18a2781e9cc4cf7826' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12956 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12957, 'ruRU', 'Я надеялся, что большинство освобожденных пленников все-таки согласится присоединиться к нам, но я не могу их винить. Хороший союзник – это союзник по доброй воле, и мы очень тебе благодарны за помощь.' FROM `quest_offer_reward` WHERE `ID`=12957 AND MD5(`RewardText`)='879a21753d5efdf7c64cdd5861fafc99' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12957 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12958, 'ruRU', 'Вот тебе значок даларанского ювелира, как и было обещано. Приходи завтра. Наверняка мне понадобится что-то еще!' FROM `quest_offer_reward` WHERE `ID`=12958 AND MD5(`RewardText`)='6919bc61880062bf0480173dd322fe80' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12958 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12959, 'ruRU', 'Вот тебе значок даларанского ювелира, как и было обещано. Приходи завтра. Наверняка мне понадобится что-то еще!' FROM `quest_offer_reward` WHERE `ID`=12959 AND MD5(`RewardText`)='6919bc61880062bf0480173dd322fe80' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12959 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12960, 'ruRU', 'Вот тебе значок даларанского ювелира, как и было обещано. Приходи завтра. Наверняка мне понадобится что-то еще!' FROM `quest_offer_reward` WHERE `ID`=12960 AND MD5(`RewardText`)='6919bc61880062bf0480173dd322fe80' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12960 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12961, 'ruRU', 'Вот тебе значок даларанского ювелира, как и было обещано. Приходи завтра. Наверняка мне понадобится что-то еще!' FROM `quest_offer_reward` WHERE `ID`=12961 AND MD5(`RewardText`)='ef1b266c1530370d4e734edd7c762ff0' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12961 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12962, 'ruRU', 'Вот тебе значок даларанского ювелира, как и было обещано. Приходи завтра. Наверняка мне понадобится что-то еще!' FROM `quest_offer_reward` WHERE `ID`=12962 AND MD5(`RewardText`)='6919bc61880062bf0480173dd322fe80' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12962 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12963, 'ruRU', 'Вот тебе значок даларанского ювелира, как и было обещано. Приходи завтра. Наверняка мне понадобится что-то еще!' FROM `quest_offer_reward` WHERE `ID`=12963 AND MD5(`RewardText`)='6919bc61880062bf0480173dd322fe80' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12963 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12964, 'ruRU', '<Глыбоскал тянется, чтобы взять образец руды, но потом отшатывается.>\n\nЭта руда... мне нельзя ее трогать. Она заряжена какой-то противоестественной энергией. Существам, созданным из камня, нельзя к ней прикасаться. Интересно, и что они собираются с ней делать?' FROM `quest_offer_reward` WHERE `ID`=12964 AND MD5(`RewardText`)='c70ad949c4dfd9b1f583a9280d62a4e7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12964 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12965, 'ruRU', '<Глыбоскал мрачно кивает.>\n\nЭто существенно ослабит Закаленных Бурей, но они все равно будут сражаться. Им все равно, сколько их будет убито и ранено – они готовы пожертвовать сотнями, даже тысячами своих, лишь бы стереть нас с лица земли.' FROM `quest_offer_reward` WHERE `ID`=12965 AND MD5(`RewardText`)='1732aead5c230dd64b8009929c2cc409' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12965 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12966, 'ruRU', 'Заново перековать доспех Торима? Да, это возможно.\n\nГлавное – привести в порядок наковальню...' FROM `quest_offer_reward` WHERE `ID`=12966 AND MD5(`RewardText`)='cc2cc556d2e11c5f0ba7fe23a22590b7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12966 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12967, 'ruRU', 'Ты молодец, $R. Я непременно скажу королю о твоем славном деянии.\n\nНаковальня уже почти остыла. Увидимся в Дун Ниффелеме!' FROM `quest_offer_reward` WHERE `ID`=12967 AND MD5(`RewardText`)='5dc8e847cf87b3d0862ef264a36da84e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12967 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12968, 'ruRU', 'Юльда сама напросилась. Всякий, кто оскорбит Круг Хильд, не останется безнаказанным. Даже если она нашей крови.' FROM `quest_offer_reward` WHERE `ID`=12968 AND MD5(`RewardText`)='c8c065f2c8e4f4c54fa8a956e10d158b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12968 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12969, 'ruRU', 'Хорошая работа. Похоже, наша сделка принесла удовлетворение обеим сторонам.' FROM `quest_offer_reward` WHERE `ID`=12969 AND MD5(`RewardText`)='2bdc57fc93bdfd7bb02d048a69a1c330' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12969 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12970, 'ruRU', 'Договорились. Ты примешь участие в состязаниях Круга хильд и с моей помощью восстановишь великого Торима на его законном месте.' FROM `quest_offer_reward` WHERE `ID`=12970 AND MD5(`RewardText`)='048d34de13aec82d88b354c0003ca261' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12970 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12972, 'ruRU', 'Думаешь, мы и тебе дадим такого же медведя? Тебе придется как следует проявить себя, прежде чем ты от нас хоть что-нибудь получишь.\n\nНе надо воображать о себе слишком много только потому, что тебе удалось одержать несколько побед в Круге Хильд.' FROM `quest_offer_reward` WHERE `ID`=12972 AND MD5(`RewardText`)='ed4756d3021b9233db0124e9b2808619' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12972 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12974, 'ruRU', 'Тебя прислал Ловкий Викерс?' FROM `quest_offer_reward` WHERE `ID`=12974 AND MD5(`RewardText`)='f1e2a8508363fc35ba8906c0576d8a5a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12974 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12975, 'ruRU', 'Еще одно доброе дело, которое ты совершил от лица Торима, $C.\n\nЭто поможет смягчить сердце моего народа по отношению к нему.' FROM `quest_offer_reward` WHERE `ID`=12975 AND MD5(`RewardText`)='8151dfbff640e28c95cd106d67f731fe' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12975 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12976, 'ruRU', '<На глаза Ньормельда наворачиваются слезы, когда он высыпает на наковальню содержимое мешка.>\n\nРог Ходира...\n\nСвященный дар моему народу, который мы получили из рук самого Ходира, $R!\n\nКогда в следующий раз ты придешь в нашу крепость, ты увидишь плоды своих трудов.\n\nПрощай.' FROM `quest_offer_reward` WHERE `ID`=12976 AND MD5(`RewardText`)='ac8bd5169751f8711bc9f4596723a294' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12976 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12977, 'ruRU', 'Вас переполняет чувство покоя и удовлетворения от завершенного дела. Вы точно знаете, что беспокойные духи Громовержья упокоились с миром, и их мучения закончились.' FROM `quest_offer_reward` WHERE `ID`=12977 AND MD5(`RewardText`)='f950f8784b4563873d5e394324ebfc38' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12977 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12980, 'ruRU', '<Бруор слушает ваш рассказ о том, что вам удалось узнать в мастерской.>\n\nЗначит, хозяин Валдурана дал ему этот зловещий металл, чтобы он сконструировал гигантское оружие? Вполне вероятно, что он собирается использовать его против нас! Его надо остановить, пока он не закончил свою работу.' FROM `quest_offer_reward` WHERE `ID`=12980 AND MD5(`RewardText`)='082edc9b16488fa484f49ac67151eadb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12980 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12981, 'ruRU', 'Теперь у вас появляется ощущение завершенного дела. Вы понимаете: то, что вы сделали, укрепит узы возобновленной дружбы между Торимом и сыновьями Ходира.' FROM `quest_offer_reward` WHERE `ID`=12981 AND MD5(`RewardText`)='6ecc9fdc869905c4e1376aaa0b923f7a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12981 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12983, 'ruRU', 'Да, впечатляет... Я уже и не думала, что когда-нибудь снова увижу медведицу-матриарха. И особенно такую огромную.' FROM `quest_offer_reward` WHERE `ID`=12983 AND MD5(`RewardText`)='9c14c5b9a7ebd2ce94a37c1965b57f96' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12983 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12984, 'ruRU', 'Наконец-то, Валдуран мертв, и Закаленные Бурей ослабели, но если его похвальба была обоснована, нам придется продолжить биться с Закаленными Бурей и в его отсутствие. Это оружие, что они готовят, может покончить с нами.' FROM `quest_offer_reward` WHERE `ID`=12984 AND MD5(`RewardText`)='230aa4799536b8cfc4c1834b003bdd09' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12984 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12985, 'ruRU', 'Вот, почти все готово.\n\nКогда я его соберу, в Дун Ниффелеме трижды подумают прежде, чем на нас нападать.' FROM `quest_offer_reward` WHERE `ID`=12985 AND MD5(`RewardText`)='3c6007c1250dedc2a7e75aef7439a609' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12985 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12987, 'ruRU', '<Ньормельд смотрит на шлем Ходира, заметно растроганный.>\n\nХорошо, $малыш:невеличка:r; $R.\n\nХорошо...' FROM `quest_offer_reward` WHERE `ID`=12987 AND MD5(`RewardText`)='0baf8888895133552704b6f00917a0ac' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12987 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12988, 'ruRU', 'Отлично сработано! Это, конечно, не остановит железных дворфов, но на восстановление кузниц у них уйдет время. И это время будет работать на нас.' FROM `quest_offer_reward` WHERE `ID`=12988 AND MD5(`RewardText`)='5361b5baffa6ed9f92df103198354b13' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12988 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12989, 'ruRU', 'Йормунгары – мерзопакостные создания. Их истребление – благое дело.' FROM `quest_offer_reward` WHERE `ID`=12989 AND MD5(`RewardText`)='dbf97528b738308bfd75c65a7ca41f7e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12989 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12991, 'ruRU', 'Было время, когда я бы не стал никого посылать с поручением, которое выполнил ты, но после достаточно тесного общения с железными дворфами я уже не питаю к ним теплых чувств. Главное, нам удалось помешать врагу, а значит, мы выиграли себе время.' FROM `quest_offer_reward` WHERE `ID`=12991 AND MD5(`RewardText`)='f147c54254dbdce322148524f232f4e3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12991 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12993, 'ruRU', '<Глыбоскал начинает просматривать документы, и его глаза изумленно распахиваются.>\n\nЯ даже не думал, что железные дворфы на такое способны. Против этого чудовища, если они его соберут, у нашей армии не будет ни единого шанса. К счастью, у них, как я понял, не хватает одной ключевой детали.' FROM `quest_offer_reward` WHERE `ID`=12993 AND MD5(`RewardText`)='a4a390d82bade355ee8263f6e970594c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12993 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12994, 'ruRU', 'Когда вы надеваете цепь обратно на шею повелительнице логова, она облизывает вам лицо, выражая тем самым свою благодарность.' FROM `quest_offer_reward` WHERE `ID`=12994 AND MD5(`RewardText`)='4547fe49e526b20527507f7b7b71cbf7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12994 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12996, 'ruRU', 'Неплохо. Я-то надеялась, что Киргараак свернет тебе шею, и я смогу взять себе твою медведицу.\n\nШучу, сестра, шучу. Но в каждой шутке есть доля правды... У тебя действительно замечательная медведица.' FROM `quest_offer_reward` WHERE `ID`=12996 AND MD5(`RewardText`)='ed4ddcb8dc2661ac3b28b5c2d3942f31' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12996 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12997, 'ruRU', 'Ты сделала это! И вернулась целой и невредимой! Жаль, что нельзя сказать то же о твоей медведице.\n\nОна еще не скоро поправится. К счастью, она пока что тебе пока не понадобится.' FROM `quest_offer_reward` WHERE `ID`=12997 AND MD5(`RewardText`)='d641570e44f57dc1bc5b94e327abcf16' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12997 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 12998, 'ruRU', 'Если Сердце попадет в руки Нарвира, колосс обретет свою полную силу! У нас не останется выбора, нам придется сражаться.' FROM `quest_offer_reward` WHERE `ID`=12998 AND MD5(`RewardText`)='0a763175351b49548d9e206584674f0b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=12998 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13001, 'ruRU', 'Отойди в сторонку, $R, и смотри, как сбывается пророчество!' FROM `quest_offer_reward` WHERE `ID`=13001 AND MD5(`RewardText`)='2cad6776f6127f5c0ae60df83208ec6a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13001 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13003, 'ruRU', 'Свершилось.\n\nПосмотрев в глаза смерти, ты одержал  победу.\n\nБлистательно справившись с грозным зверем, ты ' FROM `quest_offer_reward` WHERE `ID`=13003 AND MD5(`RewardText`)='1817eb285944db95a8ae714d3fe553e9' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13003 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13005, 'ruRU', 'Неплохое начало. Но войска моего брата быстро перегруппируются и пойдут в контратаку. Нам нужна окончательная победа.' FROM `quest_offer_reward` WHERE `ID`=13005 AND MD5(`RewardText`)='3e788661b5578cb6e1e61102c4e5a0d8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13005 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13006, 'ruRU', 'Вы покрываете шлем тонким слоем масла, и иней сразу же отпадает, и шлем начинает сверкать.' FROM `quest_offer_reward` WHERE `ID`=13006 AND MD5(`RewardText`)='83ff0c64ed79a8b48be73d74f13393fd' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13006 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13007, 'ruRU', 'Мы сделали это, мы справились! И Приют цел, и Закаленные Бурей разбиты! Надо предупредить Бранна, прежде чем Локен опомнится и наберет новое войско. Мы должны закрепить сегодняшнюю победу, а для этого надо отправиться в Ульдуар и окончательно разгромить Локена!' FROM `quest_offer_reward` WHERE `ID`=13007 AND MD5(`RewardText`)='407bbf506a0a55ddd9ba9f21c655ec0f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13007 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13009, 'ruRU', '<Получив от вас перекованные доспехи, Торим поражен их великолепием.>\n\nТвои успехи бесспорны, $R, но нам предстоит еще многое сделать.' FROM `quest_offer_reward` WHERE `ID`=13009 AND MD5(`RewardText`)='d05ab7ac7414974318c4657abecc1f0a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13009 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13010, 'ruRU', 'Никакие слова не способны выразить мою благодарность, $C.\n\nТы сослужил мне поистине неоценимую службу. Прими это в знак благодарности.' FROM `quest_offer_reward` WHERE `ID`=13010 AND MD5(`RewardText`)='19b1dd41523fe53330f6182071d6eef0' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13010 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13011, 'ruRU', 'Стало быть, дело сделано.\n\nМы слышали вопли Жормуттар. Они разносились по всей долине.\n\nТы сослужил нам хорошую службу, $R.' FROM `quest_offer_reward` WHERE `ID`=13011 AND MD5(`RewardText`)='bc8a520296396cff63a1b2e10aae99f2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13011 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13012, 'ruRU', 'Приятно знать, что народ этих земель все еще отдает дань уважения древним расам. Всего хорошего, $N. Прими этот знак...' FROM `quest_offer_reward` WHERE `ID`=13012 AND MD5(`RewardText`)='0f6ce527cc9d8ad5e7d20a0d5c593d96' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13012 AND x.`locale`='ruRU');
