INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13024, 'ruRU', 'Жизнь так и кипит в тебе, $gюный:юная; |3-6($c). Я принимаю твою дань уважения. Возьми взамен этот знак...' FROM `quest_offer_reward` WHERE `ID`=13024 AND MD5(`RewardText`)='59dca4c17bd2d1169fe2d539a13985c7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13024 AND x.`locale`='ruRU');
