INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13032, 'ruRU', 'Жизнь так и кипит в тебе, $gюный:юная; |3-6($c). Я принимаю твою дань уважения. Возьми взамен этот знак...' FROM `quest_offer_reward` WHERE `ID`=13032 AND MD5(`RewardText`)='59dca4c17bd2d1169fe2d539a13985c7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13032 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13033, 'ruRU', 'Жизнь так и кипит в тебе, $gюный:юная; |3-6($c). Я принимаю твою дань уважения. Возьми взамен этот знак...' FROM `quest_offer_reward` WHERE `ID`=13033 AND MD5(`RewardText`)='59dca4c17bd2d1169fe2d539a13985c7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13033 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13034, 'ruRU', 'Как интересно… Это совсем не похоже на историю, которую мне рассказал укротитель ветра Бара.' FROM `quest_offer_reward` WHERE `ID`=13034 AND MD5(`RewardText`)='c502a3397520944e55304df4c99c214c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13034 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13035, 'ruRU', 'Один за другим, все прислужники моего брата повержены. Уже совсем скоро мятеж Локена будет подавлен.' FROM `quest_offer_reward` WHERE `ID`=13035 AND MD5(`RewardText`)='784f40a122dc668bbf5dcd061a952486' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13035 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13037, 'ruRU', 'Даже вождь начинает терять память? Прошлое переиначивается прямо у нас на глазах, и если нам не удастся узнать, кто за этим стоит, все наследие Штормового Копыта будет утрачено навсегда!' FROM `quest_offer_reward` WHERE `ID`=13037 AND MD5(`RewardText`)='6df820d3f7b8e4c43eae1afea7d92514' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13037 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13046, 'ruRU', 'Вы укрепляете зуб в десне Арнгрима, и у вас складывается впечатление, что муки голода старого короля ослабли… на какое-то время.' FROM `quest_offer_reward` WHERE `ID`=13046 AND MD5(`RewardText`)='fede0366246740c1f4a89890267e4653' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13046 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13047, 'ruRU', 'Нет… Не может такого быть...\n\nНикому не под силу победить Торима в схватке один на один. Ни великану, ни зверю… вообще никому! И уж точно никак не его братцу, мерзавцу и трусу.\n\nКлянусь именами моих славных предков...\n\nЛокен заплатит за это!' FROM `quest_offer_reward` WHERE `ID`=13047 AND MD5(`RewardText`)='8488247182b0eaa6e4d0b8f9a0720b52' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13047 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13049, 'ruRU', 'Это большая удача, $N, что тебе удалось вернуть их в целости и сохранности. Теперь мы сможем использовать Молот Знаний, чтобы отправить тебя в прошлое, в тот момент, когда Северный Ветер только начал искажать подлинную линию времени. Только так можно восстановить истинную историю этого места.' FROM `quest_offer_reward` WHERE `ID`=13049 AND MD5(`RewardText`)='e688d0ae10928005eca5e2228abf2e70' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13049 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13051, 'ruRU', 'Какое счастье, когда старый друг возвращается целым и невредимым! Похоже, удача вновь повернулась ко мне лицом... и все – благодаря тебе!' FROM `quest_offer_reward` WHERE `ID`=13051 AND MD5(`RewardText`)='04d376a646ecc84a3802079a4e785d7e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13051 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13058, 'ruRU', 'Твой сегодняшний подвиг не даст Штормовому Копыту и его славным деяниям сгинуть в безвестности. Твое имя тоже навечно войдет в историю Азерота. Я все запомню и опишу твои подвиги, дабы они сохранились в веках!' FROM `quest_offer_reward` WHERE `ID`=13058 AND MD5(`RewardText`)='a2c85358b7c4b77a2cc4bd7656ac60ca' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13058 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13061, 'ruRU', 'Ты неплохо справляешься. Честно сказать, я не думала, что ты сумеешь добиться столь выдающегося положения среди хильд за такое короткое время.' FROM `quest_offer_reward` WHERE `ID`=13061 AND MD5(`RewardText`)='3c1c4188e572c458466a20477171915e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13061 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13062, 'ruRU', 'Ты готова, сестра? Помни: назад пути нет.' FROM `quest_offer_reward` WHERE `ID`=13062 AND MD5(`RewardText`)='7d811f679fae49a4a54719e8cced7162' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13062 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13063, 'ruRU', 'Так что же, сестра, ты считаешь себя героиней, потому что исполнила пару простых поручений?\n\nТебе еще многому предстоит научиться...' FROM `quest_offer_reward` WHERE `ID`=13063 AND MD5(`RewardText`)='a225fc5e340dad3ce829933a4bc5a4b8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13063 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13064, 'ruRU', 'Теперь ты знаешь историю этой земли... моей земли.\n\nЯ прошу тебя: помоги мне все исправить.' FROM `quest_offer_reward` WHERE `ID`=13064 AND MD5(`RewardText`)='0e1aea778ccca0d92c6f4169404c1dc6' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13064 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13068, 'ruRU', 'Не подходи! Берегись! Я заражен! И не хочу, чтобы эта зараза коснулась тебя или кого-то еще!' FROM `quest_offer_reward` WHERE `ID`=13068 AND MD5(`RewardText`)='e59160f9ad0eff429c1c28ea3547b9c7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13068 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13069, 'ruRU', 'Ты настоящий борец за справедливость, $N!\n\nможет, придешь еще завтра? Еще протодраконов постреляешь.' FROM `quest_offer_reward` WHERE `ID`=13069 AND MD5(`RewardText`)='0a3f5cb52c69106a662ce40daf77e6e0' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13069 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13072, 'ruRU', 'Бриденбрад заразился? Трудно представить более страшную участь для воина, который всю свою жизнь посвятил пути Света! Я не могу бросить его умирать, не попытавшись помочь.\n\nМы спасем его от нежизни! Мы найдем способ помочь этому доблестному герою.' FROM `quest_offer_reward` WHERE `ID`=13072 AND MD5(`RewardText`)='0a1b946589dac28203c0f5e7da65a811' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13072 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13073, 'ruRU', 'Здравствуй, дитя мое.\n\nЯ понимаю, почему Тирион просит меня об этом, и доверяю ему. Итак, что же мы можем сделать для рыцаря Бриденбрада...Задача не из легких. Плеть ведь не из этого мира, и многие уже безуспешно пытаются преодолеть ее разрушительное влияние в течение долгих лет.\n\nОднако, для тех, в чьем сердце живет Свет, а помыслы благородны, надежда всегда есть.' FROM `quest_offer_reward` WHERE `ID`=13073 AND MD5(`RewardText`)='8ff4449371f15c6e8a1e22cb4fb9a12f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13073 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13090, 'ruRU', 'Прими мою благодарность.' FROM `quest_offer_reward` WHERE `ID`=13090 AND MD5(`RewardText`)='7c7f05803d2fc4ea182f9659a278f00d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13090 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13096, 'ruRU', 'Ты это сделал?! Гал\'дара уничтожен? Негодяй получил по заслугам!\n\nВот, прими это в награду за свои старания.' FROM `quest_offer_reward` WHERE `ID`=13096 AND MD5(`RewardText`)='ae3f0033a404aeeb0165957fab173c1f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13096 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13097, 'ruRU', 'Слушай, дружище. Работенка тебе предстоит не из легких!' FROM `quest_offer_reward` WHERE `ID`=13097 AND MD5(`RewardText`)='b90b18b3d6f15581427b117bef36b577' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13097 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13098, 'ruRU', '<Ба\'Кини быстро просматривает таблички и вновь обращается к вам.>\n\nДа, это подлинники, |3-6($R). Помещу их в свою коллекцию, на подобающее им место.\n\nМожет, нам все-таки удастся вразумить если не современников, то хотя бы потомков.' FROM `quest_offer_reward` WHERE `ID`=13098 AND MD5(`RewardText`)='c679cbcfc6cf041c1d05c3b12315597d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13098 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13100, 'ruRU', 'Выглядит аппетитно! Спасибо!' FROM `quest_offer_reward` WHERE `ID`=13100 AND MD5(`RewardText`)='06b6bba4fc4aeb5168b00e4eb00fb1a9' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13100 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13102, 'ruRU', 'Его съедят в две секунды! Большое спасибо!' FROM `quest_offer_reward` WHERE `ID`=13102 AND MD5(`RewardText`)='a28a2acdb26b4b1a7c351df8f0581a2a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13102 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13103, 'ruRU', 'А что?! Неплохой букет!' FROM `quest_offer_reward` WHERE `ID`=13103 AND MD5(`RewardText`)='05607c4957ae9681ca6f39b6dc63a8c0' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13103 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13104, 'ruRU', 'Никто лучше меня не знаком с тактикой Плети.\n\n<Черный Дозорный некоторое время внимательно вас рассматривает.>\n\nДо битвы за часовню Последней Надежды мы с моими рыцарями сражались на стороне Короля-лича. Он контролировал каждый наш шаг. Но все изменило сияние рассвета...' FROM `quest_offer_reward` WHERE `ID`=13104 AND MD5(`RewardText`)='589d12539b19e915f0769260ece4522d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13104 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13108, 'ruRU', 'Этот подлый червь мертв?\n\nТы принес великое благо моему народу, $R.\n\nПрими этот дар в награду за доблесть и верность.' FROM `quest_offer_reward` WHERE `ID`=13108 AND MD5(`RewardText`)='f7af4c029cc38caaff4772d56c68f49b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13108 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13109, 'ruRU', 'Волхан больше не будет тревожить сон моего народа.\n\nПродолжай в том же духе, малыш $R. Со временем, я уверен, мой народ сумеет простить Торима.' FROM `quest_offer_reward` WHERE `ID`=13109 AND MD5(`RewardText`)='3cc75a99efa235e3f1226e77e63fa57d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13109 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13110, 'ruRU', 'На пути настоящего рыцаря всегда встречается несправедливость и зло. И единственный правильный выбор – бороться с ними до конца. Сегодня ты начал свой путь, и многое еще ждет тебя впереди.' FROM `quest_offer_reward` WHERE `ID`=13110 AND MD5(`RewardText`)='1c55d88f4170f5ad3f7b49496d88c096' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13110 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13111, 'ruRU', 'Да, это именно то, что нужно!\n\nВот, это тебе – награда за труды.' FROM `quest_offer_reward` WHERE `ID`=13111 AND MD5(`RewardText`)='dbd2fa76510ed7804906c2de95ca2ccd' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13111 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13114, 'ruRU', 'С виду вроде бы аппетитно. Спасибо за помощь.' FROM `quest_offer_reward` WHERE `ID`=13114 AND MD5(`RewardText`)='a861e429845145cf5f27e4713d8aeeae' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13114 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13115, 'ruRU', 'Замечательное вино! Надо будет узнать, где его производят.' FROM `quest_offer_reward` WHERE `ID`=13115 AND MD5(`RewardText`)='954c5ec96ec1546ba47b8360d1824854' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13115 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13116, 'ruRU', 'Замечательно! Надеюсь, "Даларанские крушители" сегодня вырвутся вперед!' FROM `quest_offer_reward` WHERE `ID`=13116 AND MD5(`RewardText`)='b3c46338312760526b76357aab7dfbd0' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13116 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13130, 'ruRU', 'Древесина сама по себе устойчива к порче и разложению. А уж хрустальная древесина и вовсе их убивает! Эльфийская кладка, столько лет испытывавшая на себе чудодейственное влияние Дикой чащи, обладает теми же свойствами.\n\nскоро начнется строительство.' FROM `quest_offer_reward` WHERE `ID`=13130 AND MD5(`RewardText`)='345aef6ae46e84f155bc42068df15207' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13130 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13131, 'ruRU', 'Отлично! У тебя получилось, дружище!\n\nТеперь я могу пойти к капитану и не бояться, что он прикончит меня на месте. Так что большое тебе спасибо. И тебе, и твоим друзьям.\n\nВот, возьми. Так сказать, в знак благодарности. Ты заслужил.' FROM `quest_offer_reward` WHERE `ID`=13131 AND MD5(`RewardText`)='5ff69350244661efc2b537882ec48781' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13131 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13137, 'ruRU', 'Я спрятала Вардмадру в надежном месте. Пусть подождет в безопасности, пока мы готовим окончательное отмщение!' FROM `quest_offer_reward` WHERE `ID`=13137 AND MD5(`RewardText`)='97b932e3836acd9b706e9c88cd72c479' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13137 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13138, 'ruRU', 'Это, вне всяких сомнений, неочищенный саронит. Мы видели оружие, сделанное из него, в руках лучших воинов Короля-Лича, а теперь они вооружают им кого ни попадя. Должно быть, они добывают руду в гигантских масштабах!' FROM `quest_offer_reward` WHERE `ID`=13138 AND MD5(`RewardText`)='246b004c83e0a03b0c58b65f6e8cd73f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13138 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13140, 'ruRU', 'Пластины практически идеально совпадают с найденными осколками. Должно быть, они используют их, чтобы получать еще более сильных вурдалаков. Плеть пойдет на все ради победы. И это еще один повод поскорее уничтожить это отвратительное место!' FROM `quest_offer_reward` WHERE `ID`=13140 AND MD5(`RewardText`)='023b5722ca3b5c2d7fbe10d413bf3040' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13140 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13143, 'ruRU', 'Я приковал тварь к столбу, но мне не помешало бы заполучить еще парочку-троечку.\n\nА теперь давай займемся этим глазом.' FROM `quest_offer_reward` WHERE `ID`=13143 AND MD5(`RewardText`)='ae9026cb2b42baefdaf826d1589bfe36' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13143 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13144, 'ruRU', 'Замечательно. Что может быть лучше, чем проснуться с утра пораньше и вдохнуть запах поджаренной прогнившей плоти! Это запах победы над Плетью.' FROM `quest_offer_reward` WHERE `ID`=13144 AND MD5(`RewardText`)='8317574687f4a75b6a044e4e4be0fbab' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13144 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13145, 'ruRU', 'Блестяще сработано. В общем, я знал, что какие-то рыцари смерти до сих пор хранят верность Артасу. Но я думал, что их значительно меньше.\n\nОн и вправду использует все средства, чтобы завладеть троном Акеруса. Разрушить крепость из чистого саронита будет непросто. Хотя и не нужно ее разрушать… мы можем помешать производству и нейтрализовать предводителей рыцарей смерти прежде, чем они станут серьезной угрозой.\n\nНо самое главное, нам надо отсечь рыцарей смерти от их командиров, чтобы мы могли нанести удар.' FROM `quest_offer_reward` WHERE `ID`=13145 AND MD5(`RewardText`)='925ed9148166fe8f1c1d02a7492748b4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13145 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13146, 'ruRU', 'Они даже не сообразили тебя схватить? Я же говорил, что они предсказуемые и тупые.' FROM `quest_offer_reward` WHERE `ID`=13146 AND MD5(`RewardText`)='66ae00962d6b5c6fb4c9095ed2f5c9a2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13146 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13147, 'ruRU', 'А правда, зачем жертвовать своими солдатами, если эти ребята и так друг друга с радостью ухлопают?' FROM `quest_offer_reward` WHERE `ID`=13147 AND MD5(`RewardText`)='b0af8e27e8a848af39fa5529a2a764ab' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13147 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13152, 'ruRU', '<Темная всадница Арли недобро смеется, запрокинув голову>\n\nПодходящий конец для "доброго доктора", ты не находишь?' FROM `quest_offer_reward` WHERE `ID`=13152 AND MD5(`RewardText`)='ddafca99c7c4efa0b9c89e968e1727b4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13152 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13155, 'ruRU', 'Зловещая Крепость... лишнее подтверждение тому, как сильно Артас не любит проигрывать. Ладно, всадим клинок поглубже.' FROM `quest_offer_reward` WHERE `ID`=13155 AND MD5(`RewardText`)='67f09735e8fc1fe0ea19c45c301b9d8a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13155 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13157, 'ruRU', 'Нас ждет долгий и трудный поход к воротам Цитадели Ледяной Короны. Благодарю тебя от имени всех рыцарей Серебряного Авангарда – за все, что ты для нас сделал. Теперь мы можем спать спокойно, зная, что бы будешь сражаться бок о бок с нами в этом проклятом месте.\n\n<Верховный лорд Тирион Фордринг отдает вам честь.>' FROM `quest_offer_reward` WHERE `ID`=13157 AND MD5(`RewardText`)='8ba85e67634f0f0daf01dbf815a1c1cb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13157 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13160, 'ruRU', 'Пока ледошкуры спят, можно их не боятся.' FROM `quest_offer_reward` WHERE `ID`=13160 AND MD5(`RewardText`)='84b4d9ae8cf710f55b431e81a71f3390' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13160 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13161, 'ruRU', 'Без Рокира мир станет лучше, можешь мне поверить.' FROM `quest_offer_reward` WHERE `ID`=13161 AND MD5(`RewardText`)='dbdd1780c0d561084bb1f464a88939a8' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13161 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13162, 'ruRU', 'Честно признаюсь, мне будет слегка не хватать ее смеха... и этой улыбки, которой она улыбалась всегда перед тем, как кого-то убить. Зато теперь мне уже не придется все время оглядываться, ожидая удара в спину. Так что, наверное, грех жаловаться...' FROM `quest_offer_reward` WHERE `ID`=13162 AND MD5(`RewardText`)='bb2af6c6ec661c55f4026ad899bd012c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13162 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13163, 'ruRU', 'Значит, его больше нет? Очень рад это слышать.' FROM `quest_offer_reward` WHERE `ID`=13163 AND MD5(`RewardText`)='c84c9d01d84d8d098ed4cce8863999fb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13163 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13165, 'ruRU', 'Король-лич вернулся в Нордскол, раненный Испепелителем, но остатки его армий все еще блокируют второй этаж крепости.' FROM `quest_offer_reward` WHERE `ID`=13165 AND MD5(`RewardText`)='a003dd9b179716559ef7afb09baad82e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13165 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13166, 'ruRU', 'Отличная работа, рыцарь смерти. Скоро мы очистим Акерус от оставшихся существ Плети и начнем восстанавливать крепость.$B$BТебе осталось выполнить последнее мое поручение.' FROM `quest_offer_reward` WHERE `ID`=13166 AND MD5(`RewardText`)='c7ea7cbf1dbb554d177052b415d9345a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13166 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13167, 'ruRU', '<Глаза Киликса начинают светиться, когда он смотрит на панцирь.>\n\nС ним ПОКОНЧЕНО!\n\n$R! Твое имя будет высечено на страницах истории нашего народа.\n\nЯ пред тобой в долгу…' FROM `quest_offer_reward` WHERE `ID`=13167 AND MD5(`RewardText`)='0ef196f276e37ac480b56583926e1f4a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13167 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13168, 'ruRU', 'Ничего сложного, правда? Любой может научиться управлять мелкой нежитью. А вот с более сильными существами справится только настоящий некромант. Но это не беда: я уже придумал массу способов навредить врагу даже с помощью слабой нежити.\n\nПриступим?' FROM `quest_offer_reward` WHERE `ID`=13168 AND MD5(`RewardText`)='c152a54578c5d9c6838a5a2e38764f27' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13168 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13169, 'ruRU', 'Сморило их, да?' FROM `quest_offer_reward` WHERE `ID`=13169 AND MD5(`RewardText`)='f2bb24ec00a35527a0602744de189822' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13169 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13170, 'ruRU', 'Во как, даже рук не запачкав!' FROM `quest_offer_reward` WHERE `ID`=13170 AND MD5(`RewardText`)='bc52e2c372617fbac7c019fc2f4a9e68' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13170 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13171, 'ruRU', 'Отлично! Теперь нам мало чего приходится бояться в воздухе.' FROM `quest_offer_reward` WHERE `ID`=13171 AND MD5(`RewardText`)='9def7aaf9806a405dc16223ebc7ba064' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13171 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13172, 'ruRU', 'Да там защита – одно название. Проще не бывает.' FROM `quest_offer_reward` WHERE `ID`=13172 AND MD5(`RewardText`)='97b9b701c15b6f18af8a2d573c249070' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13172 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13174, 'ruRU', 'Так, посмотрим... посмотрим...\n\n<Керитоз внимательно изучает бумаги. Похоже, там нет ничего такого, чего он не знал раньше. И вдруг он находит то, что искал...>\n\nМаликрисс! Зловещая Крепость! Похоже, Артас никак не оправится после потери своих рыцарей смерти... Не знаю, что он там делает с таким количеством саронита, но у меня сложилось впечатление, что он как будто пытается отыграться и с лихвой компенсировать свои потери.\n\nЭтот парень не привык проигрывать.' FROM `quest_offer_reward` WHERE `ID`=13174 AND MD5(`RewardText`)='b2ecf135282f564d18e9a0bfda54a4c1' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13174 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13178, 'ruRU', 'Лок\'тар! Победа будет за Ордой!' FROM `quest_offer_reward` WHERE `ID`=13178 AND MD5(`RewardText`)='df97a1d90a74580215a58bca49e5cef7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13178 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13180, 'ruRU', 'Лок\'тар! Орду ждет победа!' FROM `quest_offer_reward` WHERE `ID`=13180 AND MD5(`RewardText`)='df97a1d90a74580215a58bca49e5cef7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13180 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13182, 'ruRU', 'Меня глубоко печалит нынешнее положение вещей. Если бы только мы могли восстановить былое величие нашей империи…' FROM `quest_offer_reward` WHERE `ID`=13182 AND MD5(`RewardText`)='6d61689494b9c5197dde3ee916b821a5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13182 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13185, 'ruRU', 'Хорошая работа. Жаль, Мурпа рядом с тобой не было, он бы помог.' FROM `quest_offer_reward` WHERE `ID`=13185 AND MD5(`RewardText`)='471ba447b5cdd9e28164029712af80f2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13185 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13186, 'ruRU', 'Отлично. Это должно существенно ослабить их атаку.' FROM `quest_offer_reward` WHERE `ID`=13186 AND MD5(`RewardText`)='e058256e438b26a888a6903c833fa169' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13186 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13188, 'ruRU', '<Вариан задумчиво смотрит вдаль.>$B$BВоистину, это весточка от старого друга... Кровь и честь!$B$B<Вариан вновь смотрит прямо на вас.>$B$BЕсли бы не это письмо – лежать бы тебе с перерезанным горлом. Благодари за свое спасение одного из величайших паладинов нашего времени!$B$BМы... мы будем сражаться вместе с твоим орденом против Плети. Против Короля-лича.$B$BИ ВО СЛАВУ АЛЬЯНСА!' FROM `quest_offer_reward` WHERE `ID`=13188 AND MD5(`RewardText`)='71a100833212afe1e0ddc47e857448fb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13188 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13212, 'ruRU', 'Думаю, "возвращение" рыцаря – это хорошая новость, но, честно сказать, сомневаюсь, что его товарищи имели в виду именно это, когда говорили о том, что его надо вернуть. Ладно, посмотрим, что можно сделать, чтобы поставить его на ноги и завершить нашу миссию.' FROM `quest_offer_reward` WHERE `ID`=13212 AND MD5(`RewardText`)='661a8fe563373f543b3b4d652df61e3b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13212 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13214, 'ruRU', 'Новая кровь…\n\n<Врайкульский рыцарь смерти плюет вам под ноги.>\n\nВсе вы считаете себя достойными воевать здесь.\n\nИ все вы ничто по сравнению с врайкулами и силой Плети!\n\nДа, тебе удалось одолеть шесть слабовольных трупов. Велика победа! В следующий раз тебе не устоять.' FROM `quest_offer_reward` WHERE `ID`=13214 AND MD5(`RewardText`)='ad7904cbe72e8fd4ed6e2fb645ccf8a6' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13214 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13215, 'ruRU', 'Думаешь, меня можно впечатлить тем, что вы с друзьями целой толпой одолели одолели одного нерубского жреца?\n\nУйди с глаз долой, а не то я сейчас на тебя вурдалаков напущу.' FROM `quest_offer_reward` WHERE `ID`=13215 AND MD5(`RewardText`)='1112942c46a0eac756a83109dea761f2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13215 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13216, 'ruRU', 'Победа над одной из хильд меня лично не особо впечатляет, $R. К тому же, тебе помогали друзья.\n\nЭто вам еще повезло, что в драке не участвовал ее дракон.' FROM `quest_offer_reward` WHERE `ID`=13216 AND MD5(`RewardText`)='318d570f17d7bc7128773212822d1749' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13216 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13218, 'ruRU', 'Уж не знаю, что за прием ты применил, чтобы победить тана: мне отсюда не видно было. Но одно могу сказать точно: следующего противника тебе не одолеть.\n\nДа, я знаю, кто это будет. Беги, $R, беги. Спрячься как можно дальше и не высовывайся.\n\nИли же оставайся и прими смерть. Мне, в общем-то, все равно.' FROM `quest_offer_reward` WHERE `ID`=13218 AND MD5(`RewardText`)='97a25aaf40c8af91546e583d7089ab12' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13218 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13219, 'ruRU', 'Мне больно слышать о поражении принца Сандовала. Да такая неумытая деревенщина, как ты, за счастье должна была счесть возможность отдать свою жизнь в бою с ним!\n\nзабирай ты свою проклятую награду. Давай только поскорее.' FROM `quest_offer_reward` WHERE `ID`=13219 AND MD5(`RewardText`)='94d78ddff7a266f89cee15d22f881be6' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13219 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13220, 'ruRU', 'Олакину крупно повезло. Никто еще не спасался из лап Плети, никто. В следующий раз ни отвага, ни крепкие нитки его не спасут. Надеюсь, он будет помнить об этом.' FROM `quest_offer_reward` WHERE `ID`=13220 AND MD5(`RewardText`)='d49099a3c15e1a580ed89f25c73ec260' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13220 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13223, 'ruRU', 'Отличная работа. Жаль, Мурпа рядом не было, он бы тебе помог.' FROM `quest_offer_reward` WHERE `ID`=13223 AND MD5(`RewardText`)='471ba447b5cdd9e28164029712af80f2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13223 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13227, 'ruRU', 'Мои верные рыцари послужили мне на славу. Похоже, они нашли мне настоящего героя!' FROM `quest_offer_reward` WHERE `ID`=13227 AND MD5(`RewardText`)='02248b4311157d8a1b1654b8897bcdfd' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13227 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13228, 'ruRU', 'Увидев, что солдаты Альянса атакуют ворота, они напали на них с тыла...\n\n<Корм ненадолго замолкает и неожиданно разражается смехом.>\n\nВот! Вот что такое Орда!\n\nЕсли бы не они, Альянс бы уже давно захватил ворота!\n\nОтвага бойцов Орды помогла нам выиграть драгоценное время.' FROM `quest_offer_reward` WHERE `ID`=13228 AND MD5(`RewardText`)='42072d8376bd6c88af1c6d7847d2bebd' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13228 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13230, 'ruRU', 'Прошло то время, когда мы еще как-то терпели Альянс, $N.\n\nОни сами сделали все, чтобы мы возненавидели их всей душой! Они будут жить в вечном страхе перед Ордой – до тех пор, пока не перестанут поганить наш мир!' FROM `quest_offer_reward` WHERE `ID`=13230 AND MD5(`RewardText`)='c1bd8149425bf80111202579a848d6dc' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13230 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13234, 'ruRU', 'Молодец, |3-6($C).\n\nОчень скоро Альянс будет дрожать от страха при одном только упоминании твоего имени, а в Орде будут славить тебя, как бесстрашную воительницу!' FROM `quest_offer_reward` WHERE `ID`=13234 AND MD5(`RewardText`)='f58cc5658bc5cc173ccd25c78b52807d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13234 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13235, 'ruRU', 'Теперь, когда мы уничтожили этого мясистого великана, Король-лич поймет, что остальные его войска тоже не неуязвимы. Говорят, что Король-лич не знает, что значит страх, но с твоей помощью мы напомним ему, что это такое.' FROM `quest_offer_reward` WHERE `ID`=13235 AND MD5(`RewardText`)='404773ce701d9241c86746fdce7d7dbd' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13235 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13238, 'ruRU', 'Занят? Пфф… Тоже мне, деловой нашелся! \n\nЛадно, неважно. Сойдешь и ты...' FROM `quest_offer_reward` WHERE `ID`=13238 AND MD5(`RewardText`)='5822b6477dca5f7dd4e6a8b89677673c' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13238 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13239, 'ruRU', 'Ничего себе! Даже отсюда мне было видно, как они загорелись! В общем, эксперимент удался. Я отмечаю очередной успех и начинаю разливать раствор по бутылкам – в плане подготовки к вторжению. Скорее всего, нам понадобится провести еще несколько испытаний. И мы их проведем! Ну, то есть, если тебе интересно...' FROM `quest_offer_reward` WHERE `ID`=13239 AND MD5(`RewardText`)='55c047ce40e255bda0154d80a78e5d1d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13239 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13241, 'ruRU', 'Выдающаяся работа, $N.\n\nЕсли бы ты не смогла это сделать, оставшиеся в живых берсерки помешали бы тебе во время битвы с королем.' FROM `quest_offer_reward` WHERE `ID`=13241 AND MD5(`RewardText`)='2510daa1ab0c56c6ef06145ab7d51041' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13241 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13242, 'ruRU', '<Саурфанг смотрит в небеса.>\n\nМой сын погиб как герой, подобно Броксу. Не горюй по нему, $N. Для орка нет лучшей смерти! Нет более великой чести! И сейчас мое сердце наполняется гордостью.\n\nСпасибо тебе, что вернул мне его доспехи. Я возложу их на его погребальный костер в Землях Предков в Награнде.\n\nМы должны переключить наше внимание на более серьезные проблемы.' FROM `quest_offer_reward` WHERE `ID`=13242 AND MD5(`RewardText`)='9faf73aecf9b8176c9d0efb6191d3176' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13242 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13243, 'ruRU', 'Мы спасены. Спасибо тебе.\n\nУвы, природа их вмешательства такова, что драконы Бесконечности обладают практически неограниченными возможностями сделать это еще раз.\n\nИ если это случится, я ясно вижу в будущем, как ты ринешься в сердце битвы, чтобы остановить их, $N' FROM `quest_offer_reward` WHERE `ID`=13243 AND MD5(`RewardText`)='dba61b78c09367c25fb65cccdadd3f06' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13243 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13245, 'ruRU', 'Хорошо. Прислони секиру к стене.\n\nЯ уверен, что Валгард и Лагерь Возмездия сегодня будут спать более спокойно, зная, что с этим злодеем благодаря тебе наконец-то покончено.' FROM `quest_offer_reward` WHERE `ID`=13245 AND MD5(`RewardText`)='01e835ac1d08dcc301876acc3bc5e72d' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13245 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13246, 'ruRU', 'Увы, это было необходимо.\n\nОрден Кирин-Тор не мог позволить столь видной представительнице красных драконов пасть жертвой нашего величайшего врага. Если бы Малигос начал использовать ее в Войне Нексуса, настал бы конец всему.\n\nНо я горюю о том, что не могли мы спасти ее.' FROM `quest_offer_reward` WHERE `ID`=13246 AND MD5(`RewardText`)='48090b19c86e2ef7ca731aacc27f2dfa' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13246 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13248, 'ruRU', '<Верховный маг хмуро кивает вам, когда вы передаете ему достаточно большой образец ювелирного искусства.>\n\nЧто сделано, то сделано. Эти врайкулы – такой благородный народ. Как жаль, что Король-лич столь глубоко вонзил в них свои смертоносные крючья.' FROM `quest_offer_reward` WHERE `ID`=13248 AND MD5(`RewardText`)='6a7f8f77bdd408c1629e8fd8f9d6faf4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13248 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13249, 'ruRU', 'Если удача будет сопутствовать нам, теперь, обезглавленная, крепость Драк\'Тарон перестанет отвлекать нас от главной проблемы в этой области – от борьбы с Плетью.\n\n<Верховный маг переводит взгляд на амулет, который он держит в руке.>\n\nЭто к лучшему, что амулет потерял свою колдовскую силу. Теперь мне не придется размышлять ни о том, как его использовать, ни о том, вправе ли я вообще это делать.' FROM `quest_offer_reward` WHERE `ID`=13249 AND MD5(`RewardText`)='33f8dd9dfe139675330048d9eb9036f5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13249 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13251, 'ruRU', 'Поразительно! Я никогда не видел ничего подобного. Я прослежу за тем, чтобы он попал в надежные руки в Аметистовой цитадели.\n$Если бы только тебе было позволено изменять ход истории... Возможно, если бы мы смогли уберечь Артаса от… нет, если думать об этом, можно сойти с ума.\n\nКонечно же, Хранители Времени понимают в этом больше, чем простые смертные.' FROM `quest_offer_reward` WHERE `ID`=13251 AND MD5(`RewardText`)='7b98e5828d1bc5608f671c3b598d56e7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13251 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13252, 'ruRU', 'Разве технология Титанов не поразительна? Информация содержится вот на этом диске!\n\nЯ лишь смею надеяться, что мы сможем найти способ извлечь ее оттуда.' FROM `quest_offer_reward` WHERE `ID`=13252 AND MD5(`RewardText`)='7fd1a5a1ad5a990983437314ebfcfd05' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13252 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13256, 'ruRU', 'С опасностью покончено, а оставшиеся пленники, оказавшиеся на свободе, снова водворены в тюрьму.\n\nДаларан перед тобой в долгу, $N\n\nТеперь мне нужно задать кое-кому пару вопросов, а конкретнее: почему легче всего было пробиться через анти-телепортационный барьер города именно в тюрьме?!' FROM `quest_offer_reward` WHERE `ID`=13256 AND MD5(`RewardText`)='8b5a5dcaf22347f42e3cd1f452818229' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13256 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13257, 'ruRU', 'Повелитель демонов Вариматас и главный аптекарь Отрекшихся Гнилесс – вот кто несет ответственность за это предательство.\n\n<Тралл кивает.>\n\nДа, тот самый Гнилесс, который нашел лекарство против недавней вспышки чумы.\n\nТе, кто не приняли их сторону, были убиты или изгнаны из нашего мира. Во время переворота чуть не погибла Сильвана.\n\nОрда потеряла Подгород. Оргриммар будет принимать беженцев-Отрекшихся у себя, пока не будет найдено решение этой проблемы. До тех пор мы находимся на военном положении.' FROM `quest_offer_reward` WHERE `ID`=13257 AND MD5(`RewardText`)='8c030383111e4fad0a348df938352804' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13257 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13260, 'ruRU', '<Кольтира осматривает вас с ног до головы.>\n\nНадеюсь, ты справишься. Иначе тебе же хуже будет, $C.' FROM `quest_offer_reward` WHERE `ID`=13260 AND MD5(`RewardText`)='6a92f322011d154ba3ea9483d2fe6bfa' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13260 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13261, 'ruRU', 'Зря старались!\n\nСперва Корм был занят, а когда я все-таки вытащил его наверх – ну, чтобы он посмотрел, – ты уже все закончила. Он обозлился, окрысился на меня и сказал, чтобы я не попадался ему на глаза, ну, как минимум, до завтра...\n\nТак что приходи завтра, и мы попробуем еще раз!' FROM `quest_offer_reward` WHERE `ID`=13261 AND MD5(`RewardText`)='ca75742986565e759c1e5e0d502e4bc4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13261 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13264, 'ruRU', 'Вот видишь, $C?\n\nНаходчивость может иногда уравнять ставки даже против, казалось бы, серьезно превосходящего тебя противника.' FROM `quest_offer_reward` WHERE `ID`=13264 AND MD5(`RewardText`)='65dcac4001ceac8beaf65ecb1af896d2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13264 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13266, 'ruRU', 'Позволь мне ввести тебя в курс дела, $N.\n\nПодгород на военном положении. Аптекари Гнилесса и демоны Вариматаса демоны захватили власть над городом. Они ушли в глухую оборону внутри города и используют против наших войск свою проклятую чуму.' FROM `quest_offer_reward` WHERE `ID`=13266 AND MD5(`RewardText`)='9172afc9bd49b8ce3ff43782b19b3869' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13266 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13267, 'ruRU', 'Завтрашний день несет с собой неопределенность. Прошли те дни, когда Альянс и Орда бились плечо к плечу друг с другом против общего врага. Новая битва грядет, $N – битва, в которой победителя не будет.\n\nНо мы должны продолжить наш поход на Ледяную Корону. В этом у нас нет выбора. Наше спасение – в героях, подобных тебе, $N. Будущее Орды – будущее всего мира – зависит от тебя.\n\nДавай вернемся в Оргриммар. Тебе нужно немедленно отправляться в Нордскол.' FROM `quest_offer_reward` WHERE `ID`=13267 AND MD5(`RewardText`)='a09cd1c2f970f5d39043b772e97979a0' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13267 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13273, 'ruRU', 'Разрушен? То есть как это – разрушен?\n\n<Бранн гневно стискивает кулаки.>\n\nНу, железные дворфы! Они мне за это заплатят! Что ж, пока что мы мало что можем сделать – займемся же тем, чтобы собрать ключ. Однако как только я попаду в чертоги Ульдуара, железные дворфы и их хозяева ответят за все, что они натворили!' FROM `quest_offer_reward` WHERE `ID`=13273 AND MD5(`RewardText`)='d5797450179a56f7c8772c3e96febf49' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13273 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13274, 'ruRU', 'Да, вот оно! Ключ практически у нас в руках! Осталось только выяснить, как соединить оболочку и ядро. Давай посмотрим, что говорится об этом у Сорена…' FROM `quest_offer_reward` WHERE `ID`=13274 AND MD5(`RewardText`)='7ab8fd4c78fe6bcc48f42763827f523b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13274 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13277, 'ruRU', 'Великолепно. Похоже, это именно то, что надо.\n\nВсегда следует по возможности бить врага его же оружием…' FROM `quest_offer_reward` WHERE `ID`=13277 AND MD5(`RewardText`)='8b42dd2933f1f7f8e475e0af1519412e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13277 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13278, 'ruRU', 'Отлично, $C!\n\nБыть может, проведя исследования, мы сумеем выяснить, как они изготовляют подобных созданий.' FROM `quest_offer_reward` WHERE `ID`=13278 AND MD5(`RewardText`)='3de01f3db4aa34985c1f6405908adfc4' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13278 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13279, 'ruRU', 'Отличная работа, $C!\n\nКогда наши войска двинутся на штурм цитадели, у нас будет готовый план по взятию врат смерти…' FROM `quest_offer_reward` WHERE `ID`=13279 AND MD5(`RewardText`)='99d54a758c5b6c26b6194a9bce1b5007' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13279 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13285, 'ruRU', '<Вы рассказываете Боктару, как помогли Бранну отыскать части краеугольного камня и соединить их. Боктар одобрительно кивает.>\n\nДа, возможно, Бранн – тот самый союзник, который нужен нам, чтобы выяснить, что же на самом деле происходит в Ульдуаре. Правильно мы сделали, что помогли ему. Против этого Локена и его прихвостней, железных дворфов, никакая помощь не будет лишней.' FROM `quest_offer_reward` WHERE `ID`=13285 AND MD5(`RewardText`)='6fa8a69cf9cfe292a3559c00cb182435' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13285 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13293, 'ruRU', 'Ох, как же я рад тебя видеть? Тебя старшой прислал из Молота?' FROM `quest_offer_reward` WHERE `ID`=13293 AND MD5(`RewardText`)='18e0ce8cfa0b084a312446425e6f2ff3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13293 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13302, 'ruRU', 'Их что-то свело с ума? Они слышат голоса у себя в голове?..\n\n Голоса в твоей голове?! \n\n Прошу тебя, дитя мое, очисти свои мысли от скверны, кою ты принес в эту чистую обитель.\n\n Мы попытаемся вывести на волю остальных завтра утром, когда ты отдохнешь.' FROM `quest_offer_reward` WHERE `ID`=13302 AND MD5(`RewardText`)='5b19688b423e59a1ab01fefa3df0917a' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13302 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13307, 'ruRU', 'Так значит, знаменосцы Плети и их прихвостни истреблены? Отлично! Будем готовиться дальше…' FROM `quest_offer_reward` WHERE `ID`=13307 AND MD5(`RewardText`)='4b12f6017b8deb9e14abca0e488f68db' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13307 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13308, 'ruRU', '<Приближаясь к этому существу, вы ощущаете очередную волну эйфории, смешанной с толикой боли.>\n\nХорошо… хорошо! А чтобы ты не сомневался, что я держу свое слово, сперва ты получишь награду.\n\nА потом, когда ты ее получишь, ты охотно отдашь мне ключ.' FROM `quest_offer_reward` WHERE `ID`=13308 AND MD5(`RewardText`)='33927cb09fb71232453c30428e50b89b' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13308 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13310, 'ruRU', 'Выходит, ты хоть на что-то годишься. Хвалю. Молодец.' FROM `quest_offer_reward` WHERE `ID`=13310 AND MD5(`RewardText`)='3d7a751d42d638acb2d7b3a887567624' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13310 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13312, 'ruRU', 'Итак, Гримкор пал от твоей руки? Отличная работа. Теперь, когда он не стоит у нас на пути, наши шансы на то, чтобы взять и удержать вал, изрядно повысились.' FROM `quest_offer_reward` WHERE `ID`=13312 AND MD5(`RewardText`)='557fb69ab6df373aa85eecb121f84769' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13312 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13313, 'ruRU', 'Хорошо. Чем меньше крыс из Альянса стоит у нас на пути, тем лучше. Мы им покажем, что такое настоящие воины!' FROM `quest_offer_reward` WHERE `ID`=13313 AND MD5(`RewardText`)='d8558fe869914cc814390f428869408e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13313 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13316, 'ruRU', 'Надеюсь, твой успех в Корп\'ретаре принесет нам удачу и станет залогом победы в будущей битве. Король-лич не будет спокойно сидеть и смотреть, как мы подступаем к воротам его твердыни.' FROM `quest_offer_reward` WHERE `ID`=13316 AND MD5(`RewardText`)='4225aaffe4635c9da076f714bff8e1a3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13316 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13324, 'ruRU', 'Итак, ты $gсобрал:собрала; колоду Призм. Отныне между тобой и ярмаркой установится прочная связь, и память о ней сохранится надолго. В знак этого я вручаю тебе одну из старших карт Новолуния.' FROM `quest_offer_reward` WHERE `ID`=13324 AND MD5(`RewardText`)='1d28c448f7cd2f3cf141ada55948f945' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13324 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13325, 'ruRU', 'Итак, ты $gсобрал:собрала; колоду Хаоса. Отныне между тобой и ярмаркой установится прочная связь, и память о ней сохранится надолго. В знак этого я вручаю тебе одну из старших карт Новолуния.' FROM `quest_offer_reward` WHERE `ID`=13325 AND MD5(`RewardText`)='e44f8aeddad7000a4a8be6a2a9931141' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13325 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13326, 'ruRU', 'Итак, ты $gсобрал:собрала; колоду Аристократов. Отныне между тобой и ярмаркой установится прочная связь, и память о ней сохранится надолго. В знак этого я вручаю тебе одну из старших карт Новолуния.' FROM `quest_offer_reward` WHERE `ID`=13326 AND MD5(`RewardText`)='067e97d8e620f6ec1d00885a6c9aa457' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13326 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13327, 'ruRU', 'Итак, ты $gсобрал:собрала; колоду Нежити. Отныне между тобой и ярмаркой установится прочная связь, и память о ней сохранится надолго. В знак этого я вручаю тебе одну из старших карт Новолуния.' FROM `quest_offer_reward` WHERE `ID`=13327 AND MD5(`RewardText`)='f027d7c2b34e4626555f1109badc9a91' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13327 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13330, 'ruRU', 'Ага, значит, не так уж они непобедимы! Король-лич получит то, что ему причитается.' FROM `quest_offer_reward` WHERE `ID`=13330 AND MD5(`RewardText`)='46a316456003be3cc42b9092fb57067f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13330 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13351, 'ruRU', 'Отлично, отлично, $C!\n\nТеперь, когда ты своими глазами видел, с чем приходится иметь дело, пора браться за работу…' FROM `quest_offer_reward` WHERE `ID`=13351 AND MD5(`RewardText`)='36954c7c2f329ff31c8ac8ecdfc0ab88' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13351 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13352, 'ruRU', 'Не правда ли, эффективное оружие – в соответствующих обстоятельствах, конечно?\n\nЭтот трюк никогда не устаревает…' FROM `quest_offer_reward` WHERE `ID`=13352 AND MD5(`RewardText`)='3e7cf7cc773b38a98829ca165ebd0d23' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13352 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13354, 'ruRU', 'Отличная работа, $R. Но почивать на лаврах рановато! На место этих надзирателей скоро встанут новые…' FROM `quest_offer_reward` WHERE `ID`=13354 AND MD5(`RewardText`)='8f93f60c92708dcaa456e84ceee7ecc2' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13354 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13355, 'ruRU', '<Меднопал выливает содержимое фляги в свой анализатор жидкостей.>\n\nО! Я знаю нужное вещество!' FROM `quest_offer_reward` WHERE `ID`=13355 AND MD5(`RewardText`)='1740668c0c5ec7184dbcbade723559d7' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13355 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13356, 'ruRU', 'Ур-ра!\n\nТо-то же! Будут знать!' FROM `quest_offer_reward` WHERE `ID`=13356 AND MD5(`RewardText`)='f75712dcab4e6fc0dbbd33a373247497' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13356 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13358, 'ruRU', 'Отличная работа, $C!\n\nНаш посланец уже успел раздобыть кое-какую ценную информацию.' FROM `quest_offer_reward` WHERE `ID`=13358 AND MD5(`RewardText`)='fca8d6459d6396fc73db411d8c7dff00' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13358 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13362, 'ruRU', 'Призрак мальчика… Сердце Артаса… Погоди-погоди. У меня голова идет кругом.' FROM `quest_offer_reward` WHERE `ID`=13362 AND MD5(`RewardText`)='dfa9879ad80abe89c913f5add4ee2e81' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13362 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13366, 'ruRU', 'Да, это весьма тревожные известия…' FROM `quest_offer_reward` WHERE `ID`=13366 AND MD5(`RewardText`)='8e05a32fa01199f9b9276a4b10b86570' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13366 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13367, 'ruRU', 'Алумет потерпел сокрушительное поражение, но дух его еще здесь, я чувствую это…' FROM `quest_offer_reward` WHERE `ID`=13367 AND MD5(`RewardText`)='ed4a8f318bbcb037225dacb61d628852' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13367 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13368, 'ruRU', 'Алумет потерпел сокрушительное поражение, но дух его еще здесь, я чувствую это…' FROM `quest_offer_reward` WHERE `ID`=13368 AND MD5(`RewardText`)='ed4a8f318bbcb037225dacb61d628852' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13368 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13373, 'ruRU', 'Ага, у тебя получилось! И как тебе бомбардировщик? Надеюсь, ты с ним сроднился, потому что тебе предстоит новый боевой вылет... и на этот раз все будет гораздо серьезнее...' FROM `quest_offer_reward` WHERE `ID`=13373 AND MD5(`RewardText`)='7bd4948f0a5da67272e1ea7abfd7b748' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13373 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13376, 'ruRU', 'Отлично сработано, $N Пока тебя не было, я слышала, что о тебе говорили остальные канониры... Я бы сказала, что тебя ждет блестящее будущее в военно-воздушных силах!' FROM `quest_offer_reward` WHERE `ID`=13376 AND MD5(`RewardText`)='4a43024534085acf41c83d27c8e74ae3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13376 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13379, 'ruRU', 'Да, да! Ты нашел меня! И очень вовремя!' FROM `quest_offer_reward` WHERE `ID`=13379 AND MD5(`RewardText`)='a4ef95faefa969780ebcad24df86ae05' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13379 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13406, 'ruRU', 'Да, у тебя получилось! Даже здесь было слышно, как их разлетающиеся запчасти бьются о скалы. Ты молодец. В ближайшее время получишь новое задание...' FROM `quest_offer_reward` WHERE `ID`=13406 AND MD5(`RewardText`)='906291aff2f6d6d86e72ff68a3fc7957' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13406 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13407, 'ruRU', 'Ты покрыла нас славой, $N! Скоро этотжалкий Альянс затрещит под пятой Орды!' FROM `quest_offer_reward` WHERE `ID`=13407 AND MD5(`RewardText`)='f1a7887dd114a361f6ccacc47fec0680' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13407 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13409, 'ruRU', 'Славная работа, $N. Я как наяву слышу звуки битвы, которая там разыгралась. Хотела бы я это видеть своими глазами!' FROM `quest_offer_reward` WHERE `ID`=13409 AND MD5(`RewardText`)='ee679d6d69c03421fb77875e9b372702' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13409 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13410, 'ruRU', 'Ты славно $gпотрудился:потрудилась;, $N. Благодаря твоим ратным подвигам мы еще долго продержимся на Полуострове Адского Пламени!' FROM `quest_offer_reward` WHERE `ID`=13410 AND MD5(`RewardText`)='8d935bb6459a029420d5f20e70cd64fb' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13410 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13411, 'ruRU', 'Славная работа, $N. Я как наяву слышу звуки битвы, которая там разыгралась. Хотела бы я это видеть своими глазами!' FROM `quest_offer_reward` WHERE `ID`=13411 AND MD5(`RewardText`)='ee679d6d69c03421fb77875e9b372702' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13411 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13412, 'ruRU', 'Тебе не кажется, $R, что смертным негоже влезать в личные дела драконов?\n\nНу ладно, с моей стороны было бы несправедливо держать брата в неведении. Можешь передать своему невежливому другу, который так любит вмешиваться в чужие дела, что я буду держать брата в курсе.' FROM `quest_offer_reward` WHERE `ID`=13412 AND MD5(`RewardText`)='2e1d77e4316f57100ac16230c91288e0' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13412 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13413, 'ruRU', 'Мой дракон говорит мне, что если ты потренируешься, из тебя выйдет хороший боец.\n\nНу что же. Ради победы над Малигосом я разрешу тебе тренироваться с моими питомцами, но только в свободное время.\n\nПодготовься как следует, $R, он – свирепый и беспощадный противник.' FROM `quest_offer_reward` WHERE `ID`=13413 AND MD5(`RewardText`)='20ea3a1e4f1065cdf200d56dab3e0c58' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13413 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13414, 'ruRU', 'Сегодня, $C, у тебя получилось значительно лучше. Временами казалось, что ты составляешь одно целое с драконом.\n\nМожешь тренироваться с моими питомцами. В свободное время.' FROM `quest_offer_reward` WHERE `ID`=13414 AND MD5(`RewardText`)='0ba5f93e98f67bbab5708272ed79bb6f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13414 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13419, 'ruRU', 'Добро пожаловать на "Молот Оргрима".\n\nЗдесь мы готовимся к атаке на Артаса. Как говорится, хорошая подготовка – залог успеха. Нам предстоит еще многое сделать, но прежде чем приступать к основной части, мы должны позаботиться о том, чтобы Серебряный Авангард получил необходимое подкрепление – когда придет время, нам понадобится их помощь.\n\nИди на верхнюю палубу и поговори с братом Кельтаном.' FROM `quest_offer_reward` WHERE `ID`=13419 AND MD5(`RewardText`)='df79794895308813da12a4d13bd4ad5f' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13419 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13423, 'ruRU', 'Ты снова показала себя самой достойной. Твое присутствие делает нам честь!' FROM `quest_offer_reward` WHERE `ID`=13423 AND MD5(`RewardText`)='60be06b131dfc8eb30eec8d5e2f6a684' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13423 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13428, 'ruRU', 'Нет высшей чести, чем изгнать захватчиков с земель Орды! Мы ныне славим твою великую отвагу в помощи нашим войскам!' FROM `quest_offer_reward` WHERE `ID`=13428 AND MD5(`RewardText`)='3e11927d4ef9eb273ed4e95edc4d345e' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13428 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13433, 'ruRU', 'Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!' FROM `quest_offer_reward` WHERE `ID`=13433 AND MD5(`RewardText`)='733bff38bc8259d7b195aeaaa8c58cba' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13433 AND x.`locale`='ruRU');
