INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13481, 'ruRU', 'Ты все сделал правильно. Мы боялись, что отец Камарос погиб. Твоя храбрость станет примером для всех, кто сражается с силами Плети.' FROM `quest_offer_reward` WHERE `ID`=13481 AND MD5(`RewardText`)='5815389c64b9aadb24a56287c37c24e3' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13481 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13501, 'ruRU', 'Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!' FROM `quest_offer_reward` WHERE `ID`=13501 AND MD5(`RewardText`)='733bff38bc8259d7b195aeaaa8c58cba' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13501 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13538, 'ruRU', 'Я слышал этот взрыв! Неплохо сработано! Мы уже приступили к перенаправлению энергии в реликвию титанов, чтобы наделить наши войска суперсилой.' FROM `quest_offer_reward` WHERE `ID`=13538 AND MD5(`RewardText`)='83008b0abc5618e18f74a95cc44c6391' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13538 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13548, 'ruRU', 'Кульки с конфетами можно найти в любой таверне. Ну – чего стоишь? Хватай конфетку!' FROM `quest_offer_reward` WHERE `ID`=13548 AND MD5(`RewardText`)='733bff38bc8259d7b195aeaaa8c58cba' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13548 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13549, 'ruRU', 'Это прекрасные экземпляры, $N! теперь у моих коллег будет достаточно материала для изучений.' FROM `quest_offer_reward` WHERE `ID`=13549 AND MD5(`RewardText`)='3bf6b99cbed1197a089f406eaceefcc1' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13549 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13833, 'ruRU', 'Храбрости тебе не занимать, $N Надеюсь, ты не $gперегнул:перегнула; палку, добывая кровь для рыбалки. Если тебе понравилось ловить ужрей, приходи завтра.' FROM `quest_offer_reward` WHERE `ID`=13833 AND MD5(`RewardText`)='aecfd6cc8625cc6e97800de07d3e7b39' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13833 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 13836, 'ruRU', 'Здравствуй, $N Марсия предупредила меня, что ты нашел руку этого бедняги.\n\nОна также сказала, что в благодарность за помощь ты можешь взять эту сумку. Если честно, из сумки чем-то отвратительно воняет – так что забери ее скорее!' FROM `quest_offer_reward` WHERE `ID`=13836 AND MD5(`RewardText`)='92d2dcfd53cf61c569ceb170eaf897a5' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=13836 AND x.`locale`='ruRU');
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) SELECT 24506, 'ruRU', 'Хорошо. $N, я знаю, кто ты. Ты идеально подойдешь для выполнения этого задания.$B$BНам представилась уникальная возможность проникнуть в Цитадель Ледяной Короны, но мы должны действовать быстро, пока Артас не догадался, что происходит.' FROM `quest_offer_reward` WHERE `ID`=24506 AND MD5(`RewardText`)='3a0da85be0f2b8afc8da9f3e2fce3cc1' AND NOT EXISTS (SELECT 1 FROM `quest_offer_reward_locale` x WHERE x.`ID`=24506 AND x.`locale`='ruRU');
